WordHunterWoW_QuestEN[28934] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Uldum, just east of the Tomb of Khartut, close to the entrance from Tanaris. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Technicians and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of the Tomb of Khartut in Uldum, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[28935] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in Uldum, east of the Tomb of Khartut and near the entrance from Tanaris. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Technicians and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of the Tomb of Khartut in Uldum, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
