WordHunterWoW_QuestEN[29021] = { title = "Samophlange", description = "The Venture Company have a small research facility west of here, just past the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", objectives = "Access the control console at the Venture Company research site.\n\nProvided item:", completion = "A variety of buttons, levers, and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel." }
WordHunterWoW_QuestEN[29022] = { title = "Samophlange", description = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.", objectives = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.", progress = "Blinking lights on the control console indicate that the main control valves have not been closed off.", completion = "The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off." }
WordHunterWoW_QuestEN[29023] = { title = "Samophlange", description = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.", objectives = "Get the Console Key from Tinkerer Sniggles.", progress = "The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.", completion = "Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal." }
WordHunterWoW_QuestEN[29024] = { title = "Samophlange", description = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.", objectives = "Return the Samophlange to Sputtervalve at Nozzlepot's Outpost in Northern Barrens.", progress = "Oh, you're back, <name>! Do you have the samophlange?", completion = "This is... er... interesting... yes. A device this complex is best analyzed by a team of skilled engineers in a clean room, painstakingly reverse engineering each component in a controlled environment.\n\nBut who has that kind of time?\n\nLet's just fire this thing up and see what it does..." }
WordHunterWoW_QuestEN[29025] = { title = "Samophlange Repair", description = "Well that didn't go as expected. I think I busted it.\n\nNo need to panic, though. Do me a favor and walk this across the way to Brak here in the camp. He'll bang this sucker back into shape real quick!You will receive:", objectives = "Walk the Broken Samophlange over to Brak Blusterpipe within the encampment." }
WordHunterWoW_QuestEN[29026] = { title = "Wenikee Boltbucket", description = "I think I really put my foot into that one - it looks like I might have knocked one of the load-bearing fluxors into the spokes of the deregulator gear. We can fix this, easy. I know an expert on triple-expansion piston drives who would love to get her hands on a samophlange. Take the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, she'll patch 'er right up.\n\nHey, no need to walk - this gives me the perfect opportunity to test my personal people porter device!", objectives = "Bring the Broken and Battered Samophlange to Wenikee Boltbucket. Talk to Brak to teleport directly to her.", progress = "I'm very busy with my work, <class>.  Unless you have something for me, it'd be best if you moved along...", completion = "Oh, what's this? A samophlange, you say? What's a samophlange??\n\nAh... but look at the way it moves when you handle it.  And there's the sound of intricate gears inside. Oh my! I want to fix it and see what it does, don't you??" }
WordHunterWoW_QuestEN[29027] = { title = "Nugget Slugs", description = "I want to fix this samophlange, but to do that I'm going to need some supplies. I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nUnfortunately, the closest place to get them is the Burning Blade farm to the southwest. The place will be heavily guarded, so be careful, but the samophlange just might be worth the risk. Search the tool buckets, then return to me when you've gathered enough nugget slugs.", objectives = "Collect 10 Nugget Slugs from buckets around the Burning Blade farm to the southwest.", progress = "Do you have the nugget slugs, <name>?  I've been eyeing this Samophlange and I can't wait to tinker with it.", completion = "Great, you got them!  Now I can get to work..." }
WordHunterWoW_QuestEN[29028] = { title = "Into Jaedenar", description = "The Shadow Council corrupts this once beautiful forest from their stronghold, Jaedenar, in the northwest.\n\nNow, one of our own is missing. We sent a lone scout by the name of Andalar Shadevale to Jaedenar, in hopes of thinning the enemy's ranks by stealth. \n\nWe have not heard from him in days, and we fear the worst. There is a small chance he may still be alive. {name}, please go at once and find him!", objectives = "Find Andalar Shadevale in Jaedenar.The Shadow Council corrupts this once beautiful forest from their stronghold, Jaedenar, in the northwest.\n\nNow, one of our own is missing. We sent a lone scout by the name of Andalar Shadevale to Jaedenar, in hopes of thinning the enemy's ranks by stealth. \n\nWe have not heard from him in days, and we fear the worst. There is a small chance he may still be alive. <name>, please go at once and find him!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29029] = { title = "Dying Knowledge", description = "<The corrupted water bubbles and froths, as if trying to break free from itself.>\n\nTake this water to our scout in the field. He should be able to purify it for our attack on the Shadow Hold's defenses!", objectives = "Take the filled canteen to Andalar Shadevale.<The corrupted water bubbles and froths, as if trying to break free from itself.>\n\nTake this water to our scout in the field. He should be able to purify it for our attack on the Shadow Hold's defenses!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29030] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Earthen Ring Bonfire in Hyjal.", completion = "Honor the Mount Hyjal flame." }
WordHunterWoW_QuestEN[29031] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Earthen Ring Bonfire in Vashj'ir.", completion = "Honor the Vashj'ir flame." }
WordHunterWoW_QuestEN[29032] = { title = "Get Them While They're Young", description = "I can teach you to ride a Winterspring frostsaber, but it takes time and dedication. For this to work, both saber and rider must be highly trained and both must share a bond of deep trust.\n\nThe cubs are only receptive to this training if they're introduced to their riders at a young age. Some of the cubs in the dens surrounding Frostsaber Rock are at the proper age to begin their training. If you help me gather the most promising of those cubs, I'll allow you to begin training with your own cub.", objectives = "Gather 8 Frostsaber Cubs from the dens around Frostsaber Rock.", progress = "We must get the saber cubs while they're still young enough to bond with people. If they get too old, the cats will remain feral forever.", completion = "These cubs are just the right age to begin their training. A few of them even have the proper traits to be trained as mounts. As promised, I'll select one of these cubs for you to train. This fellow here seems to have an affinity for you.\n\nI'll train the more common, docile cubs for the market in Darnassus." }
WordHunterWoW_QuestEN[29033] = { title = "[PH] Bridle Buy-In", description = "", objectives = "" }
WordHunterWoW_QuestEN[29034] = { title = "They Grow Up So Fast", description = "I think this little fellow will be a good match for you.\n\nThis cub is going to require a lot of attention to ensure that he grows up strong and healthy. You should check up on your cub at least once each day. Feeding and caring for your Winterspring cub is the best way to build a bond of trust with him.\n\nAs your cub grows, he will shed his old whiskers and grow new ones appropriate to his size. Once your cub has shed twenty whiskers, bring him back to me along with some materials for your saddle.", objectives = "Accumulate 20 Winterspring Cub Whiskers shed by your Winterspring Cub. Bring the whiskers, 20 Runecloth, 20 Rugged Leather, and 80 gold to Rivern Frostwind.", progress = "How fares your young saber?", completion = "It looks like you've done an admirable job of raising your cub, <name>. Your saber has grown up to be strong, healthy, and loyal. Both of you are well-matched.\n\nYour Winterspring frostsaber will respond to your call anytime you wish to ride together." }
WordHunterWoW_QuestEN[29035] = { title = "A Cub's Cravings", description = "Your Winterspring cub looks at you and licks its lips. The little cat must be hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of shardtooth bears can be found all over Winterspring.", objectives = "Gather 6 pieces of Shardtooth Meat from any of the Shardtooth bears in Winterspring and feed them to your Winterspring Cub.", progress = "Your wintersaber cub looks at you as if to say, \"Is that it?\"", completion = "Your Winterspring cub looks happy, satisfied, and ready to curl up for a nap." }
WordHunterWoW_QuestEN[29036] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Earthen Ring Bonfire in Deepholm.", completion = "Honor the Deepholm flame." }
WordHunterWoW_QuestEN[29037] = { title = "'Borrowing' From the Winterfall", description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat licks its lips. It must be meal time again! As the cub's surrogate father you're responsible for providing meat until it can hunt on its own.\n\nBut what if you let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few pieces and your cub would get to try something new.", objectives = "Obtain 6 pieces of Smoked Meat from either Winterfall furbolg camp in Winterspring and feed them to your Winterspring Cub.", progress = "Your cub still looks hungry. What's the hold up?", completion = "Your cub looks satisfied for now." }
WordHunterWoW_QuestEN[29038] = { title = "Hunting Practice", description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub hunting for the small arctic hares that burrow in the snow of northern Winterspring. Bring your cub close to the mounds of snow covering the hare burrows and wait for the cub's instincts to take over.", objectives = "Bring your cub near snow-covered burrows in northern Winterspring 5 times to help it learn how to hunt arctic hares.", progress = "The cub looks at you, as if asking to continue the game.", completion = "Your Winterspring cub looks tired, content, and perhaps a bit more experienced." }
WordHunterWoW_QuestEN[29039] = { title = "Hunting Practice", description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub hunting for the small arctic hares that burrow in the snow of northern Winterspring. Bring your cub close to the mounds of snow covering the hare burrows and wait for the cub's instincts to take over.", objectives = "Bring your cub near snow-covered burrows in northern Winterspring 5 times to help it learn how to hunt arctic hares.", completion = "Your cub looks tired, content, and perhaps a bit more experienced." }
WordHunterWoW_QuestEN[29040] = { title = "Cub's First Toy", description = "The winterspring cub plays with a small tuft of fur from a large animal, batting the discarded hair about. While your cub looks like it's enjoying the new game, you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of leather from a yeti pelt and some feathers from crazed moonkin, you could make a respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.", objectives = "Obtain a Tough Yeti Hide from any Ice Thistle Yeti and 5 Wildkin feathers. Combine them to make a Winterspring Cat Toy and use it to play with your Winterspring Cub.", progress = "The cub looks at you. What could you be planning?", completion = "Your Wintersrping cub seems thrilled with its new toy, but there's no telling how well it will survive the cub's enthusiasm." }
WordHunterWoW_QuestEN[29041] = { title = "Welcome to Paradise", description = "Eaaaauuuugggghhhh!\n\nOh my goodness, I thought you were one of THEM.\n\nWho are you? <name>? Look, we could really use your help.\n\n<Lasha listens as you ask what's going on.>\n\nAre you blind? The entire resort's on fire! These pesky little Flamekin Firestarters are running around the place, torching everything they can get their grubby little claws on. Kill them all before our profits suffer!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 6 Flamekin Firestarters" }
WordHunterWoW_QuestEN[29042] = { title = "Kitchen Clean-Up", description = "Why would anyone want to attack us? We're not hurting anybody! Anyway, it's a good thing you showed up when you did.\n\nLook <name>, I need to find out who's sabotaging us before I lose my job. You're going to go undercover and dig up as much information as you can. First though, you need to show me you can blend in as one of our staff.\n\nFirst thing we need to do is keep this place clean. Go down to the beach to the west and clean up any empty cans that you see.You will receive:", objectives = "Collect 8 Empty Kaja'Cola cans" }
WordHunterWoW_QuestEN[29043] = { title = "Lunch Break", description = "Are you the new assistant that Lasha's been talking about?\n\n<Dodd looks you up and down, not even trying to conceal a look of distaste.>\n\nI need you to deliver these leftover lunches to the rest of the Resort Staff. I don't like my Staff taking their own meal breaks - they run the risk of wandering into forbidden places, loitering, or even gossiping. Filthy habits! Make sure they eat the food!You will receive:", objectives = "Deliver lunch to 5 Resort Staff" }
WordHunterWoW_QuestEN[29044] = { title = "No Child of Mine", description = "The only thing I detest more than sunshine and rainbows are children. And our omnipresent guests are always bringing their brats along on their so-called family vacations! The pests run around, make loud noises, and are forever tainting my resort with their fun.\n\n<Assistant Resort Director Finnert makes a look of disgust.>\n\nTake this certified Child Safety Harness and bring them back to the child play area. They shouldn't be running free around these grounds!You will receive:", objectives = "Harness 5 Children." }
WordHunterWoW_QuestEN[29045] = { title = "Fit for a King", description = "Now that the resort's back up and running, I've got a lot of mouths to feed and no time to waste! I'm going to make crab risotto and we're running low on meat. Bring me back some crab meat from the crawlers around the pools.You will receive:", objectives = "Collect 6 King Crawler legs" }
WordHunterWoW_QuestEN[29046] = { title = "Chef's Challenge: Steelback", description = "Those king crawlers you killed earlier are nothing compared to the ultimate crustacean - Steelback. He lives up to his name, but I have faith in you, <name>. Now prove that you're a worthy student and bring me his claw!You will receive:", objectives = "Bring back Steelback's Claw" }
WordHunterWoW_QuestEN[29047] = { title = "Chef's Challenge: Faewing", description = "I've heard of an enormous moth that inhabits the lake shore to the west. Moth horn is an incredible delicacy, and I'm planning to use it for an unforgettable dish. Go hunt down Faewing and bring me back its horn.You will receive:", objectives = "Bring back Faewing's Horn" }
WordHunterWoW_QuestEN[29048] = { title = "Chef's Challenge: Grumpfin", description = "There's a fish here that's eluded me for years. He lives at the bottom of the largest lake, and we've named him Grumpfin for his personality. I think it's time to catch him and cook him! Bring him to me, but be careful - he's an ornery old devil.You will receive:", objectives = "Bring back Grumpfin's Eye" }
WordHunterWoW_QuestEN[29049] = { title = "So Sous Me", description = "TBDYou will receive:", objectives = "Talk to Auguste YarmesTBDYou will receive:" }
WordHunterWoW_QuestEN[29050] = { title = "Out of Gas", description = "So you need a boat, eh? Well my sweetheart here can take you across the lake, but the Lucky Bucket's plum lucked out of gas!\n\nListen, there are some Oil Slimes in the mountains to the south. If you can go fill up my gas tank, we'll have enough juice for a nice boat ride. Whaddaya say?You will receive:", objectives = "Use the Goblin Gas Tank to siphon oil from 8 dead Oil Slimes" }
WordHunterWoW_QuestEN[29051] = { title = "Cub's First Toy", description = "The Winterspring cub plays with a small tuft of fur from a large animal, batting the discarded hair about. While your cub looks like it's enjoying the new game, you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of leather from a yeti pelt and some feathers from crazed moonkin, you could make a respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.", objectives = "Obtain a Tough Yeti Hide from any Ice Thistle Yeti and 5 Wildkin feathers. Combine them to make a Winterspring Cat Toy and use it to play with your Winterspring Cub.", completion = "Your Winterspring cub seems thrilled with its new toy, but there's no telling how well it will survive the cub's enthusiasm." }
WordHunterWoW_QuestEN[29052] = { title = "A Cub's Cravings", description = "Your Winterspring cub looks at you and licks its lips. The little cat must be hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of shardtooth bears can be found all over Winterspring.", objectives = "Gather 6 pieces of Shardtooth Meat from any of the Shardtooth bears in Winterspring and feed them to your Winterspring Cub.", completion = "Your Winterspring cub looks happy, satisfied, and ready to curl up for a nap." }
WordHunterWoW_QuestEN[29053] = { title = "'Borrowing' From the Winterfall", description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat licks its lips. It must be meal time again! As the cub's surrogate <father/mother> you're responsible for providing meat until it can hunt on its own.\n\nBut what if you let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few pieces and your cub would get to try something new.", objectives = "Obtain 6 pieces of Smoked Meat from either Winterfall furbolg camp in Winterspring and feed them to your Winterspring Cub.", completion = "Your cub looks satisfied for now." }
WordHunterWoW_QuestEN[29054] = { title = "Stink Bombs Away!", description = "Greetings, {class}!  I hope Hallow's End is treating you well.  Bah, enough of the small talk... Let's get down to business.  Undercity.  They have employed Hags and foul magic to launch petty attacks on our town.  Some may say, ignore the childish Horde.  I say, let's show them!\n\nSpeak to my sister, Gertrude, and she will send you on your way to toss some stink bombs in Undercity.", objectives = "Speak to Gertrude Fenlow to gain access to a broom, then drop stink bombs in the Undercity.", progress = "Bombs away, am I right?", completion = "That will show those foolish crones who the strongest is.\n\nTake these treats and treat yourself to something nice, <class>." }
WordHunterWoW_QuestEN[29055] = { title = "Float My Boat", description = "We're all set! Just hop on the boat and we'll get going!You will receive:", objectives = "Take a ride around the lake on Trip's boat" }
WordHunterWoW_QuestEN[29056] = { title = "Fruit Round-Up", description = "You're Lasha's little helper, aren't you? Well she said something about a special errand, and she asked me to whip up some special drinks for our guests. Apparently, there are some new brews that are all the rage in Stormwind and Orgrimmar, but I'm missing a major ingredient - coconut! Luckily, they grow in the palm trees right around the camp. Fly up there now and get some for me, will you?You will receive:", objectives = "Collect 8 coconuts" }
WordHunterWoW_QuestEN[29057] = { title = "Firebeak", description = "Okay <name>, that's it. I'm not surprised in the slightest that Dodd was behind this. I never liked him, or his stupid moustache! It's time to FIGHT BACK!\n\nIn the mountains to the east lives a powerful creature known as Firebeak. He is the key to the Twilight Cultists' destruction.\n\nFight the beast and show him that you're its master. When he is weakened, ride him down the pools to rain destruction upon our enemies!You will receive:", objectives = "Fight Firebeak and weaken him" }
WordHunterWoW_QuestEN[29058] = { title = "Roc Collection", description = "Okay, now we're in a real crisis, and you know what? I'm MAD! No one tries to destroy MY resort! Especially not that little worm Dodd Finnert. I've always disliked him, especially his stupid moustache!!!\n\nListen <name>, we're going to try one last, crazy plan that should get rid of the Twilight cultists once and for all. The greater rocs that live in the mountains to the east have enormously fireproof qualities. We're going to fashion a fireproof bridle out of their guts. 12 should do it.You will receive:", objectives = "Gather12 Roc Guts" }
WordHunterWoW_QuestEN[29059] = { title = "Save 'Em", description = "", objectives = "" }
WordHunterWoW_QuestEN[29060] = { title = "At Your Service", description = "Now that you've had a chance to blend in, I need you to do go undercover among the guests. We've pinpointed our recent troubles on a surviving branch of the Twilight's Hammer, and we think some of guests might be working for them.\n\nTake these drinks and see if you can gather up any clues about the Cultists posing as guests. Some of the customers may need their tongues loosened, so make sure you're serving them the right kind of drink.You will receive:", objectives = "Serve 6 Resort Guests and gather 4 Twilight Cultist clues" }
WordHunterWoW_QuestEN[29062] = { title = "Finding the Cultist", description = "It sounds like we have a member of the Twilight's Hammer in our presence.\n\n<name>, it's up to you to expose the spy. Question the Resort Guests and accuse anyone who matches the description of a Twilight Cultist!\n\nRemember, the suspect is:\n\nTALL\nRUDE\nWEARING THE COLOR RED\n\nThis isn't a task for the weak - if the culprit gives you any trouble, you may have to beat the information out of them.You will receive:", objectives = "Question Resort Guests to find the Twilight Evidence" }
WordHunterWoW_QuestEN[29063] = { title = "Subversion", description = "", objectives = "" }
WordHunterWoW_QuestEN[29064] = { title = "We Need a Boat", description = "It all makes sense now! Initial architectural surveys of this area revealed quite an energetic anomaly. It's the same energy that powers these superheated mineral pools.\n\nJudging from the evidence, the Twilight's Hammer is going to harness the energy to open a portal to the elemental plane of water! If that happens, our whole venture - and a lot of lives of course - is sunk.\n\n<name>, you need to investigate immediately! Go talk to Trip Hullbolt. He has a boat that can take you to the spot on the map.You will receive:", objectives = "Speak to Trip HullboltIt all makes sense now! Initial architectural surveys of this area revealed quite an energetic anomaly. It's the same energy that powers these superheated mineral pools.\n\nJudging from the evidence, the Twilight's Hammer is going to harness the energy to open a portal to the elemental plane of water! If that happens, our whole venture - and a lot of lives of course - is sunk.\n\n<name>, you need to investigate immediately! Go talk to Trip Hullbolt. He has a boat that can take you to the spot on the map.You will receive:" }
WordHunterWoW_QuestEN[29065] = { title = "Out of This World", description = "We've had no end of trouble here, <name>! Sabotaged food shipments, tampered water supply, and now this! You can't send a more unsubtle message than fire. We clearly aren't wanted here!\n\nBut first things first. Whoever is trying to get rid of us has summoned vile totems all around the grounds. If we destroy those totems, those blasted Flamekin demons will stop appearing.\n\nDestroy any totems that you see before we're overrun!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 6 Twilight Totems" }
WordHunterWoW_QuestEN[29066] = { title = "Good News... and Bad News", description = "<Blackhorn used the power of Thol'embaar's remains to slip his bonds. But at least the inferno seems to be subsiding.>\n\n<Matoclaw will want to know what happened here. She's waiting for you back at the Grove of Aessina.>", objectives = "Talk to Matoclaw at the Grove of Aessina in Mount Hyjal.", completion = "What? Blackhorn helped you combat the inferno but escaped in the process? That crafty weasel!\n\nIt's not your fault, <name>. He'd probably been plotting this the moment he saw the flames begin creeping up the mountain. We'll have to deal with him later." }
WordHunterWoW_QuestEN[29067] = { title = "Potion Master", description = "Potions, potions, potions.  Can I teach you about potions!\n\nYou're going to have to bring me samples of your work, so I know you're ready.\n\nRemember <name>, you can only learn ONE specialization, so if you complete your potion training, then elixir and transmutation specialization will no longer be available.", objectives = "Bring a large supply of potions to an alchemy trainer in any capital city.", progress = "Have you the potions?", completion = "Excellent!" }
WordHunterWoW_QuestEN[29068] = { title = "Potion Specialist", description = "", objectives = "" }
WordHunterWoW_QuestEN[29069] = { title = "Transmutation Specialist", description = "", objectives = "" }
WordHunterWoW_QuestEN[29070] = { title = "Twilight Plight", description = "", objectives = "Kill 10 Twilight CultistsYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29071] = { title = "Make Haste to Stormwind!", description = "Veterans of Northrend, King Wrynn and the Alliance need your help! Stormwind and the Alliance face unprecedented threats from Deathwing and his Twilight's Hammer minions!\n\nPlease find the enclosed hearthstone and use it to transport yourself to Stormwind. The crown has arranged lodging for all returning heroes at The Golden Keg in the Dwarven District.", objectives = "Veterans of Northrend, King Wrynn and the Alliance need your help! Stormwind and the Alliance face unprecedented threats from Deathwing and his Twilight's Hammer minions!\n\nPlease find the enclosed hearthstone and use it to transport yourself to Stormwind. The crown has arranged lodging for all returning heroes at the The Golden Keg in the Dwarven District." }
WordHunterWoW_QuestEN[29072] = { title = "Last Resort, Literally", description = "We've managed to stop the assault temporarily, leaving Dodd vulnerable.\n\nHowever, in all the chaos, he was able to summon Ahti, a powerful elemental lord, across the rift and into our world. With Ahti's allegiance, the Twilight's Hammer will pour into the nearby regions, killing thousands of innocents.\n\nThis is bigger than me or this resort. We must stand against them here and now. I ask of you one last task - kill Ahti and save us all.You will receive:", objectives = "Kill Ahti" }
WordHunterWoW_QuestEN[29073] = { title = "Make Haste to Orgrimmar!", description = "Veterans of Northrend, King Wrynn and the Alliance need your help! Stormwind and the Alliance face unprecedented threats from Deathwing and his Twilight's Hammer minions!\n\nPlease find the enclosed hearthstone and use it to transport yourself to Stormwind. The crown has arranged lodging for all returning heroes at The Golden Keg in the Dwarven District.", objectives = "Veterans of Northrend, Warchief Garrosh commands you to return to Orgrimmar at once! You will be the blade the Horde wields against Deathwing and his Twilight's Hammer minions.\n\nUse the attached hearthstone to transport yourself to Orgrimmar. Our allies await your return, hero." }
WordHunterWoW_QuestEN[29074] = { title = "A Season for Celebration", description = "Merry met, {class}!\n\nHallow's End is a time for celebration and reflection, though many of us have forgotten why. Indeed some aspects of the festival, like the Wickerman, had been lost to time... until the Gilneans returned to the Alliance fold.\n\nTravel outside the gates of Stormwind and speak to Celestine of the Harvest. She can tell you more about the Wickerman ceremony.", objectives = "Speak with Celestine of the Harvest just outside the gates of Stormwind.", completion = "The Wickerman ceremony is a time honored tradition.  It is good to see the Alliance celebrating it once again." }
WordHunterWoW_QuestEN[29075] = { title = "A Time to Gain", description = "Greetings, {class}.  The Wickerman you see before you symbolizes self.  The flames that burn it are a cleansing fire.\n\nTradition states that we take our burdens and give them to the fires.  We let go of our burdens as we approach the winter season and we gain clarity and peace.  Join us in our tradition, {class}.\n\nTake a branch from the nearby bonfire and hurl it at the Wickerman.", objectives = "Use the bonfire in front of the Wickerman.", progress = "Have you released your burdens, <class>?", completion = "Do not let your burdens trouble you any longer.  Any time you are feeling burdened, remember the Wickerman." }
WordHunterWoW_QuestEN[29076] = { title = "Kevin's Test Quest", description = "A testing quest", objectives = "Just complete it.A testing quest" }
WordHunterWoW_QuestEN[29077] = { title = "What Hath Dodd Wrought", description = "I can't believe it! You actually bested Firebeak! Jump onto his back, fly down to the lake, and blast the invaders out of the water! Kill every last one of them!You will receive:", objectives = "Kill 50 Seething Water Elementals and 20 Twilight Summoners" }
WordHunterWoW_QuestEN[29078] = { title = "Beating Them Back!", description = "Another Alliance recruit, eh? I'm Marshal McBride, commander of this garrison. We don't see many of your kind here, {race}, but we could sure use the help.\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", objectives = "Kill 6 Blackrock Worgs.", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, <name>, but we've got even bigger problems to deal with now." }
WordHunterWoW_QuestEN[29079] = { title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", objectives = "Kill 8 Blackrock Spies.", progress = "Kill the spies!", completion = "Excellent work, <name>. You've turned out to be quite an asset to this garrison.\n\nFeel free to speak with any of our trainers within and around the abbey if you need to sharpen any of your combat skills.\n\nWhen you're ready, I have another assignment for you..." }
WordHunterWoW_QuestEN[29080] = { title = "Join the Battle!", description = "I have here an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", objectives = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!" }
WordHunterWoW_QuestEN[29081] = { title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", objectives = "Kill 8 Goblin Assassins.", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs." }
WordHunterWoW_QuestEN[29082] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!" }
WordHunterWoW_QuestEN[29083] = { title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!" }
WordHunterWoW_QuestEN[29084] = { title = "Classic Random 35-39 (1st)", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[29085] = { title = "Classic Random 35-39 (Nth)", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[29086] = { title = "Competition Schmompetition", description = "I'm just a little guy, trying to set up my own independent business. Working hard toward the Azerothian dream, ya know?\n\nWell soon as I set up shop, the Venture Co. next door decided they wanted me out. They've been harrassing me with threatening letters, using words like 'cease' and 'desist.' \n\nWorst of all, the schematics for my newest machine are missing, and I know those corporate pilferers stole them! Go to the Sludge Fen and knock out some of their employees. I know they're hiding my blueprints!", objectives = "Recover 6 of Sputtervalve's Blueprints from Venture Co. Drudgers, Mercenaries, or Peons.", progress = "I can't believe they would stoop so low! Did you get my blueprints back?", completion = "Thanks for recovering my blueprints. Now my work on the Silver Bullet X-831 can continue." }
WordHunterWoW_QuestEN[29087] = { title = "Sludge Investigation", description = "Hey {name}, do you see this footprint? We found them all over the camp last night! Nothing's missing, but all our belongings have been...examined. The muddy trails lead back toward the Sludge Fen.\n\nSomeone's been sniffing around, and I don't like it one bit. Can you go west to the Sludge Fen and investigate? See if you can find any more tracks just like this one!", objectives = "Investigate 5 Muddy Tracks at the Sludge Fen.", completion = "You look around and notice the lake is covered in slick oil. This once beautiful oasis has been ravaged. You feel a deep sense of foreboding." }
WordHunterWoW_QuestEN[29088] = { title = "Hyena Extermination", description = "Hey {name}, we've got a real problem here. There's an overpopulation of hyenas just west of the Sludge Fen, and they're starting to become a menace.\n\nIf I have to listen to them caterwauling one more night, I just might go crazy! Vernon over there says the hyenas might even have made off with one of his stabled pigs. We can't have that happening.\n\nCan you go thin out the hyena numbers? You'll find them parading in broad daylight to the west.", objectives = "Kill 6 Hecklefang Hyenas.", completion = "Good riddance! Those filthy pests are more trouble than they're worth." }
WordHunterWoW_QuestEN[29089] = { title = "Sludge Beast!", description = "Whatever is lurking around the Sludge Fen, it doesn't appear to be human. Judging from the remains around its tracks, it's also dangerous.\n\nYou decide to follow the tracks down to the bottom of the lake and look for the creature's resting place.", objectives = "Investigate the Sludge Beast's resting place and kill whatever comes out.", completion = "You saw sludge being dumped straight into the lake? I wouldn't be surprised if the Sludge Beast were a product of the Venture Co.'s carelessness." }
WordHunterWoW_QuestEN[29090] = { title = "A Burning Threat", description = "While we cast our eyes toward the cataclysm, who watches our backs? While our leaders take up arms against Deathwing, the Burning Blade plots our downfall.\n\nEven as we speak, they are gathering recruits and supplies at the farm to the southwest. I care not to meet death at the hands of the Burning Legion. It's time we take matters into our own hands.\n\n{name}, will you help me keep the vigil? Go and slaughter their ranks before it's too late.", objectives = "Kill 8 members of the Burning Blade at the farm to the southwest.", progress = "I may be old and retired, but my mind is still as sharp as my sword.", completion = "Thank you, <name>. This old orc will sleep more safely at night." }
WordHunterWoW_QuestEN[29091] = { title = "Freedom Movement", description = "", objectives = "" }
WordHunterWoW_QuestEN[29092] = { title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", objectives = "Travel to a capital city and speak to the Earthen Ring Elder.", completion = "This is grave news indeed. We must do everything in our power to stop this war from coming to pass." }
WordHunterWoW_QuestEN[29093] = { title = "Cruisin' the Chasm", description = "One of my friends says that a steam tank mechanic in Westfall lets visitors use his choppers. My friend even got to ride one!\n\nI've seen people ride by the orphanage in choppers. They're real loud and just about the fastest thing I've ever seen! I want to try one out!\n\nCould we go to Sentinel Hill in Westfall and ride one of those choppers? Please? I promise to behave myself and we could see the crazy giant hole left when the world changed!", objectives = "Travel to Sentinel Hill in Westfall and climb aboard a Rental Chopper to tour the Raging Chasm with your orphan.", progress = "This is going to be the best week ever!", completion = "That was the best! I want to come back and do this again next year. When I grow up, I'm going to have a chopper, except I'm gonna make it myself, and take all my friends for a ride!" }
WordHunterWoW_QuestEN[29094] = { title = "The Short Way Home", description = "Looks like your work here is done, {class}. You'd better head back to the Crossroads.\n\nLuckily for you, my Silver Bullet X-831 prototype is finished, and she's ready for a test drive. Whaddaya say you do me one last favor and take her for a little spin?\n\nOne of my assistants will accompany you. Your sweet, sweet ride is waiting on the platform behind me. Just hop on when you're ready.", objectives = "Take a ride on the Silver Bullet X-831.", completion = "I thought you were a goner. Glad to see you're still in one piece." }
WordHunterWoW_QuestEN[29095] = { title = "Report to Thork", description = "Now that the threat here has been stilled, you should return to the Crossroads. Thork would like to speak to you.\n\nFarewell, friend.", objectives = "Report to Thork at the Crossroads in the Northern Barrens.", completion = "Hello <name>. I have heard of your deeds from Darsok. You are a valuable <class> of the Horde, indeed." }
WordHunterWoW_QuestEN[29096] = { title = "Mor'shan Caravan Pick-Up", description = "Rocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.", objectives = "Speak to Rocco Whipshank and ride north with the Mor'shan Caravan." }
WordHunterWoW_QuestEN[29097] = { title = "Mor'shan Caravan Rescue", description = "TBDYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "TBDTBDYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29098] = { title = "Demon Seed", description = "TBDYou will receive:", objectives = "TBDTBDYou will receive:" }
WordHunterWoW_QuestEN[29099] = { title = "Mor'shan Caravan Delivery", description = "TBDYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "TBDTBDYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29100] = { title = "Bwemba's Spirit", description = "Dese be troublin' times for us Darkspear.  Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we can.  But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn da people.  But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI gonna bind my spirit wit' ya.  When ya get to Stranglethorn, I be able to aid ya.", objectives = "Warn the people of Stranglethorn and find the other Darkspear emissary.", progress = "Dis won't be no easy task, <name>.", completion = "Dere ya have it, <name>.  It look like we gonna lead an assault on da Gurubashi in Zul'Gurub.\n\nDese be dire times for us Darkspear.  But dey be even more dire for da Zandalar.  Dey goin' too far.\n\nYa been good to Bwemba, hopefully ya gonna continue to help out all of Stranglethorn.\n\nSpirits be wit' ya, <name>." }
WordHunterWoW_QuestEN[29101] = { title = "Punting Season", description = "Baby turtles are sweet, even if they can be somewhat bitey.\n\n<Mylune holds up a bandaged finger.>\n\nBut they're so slow with their tiny little legs, they can't escape the fire creatures who are attacking Hyjal!\n\n<Mylune claps her hands together.>\n\nPLEASE save them, {name}! Pick up the wee turtles and punt them into the water of the Ashen Lake. Don't worry about the kicking, they have hard shells.\n\nThey also have hard teeth, so don't pick them up by the mouth.", objectives = "Punt 5 Children of Tortolla into water.", completion = "<Mylune's voice echoes in your head, along with an unwanted image of playful kittens.>\n\nYou saved the wee turtles, <name>! I hope you gently, lovingly kicked them as hard as you possibly could." }
WordHunterWoW_QuestEN[29102] = { title = "To Fort Livingston", description = "Da first place we check gonna be da place most likely to be attacked first.  You call it Fort Livingston.\n\nFort Livingston be surrounded by troll ruins... It make for an easy target.\n\nMaybe we find da emissary dere.  Hopefully it ain't too late.", objectives = "Head to Fort Livingston in Northern Stranglethorn Vale to find the Darkspear emissary.", completion = "Another Darkspear emissary passed through some time ago telling us to be on our guard.\n\nHe mentioned some other trolls may show up, but not in spirit form, and not escorted by a <race> <class>." }
WordHunterWoW_QuestEN[29103] = { title = "Serpents and Poison", description = "Because of the emissary's warning we were able to gather more adventurers to help defend.  But we thought we were going to be fighting trolls.\n\nInstead we found ourselves overwhelmed by serpents!\n\nThey seem to have come from everywhere.  We are barely able to hold on, and I only suspect it's going to get worse.\n\nHelp us and eliminate the serpents and perhaps your troll friend here can use some magic to cure the poisoned.", objectives = "Kill Jungle Serpents and inspect the poisoned adventurers to allow Bwemba to heal them.", progress = "It doesn't look like there is an end to these serpents.", completion = "Thanks for the help, <name>.  These serpents, there doesn't appear to be an end to them." }
WordHunterWoW_QuestEN[29104] = { title = "Spirits Are With Us", description = "Dere was somethin' not right about dem serpents, {name}.  Dere was a trace of some bad mojo in da poison an' dat don't happen naturally.\n\nDa bonfire in da middle of da camp, we can use dat to perform a ritual.\n\nWhatever be makin' dese serpents attack, dey probably still watchin' over dem.\n\nDa only problem, {name}, is dat I only be here in spirit form.  I need you to be my hands.  I need you to go to da fire an' prepare it for me.  Den I'll handle da rest.", objectives = "Prepare the bonfire in Fort Livingston for Bwemba's ritual.", completion = "Venoxis... Dis can't be good, <name>." }
WordHunterWoW_QuestEN[29105] = { title = "Nesingwary Will Know", description = "Great, just what we need, the Gurubashi on the rampage using serpents to lead the charge.  Well at least we know that much.\n\nIt's probably a safe bet that the hunters at Nesingwary's Expedition have some insight into this.  If they don't they at least know how to fight the serpents.\n\nHead there and let them know what you saw here.  Let them know that the trolls are using serpents as their weapon.", objectives = "Warn the hunters at Nesingwary's Expedition in Northern Stranglethorn Vale.", completion = "We know all about the serpents, <name>.  But there is something else out there lurking...  The jungle has come to life, <class>!" }
WordHunterWoW_QuestEN[29106] = { title = "The Biggest Diamond Ever!", description = "I heard that Magni Bronzebeard, who used to be the king of Ironforge, turned into a giant diamond! Is that true? How does someone just turn into a diamond? Maybe you have to be a king and that's why no one's done it before.\n\nCan we go see him? He should be in the part of Ironforge called Old Ironforge underneath the High Seat.", objectives = "Take your Human Orphan into Old Ironforge, beneath the High Seat. Make sure to call for him if he is not present when you arrive.", progress = "I've never met a king before.", completion = "So King Magni turned into a diamond then had to go on a quest? That's neat.\n\nI wish I could turn into a diamond, then no one could hurt me. I could even buy a castle for everyone in the orphanage!" }
WordHunterWoW_QuestEN[29107] = { title = "Malfurion Has Returned!", description = "I heard that Malfurion Stormrage came back from the Emerald Dream. I don't know where that is, but it sounds like it's really far away.\n\nAnyway, he's supposed to be at the top of the Temple of the Moon in Darnassus with the High Priestess. D'you think we could go meet him? He's got to be the most powerful druid in the history of Azeroth!", objectives = "Take your Human Orphan to meet Malfurion Stormrage in the Temple of the Moon in Darnassus. If your orphan is not present when you arrive, call for him.", progress = "Do you think I could be a druid one day?", completion = "That was the best! Did you see when Malfurion cast those wings on me? The other orphans are going to be sorry they missed out on this trip!" }
WordHunterWoW_QuestEN[29108] = { title = "Mor'shan Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[29109] = { title = "Mor'shan Caravan Pick-Up", description = "The battle in Ashenvale rages on without relent. Our forces at the Mor'shan Ramparts are in desperate need of reinforcements and supplies.\n\nWe have a major shipment of medicines and food headed north, and I need a capable {class} like you to guard it.\n\nRocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.", objectives = "Speak to Rocco Whipshank and ride north with the Mor'shan Caravan.", progress = "Mor'shan Ramparts is in dire need of supplies. Speak to Rocco Whipshank at the northern-most point of the Crossroads. He should be waiting for you by the side of the road.", completion = "This is terrible news! <name>, at least you arrived safely." }
WordHunterWoW_QuestEN[29110] = { title = "Mor'shan Caravan Rescue", description = "They took Balgor and the caravan supplies from our very doorstep!\n\nThose supplies are vital for our victory against the Alliance in Ashenvale, and Balgor...if anything happens to my dear little brother, I will rip every Burning Blade member to shreds myself.\n\n{name}, I need you to rescue Balgor and the captured caravan. Follow the path just north of us, up onto Dreadmist Peak. Do not let any of those Burning Blade dogs live.", objectives = "Rescue Balgor Whipshank.", completion = "<name>, you came for me!" }
WordHunterWoW_QuestEN[29111] = { title = "Mor'shan Caravan Delivery", description = "You've managed to stir the Burning Blade's nest. Our scouts report that they are gathering for an attack.\n\nYou must complete the caravan's journey before they arrive. The supplies are packed, the kodos are rested, and I hope you don't mind but I made a few adjustments to your gun.\n\nIf you meet up with any resistance, shoot first and ask questions later.\n\nQuickly! They come! Speak to me when you are ready to leave.", objectives = "Defend the Mor'shan Caravan.", completion = "Some days we gain quarter, other days we are beaten back behind our walls. Every day, we bury more of our brothers and sisters.\n\n<Kadrak pauses and takes a deep breath.>\n\nNot only have the supplies you brought strengthened our troops, but your heroic deeds have inspired them as well. Thank you, <class>." }
WordHunterWoW_QuestEN[29112] = { title = "Demon Seed", description = "Listen {name}, we can't leave quite yet. I managed to overhear their plans while they were preparing for the ritual sacrifice.\n\nThey're planning to use a powerful artifact called the Demon Seed to launch a full scale attack on the Horde. They're keeping it under close guard over in that cave.\n\nIf you can get your hands on the Demon Seed, we should take it to my sister Nagala. She'll know what to do with it.", objectives = "Obtain the Demon Seed.", progress = "What did you find at the top of the mountain?", completion = "<name>, you're back! Balgor made it down before you, and he's already eaten two bowls of raptor stew. Considering that his appetite hasn't suffered, I'm sure he will be fit to travel in no time.\n\nI'll make sure that this artifact is taken care of. You've done us a great service today." }
WordHunterWoW_QuestEN[29114] = { title = "Track the Tracker", description = "We've been fending off serpents for days now, {name}.  But the serpents are nothing compared to what else is out in that jungle.\n\nWe hunters are being hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer headed off to the east, perhaps you can find them there.", objectives = "Find Grent Direhammer in Northern Stranglethorn Vale.", completion = "Shhh...." }
WordHunterWoW_QuestEN[29115] = { title = "The Hunter's Revenge", description = "The beast that's been hunting us... I've been hunting it.\n\nWe call him Mauti.  He's a clever one.  But he made a grave mistake when he killed my brother.  Now that mistake is going to cost him.  Ol' Direhammer has got his scent.\n\nI've noticed him roaming just above Kurzen's Compound.  If we act fast, we can take him down.\n\nAre you ready, {name}?", objectives = "Give Grent Direhammer the closure he needs by killing Mauti." }
WordHunterWoW_QuestEN[29116] = { title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "Find where Mauti has taken Grent Direhammer.", progress = "Don't be underestimating Mauti, she be a smart panther, <name>.", completion = "We be here... Da hunter, he be in da cave.  Da beast... Sometin' ain't right about her..." }
WordHunterWoW_QuestEN[29117] = { title = "Let's Go Fly a Kite", description = "The other day, when some of us were out with the matron, I saw a gnome pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time.\n\nI think the gnome's name was Craggle Wobbletop or something like that. If we can find him, could we get some kites and fly them together? I saw him walking around the canals outside the Trade District.", objectives = "Purchase a Dragon Kite Two-Pack from Craggle Wobbletop in Stormwind and then use it to fly kites with your Human Orphan. If your orphan is not present, call for him.", progress = "I thought for sure I was going to have to save all my money for like a million years to get a kite!", completion = "Thanks for the kite, <name>. Every time I fly it, I'll remember the day you gave it to me!" }
WordHunterWoW_QuestEN[29118] = { title = "Follow That Cat", description = "The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "Find where Mauti has taken Grent Direhammer.", completion = "We be here... Da hunter, he be in da cave.  Da beast... Sometin' ain't right about her..." }
WordHunterWoW_QuestEN[29119] = { title = "You Scream, I Scream...", description = "There's a brand new ice cream shop in Stormwind, and it's not just any old ice cream either. This ice cream is made by mages! You don't think I'm going to be hungry fifteen minutes after eating it, do you?\n\nI bet it tastes really good. Let's go try it!\n\nI heard some of the other kids talking about it, and they were saying the store is called The Cone of Cold and it's over near the Blue Recluse in the Mage Quarter.", objectives = "Purchase ice cream at The Cone of Cold and then share it with your orphan.", progress = "Ice cream is my favorite.", completion = "Do you think the apprentices mind freezing all that ice cream? I wish I got to make ice cream at school. That would make lessons a lot more fun, don't you think?" }
WordHunterWoW_QuestEN[29120] = { title = "Mauti", description = "I got da feeling dat somethin' ain't right wit' dat panther, {name}.  It ain't natural.  I gonna need to perform some rituals over da body.  Put Mauti down, an' den let's see what we can find out, {name}.", objectives = "Bring Bwemba to the remains of Mauti.", progress = "Mauti, she got some powerful mojo, <name>.", completion = "High Priestess Kilnara be behind dis abomination.  Dis ain't looking good.  We should see to da dwarf and then make our way to see what other trouble be going on." }
WordHunterWoW_QuestEN[29121] = { title = "Bury Me With Me Boots...", description = "Ah... It's you, {name}.  Mauti... He's dead?  Then my brother has been avenged.  I've only one request from ya... This scamp here, he's been pawing at me bare feet.  No dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.", objectives = "Collect Grent Direhammer's boots.", progress = "Do ya have me boots?  Grant a dwarf his last request will ya?", completion = "Th-thank ye, lad.\n\nPappy...?\n\n\nIs that...\n\n\n\nyou...\n\n\n\n\n..." }
WordHunterWoW_QuestEN[29122] = { title = "Echoes of Nemesis", description = "<Mylune's voice sings like a melody in your head.>\n\nRemember that awful fire turtle, Nemesis, from the Firelands? He's dead now (yay!) but echoes of him keep trying to break through to Mount Hyjal.\n\nGo to the shores of the Ashen Lake and speak with my friend Tooga. Let him know you're ready to fight an echo of Nemesis, and the turtles will draw him into this world. Then you can hit him! Hard!\n\nHide inside of Tooga's shell if he starts to erupt.", objectives = "Speak with Tooga to summon and kill Nemesis. Stand under Tooga's shell to protect you from Nemesis' Molten Fury.", completion = "Hooray! It just goes to show you, when a turtle puts his mind to something -\n\n<Mylune is distracted by a butterfly and never finishes her thought.>" }
WordHunterWoW_QuestEN[29123] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "Kill any 6 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, <name>. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive." }
WordHunterWoW_QuestEN[29124] = { title = "Warn the Rebel Camp", description = "Dis death ain't be in vain, {name}.  We figure out dat Kilnara be on da prowl.  Tings don't look good.\n\nWe better check out da Rebel Camp to da north.  Maybe we find my contact dere.", objectives = "Make your way to the Rebel Camp.", completion = "First we had snakes, then we had panthers, now we have trolls.\n\nIt's good that you're here, we could use all the help we can get." }
WordHunterWoW_QuestEN[29125] = { title = "Between the Trees", description = "Spirit fragments of Malorne - seen to us mortals as ghostly white deer - still frolic through these forests. While Malorne is no longer with us, these pieces of his spirit may be of use to us.\n\nTravel east and walk among the trees. If you are able to get close enough to one of the spirit fragments, it will bestow its power to you.\n\nOh, and take this staff. You may need it later.", objectives = "Catch three Spirits of Malorne by walking close to them.", completion = "<Immediately after touching the final spirit of Malorne, you hear Matoclaw's voice.>\n\nWell done, <name>. With the horns of Malorne on our side, we stand a chance against one of the Firelands' most difficult foes: Galenges." }
WordHunterWoW_QuestEN[29126] = { title = "The Power of Malorne", description = "<Matoclaw's voice continues.>\n\nThe portal that opened up to our east is guarded by a powerful flamewaker by the name of Galenges. We will need all of Malorne's help in defeating him.\n\nDo you remember the staff that I gave you? Place it in the pile of ash in front of the portal. Then pray that Malorne comes to your aid.", objectives = "Use the Guardian's Staff to summon and defeat Galenges.", completion = "Galenges has fallen, the unbreakable is broken... but our work is not done." }
WordHunterWoW_QuestEN[29127] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "Kill any 8 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, <name>. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive." }
WordHunterWoW_QuestEN[29128] = { title = "The Protectors of Hyjal", description = "We need to place pressure on the assault camp at Sethria's Roost. Ragnaros' minions are using this area as a point to push their battlefront beyond the bounds of Hyjal. I'm putting you in charge of a small squad to deal with them.\n\nI have selected an elite group of fighters to assist you. Travel to Sethria's Roost. Your compatriots have been instructed to meet you once you arrive. Then put an end to the elementals' assault.", objectives = "Slay 6 Fiery Behemoths or Seething Pyrelords.", completion = "A job well done, soldier. While our mission in the Firelands is critical, we must not forget about the well-being of Hyjal.\n\nSpeak with my brother again tomorrow, and he will have another squad prepared for you." }
WordHunterWoW_QuestEN[29129] = { title = "A Legendary Engagement", description = "A pleasure, {class}.\n\n<Ziradormi smiles.>\n\nIt was kind of you to arrive so quickly.\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would counsel you not to take this invitation lightly. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once.\n\nSpeak to me when you are ready and I shall personally deliver you.", objectives = "Speak to Anachronos in the Caverns of Time.", completion = "It is no whimsical dalliance that brings you here, mortal.\n\nMuster every fiber of your courage for what you are about to behold." }
WordHunterWoW_QuestEN[29131] = { title = "Defend the Rebel Camp", description = "We are in trouble here, {name}.  Your troll friend has been through here and warned us that things were going to get serious, but I didn't think it would be this bad.\n\nWe are doing our best to hold off these trolls.  But any help you can offer would greatly help.", objectives = "Help defend the Rebel Camp for three minutes.", progress = "There is no end to these trolls, <name>.", completion = "Thanks for giving us a bit of a breather, <name>.\n\nLike I said before, your troll friend was here for a small amount of time.  He warned us and then left.\n\nJames Stillair helped get him to his next destination, maybe he can help you out.\n\nGood luck out there, <name>." }
WordHunterWoW_QuestEN[29132] = { title = "A Legendary Engagement", description = "I expected that I would find you here, {class}. But then, we of the bronze flight have somewhat of an advantage when it comes to such things.\n\n<Coridormi smiles.>\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would counsel you not to take this invitation lightly, {name}. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once.\n\nSpeak to me when you are ready and I shall personally deliver you.", objectives = "Speak to Anachronos in the Caverns of Time.", completion = "It is no whimsical dalliance that brings you here, mortal.\n\nMuster every fiber of your courage for what you are about to behold." }
WordHunterWoW_QuestEN[29133] = { title = "To the Digsite", description = "The other Darkspear emissary was here briefly.  He was eager to get to the next location and warn them.   I sent him on a flight to the Explorers' League Digsite in the Cape of Stranglethorn.  I hope he wasn't too late.\n\nI will give you use of one of my gryphons, a direct flight there.\n\nTalk to me when you are ready to go, {name}.", objectives = "Head to the Explorers' League Digsite in Southern Stranglethorn Vale.", completion = "Dis don't look very good, <name>." }
WordHunterWoW_QuestEN[29134] = { title = "A Wrinkle in Time", description = "Listen carefully, {class}, for though we are only beginning, time already grows short and the consequences of our failure are unfathomable.\n\nAn event in the recent past has been obscured from my vision by the most powerful of magics. Its impact, however, has not.\n\nIf action is not taken to change the course of this timeline's future, the outcome is clear.\n\nBrace yourself, mortal, and behold the future of Azeroth.", objectives = "Speak to Anachronos in the Caverns of Time to witness the future of Azeroth.", progress = "Witness the undoing of our world, <class>.", completion = "Now, <race>, you know the reasoning behind your summons." }
WordHunterWoW_QuestEN[29135] = { title = "All-Seeing Eye", description = "I perceive the questions that burn within your mind and I must confess that I share in your uncertainty... a rare position for one such as I, and a most unsettling one.\n\nAs I scour time to find traces of this obscured event, you must aid me in the creation of an Eye, both to test your worthiness, and to provide an essential tool in the unraveling of this mystery.\n\nVenture into the Plane of Fire, {class}, and gather Eternal Embers. Bring them to me with Sands of Time and I will create the Eye.", objectives = "Collect 25 Eternal Embers from The Firelands and 3 Sands of Time.", progress = "Well, <class>?\n\nHave you acquired the necessary materials?", completion = "You have done well, friend.\n\nBe still as I weave ancient magics to create the Timeless Eye." }
WordHunterWoW_QuestEN[29137] = { title = "Breach in the Defenses", description = "Lava worms are bursting through the ground behind our lines, breaking our formations and allowing elementals to slip through. You'll find them scattered throughout our entire front to the north, and upon the Ashen Fields further out.\n\nStomp them back into their holes.", objectives = "Kill 5 Lava Bursters.", completion = "We're grateful for your support. Your presence on the battlefield gives us the time we need to refortify. Your efforts make all the difference." }
WordHunterWoW_QuestEN[29138] = { title = "Burn Victims", description = "We have warriors out in the field who are falling wounded, and many of our druids are too busy fighting to give them proper aid. I need you to go to the north, towards the Ashen Fields, and tend their wounds at least enough that they can make it back to safety.\n\nIf you haven't any bandages or healing spells, I had Rayne put together this salve, which should prove sufficient to get them on their feet.", objectives = "Heal 8 Wounded Hyjal Defenders.", completion = "I saw several of our warriors make it back to safety shortly after you departed. It seems your efforts were quite effective. Thank you." }
WordHunterWoW_QuestEN[29139] = { title = "Aggressive Growth", description = "Our warriors are doing everything they can to hold back the elementals, but their numbers are endless. We need to do something to slow down the assault.\n\nFind some suitable patches of dirt or ash out on the Ashen Fields to our north and plant these seeds. They will grow deadly vines that may slow down our enemies a bit. It's not much, but every bit helps.", objectives = "Plant 5 Smothervine Seeds in the Ash Piles in the Ashen Fields.", completion = "We will win this battle. Whatever it takes, we will not let these elementals back into Hyjal." }
WordHunterWoW_QuestEN[29140] = { title = "Under the Skylord's Gaze", description = "This is the wrong choice. Accept the quest, \"The Warden's Charge.\" Those quests are more fleshed out.", objectives = "This is the wrong choice. Accept the quest, \"The Warden's Charge.\" Those quests are more fleshed out." }
WordHunterWoW_QuestEN[29141] = { title = "The Harder They Fall", description = "Molten Behemoths have joined the elementals upon the battlefield. They are crushing our front lines. I need you to halt their momentum.\n\nYou'll find the beasts slow and clumsy. They can easily be outmaneuvered, but they will pack a devastating punch if they hit you. Be nimble, {class}.", objectives = "Kill 3 Molten Behemoths.", completion = "The elementals shall grow to fear you." }
WordHunterWoW_QuestEN[29142] = { title = "Traitors Return", description = "The Druids of the Flame assault our front line, {name}.\n\nThese vile creatures have turned their backs on Elune's teachings and worship instead the Fire Lord, Ragnaros. Twisted by his insane power, they desire nothing more than to bury us in ash.\n\nWe must counter their attack immediately!", objectives = "Kill 3 Druids of the Flame.", completion = "Good. Our enemies now know that our strength is to be feared." }
WordHunterWoW_QuestEN[29143] = { title = "Wisp Away", description = "The fire elementals are pouring out of portals on the far side of the Ashen Fields. We need someone to close them. Cut off some of their reinforcements.\n\nBanishing these kinds of elemental magics is something our wisps are perfectly suited for. One will come with you. Lead it to a portal and keep it alive until it finishes.", objectives = "Lead a Hyjal Wisp to one of the fire portals in the Ashen Fields, and protect the wisp until it closes the portal. If you lose your wisp, return to Rayne Feathersong at Malfurion's Breach.", completion = "Well done, <class>. I'll have to make more use of your skills in the future." }
WordHunterWoW_QuestEN[29144] = { title = "Clean Up in Stormwind", description = "Greetings, {class}!  Are you enjoying Hallow's End?  It seems that in response to our stink bombing the Undercity, the Horde has decided to stink bomb our city.  The stink bombs they drop are more potent than the ones used in the past.  The power of pine won't be enough.  We will need something with a little more power.  Use this Arcane Cleanser to remove the stink bombs from the city.", objectives = "Use the Arcane Cleanser to remove stink bombs around Stormwind.", progress = "Arcane magic... Works every time.", completion = "Ah, much better, <name>.  Those crones in the Undercity have no idea how powerful we have become.  Now I suppose you would like a reward." }
WordHunterWoW_QuestEN[29145] = { title = "Opening the Door", description = "You're a bit late. Hamuul, Malfurion, and some of our esteemed guests have already traveled to the invasion point, atop that cliff.\n\nOur gate to the Firelands is not yet completed, but it will be shortly. The sooner we can break through, the better.\n\nGo on! Hamuul will be expecting you.", objectives = "Report to Arch Druid Hamuul Runetotem at Nordune Ridge in Mount Hyjal.", completion = "<name>. It is good to see you again. Our gate is nearly opened." }
WordHunterWoW_QuestEN[29146] = { title = "Ridin' the Rocketway", description = "I heard that the goblins, built a crazy road in Azshara and it's just for rockets! Can you imagine? Ever since I heard about it, I've wanted to pay a visit. I asked Matron Battlewail about it and she said it's called the Rocketway!\n\nShe even told me they're working on a prototype rocket with two seats. D'you wanna go there and see if we can try it out? I bet the experimental rocket is near the Secret Lab at the south end of the Rocketway...", objectives = "Head to the Southern Rocketway Terminus in Azshara and board the Redhound Two-Seater prototype at the top of the tower.", progress = "This is gonna be the best Children's Week ever!", completion = "That was great! I even learned how to control the rocket and everything! Did you see how I saved us? I'm gonna be a rocket pilot when I grow up!" }
WordHunterWoW_QuestEN[29147] = { title = "Call the Flock", description = "Today, we have an opportunity to make another assault against one of Ragnaros' greater minions: Millagazor. However, we first need to get some assistance.\n\n<Matoclaw holds up a large, silky feather.>\n\nUse this artifact to invoke the power of Aviana. Once you have done so, travel northwest and gather some of her flock by calling out to them.\n\nOnce you have done so, we may proceed against Millagazor.", objectives = "Use your Call the Flock ability to gather 12 Alpine Songbirds, 5 Forest Owls, and 2 Goldwing Hawks.", completion = "<Amidst the chirps, hoots, and frenzied caws of your fellow birds, you hear the voice of Matoclaw speaking to you from afar.>\n\nWell done, <race>. Now that the flock is assembled, we strike." }
WordHunterWoW_QuestEN[29148] = { title = "Wings Aflame", description = "<Matoclaw's voice continues to echo within your head.>\n\nMillagazor is a creature of flame, but in many ways, he is not unlike the birds of this land. As such, Aviana's artifacts may still have the power to summon him.\n\nThe fiery portal to the west is where you will find him. Use the quill near the portal's entrance, then prepare for a fierce battle.", objectives = "Use the Quill of the Bird-Queen to summon and defeat Millagazor.", progress = "Earth-Mother guide your path.", completion = "Well done, champion." }
WordHunterWoW_QuestEN[29149] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "Kill any 7 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, <name>. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive." }
WordHunterWoW_QuestEN[29150] = { title = "Voodoo Zombies", description = "Da people... Dey all zombies, voodoo zombies!  Dis ain't gonna be pretty, {name}.\n\nYou gotta kill dem.\n\nBut once dey killed, dere is a moment where I can save dem.  Change dem back into da person dey were before.\n\nWe gotta act fast.  Da zombies don' rest.", objectives = "Rescue 10 Digsite Survivors.", completion = "We done enough, <name>.  We can't keep fighting dese zombies.  We need to figure out da source of dis voodoo.  An' I tink I know where to start..." }
WordHunterWoW_QuestEN[29151] = { title = "Bad Supplies", description = "Some of da survivors mentioned food, {name}.  We better check da food supplies.  I gotta a bad feelin' about dis.", objectives = "Check out the food supplies at the Explorers' League Digsite.", completion = "Zanzil... Dis is all startin' to come together now.  If I can find my contact den we can formulate a plan of attack.  A way to end dis madness." }
WordHunterWoW_QuestEN[29152] = { title = "Making Contact", description = "You aren't one of the zombies...\n\nA troll?  I did see one, just before the outbreak...  He warned us, told us to be on our guard... But it was too late.\n\nYour troll friend headed to Booty Bay to warn them...", objectives = "Head to Booty Bay and find Bwemba's contact.", completion = "I be tellin' Baron Revilgaz about da Zandalar threat now..." }
WordHunterWoW_QuestEN[29153] = { title = "Booty Bay's Interests", description = "Look, {name}.  You've helped out plenty so far, but that's not going to be enough.  I need these crazy trolls stopped, or at least stopped from getting into Booty Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll treat you right.", objectives = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, <name>?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it." }
WordHunterWoW_QuestEN[29154] = { title = "Booty Bay's Interests", description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted.  Or that it is at least halted at the gates of Booty Bay.\n\nI want action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll make sure you get paid.", objectives = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, <name>?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it." }
WordHunterWoW_QuestEN[29155] = { title = "A Shiny Reward", description = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your prize, {class}.", objectives = "Get your reward from a chest in the statue at Janeiro's Point.", completion = "Loot at last!" }
WordHunterWoW_QuestEN[29156] = { title = "The Troll Incursion", description = "A group of trolls, claiming to represent the Darkspear tribe, have arrived at Stormwind Harbor.  Our guards are keeping them at bay, for now.\n\nThe Stormwind Harbor Guards are seeking seasoned adventurers for help in removing the trolls from the harbor.  Report to Commander Sharp at Stormwind Harbor.", objectives = "Speak with Commander Sharp in Stormwind Harbor.", completion = "Oh good, a <class>.  Maybe you'll have better luck in dealing with these trolls.\n\nSee what they want and then try to get rid of them." }
WordHunterWoW_QuestEN[29157] = { title = "The Zandalari Menace", description = "The Zandalar trolls are on the move in Stranglethorn Vale!\n\nIf you wish to help the Darkspear trolls, report to Bwemba in Orgrimmar's Valley of Spirits.", objectives = "Speak with Bwemba in Orgrimmar's Valley of Spirits.", completion = "Greetings, <race>.  Dese be desperate times.  Da Zandalar trolls be ready to take back dere lands." }
WordHunterWoW_QuestEN[29158] = { title = "The Zandalar Representative", description = "{class}!  Heed my call.  Stranglethorn Vale has need of your assistance! Long ago you helped da Zandalar out before.  We not be forgetting your deeds.  It be because of your past help dat we come to you for help.  Come to me at the harbor.", objectives = "Meet Bwemba at Stormwind Harbor.<class>!  Heed my call. Stranglethorn Vale has need of your assistance! Long ago you helped da Zandalar out before. We not be forgetting your deeds. It be because of your past help dat we come to you for help. Come to me at the harbor." }
WordHunterWoW_QuestEN[29159] = { title = "Pyrorachnophobia", description = "We've fought hard to secure this area, but our foothold is tenuous.\n\nOur scouts report that the area around us is teeming with vicious fire spiders. They are the spawn of the vicious brood widow, Beth'tilac.\n\nHelp us hold our line by clearing the area of Cinderweb Spinners or Cinderweb Creepers. It will drive her mad to see her children slain.", objectives = "Kill 8 Cinderweb Spinners or Cinderweb Creepers.", completion = "Wonderful! The more spiders we clear out, the easier it will be to push forward." }
WordHunterWoW_QuestEN[29160] = { title = "Egg-stinction", description = "We have a real problem on our hands. Not only are the nearby spiders vicious and predatory, their numbers appear to be endless.\n\nWe need to stop the growth of their army. Cut their heads off in the egg, not on the battlefield.\n\nThe Cinderweb Spinners' eggs are laid among the stone pillars to the north. Collect 20 eggs and bring them back to me.", objectives = "Collect 20 Cinderweb Eggs from the pillars in The Widow's Clutch.", progress = "It appears the Cinderweb Spinners are the caretakers of Beth'tilac's brood.", completion = "Wonderful work, <class>. Let's hope those little spider bites aren't infectious." }
WordHunterWoW_QuestEN[29161] = { title = "Those Bears Up There", description = "Oh, raspberries! Just when we had saved the last bear cub from the treetops, the fires returned and scared them again!\n\nI don't know if you know this, but baby bears are precious and soft.\n\nGo to the Whistling Grove, far to the northwest. Climb the trees, grab the bear cubs, and chuck them - gently! - to the soft target in the center of the grove.\n\n<Without warning, Mylune suddenly smashes you against her bosom and begins sobbing.>\n\nLil' b-b-b-baby bears! Save them, {name}!", objectives = "Climb up trees in the Whistling Grove, grab stranded Hyjal Bear Cubs, and then hurl them at the Soft Target from the top of the tree. This is perfectly safe.", completion = "<Mylune's thoughts echo in your mind, along with unwanted images of flowers and squirrels.>\n\nOh, you did it, <name>! The baby bears are so happy.\n\nI'm beginning to think they've started doing this on purpose." }
WordHunterWoW_QuestEN[29162] = { title = "Nature's Blessing", description = "<Mylune's voice rings in your head, like the sound of birds chirping.>\n\nI love all creatures of the forest, even spiders, despite the fact that they are icky. But the spiders from the Firelands are worse than icky. They're burny, and don't belong here.\n\nFind the fire portal in the western Regrowth, and use the gem I gave you earlier to force it open. When a fire spider emerges, step on it! Unless it's big. Then, do something {class}y to it.\n\nOh, and use the gem if spider venom makes you woozy!", objectives = "Use the Emerald of Aessina to summon and kill Pyrachnis.", completion = "Oh NO you're covered in SPIDER-SPORCH!\n\n<Mylune hides her eyes from the sight of you.>\n\nYou're such a brave <race>. I hope you'll go into the Firelands soon and step on ALL the spiders." }
WordHunterWoW_QuestEN[29163] = { title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", objectives = "Kill any 9 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, <name>. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive." }
WordHunterWoW_QuestEN[29164] = { title = "Perfecting Your Howl", description = "The wolf ancient, Lo'gosh - or, if you prefer, Goldrinn - has many weapons available to him, but always the most underestimated is his howl. Today, we will use this weapon to summon and defeat Lylagar, one of the lieutenants of flame that lurk within the Firelands.\n\nDefeat any of the creatures of flame within the Regrowth, and then use the Fang of the Wolf while standing atop their corpse. Soon, your howl will echo across all of Kalimdor.", objectives = "Use the Fang of the Wolf atop the corpses of 10 Firelands invaders within the Regrowth.", completion = "<Matoclaw's familiar voice enters your consciousness.>\n\nYes, <name>, you are ready. Now, we strike against Lylagar." }
WordHunterWoW_QuestEN[29165] = { title = "The Call of the Pack", description = "<Matoclaw continues:>\n\nThe easternmost portal of flame is the domain of Lylagar. Stand before the portal, deliver a challenging howl, and then force the fiery beast to submit.", objectives = "Use the Fang of the Wolf to summon and defeat Lylagar.", progress = "Are you beginning to see the parallels between the Firelands and our world?", completion = "I heard your triumphant cries echo across the mountain cliffs.\n\nI also heard Lylagar utter a... different type of cry." }
WordHunterWoW_QuestEN[29166] = { title = "Supplies for the Other Side", description = "One of the biggest dangers that our druids face when fighting within the Firelands is simple dehydration. Our proveditors spend a significant amount of time preparing canteens for the troops on the other side. We do have other methods, however.\n\nIn the greener thickets to the east, you should still find some blueroot vines which have not yet burned. These plants hold a tremendous amount of water in their roots - and also provide some energy for the weary soldier.", objectives = "Obtain 7 Blueroot Vines.", progress = "Let's see... how many have you managed to gather?", completion = "I will have these packaged and shipped off right away." }
WordHunterWoW_QuestEN[29167] = { title = "The Banshee Queen", description = "Lady Sylvanas is s'posed to be one of the best warriors in the Horde, maybe that's why she is warchief!\n\nI've always wanted to meet her, <name>. Maybe an adventurer like you could get an audience with her! Would you take me to the Royal Quarter of the Undercity to meet Lady Sylvanas? It's a long way away and I bet the guards would never let me in by myself!", objectives = "Take your orphan to meet Lady Sylvanas Windrunner in the Royal Quarter of the Undercity. Call for your orphan if he is not present when you arrive.", completion = "She's just as fierce as I thought she'd be! But that ambassador sure got real mad when I started talking to Lady Sylvanas." }
WordHunterWoW_QuestEN[29168] = { title = "Secondary Targets", description = "The Gurubashi trolls have gathered their most powerful allies to rebuild Zul'Gurub and re-take Stranglethorn Vale.\n\nChief among them are two monstrous trolls: Kaulema the Mover and Mor'Lek the Dismantler, and a powerful soul-stealer called Mortaxx.\n\nThough they are not the leaders of Zul'Gurub, defeating these powerful minions will aid us greatly preventing the rise of the Gurubashi.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Kaulema the Mover, Mor'Lek the Dismantler, and Mortaxx, the Tolling Bell inside of Zul'Gurub." }
WordHunterWoW_QuestEN[29169] = { title = "The Beasts Within", description = "<Maywiki shuffles nervously.>\n\nAfter the fall of Hakkar, the city of the Gurubashi fell into disrepair, and the jungle claimed most of Zul'Gurub for its own.  Several powerful beasts now reside in the cracks and hollows of the ancient city.\n\nWe have seen the powers that the Gurubashi priests wield - they turn the very plantlife against us with their venomous concoctions.  Please, heroes, dispose of these beasts, before they become mindless agents of Jin'Do and his minions!", objectives = "Kill the Florawing Hive Queen, Tor-Tun the Slumberer, and a Lost Offspring of Ghaz'Ranka inside of Zul'Gurub." }
WordHunterWoW_QuestEN[29170] = { title = "UNUSED", description = "<Finkle's helm gives you a slight jolt.>\n\nWhat is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual!\n\nKill Corla to get past this hall!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Corla, Herald of Twilight." }
WordHunterWoW_QuestEN[29171] = { title = "UNUSED", description = "<Finkle's helm gives you a slight jolt.>\n\nWhat is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual!\n\nKill Corla to get past this hall!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Corla, Herald of Twilight." }
WordHunterWoW_QuestEN[29172] = { title = "The Beasts Within", description = "<Bloodslayer T'ara eyes you for a moment.>\n\nAfter de fall of Hakkar, de city of de Gurubashi fell into disrepair, and de jungle claimed most of Zul'Gurub for its own. Some powerful beasts now be livin' in da cracks an' hollows of de ancient city. \n\nWe seen de powers dem Gurubashi priests wield - dey turn de very plantlife against us wit' venomous concoctions. You tink you be strong? Dispose of dese beasts, before dey become mindless agents of Jin'do.", objectives = "Kill the Florawing Hive Queen, Tor-Tun the Slumberer, and a Lost Offspring of Ghaz'Ranka inside of Zul'Gurub on Heroic difficulty.", progress = "The very beasts of Zul'Gurub already turn against us.  You must hurry!", completion = "<T'ara's tusks shift slightly.  Is she smiling?>\n\nYou done well.\n\nWe gonna rest easy tonight knowin' Jin'do an' Zanzil ain't gonna bind dem powerful beasts against us." }
WordHunterWoW_QuestEN[29173] = { title = "Secondary Targets", description = "Da Gurubashi trolls gathered dere most powerful allies ta rebuild Zul'Gurub an' re-take Stranglethorn Vale.\n\nChief among dem be two monstrous trolls: Kaulema da Mover an' Mor'Lek da Dismantler, an' a powerful soul-stealer called Mortaxx.\n\nDey don't be leaders of da Gurubashi, but killing dem powerful minions gonna help us prevent da rise of da Gurubashi.", objectives = "Kill Kaulema the Mover, Mor'Lek the Dismantler, and Mortaxx, the Tolling Bell inside of Zul'Gurub on Heroic difficulty.", progress = "The most powerful underlings of the Gurubashi must be dealt with!", completion = "Jin'do's empire crumbles around him like da ruins of dis forsaken city." }
WordHunterWoW_QuestEN[29174] = { title = "Break Their Spirits", description = "A city like Zul'Gurub is similar to one of the many towering trees you see nearby.\n\nThe trunk may be thick, and the canopy vast and leafy, but without nutrients from the roots far below, the tree will wither and fall.\n\nJin'Do's army is fed largely by the actions of two minor Gurubashi trolls.  Sever these roots, and the city will fall all the easier.", objectives = "Kill Gub and the Gurubashi Master Chef inside of Zul'Gurub." }
WordHunterWoW_QuestEN[29175] = { title = "Break Their Spirits", description = "A city like Zul'Gurub be similar ta one of de many towering trees you see nearby.\n\nDe trunk may be thick, and de canopy vast and leafy, but without nutrients from de roots far below, de tree gonna wither and fall.\n\nJin'do's army be fed largely by de actions of a couple a' minor Gurubashi trolls.  Sever dem roots, and de city gonna fall.", objectives = "Kill Gub and the Gurubashi Master Chef inside of Zul'Gurub on Heroic difficulty.", progress = "You must disrupt their supply lines!", completion = "Da great Gurubashi empire begin ta wither already.\n\nIt be only a matter of time, now." }
WordHunterWoW_QuestEN[29176] = { title = "The Fallen Chieftain", description = "Matron Battlewail says that when Cairne Bloodhoof died, the Horde lost a 'voice of wisdom'. I don't know what that means, but I always wanted to meet him. Some of the other orphans even have his hoofprint.\n\nWould you take me with you to Mulgore? Our tutor says tauren bring their dead to a place called Red Rocks to honor them. We should go there and see if we can find Cairne.", objectives = "Take your orphan to Red Rocks to visit the funeral pyre of Cairne Bloodhoof. Call for your orphan if he is not present when you arrive.", progress = "I want to visit Mulgore more often.", completion = "Someday, I'm going to be a great warrior, just like Cairne or the warchief. Everyone will remember my deeds, and the ancestors will welcome my spirit too!" }
WordHunterWoW_QuestEN[29177] = { title = "Vigilance on Wings", description = "The agents of Twilight continue their assault within this pocket of the Firelands. We must not let our offensive fall! Take wing, and destroy as many of those lancers as you can!\n\nDo not forget to pick up and equip your lance first.", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Lancers by flying into them. Press the flap button to flap your mount's wings!", progress = "Our vigilance must not fall. Especially not now, in this most trying of times!", completion = "Well done, <class>. I hope you don't forget about us here in the Hatchery." }
WordHunterWoW_QuestEN[29178] = { title = "Oooh, Shinies!", description = "Come closer, <man/sweetheart>! Let ol' Griftah look at yer shiny things....\n\nHmm. Yeh, yeh, not bad, but ya can do better. Much, much better.\n\n<Griftah leans in and whispers.>\n\nThere be priceless shinies everywhere, <name>, ya just gotta know where to look! It be yer lucky day; I know a fella who can help ya find more shinies than ya can ever carry.\n\nVisit my ol' friend, Budd, near Zul'Aman and show him this here. Ya be tellin' him ol' Griftah sent ya and he'll let ya in on his new project.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Budd in the Ghostlands." }
WordHunterWoW_QuestEN[29179] = { title = "Hostile Elements", description = "The elementals continue to press on us, and I do not expect them to subside any time soon.\n\nYou'll find them pouring across the Ashen Fields to the north. Thin their ranks.", objectives = "Kill 8 Charred Soldiers or Charred Vanquishers.", completion = "Your continued efforts are appreciated, <class>. We will win this war as long as people like you stand beside us." }
WordHunterWoW_QuestEN[29180] = { title = "Promises, Promises...", description = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman. There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....\n\nOur initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.\n\nForget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve Budd's Map of Zul'Aman from High Priest Nalorakk's terrace in Zul'Aman." }
WordHunterWoW_QuestEN[29181] = { title = "Druids of the Talon", description = "Skylord Omnuron and his Druids of the Talon have been a fearsome force for us back in Hyjal. I know that they prefer the familiar skies of that battlefield, but the time may come when we need them here nonetheless.\n\nIf you get your hands on enough marks, you should appeal to Omnuron that his druids should be on the main front. Omnuron watches out for his own, but he also understands the importance of this effort.", objectives = "Obtain 150 Marks of the World Tree.", progress = "It is good to see you again.", completion = "I see. I can't say I'm eager to bring my flock to the Firelands, but I knew it would become necessary at some point.\n\nWe will be there, <class>. Thank you for carrying the message." }
WordHunterWoW_QuestEN[29182] = { title = "Flight of the Storm Crows", description = "Many of the Druids of the Talon have made their way to the Molten Front, at your beckoning. You should go to Skylord Omnuron at Malfurion's Breach and see how their wings are faring in those burning skies.", objectives = "Speak to Skylord Omnuron at Malfurion's Breach.", completion = "These skies are indeed oppressive, but we've been able to navigate them for the most part.\n\nWe may need your help to secure additional landing territory past the Furnace. I will call for you when we are ready." }
WordHunterWoW_QuestEN[29183] = { title = "Daily Tier 2 Heroic (Nth)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29184] = { title = "X Marks... Your Doom!", description = "How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you.\n\nSucceed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you.\n\nThere are yet a few portions of my map that require further exploration before our excavation can be initiated....You will receive:", objectives = "Visit Halazzi's Chamber, Jan'alai's Platform, and Akil'zon's Platform in Zul'Aman." }
WordHunterWoW_QuestEN[29185] = { title = "Daily Tier 2 Heroic (1st)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29186] = { title = "The Hex Lord's Fetish", description = "Dis new warlord of da Amani, he be nothin' but an overgrown brute without da protection of a strong witch doctor and he has just dat.\n\nDa new warlord's ally be Hex Lord Malacrass, da most feared witch doctor to walk among da Amani in decades. Without da hex lord's say-so, Daakara won't be submitting his people to da control of da Zandalari.\n\nDefeat Hex Lord Malacrass, bring me his favorite fetish, and I be seein' that ya get a fittin' reward.", objectives = "Obtain the Hex Lord's Fetish from Hex Lord Malacrass in Zul'Aman.", progress = "Have ya eliminated Hex Lord Malacrass?", completion = "So dis is da fetish of da mighty Malacrass? It be a good addition to my collection, <name>. And now, I believe, rewards be in order." }
WordHunterWoW_QuestEN[29187] = { title = "Tuskin' Raiders", description = "'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya.\n\nBudd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks.\n\nMy skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. \n\nBring me back 10 troll tusks, eh mon?You will receive:", objectives = "Collect 10 Forest Troll Tusks from the trolls in Zul'Aman." }
WordHunterWoW_QuestEN[29188] = { title = "A Troll Among Trolls", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman. He still be alive too - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!You will receive:", objectives = "Speak to Zungam in Zul'Aman.Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman. He still be alive too - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!You will receive:" }
WordHunterWoW_QuestEN[29189] = { title = "Wicked Webs", description = "Some of our scouts have not reported back for duty. We fear they have succumbed to the deadly spiders in the vicinity.\n\nHope may not be lost, however. The spiders often wrap up their live prey in cocoons for later consumption.\n\nGo search the pillars to the north for cocooned victims. You may yet be able to save some of our brethren.", objectives = "Free 8 victims out of Cinderweb Cocoons.", completion = "Our lost allies have already made it back. They are shaken, but alive. Thank you for rescuing them." }
WordHunterWoW_QuestEN[29190] = { title = "Let's Go Fly a Kite", description = "The other day, when some of us were out with the matron, I saw a goblin pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time.\n\nI think the goblin's name was Blax Bottlerocket or something. If we can find him, could we get some kites and fly them together? I saw him pushing his cart around the Drag.", objectives = "Purchase a Dragon Kite Two-Pack from Blax Bottlerocket in Orgrimmar's Drag then use it to fly kites with your Orcish Orphan. If your orphan is not present, call for him.", progress = "I thought for sure I was going to have to save all my money for like a million years to get a kite!", completion = "Thanks for the kite, <name>. Every time I fly it, I'll remember the day you gave it to me!" }
WordHunterWoW_QuestEN[29191] = { title = "You Scream, I Scream...", description = "There's a brand new ice cream shop in Orgrimmar, and it's not just any old ice cream either. This ice cream is made by a crazy goblin mage! You don't think it's going to disappear if I don't finish it in fifteen minutes, do you?\n\nI bet it tastes really good. Let's go try it!\n\nI heard some of the other kids talking about it, and they were saying the store is called the Cone of Cold and it's in the Orgrimmar Embassy.", objectives = "Purchase ice cream at Cone of Cold and then share it with your orphan.", progress = "Ice cream is my favorite.", completion = "I think that's the first time I've ever seen a goblin making food that didn't involve a big, noisy machine with a lot of smoke. Maybe more people would like their food if they just made it like normal people... or like mages! That ice cream was so good!" }
WordHunterWoW_QuestEN[29192] = { title = "The Wardens are Watching", description = "We must tread carefully, {class}. Fandral's Druids of the Flame practice their fiery magic beyond the pillars to the north.\n\nI need you to capture one of those druids alive for questioning. We must seize every opportunity to learn of their plans.\n\nOne of my wardens will accompany you. Follow her instructions if you wish to survive.", objectives = "Attack a Druid of the Flame to weaken it, then lure it into your Shadow Warden's trap.", completion = "I am impressed, <class>. Your deeds will be remembered among the Shadow Wardens." }
WordHunterWoW_QuestEN[29193] = { title = "On a Wing and a Prayer", description = "Time well spent, mortal.\n\nWhile you struggled in the Plane of Fire, my watchers and I were able to determine when and, most importantly, where our vision was obscured.\n\nWe discovered that the shroud was placed over the Nexus, far to the north in the realm of the blue dragonflight.\n\nI have attuned the Timeless Eye to show you the occurrences that remain hidden to us here.\n\nBring it to Coldarra at once and seek out a place suitable for its activation.\n\nGo, child. Time is of the essence...", objectives = "Bring the Timeless Eye to Coldarra.", completion = "You are either a fool, or a lunatic. Regardless, you must return from whence you have come.\n\nWere you spotted by another of my brood, you would already have met your end." }
WordHunterWoW_QuestEN[29194] = { title = "Through a Glass, Darkly", description = "<Tarecgosa listens as you explain your presence in Coldarra.>\n\nYour tale rings true, {class}. Much has changed since the death of Malygos - little of it for the better.\n\nI know of the device you carry, and I recognize Anachronos' magic in its creation. There is but one place in all of Coldarra that would allow this Timeless Eye to be used discreetly.\n\nYou will require my assistance if you hope to succeed. Speak with me again inside the Nexus and you shall have it.", objectives = "Look into the Eye of Eternity at the Nether Vortex in the Nexus.\n\nMeet Tarecgosa inside the Nexus where she will escort you to the rift.", progress = "Tell me, mortal, what did you see?", completion = "This cannot be, <class>!\n\nIt must be some kind of trick!" }
WordHunterWoW_QuestEN[29195] = { title = "A Ritual of Flame", description = "We appear to have everything under control. Our invasion portal to the Firelands will be opened momentarily, and the elementals have not put up much fight.\n\nAssist our druids by dispatching the last few of these elementals. Then, once the gate has been opened, we can make our move.", objectives = "Fight the waves of Charred Invaders on Nordune Ridge until the portal is opened.", progress = "Continue the fight, <name>. Only a short while longer now.", completion = "Leyara... she lives. I sense Fandral's hand at play here..." }
WordHunterWoW_QuestEN[29196] = { title = "To the Sanctuary!", description = "We should not worry about this \"Druid of the Flame\" for the time being. We must be concerned with the continuance of our operation.\n\nReturn to Matoclaw at the Sanctuary of Malorne. If Ragnaros was prepared for our arrival, then I anticipate that his forces will launch a counterattack soon.", objectives = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "What happened up there? I saw fire and... never mind, you can tell me later. We have other, more immediate matters to attend to." }
WordHunterWoW_QuestEN[29197] = { title = "Caught Unawares", description = "Our invasion plan looks to have backfired. Several of our birds have already reported in, speaking of fires breaking out across the vales of central Hyjal.\n\nNow, many of our druids are stranded out in the field, unprepared for such a large-scale attack. Thisalee was near Ashen Lake, and several others were out in the Regrowth, to the northeast.\n\nGo, {name}! Find them, and make sure that they do not succumb to this backdraft!", objectives = "Help Elderlimb, Thisalee Crow, Tholo Whitehoof and Anren Shadowseeker escape the flames.", progress = "There isn't time! Move!", completion = "<name>! You're back!\n\nThey've pushed us back to the Sanctuary. We are vastly outnumbered. At this rate, the Guardians of Hyjal stand little chance of survival.\n\nI'm glad you're here with us." }
WordHunterWoW_QuestEN[29198] = { title = "The Sanctuary Must Not Fall", description = "Malfurion is working on a miracle for us. He believes that, in this time of peril, he can resurrect Malorne to protect the Sanctuary. I have faith in him.\n\nIn the meantime, we need to hold this perimeter. Stand by, and make sure no harm befalls my fellow arch druid.", objectives = "Stand by Malfurion as he resurrects Malorne.", progress = "Please, <name>. Focus on the task at hand.", completion = "Malorne's strength alone may have just saved Kalimdor. To imagine, Malorne has returned today, after so long an absence...\n\n<Malfurion surveys the area.>\n\nWe've taken heavy losses. Though the immediate threat is no longer present, our forces will need time to heal, and to put out any remaining fires here in Hyjal.\n\nOur attack on the Firelands will have to wait." }
WordHunterWoW_QuestEN[29199] = { title = "Calling for Reinforcements", description = "We suffered heavy losses during the backdraft after our invasion attempt. Our second attempt cannot fail.\n\nWe need reinforcements before we attempt another invasion. Please, {name}, work with Matoclaw to obtain enough resources to afford reinforcements. Then, we take our second and final stab at the Firelands.", objectives = "Obtain 20 Marks of the World Tree.", progress = "The sooner we can break through our invasion portal, the better.", completion = "Excellent work. I will send for our reinforcements right away." }
WordHunterWoW_QuestEN[29200] = { title = "Leyara", description = "Before we depart, {name}, I have another matter to which you should attend.\n\nA Druid of the Flame has been spotted in the ruins to the northwest. I suspect it is the same one that attacked us at the portal several days ago. Now would be an ideal time to see what it is that she truly wants... and if necessary, dispose of her.\n\nSee to this flame druid, then we can continue on our planned course.", objectives = "Find Leyara, the Druid of the Flame.", progress = "Hamuul really shouldn't worry about the affairs of a lone druid. The hour of our attack is at hand!", completion = "<Matoclaw listens intently as you explain what happened.>\n\n<She is visibly distressed.>\n\nYou deviated from our plan, <name>. Our attack was supposed to happen today! All this preparation... how will we succeed without the aid of Hamuul?" }
WordHunterWoW_QuestEN[29201] = { title = "Through the Gates of Hell", description = "There will be time to mourn for Hamuul later. His is the first of many inevitable casualties in this war.... but our attack cannot wait, nor should the momentum we have gained over the last several days be wasted.\n\nThe portal atop Nordune Ridge is now open. Our reinforcements are prepared, and they await only my order to pass through the portal.\n\nWe will meet again on the other side of the portal. Once there, we shall ensure that our foothold is secure.", objectives = "Pass through the portal atop Nordune Ridge and help Malfurion secure a foothold on the Molten Front.", completion = "Very well done, <class>. We've managed to take a foothold in our enemy's realm without their notice. Our armies are moving through to establish a front as we speak.\n\nWe have a long, brutal war ahead of us. It is my hope that you'll be around to help us see it through." }
WordHunterWoW_QuestEN[29202] = { title = "The Fate of Runetotem", description = "I apologize for speaking curtly with you earlier. The loss of Hamuul was shocking to me, and difficult to cope with.\n\nThey brought in his body while you were away. He is alive, but - as you might imagine - he is very, very badly burned.\n\nThe scars are deep. He may not live.\n\nI have arranged for some of our finest healers to attend to him. If it is not too much to ask, would you speak with Dorda'en Nightweaver? He and his fellow attendants may need your help.", objectives = "Speak with Dorda'en Nightweaver at the Sanctuary of Malorne in Mount Hyjal.", completion = "Yes, Hamuul lives. You can visit him in the tent behind me, but please, be careful. He is in a fragile condition, and we are doing everything in our power just to keep him alive and comfortable.\n\nWhoever did this to the Arch Druid showed no mercy. I hope that you are someday able to return the favor." }
WordHunterWoW_QuestEN[29203] = { title = "Into the Depths", description = "Leyara has been spotted in the Igneous Depths. A group of Shadow Wardens has cornered her.\n\nGo there immediately. I will join you as soon as I make one necessary preparation.", objectives = "Kill Leyara.", completion = "Leyara's tale is a tragic one. It pains me that it came to this.\n\nStaghelm must be stopped, before he drags anyone else down with him." }
WordHunterWoW_QuestEN[29204] = { title = "The Warden's Charge", description = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise.\n\nI've assigned her a large number of our men, but her chances of success would be greatly increased if you join her cause. It's your decision, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "If you want to help the Wardens attack the Forlorn Spire, seek out Captain Saynna Stormrunner in northeastern Ashen Fields." }
WordHunterWoW_QuestEN[29205] = { title = "The Forlorn Spire", description = "Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you'll find her at the bottom of the ramp leading up towards that rise.\n\nGo there and escort one of her druids to the tower with any forces that she can spare. You'll have quite a fight ahead of you - make sure the druid lives to see the end of it or they'll not be able to seize the tower.", objectives = "Protect one of the druids attempting to take the Forlorn Spire.", completion = "Well done, <class>. This should prove a good staging ground for pushing further into enemy territory.\n\nI sense Druids of the Flame nearby. Perhaps we shall have some sport of them as well." }
WordHunterWoW_QuestEN[29206] = { title = "Into the Fire", description = "Skylord Omnuron and his druids are seeking to push through the Furnace to our northwest. They've been able to fly over the dangers, but they really need someone on the ground to help them secure the territory past the fire... someone like you.\n\nIf you want to aid the Druids of the Talon, wait for one of Omnuron's Windcallers to start pushing through the fire, stay close to him, and keep him safe from any attackers within the flames.", objectives = "Escort a Windcaller through the Furnace and secure the entrance to the Molten Flow.", completion = "Glad to see the Skylord was finally able to get someone capable through without wings. Our flight has been of little use to us in these confined spaces and amidst the thermals beyond this ridge.\n\nLooks like we'll have to resort to more conventional tactics. You game?" }
WordHunterWoW_QuestEN[29208] = { title = "An Old Friend", description = "", objectives = "Among all of the raptors in Mandokir's domain, one familiar face stands out. She's grown a little bigger, and she's earned a few scars, but the lashtail hatchling is still here.\n\nShe recognizes you. Her father has finally come back to save her." }
WordHunterWoW_QuestEN[29209] = { title = "Into the Fiery Depths", description = "One of our druids moved ahead into the Igneous Depths in pursuit of a Druid of the Flame.\n\nGo to her. Help her.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Theresa Barkskin in the Igneous Depths." }
WordHunterWoW_QuestEN[29210] = { title = "Enduring the Heat", description = "Shalis has gone with one of our druids to stop a Druid of the Flame that is performing a summoning ritual in the Igneous Depths, below us. They have been tasked with killing the druid, but I need you to stop the ritual.\n\nYou'll find the entrance to the cavern east of the Magma Springs. Once inside, you'll see 8 blue runes spread throughout the cavern. You can use these runes to protect you from the fiery creatures, but you need to stamp all of them out to end the ritual. You will need to be swift.", objectives = "Find your way to the Igneous Depths, then destroy all 8 of the blue runes within.", progress = "You must destroy the runes! Hurry!", completion = "Well done!\n\nThey've been attempting to start rituals of this sort all over the Molten Front, but we've been able to thwart them every time so far. Hopefully you will be present in the future to help us keep up that trend." }
WordHunterWoW_QuestEN[29211] = { title = "Solar Core Destruction", description = "The fight has taken us to Fandral's doorstep. His druids are channeling energies of the Firelands into a vessel called the Solar Core.\n\nShould this vessel detonate on Azeroth, none of us will have a home to return to.\n\nWe need to strike at the Solar Core now, while it is still vulnerable. You can find the infernal device to the northeast.", objectives = "Detonate the Solar Core.", completion = "It is destroyed? Good. I doubt this will deter Fandral for long, but we must gain every advantage we can muster." }
WordHunterWoW_QuestEN[29212] = { title = "Fire Hawk Down", description = "PH - Shoot down 5 fire hawks.", objectives = "PH - Shoot down 5 fire hawks.PH - Shoot down 5 fire hawks." }
WordHunterWoW_QuestEN[29213] = { title = "How's the Hunter Holding Up?", description = "Tings ain't looking good.  Dat panther was under some powerful magic.  We better check on dat hunter an' see how he be doin'.", objectives = "Check on Grent Direhammer.", completion = "Oh... Me spine...  Brother, is that you?" }
WordHunterWoW_QuestEN[29214] = { title = "The Shadow Wardens", description = "The Shadow Wardens are back in the Regrowth. I know that they take the loss of Fandral from their custody very seriously, so it wouldn't take much prodding to bring them to the Firelands to hunt the Druids of the Flame, and perhaps aid us otherwise in the process.\n\nShould you come upon enough marks, you should seek out Captain Saynna Stormrunner at the Sanctuary of Malorne and secure her aid.", objectives = "Obtain 150 Marks of the World Tree.", progress = "Yes, <class>?", completion = "I see. It is time for us to join the hunt in the Firelands then. My sisters will be with you, <class>." }
WordHunterWoW_QuestEN[29215] = { title = "The Hunt Begins", description = "The Shadow Wardens have joined the fight at the Molten Front, on your request. You should find Captain Saynna Stormrunner and see to it that they've found a way to best apply their skills.", objectives = "Speak to Captain Saynna Stormrunner at Malfurion's Breach.", completion = "Hello, <name>. It's good to see you again.\n\nYou needn't worry. We've settled in quite well. I've dispatched several of my wardens to assist in hunting down the Druids of the Flame, and I've drawn assault plans for the Forlorn Spire. When the time is right, perhaps you will join us there." }
WordHunterWoW_QuestEN[29216] = { title = "Malfurion's Breach", description = "", objectives = "Secure a foothold in the Firelands." }
WordHunterWoW_QuestEN[29217] = { title = "The Captive Scouts", description = "After we arrived, I dispatched my scouts to learn more about da Zandalari presence here in Zul'Aman. Many returned with useful information, but four still be missin'. If we do not act quickly, da new warlord's lieutenants will offer dem as sacrifices in honor of da Zandalari emissaries.\n\nFind my scouts, {name}, and free dem before da priests offer dem as sacrifices!", objectives = "Free the captive scouts: Hazlek, Bakkalzu, Norkani, and Kasha. They are being held captive by the Amani high priests.", completion = "I hadn't expected to see dem again, <name>. The information dey gathered will be da key to destroying Zandalari influence in Zul'Aman. Ya have my thanks and da thanks of my scouts." }
WordHunterWoW_QuestEN[29218] = { title = "Marks of the World Tree", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[29219] = { title = "Bwemba's Spirit", description = "Dese be troublin' times for us Darkspear.  Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we can.  But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn da people.  But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI gonna bind my spirit wit' ya.  When ya get to Stranglethorn, I be able to aid ya.", objectives = "Warn the people of Stranglethorn and find the other Darkspear emissary.", progress = "Dis won't be no easy task, <name>.", completion = "Dere ya have it, <name>.  It look like we gonna lead an assault on da Gurubashi in Zul'Gurub.\n\nDese be dire times for us Darkspear.  But dey be even more dire for da Zandalar.  Dey goin' too far.\n\nYa been good to Bwemba, hopefully ya gonna continue to help out all of Stranglethorn.\n\nSpirits be wit' ya, <name>." }
WordHunterWoW_QuestEN[29220] = { title = "To Bambala", description = "Da first place we check gonna be da place most likely to be attacked first, Bambala.\n\nBambala be dangerously close to da troll city Zul'Gurub... It make for an easy target.\n\nMaybe we find da emissary dere.  Hopefully it ain't too late.", objectives = "Head to Bambala in Northern Stranglethorn Vale to find the Darkspear emissary.", completion = "It seems da spirits be wit' you, <class>." }
WordHunterWoW_QuestEN[29221] = { title = "Serpents and Poison", description = "Da warning helped, {name}.\n\nWe gathered more Headhunters to help defend.  But Headhunters... Dey not used to hunting heads on serpents.  So we soon be overwhelmed.  Dese serpents, dey seem to come from everywhere.  An' it probably only gonna get worse.\n\nHelp us and kill da serpents and have Bwemba use her mojo to cure da ones dat are sick from poison.", objectives = "Kill Jungle Serpents and inspect the poisoned Headhunters to allow Bwemba to heal them.", completion = "Thanks for da help, <name>.  Dese serpents, dere don't seem to be an end to dem." }
WordHunterWoW_QuestEN[29222] = { title = "Spirits Are With Us", description = "Dere was something about da way da serpents attacked, {name}.  Something unnatural...  Even da poison had a hint of some bad mojo.\n\nDere be a shrine near here wit' a bonfire.  We can use dat to perform a ritual.\n\nWhatever be makin' dese serpents attack, dey probably still watchin' over dem.\n\nDa only problem, {name}, is dat I only be here in spirit form.  I need you to be my hands.  I need you to go to da fire an' prepare it for me.  Den I'll handle da rest.", objectives = "Prepare the bonfire in front of the serpent shrine near Bambala for Bwemba's ritual.", completion = "Venoxis... Dis can't be good, <name>." }
WordHunterWoW_QuestEN[29223] = { title = "Nesingwary Will Know", description = "So da Gurubashi be on da rampage an' dey usin' serpents to lead da charge.\n\nYou know who be good at keepin' da animal population in check?  Da hunters at Nesingwary's Expedition.\n\nHead over dere and see how dey doin'.  See if dey know a good way to get rid of da serpents.\n\nIf dey don't know, den you gotta at least warn dem dat dese serpents, it ain't all natural.", objectives = "Warn the hunters at Nesingwary's Expedition in Northern Stranglethorn Vale.", completion = "We know all about the serpents, <name>.  But there is something else out there lurking...  The jungle has come to life, <class>!" }
WordHunterWoW_QuestEN[29225] = { title = "Actionable Intelligence", description = "<Tarecgosa listens intently as you describe your vision.>\n\nImpossible!\n\nNot even Arygos would dare to go to such lengths.\n\nI do not question your integrity, {class}, but you must understand - your mortal mind can easily be deceived.\n\nRegardless, Kalecgos must be informed of these events. You must travel to Nordrassil at once to seek him out.\n\nI shall remain here to conceal the evidence of our activities. Speak of this to no one else!", objectives = "Speak to Kalecgos at Nordrassil in Mount Hyjal.", completion = "<Kalecgos listens to your account of recent events.>\n\nIt was wise of Tarecgosa to send you to me, <class>.\n\nThough your vision in the Nexus was almost certainly an elaborate illusion, it would be irresponsible of me not to investigate it." }
WordHunterWoW_QuestEN[29226] = { title = "Track the Tracker", description = "We've been fending off serpents for days now, {name}.  But the serpents are nothing compared to what else is out in that jungle.\n\nWe hunters are being hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer headed off to the east, perhaps you can find them there.", objectives = "Find Grent Direhammer in Northern Stranglethorn Vale.", completion = "Shhh...." }
WordHunterWoW_QuestEN[29227] = { title = "The Hunter's Revenge", description = "The beast that's been hunting us... I've been hunting it.\n\nWe call him Mauti.  He's a clever one.  But he made a grave mistake when he killed my brother.  Now that mistake is going to cost him.  Ol' Direhammer has got his scent.\n\nI've noticed him roaming just above Kurzen's Compound.  If we act fast, we can take him down.\n\nAre you ready, {name}?", objectives = "Give Grent Direhammer the closure he needs by killing Mauti." }
WordHunterWoW_QuestEN[29228] = { title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "Find where Mauti has taken Grent Direhammer.", completion = "We be here... Da hunter, he be in da cave.  Da beast... Sometin' ain't right about her..." }
WordHunterWoW_QuestEN[29229] = { title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", objectives = "Find where Mauti has taken Grent Direhammer.", completion = "We be here... Da hunter, he be in da cave.  Da beast... Sometin' ain't right about her..." }
WordHunterWoW_QuestEN[29230] = { title = "Mauti", description = "I got da feeling dat somethin' ain't right wit' dat panther, {name}.  It ain't natural.  I gonna need to perform some rituals over da body.  Put Mauti down, an' den let's see what we can find out, {name}.", objectives = "Bring Bwemba to the remains of Mauti.", completion = "High Priestess Kilnara be behind dis abomination.  Dis ain't looking good.  We should see to da dwarf and then make our way to see what other trouble be going on." }
WordHunterWoW_QuestEN[29231] = { title = "How's the Hunter Holding Up?", description = "Tings ain't looking good.  Dat panther was under some powerful magic.  We better check on dat hunter an' see how he be doin'.", objectives = "Check on Grent Direhammer.", completion = "Oh... Me spine...  Brother, is that you?" }
WordHunterWoW_QuestEN[29232] = { title = "Bury Me With Me Boots...", description = "Ah... It's you, {name}.  Mauti... He's dead?  Then my brother has been avenged.  I've only one request from ya... This scamp here, he's been pawing at me bare feet.  No dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.", objectives = "Collect Grent Direhammer's boots.", progress = "Do ya have me boots?  Grant a dwarf his last request will ya?", completion = "Th-thank ye, lad.\n\nPappy...?\n\n\nIs that...\n\n\n\nyou...\n\n\n\n\n..." }
WordHunterWoW_QuestEN[29233] = { title = "Warn Grom'gol", description = "Dis death ain't be in vain, {name}.  We figure out dat Kilnara be on da prowl.  Tings don't look good.\n\nWe better check out Grom'gol Base Camp to da west.  Maybe we find my contact dere.", objectives = "Make your way to Grom'gol Base Camp.", completion = "First we had snakes, then we had panthers, now we have blood-thirsty trolls.\n\nIt's good that you're here, <class>, there are plenty of trolls to kill." }
WordHunterWoW_QuestEN[29234] = { title = "Delegation", description = "I am duty-bound to look into your claims immediately, {race}, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the World Tree's branch.", objectives = "Recover the Branch of Nordrassil from the Firelands.", progress = "Were you able to recover Nordrassil's Bough, <class>?", completion = "Nordrassil's Bough...\n\nYou have done well, mortal." }
WordHunterWoW_QuestEN[29235] = { title = "Defend Grom'gol", description = "I hope you like to fight, {name}.  Your troll friend has been through here and warned us that the Gurubashi were on the rampage.  I never thought the battle would be this glorious though.\n\nCome, join in our fight and let's show these Gurubashi trolls the might of the Horde!", objectives = "Help defend Grom'gol Base Camp for three minutes.", progress = "There is no end to these trolls, <name>.  I like it that way!", completion = "These trolls just keep coming, <name>.  I love it!\n\nLike I said before, the Darkspear emissary was here for a small amount of time.  He warned us and then left.\n\nThysta, our Wind Rider Master, helped get him to his next destination, maybe she can help you out.\n\nHappy hunting, <name>." }
WordHunterWoW_QuestEN[29236] = { title = "To Hardwrench Hideaway", description = "Bwemba...  Is that you?\n\nYour contact was here.  He was eager to get to the next location and warn them.  And really, who could blame him?  I gave him use of a wyvern to reach the goblins of Hardwrench Hideaway, in the Cape of Stranglethorn.\n\nI will give you use of one of my wyverns to reach Hardwrench.\n\nTalk to me when you are ready to go, {name}.", objectives = "Head to Hardwrench Hideaway in The Cape of Stranglethorn.", progress = "We better hury, <name>.", completion = "Dis don't look very good, <name>." }
WordHunterWoW_QuestEN[29237] = { title = "Voodoo Zombies", description = "Da people... Dey all zombies, voodoo zombies!  Dis ain't gonna be pretty, {name}.\n\nYou gotta kill dem.\n\nBut once dey killed, dere is a moment where I can save dem.  Change dem back into da person dey were before.\n\nWe gotta act fast.  Da zombies don' rest.", objectives = "Rescue 10 Hideaway Survivors.", progress = "Dis be a rush job wit da voodoo.  But it still be dangerous.", completion = "We done enough, <name>.  We can't keep fighting dese zombies.  We need to figure out da source of dis voodoo.  An' I tink I know where to start..." }
WordHunterWoW_QuestEN[29238] = { title = "Bad Supplies", description = "Some of da survivors mentioned food, {name}.  We better check da food supplies.  I gotta a bad feelin' about dis.", objectives = "Check out the food preparation area in Hardwrench Hideaway.", completion = "Zanzil... Dis is all startin' to come together now.  If I can find my contact den we can formulate a plan of attack.  A way to end dis madness." }
WordHunterWoW_QuestEN[29239] = { title = "Nordrassil's Bough", description = "Much has transpired since last we spoke.\n\nI have taken it upon myself to visit the Nexus and recover Anachronos's artifact, but not before using it for myself. Now I too have witnessed that which you have seen.\n\nBefore discussing the matter further, allow me to express my gratitude to you for your assistance, both here and in the Plane of Fire.", objectives = "Collect the Branch of Nordrassil at Amber Ledge in Borean Tundra.", completion = "Nordrassil's Bough is now joined with the Timeless Eye.\n\nEven a battleworn hero such as yourself cannot help but be humbled by such a gift." }
WordHunterWoW_QuestEN[29240] = { title = "Emergency Extraction", description = "Now, back to the matter at hand...\n\nI am convinced that the vision in the Nexus is one of Deathwing's illusions designed to bring conflict into our flight at a very fragile time.\n\nThe Worldbreaker would only be strengthened were we to fall to infighting.\n\nStill, a gnawing sense of unease tempts me to take a path of caution.\n\nIt would be wise for me to take Tarecgosa and withdraw until the time of choosing.", objectives = "Accompany Kalecgos to Coldarra.\n\nSpeak to him when you are ready.", completion = "She is dying, <name>.\n\nI have... failed her." }
WordHunterWoW_QuestEN[29241] = { title = "Break the Godbreaker", description = "<Bloodslayer Zala points at the temple in the distance.>\n\nWhen Jin'do was last ripped from dis world, he survived as a shade, weak and broken, in da spirit world.\n\nBut Jin'do always had power over da spirits.  One by one, he broke dem to his will, and wit' each soul devoured, Jin'do got closer ta' rippin' a hole through to dis world.\n\nTa be here now...\n\nDa spirits be wit' us, we must end Jin'do.", objectives = "Kill Jin'do the Godbreaker inside of Zul'Gurub on Heroic difficulty.", completion = "<Bloodslayer Zala clutches her hand to her chest.>\n\nIt be done, then.  Spilling da blood of our brothers be a grim task.  Da city of da Gurubashi has seen only death an' hatred for years.\n\nMaybe it be time for da jungle ta retake Zul'Gurub, an' wash da scent of death from dis place.\n\nBlood and honor, champion, to da Siame-Quashi you will always be known as \"Bloodslayer\"." }
WordHunterWoW_QuestEN[29242] = { title = "Putting a Price on Priceless", description = "Listen, friend.  I don't know you, and you don't know me.  But as long as we're both here, there's something Revilgaz wanted me to mention.\n\nMaybe you're taking a stroll through this troll-infested jungle-ocalypse.  Maybe you happen to find a priceless troll artifact or two.  Maybe you bring it back to me and I accidentally leave behind a little present for ya'.\n\nIf you must know, it's for a project.  And no, you can't ask what the project is.", objectives = "Investigate the Cache of Madness and find the Mysterious Gurubashi Bijou.", progress = "So, did you find a thing?  Because my pants are getting pretty heavy from all of this treasure of yours I'm holding onto.", completion = "What have you got there?\n\nA crazy-looking snake idol?  What am I supposed to do with this?  Hit someone over the head with it and steal something that's actually valuable?\n\nThis thing is worthless!\n\n<Briney tosses the Bijou into the water.>\n\nThanks for the \"help,\" I guess.  Here's your \"reward.\"\n\nIdiot." }
WordHunterWoW_QuestEN[29243] = { title = "Strike at the Heart", description = "One of Ragnaros' Lieutenants has shown itself at Ragnaros' Reach.  It is time to strike. Captain Saynna has requested that you be there to help see the fight through.\n\nWitherbranch and some others will have joined the battle by the time you arrive.  You should make haste to the northwest and find them.", objectives = "Kill the Lieutenant of Flame.", completion = "Very well done, <name>! This should delay them significantly.\n\nIf we keep this up, we can easily push the fight back to Ragnaros himself." }
WordHunterWoW_QuestEN[29244] = { title = "A Lieutenant of Flame", description = "Captain Saynna has requested your presence at Ragnaros' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him.\n\nMake your way there as soon as you're able.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to Captain Saynna Stormrunner at Ragnaros' Reach." }
WordHunterWoW_QuestEN[29245] = { title = "The Mysterious Seed", description = "A small, dried acorn has fallen out of the Flame Druid's robe.\n\nWhy would a Druid of the Flame be carrying it around?\n\nPerhaps someone at Malfurion's Breach would like to see it.", objectives = "Take the Acorn to Avrilla at Malfurion's Breach in the Firelands.\n\nProvided item:", completion = "Fascinating! It appears to be an acorn!" }
WordHunterWoW_QuestEN[29246] = { title = "Relieving the Pain", description = "The Arch Druid has an immense tolerance for pain. I've treated burn victims that spend twenty-two hours a day screaming in pain, and their burns weren't even half as bad as what Hamuul has suffered.\n\nNevertheless, I can sense that he is in greater discomfort than normal today. Bring me the hearts of the large fire elementals to the southeast. I can use them to prepare a soothing salve for our patient.", objectives = "Obtain 4 Flame-Wreathed Hearts from Seething Firelords.", progress = "These hearts will give us exactly what Hamuul needs to rest.", completion = "I must get to work preparing the salve immediately. These reagents lose their efficacy by the minute.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[29247] = { title = "Treating the Wounds", description = "We have an ample supply of medical supplies here at the Sanctuary, but we mustn't lose sight of the fact that we are at war. Hamuul isn't the only person who has need of bandages.\n\nThe fiery behemoths that roam Sethria's Roost wear flame-resistant wrappings that will serve Hamuul as ably as any bandage. Bring me those wrappings, and I will prepare them for use on the Arch Druid.", objectives = "Obtain 4 Sulfur-Laced Wrappings from Fiery Behemoths in Sethria's Roost.", progress = "There are some who say that the sulfur in those wrappings has curative properties. Personally, I am unconvinced, but I am willing to endure the smell on the off-chance that it does.", completion = "Many thanks, <class>.\n\nYou do the war effort a favor. Burn victims have a notorious appetite for bandages, and Hamuul is no exception." }
WordHunterWoW_QuestEN[29248] = { title = "Releasing the Pressure", description = "Having been burned so badly, Arch Druid Hamuul is suffering from edema - swelling of the body's tissues. It takes a great deal of his attendants' effort to keep his swelling down enough for him to breathe.\n\nNormally, to reduce this swelling, we make cuts in his flesh, but he is weak, {name}. I cannot cut him today. I need your help.\n\nFlamewaker scales will aid with the swelling, but you need a lot of them.", objectives = "Obtain 100 Flamewaker Scales.", progress = "Do you have the scales? I hesitate to cut the Arch Druid again, but we must relieve the swelling somehow.", completion = "You are a compassionate <race>. With this many scales, we won't have to cut him again for another day, at least. Perhaps two." }
WordHunterWoW_QuestEN[29249] = { title = "Planting Season", description = "The acorn seems to be unharmed.\n\n<Avrilla shrugs.>\n\nNo point in beating around the bush. Let's plant it and see what comes out.\n\nLuckily for you, we brought some leftover soil with us to help establish our base.\n\nYou'll find the soil at the graveyard directly east.", objectives = "Plant the Acorn in the Un'Goro Soil at Malfurion's Breach.", completion = "A red flower pops its head out of the soil." }
WordHunterWoW_QuestEN[29250] = { title = "Making Contact", description = "You aren't one of the zombies...\n\nA troll?  I did see one, just before the outbreak...  He warned us, told us to be on our guard... But it was too late.\n\nYour troll friend headed to Booty Bay to warn them...", objectives = "Head to Booty Bay and find Bwemba's contact.", completion = "I be tellin' Baron Revilgaz about da Zandalar threat now..." }
WordHunterWoW_QuestEN[29251] = { title = "Booty Bay's Interests", description = "Look, {name}.  You've helped out plenty so far, but that's not going to be enough.  I need these crazy trolls stopped, or at least stopped from getting into Booty Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll treat you right.", objectives = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, <name>?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it." }
WordHunterWoW_QuestEN[29252] = { title = "Booty Bay's Interests", description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted.  Or that it is at least halted at the gates of Booty Bay.\n\nI want action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll make sure you get paid.", objectives = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, <name>?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it." }
WordHunterWoW_QuestEN[29253] = { title = "A Shiny Reward", description = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your prize, {class}.", objectives = "Get your reward from a chest in the statue at Janeiro's Point.", completion = "Loot at last!" }
WordHunterWoW_QuestEN[29254] = { title = "Little Lasher", description = "The little red flower wiggles its tendrils happily. It seems to like you!\n\nPerhaps Avrilla would like to see what grew out of the acorn.", objectives = "Bring the Crimson Lasher to Avrilla.", completion = "Oh my! Who's your little friend? It followed you, you say?" }
WordHunterWoW_QuestEN[29255] = { title = "Embergris", description = "The Crimson Lasher has developed some cracking blisters on its vines. Without treatment, this condition could be life threatening.\n\nLuckily, the Charred Soldiers and Charred Vanquishers in the area produce a waxy substance known as Embergris, which should soothe the Lasher's pain.\n\nBring me some of this substance, and kill those nasty fire elementals while you're at it.", objectives = "Retrieve 5 Embergris from Charred Soldiers and Charred Vanquishers.", progress = "The Lasher is growing quite quickly.", completion = "It isn't very pleasant-smelling, but this should fix the Lasher right up." }
WordHunterWoW_QuestEN[29256] = { title = "Eat Your Heart Out", description = "Hello <name>. Checking in on your Fire Lasher?\n\nHe seems quite hungry, but no mixture of fertilizer or plant growth seems to interest him.\n\nSome plants are carnivorous, and I'd like to test this rather unconventional theory.\n\nWould you retrieve some Lava Burster Hearts for me? The Lava Bursters frequent the fields to the north.You will receive:", objectives = "Retrieve 3 Lava Burster Hearts." }
WordHunterWoW_QuestEN[29257] = { title = "Steal Magmolias", description = "We've discovered a new species of flower growing in the Magma Springs to the north. Amazingly, they sustain themselves in pure molten lava!\n\nPlease go and retrieve some specimens for me. I'm sure that further study of these plants will shed some light on your little friend here.\n\nSpeaking of which, he seems quite eager to go with you. Let's hope he behaves himself.", objectives = "Collect 8 Magmolias from the Magma Springs to the north.", progress = "Fascinating! The more time I spend in the Firelands, the more I see there is an ecosystem at work here.", completion = "Thank you, <name>. I will start analyzing these samples at once." }
WordHunterWoW_QuestEN[29258] = { title = "Meteorite Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[29259] = { title = "Hide and Seek", description = "Good to see you again, <name>. Your Lasher here has invented a new game - hide and seek!\n\nIt looks like he wants to play with you.\n\nWait until he hides himself, then look for him somewhere in the camp.\n\nIf he's too well-hidden, I've created this special mist that will reveal his general direction. Don't tell him I gave it ito you.", objectives = "Find and expose the hidden Fire Lasher in Malfurion's Breach." }
WordHunterWoW_QuestEN[29260] = { title = "Enlighten Us", description = "Your Fire Lasher has been quite restless. He keeps visiting the old burnt tree, though for what reason, I cannot fathom.\n\n<name>, would you do me a favor and take your Fire Lasher to the tree? Perhaps you can figure out what interests him so much about that place.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Fire Lasher to the burnt tree." }
WordHunterWoW_QuestEN[29261] = { title = "Zul'Aman Voodoo", description = "The maker of this voodoo pile perished in the process.  Perhaps if you could finish it, the spirits would protect you instead....", objectives = "The maker of this voodoo pile perished in the process.  Perhaps if you could finish it, the spirits would protect you instead....", progress = "The maker of this voodoo pile perished in the process.  Perhaps if you could finish it, the spirits would protect you instead....", completion = "The tablet provides the final incantation to bind the voodoo pile's magic to you and your party!" }
WordHunterWoW_QuestEN[29262] = { title = "Zul'Gurub Voodoo", description = "This potent pile of voodoo witchery emanates strong mojo...", objectives = "This potent pile of voodoo witchery emanates strong mojo...", progress = "This potent pile of voodoo witchery emanates strong mojo...", completion = "As you slip the tablet into the voodoo pile, a primal screech shatters the silence." }
WordHunterWoW_QuestEN[29263] = { title = "A Bitter Pill", description = "As far as I'm concerned, there's no problem that can't be solved with bombs. And if a bomb doesn't solve your problem on the first try... use a bigger bomb.\n\nSo there's this big worm that's been eating people near the lava pools up north. Search for breath bubbles to find it. Attack it until it prepares to bite, then place this bomb down in front of it. Then sit back and watch the fireworks.\n\nHmm... there was one other thing I wanted to say... oh yeah! Don't get eaten.", objectives = "Find the Subterranean Magma Worm's breath bubbles, then defeat it by making it swallow the Bitter Pill.", completion = "Ah knew Ricket's bombs'd come in handy. Twas just a matter ah findin' somethin' big enough to explode." }
WordHunterWoW_QuestEN[29264] = { title = "Flamewakers of the Molten Flow", description = "Of all Ragnaros' minions, the flamewakers appear to be the most devoted. Most of them dwell within this cave, preparing for another attack. Our foothold may be strong, but we will not tolerate any surprise attacks from these worms.\n\nNo, we will strike first.\n\nTear them apart, {name}.", objectives = "Slay 8 Flamewakers within the Molten Flow.", completion = "I like the way you work, <name>." }
WordHunterWoW_QuestEN[29265] = { title = "Fire Flowers", description = "My fellow druid, Choluna, has asked us to collect any specimens of plant life that we might find here in the Firelands...\n\n...I don't know whose idea it was to bring scholars to a warfront.\n\nNevertheless, you will already be in the cave - killing things - so be on the lookout for anything growing out of the ground.", objectives = "Obtain 5 Luciferns.", progress = "They could be growing anywhere. Keep your eyes open.", completion = "These things never cease to amaze me. Whether they're actual plants, or just delicate stone formations, the fact that they can grow in such hostile conditions astounds me.\n\nI'll have these sent to Avrilla for analysis right away." }
WordHunterWoW_QuestEN[29266] = { title = "DEPRECATED Zul'Gurub Voodoo (NYI)", description = "", objectives = "" }
WordHunterWoW_QuestEN[29267] = { title = "Some Good Will Come", description = "So much violence, so much death.  Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it.\n\nWill you take a pause from the violence to help care for a panther cub?", objectives = "The panther cub looks at you with a look in its eyes that says, \"Will you be my new dad?\"" }
WordHunterWoW_QuestEN[29268] = { title = "Some Good Will Come", description = "So much violence, so much death.  Brothers have died, a mother has died, and now a panther cub will die if there is no one to take care of it.\n\nWill you take a break from the violence and help care for a panther cub?", objectives = "Care for the panther cub, after all, you did kill it's mother.", completion = "The panther cub looks at you with a look in its eyes that says, \"Will you be my new dad?\"" }
WordHunterWoW_QuestEN[29269] = { title = "At One", description = "I was charged with her protection, yet it was she who sacrificed herself for my sake.\n\nI cannot bear to lose her, {name}. I must make a solemn request of you.\n\nNever has a mortal borne the essence of a true dragon, but with your permission I would make an exception.\n\nPlease, while there is life in her, will you allow me to bind Tarecgosa to you? ", objectives = "Speak to Kalecgos to agree to his proposition.", completion = "I am grateful, <name>.\n\nWere you not present, or had you refused, Tarecgosa would be lost to me." }
WordHunterWoW_QuestEN[29270] = { title = "Time Grows Short", description = "Tarecgosa is bound to you, {name}, but only temporarily. An aspect's power is required to permanently seal her essence.\n\nMalygos's successor will not be chosen until Azeroth's moons next eclipse, and the bond you share will not last until then.\n\nFortunately, there is a way to buy us the time we need. Powerful elements exist that can extend the ritual's effects. Some of these can be found in the Plane of Fire, with which you've become familiar.\n\nObtain them, {class}, and sustain Tarecgosa until the eclipse.", objectives = "Collect 1000 Seething Cinders from the Firelands.", progress = "It is good to see you again, <name>.", completion = "I sense that Tarecgosa is still with you.\n\nYou have done well, my friend." }
WordHunterWoW_QuestEN[29271] = { title = "Bound for Warmer Weather", description = "We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to General Taldris Moonfall at Malfurion's Breach on the Molten Front.We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29272] = { title = "Need... Water... Badly...", description = "Need... water... badly...", objectives = "Bring Anren Shadowseeker to the entrance of the Molten Front.", completion = "You! You're the one who saved Anren. My best friend, Anren.\n\nWe got separated in that cave. I didn't know what to do without Anren.\n\nYou are a resourceful <class>. We may call upon you later to assist us in our reconnaissance missions. With your help, Anren and I might no longer face the terrifying risk of being separated from one another." }
WordHunterWoW_QuestEN[29273] = { title = "How Hot", description = "The fire hawks of Fireplume Peak can withstand incredible temperatures. While you'll often find them circling the skies above, they're also known to swim in molten lava.\n\nIsn't that right, Anren?\n\nWe'd like to know just how hot that lava can get. Fireplume Peak has three large lava pools. Use this to measure the temperature of each.", objectives = "Use Tholo's Thermometer to measure the temperature of the three large lava pools on Fireplume Peak.", completion = "These results will go a long way to help us understand the fire hawks, and - more importantly - Alysrazor, their new, fiery queen.\n\nTholo and I are thankful that you've been helping us out." }
WordHunterWoW_QuestEN[29274] = { title = "Hounds of Shannox", description = "On the Firelands' largest island, our troops have been having trouble against Shannox, the flamewaker hunter. Not only does he have impeccable aim, but he keeps trained hounds that give our troops no end of trouble.\n\nTholo, in all his wisdom, thinks it would be a good idea to study the biology of these hounds. I, of course, agree with Tholo.\n\nYou will find several hounds in the Molten Flow, beneath the Furnace. We will need their ashes to study.", objectives = "Obtain 6 small piles of Houndbone Ash.", progress = "Any information we can get will be instrumental in helping our men defeat Shannox.", completion = "This ash may seem indistinguishable from any other type of ash you find on this forsaken island, but trust me... you have found the right stuff.\n\nWe will have it analyzed immediately.\n\nReturn again soon. While I do enjoy spending time with Anren, we also appreciate your company, <name>." }
WordHunterWoW_QuestEN[29275] = { title = "Fandral's Methods", description = "The Druids of the Flame... an order of druids that, up until a few weeks ago, Tholo and I had never even heard of. Now, under the leadership of Fandral Staghelm, they threaten our mission's success with their mastery of fire.\n\nIt would appear that they store some supplies in the Igneous Depths, to the northeast. Perhaps, if we can get some of those supplies, we will have more luck when we take the fight to Fandral.", objectives = "Obtain a Flame Druid Staff, a Flame Druid Spellbook, a Flame Druid Reagent Pouch, and a Flame Druid Idol.", progress = "Trust me - whatever information we can gather here will go far to helping us understand the source of Fandral's powers.", completion = "Anren, look what <name> found! This is exactly what we needed!\n\nIt will take us some time to look through these supplies. For now, you have our thanks." }
WordHunterWoW_QuestEN[29276] = { title = "The Flame Spider Queen", description = "The Widow's Clutch, to the northeast, is named after Beth'tilac, the enormous queen of the flame spiders. Her webs and her poison are a nagging threat to our main offensive force.\n\nWe believe that if we study the flame spiders here on the Molten Front, we can use that information to find success against Beth'tilac. Use whatever methods you can to gather their venom and their web fluid, then return to my trusted friend Anren.", objectives = "Obtain 8 samples of Flame Venom and 8 samples of Searing Web Fluid.", progress = "Be careful with those fluids, <name>. We don't want them spilling anywhere.", completion = "You are an asset to our cause, <name>. Tholo and I thank you." }
WordHunterWoW_QuestEN[29277] = { title = "Druid Tree, Stage 3 Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[29278] = { title = "Living Obsidium", description = "Have you seen those fireballs falling out of the sky? I saw one crash in the fields to the north, and the rock that landed was made of pure Living Obsidium!\n\nI can use the material to craft ultra-sturdy heat proof armor and weapons for our troops. Can you bring me a lode?\n\nGo to the Magma Springs and touch one of the magnetic stones. Just watch where you're standing when the rain of fire hits, and gather up the rocks before they crumble from the impact.", objectives = "Retrieve 10 Obsidium Meteorites.", progress = "How's it going? Found any meteorites yet?", completion = "Fantastic! Now ah kin get ta work." }
WordHunterWoW_QuestEN[29279] = { title = "Filling the Moonwell", description = "We've constructed this moonwell, but it serves little purpose until it is filled with the sacred waters of the Well of Eternity.\n\nWith an active moonwell, we would be able to bless our food stores, and we may also be able to use the blessing to offer you some protection from fire as well.\n\nWhen you've obtained enough marks, speak to Matoclaw at the Sanctuary of Malorne. She'll be able to secure transport of the sacred waters.", objectives = "Obtain 125 Marks of the World Tree.", progress = "How can I be of aid, <name>?", completion = "Of course. I will see to it that the sacred waters are transported through the portal right away.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[29280] = { title = "Nourishing Waters", description = "I have dispatched the sacred moonwell waters to Malfurion's Breach, as you requested. Ayla is well trained in tending to them. You should return to her and see the boons she weaves for you there.", objectives = "Speak to Ayla Shadowstorm at Malfurion's Breach.", completion = "You will pleased to know that the waters arrived safely. With the moonwell filled, and the shade of the Sentinel Tree upon us, I can almost forget we're in the Firelands for moments at a time.\n\nI've spread the moonwell's blessing upon these trees and bushes. Take the fruit with you before you venture out. It is more refreshing than you can possibly imagine." }
WordHunterWoW_QuestEN[29281] = { title = "Additional Armaments", description = "These druids be lackin' the tools ta properly handle the job out 'ere. I got meself a buddy back at day ol' stag shrine through the portal though. If we were ta be gettin' reunited, we'd sure have some real toys ta use against ol' Ragboy and 'is cronies.\n\nTake some of dem mark things an' go find Matoclaw. Ask her fer Ricket. We need'r here so we can be causin' some real trouble. ", objectives = "Obtain 125 Marks of the World Tree.", progress = "Yes, <name>?", completion = "I was wondering if those two would come in handy. They've seemed quite out of place ever since they arrived.\n\nI saw Ricket around here just a moment ago. I'll gladly send her back through the portal with you. She's less likely to be blowing up any local plant life on that side of things anyway.\n\nLet's see... where is she..." }
WordHunterWoW_QuestEN[29282] = { title = "Well Armed", description = "Ricket should be at Malfurion's Breach with Damek, as you requested. I'm not sure you fully know what you're getting into with those two though.\n\nSpeaking of which, you should probably go check on them... make sure they haven't managed to blow up the Sentinel Tree itself. As long as you keep them busy with the elementals, the chances of \"accidents\" at the breach should lessen dramatically.", objectives = "Speak to Ricket at Malfurion's Breach.", completion = "Hey you! Good to see you again!\n\nI'm settled in good and fine, actually! It's good to be with good old Damek again. I never thought I'd be mixing with a dwarf so well, but he and I, we've got like minds on all the important stuff.\n\nYou go do your thing. Don't be worrying about us. If we cook up any good toys for you, we'll be sure to let ya know!" }
WordHunterWoW_QuestEN[29283] = { title = "Calling the Ancients", description = "The ancients await in Hyjal. The Firelands will prove a dangerous place for them considering their... composition, but their strength will be of great use to us if we are to face any of Ragnaros' lieutenants.\n\nGather your marks, and seek out Elderlimb at the Sanctuary of Malorne. If they are to march with us, he would be the one leading them through the portal.", objectives = "Obtain 125 Marks of the World Tree.", progress = "Greetings to you, young one.", completion = "I understand. We are prepared. We shall join the march and meet you on the far side of the portal." }
WordHunterWoW_QuestEN[29284] = { title = "Aid of the Ancients", description = "The ancients have seen the value of your wisdom, and have set root at Malfurion's Breach. You should seek out Elderlimb. I am certain he would like to hear from you.", objectives = "Speak to Elderlimb at Malfurion's Breach.", completion = "You chose a wise time to call upon us, <class>. I was concerned for our ability to stand against the elements in this realm, but the protection of the Sentinel Tree has proven far more than sufficient shelter.\n\nWe will do anything we can to aid your efforts here. Witherbranch has met with your other allies and is discussing a way to corner some of Ragnaros' lieutenants. You should speak with them when the time comes." }
WordHunterWoW_QuestEN[29285] = { title = "Alignment", description = "The time of choosing has arrived, {name}.\n\nWhile only members of the blue dragonflight may attend, Tarecgosa's binding makes your presence requisite.\n\nI must ask that you take on her form and vote on her behalf.\n\nDo not tarry. The moment of the eclipse draws near....", objectives = "Accompany Kalecgos to the blue dragon council.\n\nSpeak to Kalecgos in Coldarra when ready.", progress = "It is done, <class>.", completion = "Arygos's machinations have been undone, thanks in great part to you, <class>.\n\nAs my first act as aspect of the blue dragonflight, your bond with Tarecgosa is now made stable.\n\nThe power that once sustained that bond I now infuse into your staff.\n\nMay the Runestaff of Nordrassil serve you well!" }
WordHunterWoW_QuestEN[29286] = { title = "Druid Tree, Stage 2 Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[29287] = { title = "Peaked Interest", description = "These fire hawks are beings of fire, but they exhibit much of the same behavior that we've seen in birds back home. It makes me wonder from where they originate.\n\nBack to the point - I think we might be able to train them. Domesticate them if you will. Use them against our enemies.\n\nI'd like you to retrieve one of their eggs from the top of Fireplume Peak. If you can bring it back to me safely, I will see to the rest.", objectives = "Retrieve a Fire Hawk Egg from the top of Fireplume Peak.", progress = "Were you able to recover an egg?", completion = "This will do perfectly! Come see me again in a day or two and we'll see how things have progressed." }
WordHunterWoW_QuestEN[29288] = { title = "Starting Young", description = "Our scouts are bringing back reports of fire hawk hatchlings all over the peak... their eggs must have hatched very recently. Better yet, it seems that they're extremely docile.\n\nI know it may sound a strange and perhaps unsavory request, but if you were able to bring some of those hatchlings back to me, I might be able to train them to aid us in our war efforts.\n\nAre you willing?", objectives = "Recover 5 Fire Hawk Hatchlings.", progress = "I can't make up my mind on how to regard these creatures. They act like much like other avians, but they are very obviously native to this fiery place.\n\nI wonder why Ragnaros and his minions have not made attempts to rally them against us...", completion = "They look to have singed your gloves a bit, but I don't see any damage otherwise. Well done, <class>.\n\nCome by again within the next few days to see how the training has gone." }
WordHunterWoW_QuestEN[29289] = { title = "Mother's Malice", description = "Unsurprisingly, their matriarch has taken offense to us taking her young to train for our own uses. It's understandable... and a bit tragic actually. We are very much the villains in this exchange.\n\nNow is not the time for such thoughts. These creatures are beings of fire, and on more than one occasion, they've claimed the lives of our kin. With their matriarch angered, the danger has grown immensely.\n\nI need someone to quiet her rage, and I fear you may be the most capable.", objectives = "Defeat the Fire Hawk Matriarch." }
WordHunterWoW_QuestEN[29290] = { title = "Fire in the Skies", description = "Look at that! It's incredible! Born less than two days ago and already full grown. Sadly, I suspect their life cycle is similarly short, so we'll have to take advantage of any time we have.\n\nHis training went remarkably well. I want you to be the one to take him out and unleash him on the bulk of the enemy forces gathered near Ragnaros' keep.\n\nShow no mercy, {race}.", objectives = "Use the Trained Fire Hawk to kill 100 of the Flamewaker Salamanders, 40 of the Cinderweb Spiders, and 3 of the Molten Lords that are amassing in the Firelands.", progress = "Some of our most capable forces are poised to strike at Ragnaros himself. If these attacks go well, we may be able to give them the opportunity they need.", completion = "I take it your assault was a success! Brilliant. This could be a key moment in opening up Ragnaros' defenses." }
WordHunterWoW_QuestEN[29291] = { title = "Straight Chuting", description = "", objectives = "" }
WordHunterWoW_QuestEN[29292] = { title = "Hawk Fire", description = "", objectives = "" }
WordHunterWoW_QuestEN[29293] = { title = "Singed Wings", description = "Many of our Storm Crows have gone ahead to scout the peak and attempt to retrieve some of the fire hawk eggs, but to very little success I'm afraid. The thermals make it nearly impossible to fly safely, and the fire hawks aren't exactly friendly either.\n\nI need you to head over there and rescue any druids that you can. I've got splints, bandages, burn salves, smelling salts... anything you'll need to get them back on their feet, assuming they're still alive. Please hurry and help anyone you can find.", objectives = "Rescue 5 Injured Druids of the Talon on Fireplume Peak.", progress = "There must be more of them alive over there... it's just a matter of finding them.", completion = "Several of our brothers and sisters passed by while returning to the safety of the Sentinel Tree. You did very well out there, <name>. Thank you." }
WordHunterWoW_QuestEN[29294] = { title = "Animate Embers", description = "Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.You will receive:", objectives = "Retrieve 6 Animate Embers.Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.You will receive:" }
WordHunterWoW_QuestEN[29295] = { title = "The Bigger They Are", description = "You're not going to take on fiery behemoths wearing THAT, are you? If you aren't wearing my obsidium crafted goods, you're going to burn right up! And even if you are, you can never have enough of the good stuff.\n\nLook brother, I can craft you the best armor that gold can buy, but I need pure, unsmelted Living Obsidium first.\n\nThe Obsidium Punishers on Fireplume Peak are literally made of the stuff. Go kill them and gather their pieces.", objectives = "Collect 10 Living Obsidium from the Obsidium Punishers on Fireplume Peak.", progress = "Did you bring me the goods?", completion = "This'll do. Nice work, <name>." }
WordHunterWoW_QuestEN[29296] = { title = "Territorial Birds", description = "The fire hawks are upset by our continued presence. They're getting extremely hostile, and not just in the usual territorial ways. I worry that if we leave them unchecked, they will soon be joining the assault on our tree, and I'm not sure we're capable of handling that.\n\nGo across the way to Fireplume Peak and do what you have to to keep them in check. I'm far more concerned with our safety right now than theirs, so be decisive about it.", objectives = "Slay 5 Fire Hawks.", completion = "Well done, <name>. It's good to know I can count on you." }
WordHunterWoW_QuestEN[29297] = { title = "Bye Bye Burdy", description = "Staghelm's druids are putting up a fierce fight at Wildflame Point to the northeast.\n\nThe druids fly above us in fire crow form, then strike when we least expect it. Worst part is, they know exactly how to stay out of our reach!\n\nWe would be totally helpless, except Damek lent me his trusty harpoon. He says these weapons will fly straight and true even in this super dense air.\n\nTake the dwarf's weapon and shoot some birds out of the sky!", objectives = "Kill 3 Druids of the Flame, while in Fire Crow form, with the Burd Sticker.", completion = "Those blasted burds are dead? Good riddance!" }
WordHunterWoW_QuestEN[29298] = { title = "A Smoke-Stained Locket", description = "This locket has a few small leaf-shaped carvings etched into its face, but any other details have been rubbed away with time, or burned away with fire. It appears to be druidic in nature.\n\nMost druids pass through Moonglade during their training. If anybody can help you decipher where this locket came from, it would be Rabine Saturna of Nighthaven.", objectives = "Bring the Smoke-Stained Locket to Rabine Saturna at Nighthaven in Moonglade.", progress = "Yes, young <race>?", completion = "What have we here? A necklace? No, a locket...\n\nOh, my..." }
WordHunterWoW_QuestEN[29299] = { title = "Some Like It Hot", description = "I've been making progress in my research, {name}. Based on what we've witnessed in the local flora, it's quite possible that your Lasher also accepts superheated liquids as a principal source of nutrition.\n\nI'd like you to help me with a little experiment. The Emberspit Scorpions that inhabit the Magma Springs to the north spew out burning pools of fire during combat.\n\nTake the Lasher and observe his reaction to the scorpions' Ember Pools.", objectives = "Observe the Crimson Lasher drinking from 6 Ember Pools. Ember Pools are created by fighting Emberspit Scorpions.", completion = "Did it work? So my theory was correct?" }
WordHunterWoW_QuestEN[29302] = { title = "Unlocking the Secrets Within", description = "The initials seem to have worn off of this locket, but I can sense a power within it that suggests only one possible owner:\n\nLeyara, the Druid of the Flame.\n\nStand back, and we shall see what surprises this locket contains.", objectives = "Witness the memories stored within the Smoke-Stained Locket.", completion = "If Leyara bore witness to the War of the Shifting Sands, then it seems likely she knew Fandral - and his late son, Valstann - far more closely than any of us suspected.\n\nIt would seem that your journey does not end here, <name>." }
WordHunterWoW_QuestEN[29303] = { title = "Tragedy and Family", description = "You were insightful to bring this locket to me, {name}. I am among the few who know where Valstann's body lays.\n\nYou can find his resting site in a small graveyard, southeast of Astranaar, in Ashenvale. Bring this locket to the site, and it may unlock more memories.\n\nFarewell, {name}, and good luck on your journey.", objectives = "Bring the Smoke-Stained Locket to the Night Elf Grave near Astranaar in Ashenvale." }
WordHunterWoW_QuestEN[29304] = { title = "The Dogs of War", description = "Our forces are falling beneath an unleashed monstrosity - Charhounds from the molten depths.\n\nThese dogs fear nothing and will not stop until their lust for blood is satisfied. Our forces are barely holding them back.\n\nGo join the defenders in the Ashen Fields or in the Molten Flow. Perhaps you can make a dent in their numbers.", objectives = "Kill 5 Charhounds or Ancient Charhounds.", completion = "Good, <class>. The enemy may be tough, but you have proven today that you are tougher." }
WordHunterWoW_QuestEN[29305] = { title = "Strike at the Heart", description = "One of Ragnaros' Lieutenants has shown himself at Ragnaros' Reach, the walled area to our northeast.\n\nI hoped to send you as soon as you returned, but I suspect Witherbranch and some of our forces have already joined the fight by now. You should hurry.\n\nYou should be able to drop down the cliff wall right here and reach them quickly.", objectives = "Kill the Lieutenant of Flame.", progress = "Today we cripple their war effort.", completion = "Very well done, <name>! This should delay them significantly.\n\nIf we keep this up, we can easily push the fight back to Ragnaros himself." }
WordHunterWoW_QuestEN[29307] = { title = "Heart of Flame", description = "You are the first mortal to witness a dragon council, {name}, and among the only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home.\n\nI would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen next we meet, I will be able to suitably thank you for all that you have done.", objectives = "Empower the Runestaff of Nordrassil with 250 Smouldering Essences and obtain the Heart of Flame.", progress = "A fine day for a ceremony. Don't you think, <name>?", completion = "You have done well, <name>.\n\nNow prepare to receive a hero's reward." }
WordHunterWoW_QuestEN[29308] = { title = "Heart of Flame", description = "You are the first mortal to witness a dragon council, {name}, and among the only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's bond with you, though she will require a more... permanent home.\n\nI would have you venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen next we meet, I will be able to suitably thank you for all that you have done.", objectives = "Empower the Runestaff of Nordrassil with 250 Soul Flame Essences and obtain the Heart of Flame.", progress = "A fine day for a ceremony. Don't you think, <name>?", completion = "You have done well, <name>.\n\nNow prepare to receive a hero's reward." }
WordHunterWoW_QuestEN[29309] = { title = "The Stuff of Legends", description = "It is an honor to make your acquaintance, {race}.\n\nYour deeds echo in the ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there when you are ready.", objectives = "Speak to Hallegosa.", progress = "Behold! Dragonwrath, Tarecgosa's Rest.", completion = "Your heroic deeds will never be forgotten, <name>." }
WordHunterWoW_QuestEN[29310] = { title = "The Tipping Point", description = "On the day when Leyara attacked Hamuul, she was waiting near some ruins in Hyjal, northwest of the Regrowth. She acted strangely at the time: calm, silent, and staring off into the distance. Perhaps that location is of some importance to her.\n\nThe locket might react if brought to that location.", objectives = "Bring the Smoke-Stained Locket to the Small Gravestone at Leyara's Sorrow in Hyjal." }
WordHunterWoW_QuestEN[29311] = { title = "The Rest is History", description = "In her memories, Leyara spoke of Malfurion. The tragedies of her past - at least, in her opinion - are largely due to his actions.\n\nMalfurion must remember Leyara from before she became a Druid of the Flame. You resolve to bring the locket to him in the Firelands. Hopefully he can answer any remaining questions.", objectives = "Bring the Smoke-Stained Locket to Malfurion in the Molten Front.\n\nProvided item:", completion = "Yes, I knew Leyara, and I was aware of her anger even before she joined the Druids of the Flame. She was a promising young druid, once. Unfortunately, the bonds of family are often stronger than the power of reason, and ultimately, she chose to follow Fandral down his treacherous path.\n\nYou should keep this locket, <name>. May it remind you that each of us walks our own path through life... and that some paths are easier than others." }
WordHunterWoW_QuestEN[29312] = { title = "The Stuff of Legends", description = "It is an honor to make your acquaintance, {race}.\n\nYour deeds echo in the ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there when you are ready.", objectives = "Speak to Hallegosa.", progress = "Behold! Dragonwrath, Tarecgosa's Rest.", completion = "Your heroic deeds will never be forgotten, <name>." }
WordHunterWoW_QuestEN[29313] = { title = "The Secret to Perfect Kimchi", description = "My family has been making the best kimchi in Darnassus since the city was founded, {name}. The secret is something simple, but it makes all the difference.\n\nWe bury the jars in the ground until it's ready to serve and my latest batch has just reached that point. You can find the jars buried in earthen mounds all over the city. Would you help me gather them while the contents are just right?", objectives = "Find 8 Buried Kimchi Jars in Darnassus.", progress = "Were you able to find the jars?", completion = "Thank you, <name>. There's no way I could've found them all in time and it would be a shame to miss out on so much good kimchi!" }
WordHunterWoW_QuestEN[29314] = { title = "Remembering the Ancestors", description = "The living are not the only ones who require sustenance. One of my duties is to prepare the rice cakes that are left for the ancestors. Normally, my senior apprentice has the honor of taking the cakes to the Temple of the Moon for blessing and then presenting them to the ancestors. Since she is out of the city today, would you mind performing the duty in her place?", objectives = "Collect the Blessed Rice Cakes from the Temple of the Moon.", progress = "This is the shrine the trainer mentioned.", completion = "<You lay out the rice cakes around the shrine, which begins to glow softly. A faint sense of approval washes over you.>" }
WordHunterWoW_QuestEN[29315] = { title = "Fungus Among Us", description = "Some chefs complain that our beloved Undercity doesn't boast the ingredients to create truly fine fare.\n\nSuch mewling little cretins. Delicious delights abound!\n\nGather some of the rank, slimy Sewer Caps growing in Undercity's northwest sewer line and return them to me.", objectives = "Obtain 12 Sewer Caps. Deliver the fungus to Eunice Burch in Undercity.", progress = "Did you find enough Sewer Caps?", completion = "These smell absolutely wretched. Perfect!" }
WordHunterWoW_QuestEN[29316] = { title = "Back to Basics", description = "There are certain things that everyone needs, from the basic household cook to the master chef. One of the city's most important staples is rice flour. Most families keep at least one basket of rice in their houses and the residents of the Craftsmen's Terrace and Tradesmen's Terrace are no different.\n\nI often ask my students to help with the task of pounding rice into flour since it's good practice and an endless task. Why don't you give it a try?", objectives = "Help the inhabitants of the Craftsmen's Terrace and Tradesmen's Terrace make rice flour by pounding the contents of Rice Baskets.", completion = "It takes a lot of effort to ensure that there's enough flour for everyone's needs. Thank you for your help, <name>." }
WordHunterWoW_QuestEN[29317] = { title = "Fish Head", description = "There was an... incident... with an orc guard and one of Master Apothecary Faranell's abominations.\n\nApparently, the Kor'kron Overseer chopped its head clean off and kicked it into the slime.\n\nFaranell's apprentices searched for hours but they can't find the thing. Care to try fishing it up? I'm sure the old fellow'd be grateful.", objectives = "Armand Cromwell wants you to fish up a Severed Abomination Head in Undercity for Master Apothecary Faranell.", progress = "You haven't by any chance come across a severed abomination head, have you...?", completion = "Ah! THERE it is! How ever did you find it?\n\nWell, no matter. My apprentices weren't able to recover the head despite hours splashing about in the slime, though they DID recover this bag of shiny things... perhaps you've a use for what's inside?\n\nMy thanks." }
WordHunterWoW_QuestEN[29318] = { title = "Ribs for the Sentinels", description = "One of my responsibilities is to feed the sentinels of Darnassus while they're on duty. It's a time-consuming task, but one I'm happy to undertake. It's also a great way to practice your skills. Would you mind helping me with today's meal? Simply take these ribs, cook them near a stove or fire, and distribute them to sentinels throughout the city.", objectives = "Use the Uncooked Ribs near a stove or campfire to cook them and then use them to feed 5 Darnassus Sentinels.", completion = "Feeding all those sentinels is much easier with your help. Nobody had to wait in line for their meal this time." }
WordHunterWoW_QuestEN[29319] = { title = "Tadpole Terror", description = "Some of our apothecaries took to dumping their more volatile waste chemicals into Stillwater Pond and... well, let's just say that no one wants to know how big mutant flesh-eating toads can grow.\n\nWould you consider fishing up some giant flesh-eating tadpoles before it gets to that? Just don't try to handle them with your bare hands.", objectives = "Armand Cromwell in Undercity wants you to bring him 8 Giant Flesh-Eating Tadpoles.", progress = "Catch any mutant tadpoles? Don't try to handle them with your bare hands.", completion = "Excellent work, <name>. I'll see that these are, ah, disposed of immediately.\n\nAfter all, what would our fine apothecaries want with an army of monstrous, poison-spitting, flesh-eating super-toads?" }
WordHunterWoW_QuestEN[29320] = { title = "Like Pike?", description = "You've fished in Brightwater Lake, yes?\n\nThe prize catch there is one of the lake's massive corpse-fed pikes. However, they only bite on a very specific type of bait... corpse worms.\n\nSearch the graves in the courtyard up top and you should find some.", objectives = "Dig up a Corpse Worm in the Ruins of Lordaeron courtyard and use it as bait to catch a Corpse-Fed Pike. Corpse-Fed Pike can be fished up in Brightwater Lake, northeast of Undercity.", progress = "Catch that pike, yet?", completion = "That's a fine, fat pike, <name>.  Well done." }
WordHunterWoW_QuestEN[29321] = { title = "Happy as a Clam Digger", description = "It seems like everyone I know loves clams, but I can't stand them! They're smelly and slimy, and harvesting them means digging through mud. Give me a fishing pole and some bait any day.\n\nStill, I want to surprise my brother with a bucket of fresh clams. I'd reward you if you were willing to gather those clams for me.\n\nJust go through the portal to Rut'theran Village and look for the clams in the shallows near the shore.", objectives = "Gather 10 Teldrassil Clams from the shores near Rut'theran Village.", progress = "Did you find enough clams?", completion = "Yuck, they're so gross-looking, but they're my brother's favorite. Thanks for sparing me from that messy job!" }
WordHunterWoW_QuestEN[29322] = { title = "Time for Slime", description = "It takes a special sort of fisherman to reap the bounty of Undercity's burbling slime troughs. Think you can handle gathering some of the squirming, sentient slime mold slithering about down there?\n\nYou can try to fish them up, but they're wily; you might be better off just diving into the ooze and grabbing them.\n\nRemember, they're only useful alive and intact... who'd want to eat a dead slime mold?! Disgusting.", objectives = "Collect 10 Squirming Slime Molds. Deliver them to Armand Cromwell in Undercity.", progress = "Difficult to catch, aren't they?", completion = "These slimes look perfect.  I will send these along to Eunice for preparation, thank you." }
WordHunterWoW_QuestEN[29323] = { title = "Stocking Up", description = "We've used up most of our food stores in taking care of refugees and feeding those whose homes and livelihoods were destroyed. If we don't replenish our stores, we'll all be in danger next time there's a bad storm or a Horde invasion.\n\nPerhaps you'd be willing to help me build up our stock of lake whitefish. You can catch it anywhere in Darnassus, and once it's dried, it'll keep until it's needed.", objectives = "Catch 5 Lake Whitefish by fishing in Darnassus.", progress = "If all of our fishermen pitch in, it won't take long to rebuild our supplies.", completion = "These are beautiful! Thank you, <name>. I'll set them out to dry." }
WordHunterWoW_QuestEN[29324] = { title = "The Sister's Pendant", description = "Have you met Sister Aquinne? She and I trained together in Dolanaar, and she recently came to the city to study at the Temple of the Moon. We decided to go for a boat ride, but the clumsy oarsman managed to capsize the craft!\n\nWhen we got back to the shore, Aquinne's moon pendant was missing. The lakes in Darnassus are full of giant catfish who will gobble up anything shiny!\n\nI've been catching them nonstop, hoping to find the one with her pendant. I don't suppose you want to help?", objectives = "Retrieve Aquinne's Moon Pendant from the belly of a Giant Catfish. You should be able to catch them anywhere you can fish in Darnassus.", progress = "Have you had any luck finding Aquinne's missing pendant? I must've caught fifty of those monsters and I have nothing to show for it!", completion = "<Astaia takes the pendant from you.>\n\nUnderneath all the slime and tarnish, I think this is it! Aquinne will be so happy to have this back... after a thorough cleaning, of course. I can't thank you enough, <name>." }
WordHunterWoW_QuestEN[29325] = { title = "A Slippery Snack", description = "Have you ever eaten octopus meat? It takes some getting used to, but it's my favorite! I even know some people who like to eat the whole thing while it's alive!\n\nI don't plan on trying that anytime soon, but I am out of fresh octopi at the moment. Will you help me gather some more? They live in the shallow water off the shore near Rut'theran Village.", objectives = "Gather 6 Baby Octopi from the shallow water near Rut'theran Village.", progress = "It's impossible to catch octopi with a fishing line, so you're just going to have to grab them!", completion = "These are going to be delicious, I can already tell! Thanks, <name>!" }
WordHunterWoW_QuestEN[29326] = { title = "The Nordrassil Summit", description = "Hello, {class}! My brothers and sisters of the Earthen Ring have spoken well of your deeds in the wake of the Cataclysm. But much remains to be done if we are to heal this broken world.\n\nWalk with me, friend. Preparations for a ceremony are underway, a ritual that I hope will be a turning point in our battle against the Twilight's Hammer.\n\nWhen all is done, you will be able to spread the word about our triumph here.", objectives = "Speak with Thrall under the World Tree in Mount Hyjal and witness the Earthen Ring ceremony.", completion = "It can't be over. We mustn't give up hope!" }
WordHunterWoW_QuestEN[29327] = { title = "Elemental Bonds: Doubt", description = "I do know the one you seek... but I do not know if it is wise for you to follow him. He has cast himself into the cyclone. The winds now tear at his body and mind, leaving nothing but shreds of flesh and doubt.\n\nChasing after him would only expose you to the same fate. The wind's edge leaves nothing uncut.\n\nYou have been warned. Now what will you do?", objectives = "Speak with Cyclonas to secure passage to Thrall. Then, fight the wind elementals that torment him until he is freed.", progress = "Stay vigilant, <name>! Do not give up on Go'el.", completion = "What is this... water?" }
WordHunterWoW_QuestEN[29328] = { title = "Elemental Bonds: Desire", description = "Once again, {class}, I cannot do this without your help. I will try to quiet this tempest, but you will need to fight back the unstable elementals that whirl around it. Only then can we free Go'el!", objectives = "Slay the Tides of Longing and Vortexes of Longing near the Abyssal Breach until Thrall is free of their grasp.", progress = "My Go'el cannot tread these waters forever, <name>!", completion = "Air, water... now earth?" }
WordHunterWoW_QuestEN[29329] = { title = "Elemental Bonds: Patience", description = "With the Stonemother's blessing, I can take us to where Go'el is being held.\n\nWe must be careful. The Twilight's Hammer has agents all around. You help me hold them off while I attempt to get through to Go'el!\n\nSpeak with me when you are ready, and I will take you to him.", objectives = "Speak with Aggra when you are ready to help Thrall. Then defeat the Elements of Patience and Corestones of Patience that are holding him captive.", progress = "We are nearly there, <name>. Stay by my side a bit longer. We will get through to him yet.", completion = "<Aggra clenches her fists, and stares at the spot where Thrall stood moments ago.>" }
WordHunterWoW_QuestEN[29330] = { title = "Elemental Bonds: Fury", description = "The totems, {name}! We need to activate them, or Go'el is lost!\n\nKill the elementals next to each of my totems, located around the edges of this plateau. Once all four totems are activated, we should be able to free the last piece of Go'el's soul!", objectives = "Kill fire elementals next to Aggra's Air Totem, on the western edge of the plateau, until it activates. Then continue to Aggra's Water Totem, Aggra's Earth Totem, and Aggra's Fire Totem." }
WordHunterWoW_QuestEN[29331] = { title = "Elemental Bonds: The Vow", description = "Before he passed through the portal to Mount Hyjal, Thrall asked you to follow him. There is something he would like you to witness.", objectives = "Speak with Thrall at Nordrassil in Mount Hyjal.", completion = "Thanks to you, my friend - I live again! And due to the combined efforts of the Cenarion Circle and the Earthen Ring - the World Tree will bring new life to Azeroth as well.\n\nWhile Deathwing and the rest of our foes remain to be dealt with, I wish to share something with you." }
WordHunterWoW_QuestEN[29332] = { title = "Lily, Oh Lily", description = "The lilies that grow around Stillwater Pond can be rendered down into a delightful broth.\n\nWell... by \"delightful,\" I mean \"won't immediately sicken any orc who drinks it.\"\n\nWhy don't you go gather some for me, hmmm? Just watch out for the giant flesh-eating tadpoles.", objectives = "Obtain 10 Stillwater Lilies. Deliver the plants to Eunice Burch in Undercity.", progress = "Did you find enough Stillwater Lilies?", completion = "Ah, what a luscious batch of lilies. Bravo! I'll boil them down right away..." }
WordHunterWoW_QuestEN[29333] = { title = "Escargot A Go-Go", description = "The orc guards are always grumbling about bland and moldering Undercity fare - as if it's OUR fault they can't get by on a diet of mushrooms and old corpses - so I think it's time they learn just the sort of exotic delights we can cook up when we've a mind to.\n\nGather some of the freshwater snails ambling about beneath Brightwater Lake and I'll show them what a true culinary master can create.", objectives = "Collect 8 Brightwater Snails. Deliver them to Eunice Burch in Undercity.", progress = "Gather those freshwater snails, yet?", completion = "You must be quite the swimmer... all I can manage is the dead man's float.\n\nIn any case, excellent batch of snails you've gathered. Thank you." }
WordHunterWoW_QuestEN[29334] = { title = "Roach Coach", description = "For all the grousing those Kor'kron Overseers do about Undercity food, there's ONE thing they'll eat in spades: My sister Audrey's Thrice-Spiced Crunchy Stew.\n\nIts popularity means she's always running low on ingredients. Could you gather some for her at the coach she sells them from?\n\nYou'll find traps all over the city; just take their contents to Audrey and she'll handle the rest!", objectives = "Obtain 20 Plump Cockroaches. Deliver the insects to Chef Audrey in Undercity.", progress = "I call my little traps \"Cockroach Cabins.\"\n\nCockroaches check in, but they don't check out!", completion = "Oh, and just as I was nearly out. Thank you!" }
WordHunterWoW_QuestEN[29335] = { title = "Into Slashing Winds", description = "{class}, I refuse to believe my Go'el is lost forever. His spirit has been scattered across the elemental planes. If even a part of him still exists, we can find him, but I will need your help.\n\nWe will start with the plane of air.\n\nSpeak to me and we will travel to the Vortex Pinnacle together. We must speak with an elemental, Cyclonas. He's capricious, but he sees everything in the realm of air. If my love is there, Cyclonas will know what's become of him.", objectives = "Speak with Cyclonas on the Bluff of the South Wind in Uldum.", completion = "<You feel the wind racing over your arms, your face, your weapons and armor...>\n\n<Cyclonas is looking you over.>" }
WordHunterWoW_QuestEN[29336] = { title = "Into Coaxing Tides", description = "Go'el must be in the plane of water... the Abyssal Maw itself! I shudder to imagine what fate awaits him there.\n\nFind the elemental, Hydrius, near the Abyssal Breach. He knows of Go'el and is sympathetic to our fight against Ragnaros. If anyone can help you there, it's him.\n\nI will meet you beneath the tides of Vashj'ir, {race}...", objectives = "Speak with Hydrius at the Abyssal Breach in the Abyssal Depths of Vashj'ir.", completion = "I will do what I can to aid you, <class>." }
WordHunterWoW_QuestEN[29337] = { title = "Into Constant Earth", description = "Time is short! My love lies in Deepholm. I will take us there when you are ready, and we will speak with Therazane the Stonemother.", objectives = "Speak with Therazane at Therazane's Throne in Deepholm.\n\nAggra can teleport you to Therazane's Throne from the Abyssal Breach.", completion = "I already know what it is you seek, fleshlings. And I have chosen to aid you." }
WordHunterWoW_QuestEN[29338] = { title = "Into Unrelenting Flame", description = "We must travel now to the Firelands. Within that realm, Go'el's burning spirit could become as terrible as Ragnaros himself! Prepare yourself, for we will be alone in a hostile world.\n\nSpeak with me when you are ready... and may the ancestors protect us! ", objectives = "Speak with Aggra on the Staidridge in Deepholm to secure passage to the Firelands.", completion = "Be ready, <name>." }
WordHunterWoW_QuestEN[29339] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[29340] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[29341] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[29342] = { title = "Cold Water Fishing", description = "The best tastin' fish live in the cold waters o' Dun Morogh, {name}, an' don't let anyone else tell ye otherwise! Me favorite, an' the most popular one in Ironforge, is the arctic char, which only comes from our ancestral lands.\n\nI like tae think o' it as Ironforge's gift t' the world!\n\nWhy don't ye try yer hand at catchin' a few yerself? The best place tae find 'em is down in Helm's Bed Lake, in the eastern end o' Dun Morogh.", objectives = "Catch 5 Arctic Char by fishing in Helm's Bed Lake in Dun Morogh.", progress = "Have ye tried to catch those char?", completion = "These are beautiful, <name>! I think ye've got the hang of it." }
WordHunterWoW_QuestEN[29343] = { title = "One fer the Ages", description = "I'm sure by now ye've heard the tale o' Old Ironjaw, the most famous and elusive fish in the waters o' Ironforge's Forlorn Cavern. Well, in his many years, he's been responsible for the rise o' many young ironjaws. Don't let the name fool ye, {name}, these young'uns are every bit as clever as their dad, but somewhat lackin' in experience.\n\nWith skill an' patience, ye could probably catch one, an' when ye do, bring it to the museum in Ironforge's Library an' put it on display fer all to see!", objectives = "Catch a Young Ironjaw in Ironforge's Forlorn Cavern and display it in the Library near the Empty Plaque.", progress = "Did ye catch one o' Ironjaw's offspring?", completion = "Well done, <name>! Maybe seein' yer catch will inspire more dwarves to take up fishin'!" }
WordHunterWoW_QuestEN[29344] = { title = "Fish fer Squrky", description = "Hae I introduced ye tae me pet, Squrky? I'm teachin' him tae fish all proper-like. Fer now, I've been feedin' him minnows fished from the pool in this cavern.\n\nMaybe ye'd like tae give it a try? Just cast yer lure in the pool over there and feed Squrky any minnows ye happen tae fish up. He'll love ye ferever!", objectives = "Catch 3 Blind Minnows in the pool in the Forlorn Cavern and feed them to Squrky.", progress = "How's Squrky's lunch comin'?", completion = "Ye've done a good job. Squirky seems happy and I've had some time to make some new lures. Thank ye fer the help!" }
WordHunterWoW_QuestEN[29345] = { title = "Pond Predators", description = "A well-meaning goblin visitor introduced Azshara snakeheads to our waters and now they're overrunning the pond.\n\nPlease, if you can catch some of these voracious predatory fish before they eat every smallfish and mud snapper in Thunder Bluff, I'd be terribly grateful.", objectives = "Kah Mistrunner in Thunder Bluff wants 8 Azshara Snakehead fish from the Thunder Bluff pond.", progress = "Have you caught any Azshara snakeheads, yet?", completion = "Good work, <name>. It's up to all of Thunder Bluff's fishers to keep this vicious creature out of Mulgore's waters." }
WordHunterWoW_QuestEN[29346] = { title = "The Ring's the Thing", description = "One of the Forsaken from the Pools of Vision came to me and said he'd lost his ring to a blind cavefish in the waters there.\n\nOr perhaps it was his finger. It was hard to tell; his jaw did not move and his Orcish was no better than mine.\n\nIn any case, I thought it would be a kind gesture towards our unusual visitors to catch and gut cavefish until the ring - or finger - was found.\n\nWould you help?", objectives = "Fish up a Blind Cavefish from the Pools of Vision in Thunder Bluff. Once you catch a cavefish, fillet it and check if it swallowed the ring.", progress = "You haven't seen a ring about, have you? I think one of the cavefish might have swallowed it...", completion = "You found my ring, did you? I'm most grateful.\n\nTo be honest, I've no idea why I keep the thing. I'm not even certain how I acquired it... I suppose I am simply a creature of habit.\n\nStill, as I said, I am grateful. Say... I found these things while searching for it myself. Perhaps they'd be of some use to you?" }
WordHunterWoW_QuestEN[29347] = { title = "Live Bait", description = "If ye've ever fished fer crayfish, ye know they respond best to live bait, an' the more bait, the better. Would ye like to test my new bait? Simply smear this on yerself an' hop into Helm's Bed Lake in eastern Dun Morogh.\n\nAfter ye've got the catch, take it to me friend, Cook Ghilm at Gol'Bolar Quarry, west of the lake. He's an expert at cookin' those oversized bugs!", objectives = "Use Grimnur's Bait on yourself, then jump into Helm's Bed Lake in Dun Morogh.", progress = "Oh... this might hurt a wee bit.", completion = "These are beautiful, <name>! Grimnur's goin' tae be so proud when he hears about this!\n\nOh, he did say tae pass this along tae ye, if the scheme worked." }
WordHunterWoW_QuestEN[29348] = { title = "The Race to Restock", description = "Thunder Bluff's fishing pond is being overrun with voracious Azshara snakeheads; there are hardly any smallfish or mud snappers left.\n\nWe already have fishers trying to kill as many snakeheads as they can, but can you assist us in our restocking efforts?\n\nIf you could gather some fish from Stonebull Lake and bring them here to Thunder Bluff, I would be very grateful.", objectives = "Kah Mistrunner in Thunder Bluff wants 2 Randy Smallfish and 2 Amorous Mud Snappers from Stonebull Lake in Mulgore.", progress = "Did you bring those fish from Stonebull Lake, yet?", completion = "Your help is much appreciated, <name>.\n\nHopefully these fish will go a long way towards restocking our fishing pond." }
WordHunterWoW_QuestEN[29349] = { title = "Craving Crayfish", description = "One of the great delicacies of Mulgore is the crayfish that dwell in our lakes and streams. They are particularly popular during weddings or the celebration of a birth.\n\nWould you help me catch some of these crafty crustaceans for the cooking pots of Thunder Bluff?\n\nYou can fish them up from Stonebull Lake, or simply dive in and grab them.", objectives = "Kah Mistrunner in Thunder Bluff wants 10 Stonebull Crayfish from Stonebull Lake in Mulgore.", progress = "Crayfish are so tasty. Have you caught many?", completion = "Ah, so many crayfish!\n\nDid you fish these up? Or simply swim after them?\n\nWell, no matter. Excellent work, <name>." }
WordHunterWoW_QuestEN[29350] = { title = "The Gnomish Bait-o-Matic", description = "One o' the gnomish engineerin' trainers gave me a blueprint fer a fancy lure he says'll help me catch fish faster and keep 'em from gettin' away. The whole thing sounds a mite silly if ye ask me, but I'll try anythin' once.\n\nHere are the blueprints. Ye're going to need shiny baubles, which ye can buy from my assistant inside the buildin', a hair trigger ye can buy from an engineerin' supplier in Tinker Town, and a few rat traps from the Deeprun Tram.", objectives = "Use the Bait-o-Matic Blueprint with 5 Shiny Baubles, a Hair Trigger, and 3 Rat Traps to create the Gnomish Bait-o-Matic.", progress = "How's that fancy new lure comin' along?", completion = "It doesn't look like anything I think a fish'd be interested in, but ye never know. Fish're strange creatures. Thanks fer givin' this a try, <name>." }
WordHunterWoW_QuestEN[29351] = { title = "A Round for the Guards", description = "The guards who defend Ironforge put their lives on the line against our many enemies, and it's up to us to take care of them.\n\nToday, their rations consist of two dwarven favorites, haggis and Ironforge pale ale. Would ye be so kind as to help me distribute them? That way, everyone gets his food in a timely manner and we can move on to other tasks.", objectives = "Distribute the Ironforge Rations to 6 Ironforge Guards.", completion = "A full guard is a happy guard, as I always say. Thanks fer yer help, <name>." }
WordHunterWoW_QuestEN[29352] = { title = "A Fowl Shortage", description = "Oh, no, {name}, this is going to be a disaster if we don't find some chicken soon... Ye just cannae make cock-a-leekie soup without the chicken! It's not possible!\n\nThere's still time to make the soup and broth if ye can find some fresh chicken. Will ye help me? There are usually a few chickens running around outside the front entrance to the city. If ye can get yer hands on, say, six o' them, that should save me soup.", objectives = "Collect 6 Dun Morogh Chickens near the entrance to Ironforge.", progress = "The chickens, <name>, do ye have them or not?", completion = "Aye, that's exactly what I needed. Ye have me thanks, <name>, and me apologies fer bein' so brusque earlier. I just cannae stand the thought of not gettin' a meal finished on time." }
WordHunterWoW_QuestEN[29353] = { title = "Keepin' the Haggis Flowin'", description = "The haggis must flow. Aye, it's a figure o' speech, for haggis'll ne'er flow! Ye dinnae want to know what'll happen if the people o' Ironforge don't get their haggis.\n\nI'm working on the next batch, but I'm still missing a couple of ingredients.\n\nSognar Cliffbeard is the meat vendor in the Military Ward, an' he'll sell you the big bag o' sheep innards I need. Ye can buy mild spices from any cooking supplier and ye can find sacks o' oatmeal in any inn or among the supplies  in the city.", objectives = "Obtain a Bag o' Sheep Innards, 5 packets of Mild Spices, and 4 Sacks of Oatmeal.", progress = "Do ye have those ingredients?", completion = "Ye got them all? Wonderful! I'll get started right away." }
WordHunterWoW_QuestEN[29354] = { title = "Shiny Baubles", description = "One of a fisher's most simple and effective tools is the shiny bauble; affixed to a line, even the most novice angler has a chance at a catch.\n\nWith all the fishing going on of late, though, Thunder Bluff is in woefully short supply!\n\nMight I ask you to collect shiny stones from around the base of the central rise? Bring them to Nahari Cloudchaser so that she might craft more shiny baubles with them.", objectives = "Nahari Cloudchaser in Thunder Bluff wants 20 Shiny Stones from around the central rise's base.", progress = "Did you happen to bring me any shiny stones?", completion = "My, those are some very lovely stones! They'll make perfect shiny baubles, thank you.\n\nHere... Kah told me you'd be by with the stones, and to give this to you upon your arrival." }
WordHunterWoW_QuestEN[29355] = { title = "Can't Get Enough Spice Bread", description = "It might seem like a basic thing, {name}, but spice bread is a longtime favorite in Ironforge. Some days, I have trouble keeping up!\n\nWould ye like to cook some to practice yer skills an' help meet the demand? Ye can buy all the ingredients ye'll need from me brother, Emrul Riknussun, who is downstairs.", objectives = "Make or obtain 10 slices of Spice Bread.", progress = "How's that spice bread?", completion = "That bread looks delicious. Thanks, <name>." }
WordHunterWoW_QuestEN[29356] = { title = "I Need to Cask a Favor", description = "My stocks o' IPA, that's Ironforge Pale Ale for ye novices, are gettin' low. Luckily, the brewery isn't too far away an' they should have a new cask o' Drugan's IPA waitin' fer us. That Drugan's a genius of a brewer, I tell ye.\n\nI won't be able to get down to Kharanos meself today, but perhaps ye can dash down there, pick up the new cask an' run it back 'ere? What d'ye say?", objectives = "Pick up the Cask of Drugan's IPA outside the brewery in Kharanos and run it back to Ironforge.", progress = "Well, did ye get the cask or not?", completion = "Ah, well done! I tell ye, that Drugan's a true polymath -- explorer, historian, brewer -- is there anythin' that man hasn't mastered?" }
WordHunterWoW_QuestEN[29357] = { title = "Spice Bread Aplenty", description = "Isn't it amazing how something as simple as spice bread is used every day in Darnassus? When I'm not seeing to my other responsibilities, I like to bake spice bread to hone my skills as a cook and practice my technique.\n\nWhy don't you give it a try? You should be able to get your ingredients here in the shop.\n\nNo matter how much we make, it never goes to waste. Bring me your loaves when you're done and I'll have someone share them with our friends, the Gilneans.", objectives = "Make or obtain 10 pieces of Spice Bread.", progress = "I just love the smell of baking bread, especially spice bread. Don't you?", completion = "These are well-made, <name>. I hope you found baking as relaxing as I do." }
WordHunterWoW_QuestEN[29358] = { title = "Pining for Nuts", description = "The Shu'halo use pine nuts in so MANY dishes: meat, fish, vegetables, even baked into breads or sprinkled over sweet pastries.\n\nThe Earth Mother has blessed us in that the very BEST pine nuts come from the trees upon these very mesas. Simply gather pine cones and toast them over a cooking fire to release the nuts within.\n\nWould you please be so kind as to gather some? There are hardly ever enough to go around...", objectives = "Obtain 30 Pine Nuts by toasting Mulgore Pine Cones from Thunder Bluff. Deliver the nuts to Aska Mistrunner in Thunder Bluff.", progress = "Have you found many of those tasty pine nuts?", completion = "You work so quickly!\n\nI'll see that these are distributed to the various chefs and bakers of Thunder Bluff.\n\nThank you!" }
WordHunterWoW_QuestEN[29359] = { title = "An Old Favorite", description = "Herring is one of the most sought-after fish in Darnassus, but not just any herring. The Kaldorei herring is native only to the waters surrounding Teldrassil.\n\nI try to keep a good supply of it because it's so versatile! I just finished smoking a batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch Kaldorei herring by fishing in Rut'theran Village.", objectives = "Catch 8 Kaldorei Herring by fishing in Rut'theran Village.", progress = "Did you get those herring?", completion = "Thanks! I wonder what I should do with this batch..." }
WordHunterWoW_QuestEN[29360] = { title = "Would You Like Some Flies With That?", description = "It's not always about making food for the orcs, {class}.  This time, it's about making food for what will hopefully be their replacements.\n\nWe need to start small, we need to catch flies.  Flies love rotting meat, and we love rotting meat... as projectile weapons!\n\nCheck out the Meat Wagons for any extra bits of meat.  Where you find the meat, you'll find the flies.\n\nBring me 25 bloated flies, and then I can start on the next stage of our cooking plan.", objectives = "Obtain 25 Bloated Flies from the \"meat\" near the Meat Wagons. Then return to Eunice Burch in Undercity.", progress = "I bet some of that \"meat\" is still good.", completion = "Ah!  Perfect!  Fat, slow and ready to be eaten!  Next up, we will feed them to our spiders.  Fatten them up, and then, we feed the spiders to the frogs...\n\nListen to me go on.  You don't need to know all the details.  This is just a small step in a grand cuisine in a grand scheme." }
WordHunterWoW_QuestEN[29361] = { title = "Moat Monster!", description = "Sometimes fishing means throwing something back, {class}.\n\nWe've been overfeeding these frogs for just that occasion.  We've fed these frogs bloated spiders, that were fed bloated flies, and now, we are going to feed a real monster.\n\nThe moat above, in the Ruins of Lordaeron, is home to our very own moat monster.\n\nToday is feeding day.  But we must train it as well.  In this bag, you will find a decoy kit and some bloated frogs.  Use the decoy kit, then toss the frogs to the monster when it appears.", objectives = "Use the Alliance Decoy Kit to summon the Moat Monster in the Ruins of Lordaeron. Then use the Bloated Frogs to feed the monster.", completion = "The dead feed the flies.  The flies feed the spiders.  The spiders feed the frogs.  The frogs feed our moat monster... It's a beautiful circle of life with the goal of ending life." }
WordHunterWoW_QuestEN[29362] = { title = "\"Magic\" Mushrooms", description = "You know of the Pools of Vision, yes?\n\nThere is a sort of mushroom that grows there... not the tough, rank fungi that dominates the place, but smaller, more delicate caps that grow beneath them.\n\nThey are rare and quite delicious, adding a flavor to meat dishes that one might even call magical.\n\n...what? No, really. They just taste good. That's it.", objectives = "Gather 6 \"Magic\" Mushrooms from the Pools of Vision in Thunder Bluff. Deliver them to Aska Mistrunner in Thunder Bluff.", progress = "Were you able to gather any mushrooms?", completion = "Thank you, <name>! I'm sure these will impart a simply magical taste to whatever dish they're used in.\n\nWhat? Stop looking at me like that!" }
WordHunterWoW_QuestEN[29363] = { title = "Mulgore Spice Bread", description = "I am often asked, \"Aska, who is making all this Mulgore spice bread?!\"\n\nIt is a reasonable question. Our fine and noble bread is traded in countless settlements in the most far-away lands, even by our staunchest foes. IT'S JUST THAT GOOD.\n\nAnd the answer...?\n\nIt is \"YOU.\" Please take this packet of Mulgore spices and use it to turn bland, boring spice bread into MULGORE spice bread!", objectives = "Use Mulgore Spices with Spice Bread to create 5 Fresh Mulgore Spice Bread (you may make your own Spice Bread or use someone else's). Deliver the bread to Aska Mistrunner in Thunder Bluff.", progress = "Have you baked that Mulgore spice bread, yet?", completion = "Ooo, that bread smells delicious. You are quite the baker, <name>.\n\nWho knows how far these exquisite loaves will go... I hear it's even popular among the draenei of the Azuremyst Isles!" }
WordHunterWoW_QuestEN[29364] = { title = "Corn Mash", description = "One of Thunder Bluff's most important staples is cornmeal; bowls of corn may be found in nearly every home.\n\nWith so many of the local mills under constant attack by harpies, gnolls, reckless mining companies and Earth Mother knows what else, I often ask my students to help with the task of grinding corn into cornmeal.\n\nWould you care to help?", objectives = "Help the inhabitants of Thunder Bluff make cornmeal by pounding bowls of Corn Kernels.", completion = "Much work is required to grind enough cornmeal for everyone's needs. Thank you for your help, <name>." }
WordHunterWoW_QuestEN[29365] = { title = "Perfectly Picked Portions", description = "Even the novice cook knows that a great dish begins with great ingredients.\n\nI have standing orders with merchants throughout Thunder Bluff, but I'd like to see how well you do at selecting the very best of what they have to offer.\n\nPlease make the rounds and gather perfect portions of meat, fish, vegetables and herbs from local merchant stalls.", objectives = "Obtain four \"perfect portions\" from merchant stalls around Thunder Bluff. Deliver the ingredients to Aska Mistrunner in Thunder Bluff.", progress = "Have you gathered all the necessary ingredients?", completion = "<Aska examines the ingredients you have chosen.>\n\nMmmhmmm. Yes. Well done!\n\nI could not have chosen better myself." }
WordHunterWoW_QuestEN[29368] = { title = "Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[29371] = { title = "A Time to Lose", description = "Well met, {class}. As we attempt to embrace the Wickerman ceremony, it is no surprise that the Horde would attempt to ruin our celebration.\n\nNow the prudent course of action may be to rise above the conflict and simply ignore the attacks.\n\nI admire those that take that high road, but I cannot help them.  But for those that seek to strike back... I can help them.  If you are interested, {class}, take this Dousing Agent and use it on the Horde's Wickerman in the Ruins of Lordaeron.", objectives = "Use the Dousing Agent on the Wickerman in the Ruins of Lordaeron.", progress = "Have you extinguished the Horde's Wickerman, <class>?", completion = "Ah, so it is done.  A momentary setback, but if it is as annoying as their attacks have been, then it is worth it.\n\nI spoke to the children about your adventure and they were very excited.  They were impressed with your bravery to venture into enemy territory.  They also seemed to get a kick out of the mischief that you helped bring about... Oh those little rascals...\n\nThey did want you to have some of these treats as a reward.  Enjoy, <name>." }
WordHunterWoW_QuestEN[29372] = { title = "Trouble in Podunk", description = "Outlaws have kidnapped the sheriff!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue the sheriff." }
WordHunterWoW_QuestEN[29373] = { title = "Trouble in Podunk", description = "We never paid no heed to Sheriff Blundy, what with his gettin' all up-in-arms at all times 'bout his \"laws\" and his \"mis-de-meanors.\" But them dirty ol' McClintocks, and their cattle-rustlin' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin' and dead-or-alive-wantin', and come this past week they done took the law into their own hands - in the most literal of senses - by haulin' up and hi-jackin' the good Sheriff. As you can see, our humbleYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue the sheriff." }
WordHunterWoW_QuestEN[29374] = { title = "Stink Bombs Away!", description = "The foolish Alliance have employed hags to fuel an attack on our city.  Well, as my sister once told me, \"Turnabout is fair play.\"\n\nWe will gladly return the favor.  Speak with my sister, and she will provide you with a broomstick flight over Stormwind.  While over Stormwind, drop stink bombs on the city and on the people.  Make them suffer!\n\nWe will show those hags in Stormwind who is the most powerful.", objectives = "Speak with Crina Fenlow and take a broomstick flight over Stormwind city. Use the stink bombs to cover the city and its people.", progress = "The magic those hags in Stormwind use is no match for our magic, <class>.", completion = "That will show the fools in the Alliance who is the strongest.\n\nTake these treats and treat yourself to something nice, <class>." }
WordHunterWoW_QuestEN[29375] = { title = "Clean Up in Undercity", description = "Greetings, {class}!  Are you enjoying Hallow's End?  It seems that in response to our stink bombing Stormwind, the Alliance has decided to stink bomb our city.\n\nFortunately, we have magics that can handle the stink the Alliance bring us.  Use this Arcane Cleanser to remove the stink bombs from the city.", objectives = "Use the Arcane Cleanser to remove stink bombs within the Undercity.", progress = "Arcane magic... Works every time.", completion = "I didn't notice a smell before, but I've come to expect weak magic from those Alliance hags.  However, the orc guards complained enough and will surely appreciate your efforts." }
WordHunterWoW_QuestEN[29376] = { title = "A Time to Build Up", description = "We burn the effigy of the Wickerman as a symbol of our struggle against those who would oppose us. We wear the ashes of the burnt Wickerman as a symbol of our neverending fight against those who would enslave us.\n\nUse the bonfire nearby and ignite the Wickerman.  Then take the ashes that lay nearby and spread them across your face.\n\nThese gestures will serve as a reminder to our enemies that we shall never yield.", objectives = "Use the bonfire in front of the Wickerman to set it ablaze. Use the ashes on the ground near the Wickerman.", progress = "This is the night that our enemies fear us the most, <class>.", completion = "NOW is the time of the Forsaken! Power to the Forsaken - NOW AND FOREVER!!!" }
WordHunterWoW_QuestEN[29377] = { title = "A Time to Break Down", description = "Well met, {class}. As we revel in the Wickerman ceremony, it comes as no surprise that the Alliance would attempt to ruin our celebration.\n\nWe have an opportunity to make them pay.  If you are interested, {class}, take this Dousing Agent and use it on the Alliance's Wickerman in front of Stormwind.\n\nExtinguish their flame and revel in their misery, {class}.", objectives = "Use the Dousing Agent on the Wickerman in front of Stormwind.", progress = "Have you extinguished the Alliance's Wickerman, <class>?", completion = "Ah, so it is done.  A momentary setback, but if it is as annoying as their attacks have been, then it is worth it.\n\nThe children learned about your adventure and were very excited.  They seemed to revel in the mayhem that you helped bring about... Oh those little rascals...\n\nThey did want you to have some of these treats as a reward.  Enjoy, <name>." }
WordHunterWoW_QuestEN[29378] = { title = "FLAG - Teleport to Vashj'ir", description = "", objectives = "" }
WordHunterWoW_QuestEN[29379] = { title = "FLAG - Teleport to Deepholm", description = "", objectives = "" }
WordHunterWoW_QuestEN[29380] = { title = "FLAG - Teleport to Firelands", description = "", objectives = "" }
WordHunterWoW_QuestEN[29381] = { title = "FLAG - Teleport to Hyjal", description = "", objectives = "" }
WordHunterWoW_QuestEN[29382] = { title = "Thanks, But No Thanks", description = "A holiday sweater may not be for everyone.\n\nThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.\n\nAll exchanges are final.", objectives = "If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant.\n\nAll exchanges are final." }
WordHunterWoW_QuestEN[29383] = { title = "Thanks, But No Thanks", description = "A holiday sweater may not be for everyone.\n\nThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.\n\nAll exchanges are final.", objectives = "If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant.\n\nAll exchanges are final." }
WordHunterWoW_QuestEN[29385] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[29386] = { title = "Hero's Call: Mount Hyjal!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade." }
WordHunterWoW_QuestEN[29387] = { title = "Guardians of Hyjal: Firelands Invasion!", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal immediately.", objectives = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "Thank you for answering our call for aid, <name>." }
WordHunterWoW_QuestEN[29388] = { title = "Guardians of Hyjal: Firelands Invasion!", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied champions of the Horde should report to the Sanctuary of Malorne in Mount Hyjal immediately.", objectives = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "Thank you for answering our call for aid, <name>." }
WordHunterWoW_QuestEN[29389] = { title = "Guardians of Hyjal: Firelands Invasion!", description = "Your work has given us the advantage we need to mobilize against the denizens of the Firelands. We are gathering our invasion force just south of our position.\n\nWe could use your strength again, {race}. Speak with Matoclaw at the Sanctuary of Malorne. She is coordinating the invasion effort.", objectives = "Report to Matoclaw at the Sanctuary of Malorne in Mount Hyjal.", completion = "Thank you for answering our call for aid, <name>." }
WordHunterWoW_QuestEN[29390] = { title = "Guardians of Hyjal: Call of the Ancients", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.\n\nWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Lo'gosh, Tortolla, Aviana, and Aessina.\n\nNew travelers to Mount Hyjal may look for a Warchief's Command to Hyjal on any Horde call board.", objectives = "Assist Lo'gosh, Tortolla, Aviana, and Aessina in Mount Hyjal." }
WordHunterWoW_QuestEN[29391] = { title = "Guardians of Hyjal: Call of the Ancients", description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.\n\nWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Goldrinn, Tortolla, Aviana, and Aessina.\n\nNew travelers to Mount Hyjal may look for a Hero's Call to Hyjal on any Alliance board.", objectives = "Assist Goldrinn, Tortolla, Aviana, and Aessina in Mount Hyjal." }
WordHunterWoW_QuestEN[29392] = { title = "Missing Heirlooms", description = "The last of my belongings were supposed to be arriving from Theramore today. The ship has arrived, but I haven't heard from the courier. The crate he was transporting had items that've been in my family for generations.\n\nWill you go down to Stormwind Harbor and see what's keeping him?", objectives = "Search the cabin of the Hired Courier's ship in Stormwind Harbor for evidence of what might be delaying him.", progress = "The crate that Anson described doesn't appear to be here...", completion = "This courier won't be meeting with his employer anytime soon and the crate he was hired to transport seems to have disappeared." }
WordHunterWoW_QuestEN[29393] = { title = "Brew For Brewfest", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", objectives = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", completion = "That crash between here and Bladefist Bay really messed up the brew flow!  It doesn't help that Dark Iron dwarves seem to be attacking every hour or so!\n\nSo if you want to help, here's the deal.  I'll let you borrow one of my rams.\n\nEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!\n\nBUT, once you start this, you won't be able to do it again until tomorrow.\n\nAre you sure you're ready to do this?" }
WordHunterWoW_QuestEN[29394] = { title = "Brew For Brewfest", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", objectives = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", completion = "There's always a need for more kegs at Brewfest, and Kharanos has a lot of kegs they can spare!\n\nI'll lend you one of my personal rams.\n\nEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!\n\nTake heed! Once you start this, you won't be able to do it again until tomorrow.\n\nAre you sure you're ready to do this?" }
WordHunterWoW_QuestEN[29395] = { title = "FLAG - Teleport to Uldum", description = "", objectives = "" }
WordHunterWoW_QuestEN[29396] = { title = "A New Supplier of Souvenirs", description = "<sigh>\n\nDon't talk to me about last year's stein...\n\nI think our shady stein suppliers were somehow involved with that Twilight Hammer cult non-sense that errupted just before the elementals invaded.\n\nAnd that's why we have a new supplier and a better stein!\n\nHere's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "What's this?  A stein voucher?  So you like drinking?  Great!  After I give you this stein, go have a few drinks!  Then a few more.  Maybe have a few more after that...  Then, now this is important, come see me.\n\nLook, I know you'll be back eventually.  If you want your Brewfest tokens redeemed you have to see me.\n\nAnyways, here's the stein, and remember to talk to me later." }
WordHunterWoW_QuestEN[29397] = { title = "A New Supplier of Souvenirs", description = "The less said about last year's stein, the better, {name}.  I'll tell you this, our previous supplier, they were shady.  Turns out they were involved in some cultist activities...\n\nWe can't work with people who are trying to destroy the world!!\n\nSo we have a new supplier and a new stein.\n\nTake this voucher to Belbi Quikswitch  near the back of the Brewfest camp.  She'll give you your free Brewfest stein.  She'll also handle any and all other Brewfest transactions that come up during the holiday.", objectives = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "Aww, it's just a stein voucher... Maybe you're just playing hard to get.  So here's this year's stein for you.\n\nBut I suspect I'll be seeing a lot more of you.  After all, if you want any Brewfest tokens redeemed, I'm your girl...\n\nOr maybe I'm his girl...  \n\nOooohhh... or his..." }
WordHunterWoW_QuestEN[29398] = { title = "Fencing the Goods", description = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished.\n\nAs you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", objectives = "Follow the spiders to their destination and question the man you find there.", progress = "Why are you still pestering me?", completion = "Keep your voice down and don't let word of this get out or I'm finished as an auctioneer!" }
WordHunterWoW_QuestEN[29399] = { title = "Shopping Around", description = "I told the 'gentleman' that there might be a shop more suited to his needs in the Dwarven District. It's called the Shady Lady and you can find the entrance near the Canals on the western side of the district.\n\nQuincy Cutler is your man. He trades in merchandise an honest broker would never touch!", objectives = "Make your way to the Shady Lady in Stormwind's Dwarven District and look for evidence of the crate-thief's visit.", progress = "You look like you know something about these missing goods.", completion = "Finally, Cutler's given me something I can work with. Before I give up that information, I'm going to want to know who you're working for." }
WordHunterWoW_QuestEN[29400] = { title = "A Season for Celebration", description = "Well met, {class}.\n\nHallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken.\n\nTravel to the Ruins of Lordaeron and speak to Darkcaller Yanka. She can tell you more about the Wickerman ceremony.", objectives = "Speak with Darkcaller Yanka in the Ruins of Lordaeron.", completion = "The Wickerman ceremony is a time honored tradition.  It is good to see the Horde joining us in celebration." }
WordHunterWoW_QuestEN[29401] = { title = "Blown Away", description = "Please, mister, you just gotta help me!\n\nMy pa brought me a bunch of balloons from the Darkmoon Faire. Best... gift... EVER! They're magical, you know, and never lose their floatiness!\n\nThere's just one thing...\n\nA big ol' gust of wind blew 'em right outta my hands. They're scattered all over Orgrimmar!\n\nI'd chase after 'em myself, but this city's so big I'd get lost for sure.\n\nCan you round 'em up for me before they float away?\n\nPlease?", objectives = "Jaga wants you to collect 5 Windswept Balloons from Orgrimmar.", progress = "Did you find all of my balloons, mister?", completion = "This is GREAT! You did it!\n\nThanks, mister!" }
WordHunterWoW_QuestEN[29402] = { title = "Taking Precautions", description = "I'd be wary of anyone identifying himself as the rightful owner of the crate and its contents. He didn't warn you of the danger?\n\nHere's a better idea: let's work together to recover the crate and ensure that its contents can't hurt anyone. To protect ourselves, we're going to need a draught made from a few ingredients that can be found around the city.\n\nAcquire some strange dust, get vials from an alchemy merchant, and pick some blood nettle from the fields north of the city.", objectives = "Obtain 2 Strange Dust, 5 Crystal Vials, and 5 Blood Nettle.", progress = "Did you get all the ingredients?", completion = "Sometimes, I think I should've followed my father into alchemy.\n\nThis concoction should protect us from the worst effects of carrying or handling the crate. Bottoms up!" }
WordHunterWoW_QuestEN[29403] = { title = "The Collector's Agent", description = "According to Quincy, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara.\n\nThe archmage's faithful servant is to meet with the man who has the crate in the catacombs beneath the Cathedral of Light.\n\nYou must get there in time to intercept the exchange and retrieve the crate before it is lost to Xylem forever. When you have the crate, meet me at the Golden Keg.", objectives = "Disrupt the meeting between Sanath Lim-yo and the thief in the catacombs beneath the Cathedral of Light.", completion = "Tendrils of dark power dance around the crate, but there's no trace of Sanath Lim-yo. You can now claim the crate and return it to your employer." }
WordHunterWoW_QuestEN[29404] = { title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", objectives = "Speak to Master Shang Xi.Fresh to your training, your first task is simple: Speak to Master Shang Xi.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29405] = { title = "The Lesson of the Iron Staff", description = "To train, first you must be properly equipped. Retrieve a weapon from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", objectives = "Loot a training weapon from a weapon rack and then equip it." }
WordHunterWoW_QuestEN[29406] = { title = "The Lesson of the Sandy Fist", description = "I'd like to observe you putting your new weapon to use, my young student. This will aid me in determining what degree of training will be best suited to your talents.\n\nWe have many training targets in the training grounds below. Practice your attacks upon them, and return to me once you're feeling comfortable with your new weapon.", objectives = "Destroy 5 Training Targets.", progress = "The training targets are just down the hill. Come back to me once you're finished.", completion = "Not bad, <name>. You may indeed have chosen the proper path.\n\nGood. Let us continue." }
WordHunterWoW_QuestEN[29407] = { title = "The First Sign of Winter", description = "At the stream below rests a single lotus flower. Within this lotus lies a sign of things to come. Bring it to me that I might show you.", objectives = "Recover the Shimmering Lotus." }
WordHunterWoW_QuestEN[29408] = { title = "The Lesson of the Burning Scroll", description = "Every wisdom has a time and place, and times are changing for those of us living here on Shen-zin Su. For this lesson, I would ask two things of you.\n\nFor the first, I hold a flame in my hand. Gather your wits, and when you think you are ready, attempt to snatch the flame.\n\nShould you succeed, I want you to then climb to the top of this temple and burn the Edict of Temperance that you find there.", objectives = "Snatch the flame from Master Shang Xi's palm, then burn the Edict of Temperance.", progress = "There will come time when you must trust your instincts and simply act.", completion = "The fact that you were able to snatch the flame so easily is no small feat.\n\nThe Edict of Temperance is a scroll of wisdom passed down from my elders' elders. Wisdom from a more peaceful time.\n\nEvery lesson has its time and place, and with darkness on the horizon, the time for this particular wisdom has passed.\n\nThe burning of the scroll is an acceptance of tidings to come and a promise to action. Your hand carried the flame, and I suspect that it will continue to do so in the future." }
WordHunterWoW_QuestEN[29409] = { title = "The Disciple's Challenge", description = "{name}, I see great strength and great courage in you, and an unsurpassed purity of soul.\n\nThe hour is young, but I think you may be ready to face a greater challenge.\n\nGo to the bottom of the stairs, and cross the bridge. There, you will find Jaomin Ro, one of our eldest students. Challenge and defeat him in honorable combat, and this first phase of your training will be complete.", objectives = "Defeat Jaomin Ro.", completion = "You truly impress, <name>. It seems certain that the path of the <class> is indeed the path for you." }
WordHunterWoW_QuestEN[29410] = { title = "Aysa of the Tushui", description = "In such a short time, you've shown me that you have the potential to be a great {class}. The training grounds are behind you, but now you must prove yourself by facing a far greater challenge, one that none of my students have accomplished.\n\nI want you to return Huo, the spirit of fire, to the Temple of Five Dawns.\n\nMy two other most gifted students will help you in this task. The first is Aysa Cloudsinger. Seek her out at the pool to the west.", objectives = "Speak to Merchant Lorvo by Fu's Pond.", completion = "You came for Aysa? You... you really shouldn't interrupt her until she finishes her exercises. She doesn't speak to anyone until her routine is done.\n\nIn the meantime, could you maybe help me? I had some bad luck with forest sprites." }
WordHunterWoW_QuestEN[29411] = { title = "What Now?", description = "You've finally found the crate that Anson sent you to retrieve. However, it appears the archaeology student's warnings about the nature of the crate's contents were correct.\n\nThere's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Hudson Barnes, who believes it better to keep the crate's contents locked away?", objectives = "Return the crate to Anson Hastings at the Gilded Rose in Stormwind.\n\n-OR-\n\nReturn the crate to Hudson Barnes at the Golden Keg in Stormwind.", progress = "Have you brought the crate as we discussed?", completion = "Ah, you did manage to get the crate before Archmage Xylem's man could get it out of the city. Excellent!" }
WordHunterWoW_QuestEN[29412] = { title = "Blown Away", description = "Please, mister, you just gotta help me!\n\nFather bought me a bunch of balloons from the Darkmoon Faire. They're magical, you know, and never lose their floatiness!\n\nThere's just one thing...\n\nA gust of wind blew them out of my hands. They're scattered all over Stormwind!\n\nI'd chase after them myself, but this city's so big I'd get lost for sure.\n\nCan you find them for me before they float away?\n\nPlease?", objectives = "Vin wants you to collect 5 Windswept Balloons from Stormwind.", progress = "Did you find all of my balloons, mister?", completion = "This is GREAT! You did it!\n\nThanks, mister!" }
WordHunterWoW_QuestEN[29413] = { title = "The Creepy Crate", description = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems bonded to you and now it's yours.", objectives = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems to have an affinity for you and now, it's yours." }
WordHunterWoW_QuestEN[29414] = { title = "The Way of the Tushui", description = "It's a pleasure to meet you, {class}. I am Aysa, of the Tushui.\n\nI've spent much time in thought since Master Shang told me we would be searching for Huo, the spirit of fire. I know where he resides, but not how to reach him. The answers are close, however.\n\nCome with me to the Cave of Meditation nearby. It is a place of great wisdom. I will meditate there, open my mind, and the path shall find us.", objectives = "Protect Aysa while she meditates.", completion = "Your path is set before you. You will be the one to rekindle the spirit of fire and bring it to the safety of the temple.\n\nThis will not be the only time you and Aysa work together. She is strong and wise. You can trust in her." }
WordHunterWoW_QuestEN[29415] = { title = "Missing Heirlooms", description = "I told that courier to take the zeppelin, but no, he had to use the goblin ship! Well, now he's late and my precious family heirlooms are with him.\n\nIf you're willing to help, would you go down to the docks east of Orgrimmar, board the goblin ship and see what's keeping him?", objectives = "Search the cabin of the Hired Courier's ship at the docks east of Orgrimmar  for evidence of what might be delaying him.", completion = "This courier won't be meeting with his employer anytime soon and the crate he was hired to transport seems to have disappeared." }
WordHunterWoW_QuestEN[29416] = { title = "Fencing the Goods", description = "A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished.\n\nAs you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?", objectives = "Follow the spiders to their destination and question the man you find there.", progress = "Why are you still pestering me?", completion = "Keep your voice down and don't let word of this get out or I'm finished as an auctioneer!" }
WordHunterWoW_QuestEN[29417] = { title = "The Way of the Huojin", description = "We call those vicious monkeys swinging into town hozen. They keep to themselves normally, but they know something bad is coming, so they're here to steal our supplies.\n\nIn situations like this, the clear answer is the only answer. These monkeys will leave when we force them to leave! To not defend our town and those we love would be the only true crime. Thus is the way of the Huojin.", objectives = "Kill 8 Fe-Feng attackers.", completion = "You've got some fight in you! I think I like you!" }
WordHunterWoW_QuestEN[29418] = { title = "Kindling the Fire", description = "Now that that's done with, let's get to it then!\n\nHuo, the spirit of fire, hungers for dry dogwood root kindling. It grows among the trees south of the village. It should be easy enough for you to gather some.", objectives = "Gather 5 Dry Dogwood Roots.", progress = "I hope you're not shy about getting your hands dirty.", completion = "<name>! You've returned, roots in hand! You're a down-to-business kind of guy, aren't you? I like that!" }
WordHunterWoW_QuestEN[29419] = { title = "The Missing Driver", description = "My driver went running off after the sprites just after they attacked. I don't think they'll really do him any harm, but I need him back to help me clean up the mess by the cart.\n\nHe chased them off towards the cliffs to the north. If you head that direction, you should find him quickly.", objectives = "Rescue the Cart Driver.", completion = "You are too kind, <class>." }
WordHunterWoW_QuestEN[29420] = { title = "The Spirit's Guardian", description = "You've done very well this far, my student. You have the materials you need to rekindle Huo, the spirit of fire.\n\nIn the cave to the southwest he awaits, but he is guarded by Master Li Fei, the pandaren elder you met in the Cave of Meditation. Go to Master Li Fei with the offerings. Prove yourself, then meet with Huo.", objectives = "Speak to Master Li Fei in the Shrine of Inner-Light.", completion = "Life isn't about finding yourself. Life is about creating yourself. There is a path before you, but you choose the trials you will face, and the trials you will overcome." }
WordHunterWoW_QuestEN[29421] = { title = "Only the Worthy Shall Pass", description = "It is time for you to face me. With these three fires illuminating your potential, we will see with certainty whether your resolved soul is truly worthy of passing.", objectives = "Defeat Master Li Fei in combat.", completion = "Remember always, the superior warrior is modest in his speech, but exceeds in his actions." }
WordHunterWoW_QuestEN[29422] = { title = "Huo, the Spirit of Fire", description = "You are worthy of passing, {class}.\n\nHuo, the spirit of fire rests in the chamber beyond. Let him feast upon the kindling you've gathered, and use the wind to fan his flames. Doing so should endear you to him. Once he is ignited, if he is willing, lead him to the Temple of Five Dawns, the building standing high in the center of the island.", objectives = "Reignite Huo, the spirit of fire.", progress = "<Huo rests quietly within the pool.>", completion = "<Through the glare, it looks like Huo is smiling. He seems to have warmed up to you.>" }
WordHunterWoW_QuestEN[29423] = { title = "The Passion of Shen-zin Su", description = "<Huo bounces around excitedly, ready to follow you.>\n\n<Master Shang Xi told you to bring Huo to meet him at the Temple of Five Dawns in the center of the island. Your next destination lies before you.>", objectives = "Bring the Spirit of Fire to the Temple of Five Dawns.", completion = "<name>, you've done very well. Huo, the spirit of fire, is here. The temple flames are reignited. You accomplished the challenge I put before you, and with seeming ease.\n\nThere is a greater purpose in bringing Huo to the temple. It is time that I tell you more of things to come." }
WordHunterWoW_QuestEN[29424] = { title = "Items of Utmost Importance", description = "Amberleaf scamps swarmed my cart and stole most of the training supplies I was bringing up to the training grounds. They've always been troublemakers, but they've never been this aggressive before. I don't know what happened.\n\nPlease, help me recover my supplies.", objectives = "Recover 6 Training Supplies from Amberleaf Scamps.", progress = "You needn't worry about hurting the sprites. They're really just living plants when it comes down to it - they'll resprout later.", completion = "Thank you! You're an honorable <class>. They've taught you well." }
WordHunterWoW_QuestEN[29425] = { title = "Shopping Around", description = "Look, I told that shady character that there might be a shop more open to his, uh, wares in the Drag. Droffer's and Son Salvage is the name of the place.\n\nLook for Dran Droffers. He oversees the 'salvage' of rare and valuable objects from all over Azeroth.", objectives = "Make your way to Droffers and Son Salvage in Orgrimmar's Drag district and look for evidence of the crate-thief's visit.", progress = "You look like you know something about these missing goods.", completion = "Leave it to Droffers to have a buyer lined up already. We should combine our efforts to track down this thief and keep the crate's contents from falling into the wrong hands." }
WordHunterWoW_QuestEN[29426] = { title = "Taking Precautions", description = "So someone else hired you to retrieve this crate? I don't like the sound of that.\n\nThat crate's contents belong in the care of the Reliquary. The items it holds are very powerful and very dangerous.\n\nWe have to find the meeting that Dran set up between the thief and the collector, but first, we'll need to protect ourselves from the effects of handling that crate.\n\nAcquire some strange dust, get vials from an alchemy merchant, and pick some blood nettle in the Valley of Wisdom.", objectives = "Obtain 2 Strange Dust, 5 Crystal Vials, and 5 Blood Nettle.", progress = "Did you get all the ingredients?", completion = "Let's see what I can remember from the alchemy lessons of my youth. If it explodes, I've done something wrong.\n\nThis concoction should protect us from the worst effects of carrying or handling the crate." }
WordHunterWoW_QuestEN[29427] = { title = "The Collector's Agent", description = "According to Dran, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara.\n\nThe archmage's faithful servant is to meet with the man who has the crate in a secluded corner of the courtyard in the Ruins of Lordaeron.\n\nQuickly, take the zeppelin to Tirisfal Glade!\n\nYou must get there in time to intercept the exchange and retrieve the crate before Xylem gets his hands on it. If you can get the crate, meet me at the Wyvern's Tail in the Valley of Honor.", objectives = "Disrupt the meeting between Sanath Lim-yo and the thief in the Ruins of Lordaeron.", progress = "This appears to be the sought-after crate.", completion = "Tendrils of dark power dance around the crate, but there's no trace of Sanath Lim-yo. You can now claim the crate and return it to your employer." }
WordHunterWoW_QuestEN[29428] = { title = "What Now?", description = "You've finally found the crate that Edgar Goodwin sent you to retrieve. However, it appears the Reliquary representative's warnings about the nature of the crate's contents were correct.\n\nThere's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Delian Sunshade, who believes it better to keep the crate's contents locked away?", objectives = "You may return the crate to either Edgar Goodwin at the Broken Tusk in Orgrimmar's Valley of Strength.\n\n-OR-\n\nReturn the crate to Delian Sunshade at the Wyvern's Tail in Orgrimmar's Valley of Honor.", progress = "Have you brought the crate as we discussed?", completion = "I never thought you'd be able to recover it. Well, let's see it." }
WordHunterWoW_QuestEN[29429] = { title = "The Creepy Crate", description = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems bonded to you and now it's yours.", objectives = "It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him.\n\nYet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive.\n\nIt seems to have an affinity for you and now, it's yours." }
WordHunterWoW_QuestEN[29430] = { title = "A Friend in Need", description = "You know, I haven't seen Anson out here yet.\n\nLately, he's been spending all his time drinking himself into a stupor at the Gilded Rose.\n\nSomething must really be bothering him! Would you mind checking in on him?", objectives = "Visit Anson Hastings at the Gilded Rose in Stormwind's Trade District.", completion = "What do you want?\n\nI'm never going to finish my research, <race>. It's my life's work, and now the courier with the experimental reagents I need is late!" }
WordHunterWoW_QuestEN[29431] = { title = "A Friend in Need", description = "There's something wrong with my friend, Edgar. Normally, he loves the Hallow's End festivities, but he's been sullen and reclusive lately.\n\nHe spends all his time in the Broken Tusk in Orgrimmar drinking with the orcs. Would you mind stopping by and seeing if there's anything you can do to cheer him up?", objectives = "Speak with Edgar Goodwin at the Broken Tusk in Orgrimmar.", completion = "What do you want?\n\nCandace sent you? She knows me too well. I've hit a rut in my research and I've been waiting for a very important delivery, but the courier's late..." }
WordHunterWoW_QuestEN[29432] = { title = "Delegation Tracker", description = "I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the world tree's branch.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the Branch of Nordrassil from the Firelands.I am duty-bound to look into your claims immediately, <race>, which means my mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the world tree's branch.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29433] = { title = "Test Your Strength", description = "For some people, it's all fun and games until someone gets hurt.  I call those people, weak.\n\nTo be the strongest, you have to hurt someone or something.  You hurt yourself as you push your body to its limits.  You hurt those that threaten the well-being of others.\n\nIf you want to be the strongest, you have to fight.  How bad do you want it?\n\nI want you to crush those that would offer a challenge to you, then bring me back proof of your triumphs.", objectives = "Kerri Hicks wants you to collect 250 Grisly Trophies. Trophies are obtained as long as you kill creatures that offer experience or honor and you have the Darkmoon Adventurer's Guide with you.", progress = "No pain, no gain.", completion = "Did you seek out worthy challenges, or did you simply find some field of boars and slaughter them?\n\nThere is a reason I am the strongest.\n\nPerhaps, one day you will see just how strong I really am, <class>.  Until then, keep pushing yourself.  But don't forget to take a break from time to time.\n\nLike now.  Here, enjoy the Darkmoon Faire." }
WordHunterWoW_QuestEN[29434] = { title = "Tonk Commander", description = "Welcome to our humble little steam tank battle simulator!\n\nFor one token, you can demonstrate your tactical mastery by navigating the course and destroying the targets.", objectives = "Use your Darkmoon Tonk to destroy 30 Tonk Targets in the time allowed.", progress = "Have tonk, will travel!", completion = "An impressive display!\n\nHere's your reward." }
WordHunterWoW_QuestEN[29436] = { title = "The Humanoid Cannonball", description = "For just one Darkmoon Game Token, you can ride the Blastenheimer 5000 Ultra Cannon.  But the fun doesn't end there!  We've placed a target in the water near the boardwalk.\n\nIf you can score five points from your landing, you can win some prize tickets!\n\nA bullseye gets you five points, a close shot three, and landing at least near it gets you one.\n\nHappy landings!", objectives = "Accumulate 5 Cannon Target Points by landing near the target.", progress = "Happy landings!", completion = "Five points?  Good job!  Here are your prize tickets.\n\nEnjoy the rest of the Darkmoon Faire!" }
WordHunterWoW_QuestEN[29437] = { title = "The Fallen Guardian", description = "Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon Alysra - one of my very own! - who was in charge of keeping Fandral secure.\n\nWe can only conclude that the Twilight's Hammer has gotten to her. You must confront her, {name}. Destroy her if you must - I cannot bear to see it.\n\nShe was last seen in the Ruins of Lar'donir, west of the World Tree.", objectives = "Confront and slay Alysra at the Ruins of Lar'donir in Mount Hyjal." }
WordHunterWoW_QuestEN[29438] = { title = "He Shoots, He Scores!", description = "Think you're a good shot?  Quick on the trigger?\n\nIt'll cost you just a single game token to test your skills.\n\nWhat do you say?  How good are you?", objectives = "Score 25 points in 60 seconds.", progress = "Shooting static targets isn't always as easy at it seems.", completion = "I knew you could do it, <class>!  Here's your prize.  Enjoy the faire." }
WordHunterWoW_QuestEN[29439] = { title = "The Call of the World-Shaman", description = "The Earthen Ring calls to you once more, {name}.\n\nAs a member of the Alliance, I know that you may have reservations working with the one you call Thrall, the former Warchief of the Horde. But he has specifically requested an Alliance hero to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.\n\nCast aside your doubts, {class}, and heed the world-shaman's call.\n\nYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree.", objectives = "Speak with Thrall just south of the World Tree in Mount Hyjal.", completion = "It would appear my message has been heard in Stormwind.\n\nThank you, <name>. Let us get to work..." }
WordHunterWoW_QuestEN[29440] = { title = "The Call of the World-Shaman", description = "The Earthen Ring calls to you once more, {name}.\n\nThrall has cast aside his mantle as warchief of the Horde, but in his new role he needs the support of his people more than ever. He has requested one of the Horde's finest to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world.\n\nYou will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. Heed the call!", objectives = "Speak with Thrall just south of the World Tree in Mount Hyjal.", completion = "I see my message has reached Orgrimmar.\n\nThank you, <name>. Let us get to work..." }
WordHunterWoW_QuestEN[29441] = { title = "From the Belly of the Beast", description = "", objectives = "" }
WordHunterWoW_QuestEN[29443] = { title = "A Curious Crystal", description = "Power swirls inside this strange crystal. Perhaps it was once a magical focus, an energy source, or simply a good luck charm. There's no way to know for certain.\n\nThe Darkmoon Adventurer's Guide indicates that the crystal would be of interest to Professor Thaddeus Paleo at the Darkmoon Faire.", objectives = "Bring the Imbued Crystal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "Where did you get this crystal?\n\nThese are very rare and much sought-after by collectors. I would like to study this one and display it at the Faire. Would you accept a generous number of Darkmoon Faire tickets in trade?" }
WordHunterWoW_QuestEN[29444] = { title = "An Exotic Egg", description = "You're not certain what kind of creature this egg harbors, but it sure doesn't look like the egg of any ordinary animal.\n\nThe Darkmoon Adventurer's Guide says that an intrepid adventurer might come across any number of strange eggs in his travels. It further notes that the Darkmoon Faire's Zoo Bizarre is always interested in acquiring such specimens.\n\nTake the egg to Yebb Neblegear at the Darkmoon Faire.", objectives = "Bring the Monstrous Egg to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "Where did you find this egg? There's sure to be something monstrous and wonderful inside! It will make a great addition to our zoo. Are you willing to part with it for a generous number of Darkmoon tickets?" }
WordHunterWoW_QuestEN[29445] = { title = "An Intriguing Grimoire", description = "This massive spellbook reveals very little of its origins. Its pages are filled with a variety of spells and enchantments, only a few of which are familiar.\n\nThe Darkmoon Adventurer's Guide says the tome may be of some interest to Sayge, the famous gnoll fortuneteller at the Darkmoon Faire.", objectives = "Bring the Mysterious Grimoire to Sayge at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "A strange grimoire, how interesting! I don't think I've seen its like before. I'd love to have it for my collection. Would you be willing to accept Darkmoon tickets in exchange?" }
WordHunterWoW_QuestEN[29446] = { title = "A Wondrous Weapon", description = "An inspection of the weapon reveals expert craftsmanship and intricate inlay work, but this is no ceremonial blade. Faint marks and nicks along the blade attest to its use in combat.\n\nThe Darkmoon Adventurer's Guide lists several types of rare and valuable weapons, leaving no doubt that Professor Thaddeus Paleo at the Darkmoon Faire would be interested in taking a look at this piece.", objectives = "Bring the Ornate Weapon to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "Where did you find such a wonderful blade?\n\nThis is a work of astounding craftsmanship and worthy weapon for any champion. I would love to have it for display.\n\nWould you accept a generous number of Darkmoon Faire tickets in trade?" }
WordHunterWoW_QuestEN[29447] = { title = "A Curious Crystal", description = "Power swirls inside this strange crystal. Perhaps it was once a magical focus, an energy source, or simply a good luck charm. There's no way to know for certain.\n\nThe Darkmoon Adventurer's Guide indicates that the crystal would be of interest to Professor Thaddeus Paleo at the Darkmoon Faire.You will receive:", objectives = "Bring the Imbued Crystal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island." }
WordHunterWoW_QuestEN[29448] = { title = "An Exotic Egg", description = "You're not certain what kind of creature this egg harbors, but it sure doesn't look like the egg of any ordinary animal.\n\nThe Darkmoon Adventurer's Guide says that an intrepid adventurer might come across any number of strange eggs in his travels. It further notes that the Darkmoon Faire's Zoo Bizarre is always interested in acquiring such specimens.\n\nWhen the Faire open, take this egg to Yebb Nebelgear near the animal pens.You will receive:", objectives = "Bring the Monstrous Egg to Yebb Neblegear when the Darkmoon Faire is running." }
WordHunterWoW_QuestEN[29449] = { title = "An Intriguing Grimoire", description = "This massive spellbook reveals very little of its origins. Its pages are filled with a variety of spells and enchantments, only a few of which are familiar.\n\nThe Darkmoon Adventurer's guide says the tome may be of some interest to Sayge, the Faire's famous fortuneteller. Look for him near his tent on Darkmoon Island.You will receive:", objectives = "Bring the Mysterious Grimoire to Sayge when the Darkmoon Faire is running." }
WordHunterWoW_QuestEN[29450] = { title = "A Woundrous Weapon", description = "An inspection of the weapon reveals expert craftsmanship and intricate inlay work, but this is no ceremonial blade. Faint marks and nicks along the blade attest to its use in combat.\n\nThe Darkmoon Adventurer's Guide lists several types of rare and valuable weapons, leaving no doubt that Professor Thaddeus Paleo at the Darkmoon Faire would be interested in taking a look at this piece.You will receive:", objectives = "Bring the Ornate Weapon to Professor Thaddeus Paleo when the Darkmoon Faire is running." }
WordHunterWoW_QuestEN[29451] = { title = "The Master Strategist", description = "This tome of strategy is the masterwork of the famous human general, Anduin Lothar. In his own words, the commander describes the proper deployment of forces and strategies needed to win almost any battle.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire would probably love to have a look at such a rare book.", objectives = "Take A Treatise on Strategy to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "That doesn't look like a common book at all...", completion = "I don't know how you got your hands on this, and I know better than to ask. Could I convince you to part with it in exchange for Darkmoon tickets?" }
WordHunterWoW_QuestEN[29452] = { title = "Your Time Has Come", description = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.>\n\nYoung {class}, be still and hear my words.\n\nI am called to collect you, to deliver you, to one whose eye none can escape.\n\nFind me in Orgrimmar, mortal, for your time has come.", objectives = "Speak to Ziradormi in Orgrimmar.", completion = "Let us begin, mortal.\n\nThere is little time to spare." }
WordHunterWoW_QuestEN[29453] = { title = "Your Time Has Come", description = "<A pleasant image fills your mind's eye as a calm voice echoes through your being.>\n\nYoung {class}, be still and hear my words.\n\nI am called to collect you, to deliver you, to one whose eye none can escape.\n\nFind me in Stormwind, mortal, for your time has come.", objectives = "Speak to Coridormi in Stormwind.", completion = "Let us begin, mortal.\n\nThere is little time to spare." }
WordHunterWoW_QuestEN[29454] = { title = "The Master Strategist", description = "This tome of strategy is the masterwork of the famous human general, Anduin Lothar. In his own words, the commander describes the proper deployment of forces and strategies needed to win almost any battle.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire would probably love to have a look at such a rare book. Look for him at the faire's home on Darkmoon Island.You will receive:", objectives = "Take A Treatise on Strategy to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island." }
WordHunterWoW_QuestEN[29455] = { title = "Target: Turtle", description = "Hey there! Step right up!\n\nWhy not show everyone how skilled you are?  Just land three rings on the Darkmoon Turtle and you'll get a prize.\n\nFor one game token you can buy a stack of rings and show the world why we call you the \"Eagle Eyed {class}.\"", objectives = "Land 3 rings on the Darkmoon Turtle.", progress = "How's that throwin' arm, champ?", completion = "I knew you could do it!\n\nWe'll take any extra rings you might have, and give you your prize ticket.\n\nHave fun!" }
WordHunterWoW_QuestEN[29456] = { title = "A Captured Banner", description = "This tattered banner bears a faded guild crest. This old banner must've seen more than its share of battles.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire collects banners and other relics of combat and he might be interested in acquiring this one. Show the banner to him next time you visit the Darkmoon Faire.", objectives = "Bring the Banner of the Fallen to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "What a splendid banner! I'd love to have it for my collection.\n\nWould you be willing to trade it for some Darkmoon tickets?" }
WordHunterWoW_QuestEN[29457] = { title = "The Enemy's Insignia", description = "This battered badge carries the insignia of an enemy officer. While worth little more to you than the metal it's made from, this piece would have significant value to a collector of military memorabilia.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire is famous all over Azeroth for his large collection of military artifacts. Show the badge to him the next time you visit the Darkmoon Faire.", objectives = "Bring the Captured Insignia to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "This is a remarkable example of an officer's insignia. While many of them visit the Faire, none are willing to part with their badges. Would you be willing to accept some Darkmoon tickets in trade?" }
WordHunterWoW_QuestEN[29458] = { title = "The Captured Journal", description = "This book is covered in battered leather stained with blood and mud. Leafing through the pages, you discover that it is a personal journal of an adventurer with a high opinion of himself and his adventures.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire might want to see something like this.", objectives = "Bring the Adventurer's Journal to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What is it you have there?", completion = "A remarkable find!\n\n<The professor browses the book's contents.>\n\nSome of these are hard to read, but if even a third of the contents of this journal are true, this is a real treasure. Would you trade it for a generous number of Darkmoon tickets?" }
WordHunterWoW_QuestEN[29459] = { title = "A Captured Banner", description = "This tattered banner bears a faded guild crest. This old banner must've seen more than its share of battles.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire collects banners and other relics of combat and he might be interested in acquiring this one.You will receive:", objectives = "Bring the Banner of the Fallen to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island." }
WordHunterWoW_QuestEN[29460] = { title = "The Enemy's Insignia", description = "This battered badge carries the insignia of an enemy officer. While worth little more to you than the metal it's made from, this piece would have significant value to a collector of military memorabilia.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire is famous all over Azeroth for his large collection of military artifacts.You will receive:", objectives = "Bring the Captured Insignia to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island." }
WordHunterWoW_QuestEN[29461] = { title = "The Captured Journal", description = "This book is covered in battered leather stained with blood and mud. Leafing through the pages, you discover that it is a personal journal of a Horde adventurer with a high opinion of herself and her adventures.\n\nProfessor Thaddeus Paleo of the Darkmoon Faire might want to see something like this.You will receive:", objectives = "Bring the Captured Insignia to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island." }
WordHunterWoW_QuestEN[29463] = { title = "It's Hammer Time", description = "So you want to whack some gnolls?  Well you've come to the right place.\n\nYour goal is simple, score 30 points in a minute.\n\nUse the mallet I give you and get ready to whack.  Speak to me when you are ready to start.", objectives = "Score 30 points by whacking Gnolls.", progress = "How did you do out there?", completion = "So you have managed to defeat the gnolls.  It felt good, didn't it?\n\nHere is your prize.  Enjoy the rest of the Darkmoon Faire!" }
WordHunterWoW_QuestEN[29464] = { title = "Tools of Divination", description = "This collection of well-worn runestones has seen much use. The pieces seem old; you can't recognize any of the markings on their surfaces.\n\nPerhaps a scholar or a collector would know more about them. Bring them to Professor Thaddeus Paleo next time you're at the Darkmoon Faire.", objectives = "Bring the Soothsayer's Runes to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island.", progress = "What do you have there?", completion = "Where did you find this collection of runes? I haven't seen anything like this in years. It'll be a splendid mystery to unravel!\n\nWould you trade these for Darkmoon tickets?" }
WordHunterWoW_QuestEN[29465] = { title = "Tools of Divination", description = "This collection of well-worn runestones has seen much use. The pieces seem old; you can't recognize any of the markings on their surfaces.\n\nPerhaps a scholar or a collector would know more about them. Bring them to Professor Thaddeus Paleo at the Darkmoon Faire.You will receive:", objectives = "Bring the Soothsayer's Runes to Professor Thaddeus Paleo at the Darkmoon Faire on Darkmoon Island." }
WordHunterWoW_QuestEN[29466] = { title = "Plenty of Plump Frogs", description = "Just about everyone in Azeroth has heard of our world famous crunchy frogs. We can barely keep up with the demand!\n\nYou look like a decent angler and a spry <race>. Would you help me restock my frog supply?\n\nThe ones that make the best crunchy frogs are the plump ones that live down near Stonebull Lake. I'll make it worthwhile for you.You will receive:", objectives = "Catch 5 Plump Frogs near Stonebull Lake." }
WordHunterWoW_QuestEN[29467] = { title = "Talkin' Tonks", description = "The steam tonks are one of the Darkmoon Faire's most popular amusements. Our visitors love to test their skills for hours and hours, but the tonks take a real beating from all that fun.\n\nYou look like you know your way around a wrench. Mind helping me fix some of the damaged tonks and return them to working order? I'll compensate you for your time.You will receive:", objectives = "Repair 5 Damaged Steam Tonks around the grounds of the Darkmoon Faire." }
WordHunterWoW_QuestEN[29468] = { title = "Baby Needs Two Pair of Shoes", description = "You may have seen my horse, Baby, over near the wagons. She pulls the cart that hauls all the animals in our Zoo Bizarre.\n\nShe's a hard worker and she tears through shoes like you wouldn't believe. It's about time for a new set. I've already bought the raw materials.\n\nAll you need to do is shape them over an anvil and apply them to Baby's feet. It's a quick job and worth some tickets, wouldn't you say?You will receive:", objectives = "Use the Iron Stock to craft 4 Horseshoes, then apply the Horseshoes to Baby at the Darkmoon Faire." }
WordHunterWoW_QuestEN[29469] = { title = "Rearm, Reuse, Recycle", description = "Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap.\n\nIt'd be a shame to let all that good metal just sit in the dirt.\n\nIf you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?You will receive:", objectives = "Collect 6 pieces of Tonk Scrap from around the Darkmoon Faire grounds." }
WordHunterWoW_QuestEN[29470] = { title = "Tan My Hide", description = "The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment.\n\nYou seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.You will receive:", objectives = "Scrape 4 Staked Skins around the grounds of the Darkmoon Faire.The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment.\n\nYou seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.You will receive:" }
WordHunterWoW_QuestEN[29471] = { title = "Writing the Future", description = "As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures.\n\nMost times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice.\n\nMy stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. I'll see to it that you're rewarded.You will receive:", objectives = "Use the Bundle of Exotic Herbs to make Prophetic Ink and then combine the ink with Light Parchment to create Sayge's Fortunes." }
WordHunterWoW_QuestEN[29472] = { title = "Eyes on the Prizes", description = "The games are more popular than ever, and that means we're giving out prizes faster than we ever have before!\n\nWe're going to need more prizes, and fast. If you've some skill in leatherworking, I can give you a kit. You'll need to buy some of the pieces from a trade goods merchant like Shadi Mistrunner up on the central rise of Thunder Bluff, but they're inexpensive.\n\nAre you willing to help?You will receive:", objectives = "Use the Darkmoon Craftsman's Kit to make 5 Darkmoon Prizes from Coarse Thread, Shiny Baubles, and Blue Dye." }
WordHunterWoW_QuestEN[29473] = { title = "Putting the Carnies Back Together Again", description = "Working the Darkmoon Faire is a dangerous job, <name>. It's no surprise that many of our workers get injured setting up, taking down, and transporting all of its attractions.\n\nWe send the most gravely wounded to the Spirit Rise in Thunder Bluff for help, but many still have minor hurts that can be tended to here. Would you take these bandages and see if you can help any of the injured workers?You will receive:", objectives = "Use the Darkmoon Bandage to heal 4 Injured Carnies." }
WordHunterWoW_QuestEN[29474] = { title = "Putting Trash to Good Use", description = "People don't just come to the fair for fun and fortunes, <name>. Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets.\n\nFor that, I need a steady supply of soothsayer's dust. Take a look around the grounds and you'll see a lot of discarded weapons. Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?You will receive:", objectives = "Collect 6 Soothsayer's Dusts by disenchanting Discarded Weapons found around the grounds of the Darkmoon Faire." }
WordHunterWoW_QuestEN[29475] = { title = "Goblin Engineering", description = "A skilled engineer can choose ONE specialization, and I know the secrets of goblin engineering.\n\nYou look like you're ready to blow things up, but I'll need some samples of your work.  Bring me twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep.\n\nSubmit these items to an engineering trainer in any of the capital cities and you'll be an official goblin engineer with access to all the schematics!", objectives = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to an engineering trainer in any capital city.", progress = "Once I receive your crafted engineering items for my review, I will grant you the knowledge required to join the exclusive club of goblin engineers!", completion = "It appears you are indeed ready for proper training.  I dub you Goblin Engineer <name>!\n\nYou'll be able to access any Goblin Engineer for some diabolical creations.  Have fun and try not to blow your face off." }
WordHunterWoW_QuestEN[29476] = { title = "Gnomish Engineering", description = "If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!You will learn:", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay." }
WordHunterWoW_QuestEN[29477] = { title = "Gnomish Engineering", description = "A skilled engineer can choose ONE specialization, and I can teach you the ways of gnomish engineering.\n\nYou look like you know what you're doing, but I'll need some samples of your work.  Bring me six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to an engineering trainer in any of the capital cities and you'll be an official gnomish engineer with access to all the schematics!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to an engineering trainer in any capital city.", progress = "Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer, granting you unlimited access to gnomish engineer schematics.", completion = "Today is the day you become a real engineer, <name>.  Don't worry about all those messy bombs and explosives, because it's time to shine!" }
WordHunterWoW_QuestEN[29478] = { title = "A Fizzy Fusion", description = "I'm sure you've made a lot of potions in your time as an alchemist. How would you like to help with something a bit more light-hearted?\n\nI've always wanted to try creating a fruit-flavored version of our popular fizzy drinks. If you're willing to give it a try, you can buy some of the base drink from me and mix it with some moonberry juice.\n\nGalissa Sundew should be able to sell you all the moonberry juice you need.You will receive:", objectives = "Use the Cocktail Shaker to combine Moonberry Juice and Fizzy Faire Drink to create 5 servings of Moonberry Fizz." }
WordHunterWoW_QuestEN[29479] = { title = "Herbs for Healing", description = "The little purple flowers that grow wild around the grounds aren't just pretty.\n\nThey play a role in everything from treating wounds to seasoing food.\n\nYou seem to have some talent for harvesting herbs. Would you like to help me rebuild my stocks of darkblossom?You will receive:", objectives = "Gather 6 Darkblossoms from around the Darkmoon Faire grounds." }
WordHunterWoW_QuestEN[29480] = { title = "Banners, Banners Everywhere!", description = "Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced.\n\nIf you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stone on the central rise in Thunder Bluff?\n\nYou can get the rest of the supplies you'll need from Shadi Mistrunner on the central rise of Thunder Bluff.You will receive:", objectives = "Use the Darkmoon Banner Kit to construct a Darkmoon Banner, then set it up in a pile of Loose Stones on Thunder Bluff's central rise." }
WordHunterWoW_QuestEN[29481] = { title = "Elixir Master", description = "Elixirs are all about potency!  If you want to become an elixir master, I can teach you.\n\nI can't just train anyone, and I require proof that you are devoted before we continue.  Several flasks should be sufficient to show your dedication.\n\nRemember <name>, you can only learn ONE specialization, so if you complete your elixir training, then potion and transmutation specialization will no longer be available.", objectives = "Bring a variety of flasks to an alchemy trainer in any capital city.", progress = "Have you the flasks?", completion = "Excellent!" }
WordHunterWoW_QuestEN[29482] = { title = "Transmutation Master", description = "Iron to gold, water to fire... if you want to become an transmutation master, then I can show you the way.\n\nThe training is very expensive, so you'll have to bring me some of the finest transmuted materials in the world.\n\nRemember <name>, you can only learn ONE specialization, so if you complete your transmutation training, then potion and elixir specialization will no longer be available.", objectives = "Bring the requested materials to an alchemy trainer in any capital city.", progress = "Have you the materials?", completion = "Excellent!" }
WordHunterWoW_QuestEN[29483] = { title = "Keeping the Faire Sparkling", description = "The Darkmoon Faire's performers and animals go through more jewelry than I'd ever imagined. Thankfully, the gems are just cut glass, but someone has to craft all of it.\n\nIf you've some skill as a jewelcrafter, perhaps you'd be willing to help craft some of the sparkling glass gems for our performers.\n\nSometimes you can find odd and amazing bits of glass around the grounds. Those make stunning gems when cut by someone with an eye for this craft.You will receive:", objectives = "Find Bits of Glass around the grounds of the Darkmoon Faire and craft it into 5 Sparkling 'Gemstones'." }
WordHunterWoW_QuestEN[29484] = { title = "Putting the Crunch in the Frog", description = "The Darkmoon Faire's crunchy frog is famous all over Azeroth!\n\nWe've just had a fresh batch of frogs delivered. How'd you like to help whip up a few and practice your cooking skills in the process?\n\nShadi Mistrunner sells flour, up on the central rise in Thunder Bluff. Get some flour from her and use it to coat these frogs, then cook them in the pot behind me.You will receive:", objectives = "Prepare 5 Crunchy Frogs by breading your Plump Frogs with Simple Flour and then frying them in the cauldron behind Stamp Thunderhorn." }
WordHunterWoW_QuestEN[29485] = { title = "Fun for the Little Ones", description = "Children are always full of questions about what an archaeologist does and how it works, so I prepared a demonstration for them.\n\nI take artifacts and fossils and bury them in the sand behind the tent. The children get to dig and make their own discoveries, learn how bones fit together, and see how archaeology can teach them about history.\n\nIf you have any spare fossils, would you consider donating them to my side project?You will receive:", objectives = "Bring 15 Fossil Fragments to Professor Thaddeus Paleo at the Darkmoon Faire." }
WordHunterWoW_QuestEN[29506] = { title = "A Fizzy Fusion", description = "I'm sure you've made a lot of potions in your time as an alchemist. How would you like to help with something a bit more light-hearted?\n\nI've always wanted to try creating a fruit-flavored version of our popular fizzy drinks. If you're willing to give it a try, you can buy some of the base drink from me and mix it with some moonberry juice.\n\nAny innkeeper in Elwynn Forest or Mulgore should be able to sell you enough juice to make your creation.", objectives = "Use the Cocktail Shaker to combine Moonberry Juice and Fizzy Faire Drink to create 5 servings of Moonberry Fizz.", progress = "How's that moonberry fizz coming?", completion = "Your creation looks promising. With any luck, we'll soon have a new favorite!\n\nThanks for your help!" }
WordHunterWoW_QuestEN[29507] = { title = "Fun for the Little Ones", description = "Children are always full of questions about what an archaeologist does and how it works, so I prepared a demonstration for them.\n\nI take artifacts and fossils and bury them in the sandbox beside the tent. The children get to dig and make their own discoveries, learn how bones fit together, and see how archaeology can teach them about history.\n\nIf you have any spare fossils, would you consider donating them to my side project?", objectives = "Bring 15 Fossil Fragments collected with Archaeology to Professor Thaddeus Paleo at the Darkmoon Faire.", progress = "How about it? Want to donate some fossil fragments?", completion = "These are great! They're just the kinds of pieces the kids will be excited to 'discover'." }
WordHunterWoW_QuestEN[29508] = { title = "Baby Needs Two Pair of Shoes", description = "You may have seen my horse, Baby, over near the wagons. She pulls the cart that hauls some of the animals in our Zoo Bizarre.\n\nShe's a hard worker and she tears through shoes like you wouldn't believe. It's about time for a new set. I've already bought the raw materials.\n\nAll you need to do is shape them over an anvil and apply them to Baby's feet. It's a quick job and worth some tickets, wouldn't you say?", objectives = "Use the Iron Stock to craft 4 Horseshoes, then apply the Horseshoes to Baby at the Darkmoon Faire.", progress = "How's old Baby doing?", completion = "Thank you for your help, <name>! Here's the payment I promised." }
WordHunterWoW_QuestEN[29509] = { title = "Putting the Crunch in the Frog", description = "The Darkmoon Faire's crunchy frog is famous all over Azeroth!\n\nWe've just had a fresh batch of frogs delivered. How'd you like to help whip up a few and practice your cooking skills in the process?\n\nYou can get the flour you'll need to bread the frogs from any trade goods vendor in Elwynn Forest or Mulgore.", objectives = "Prepare 5 Crunchy Frogs by breading your Plump Frogs with Simple Flour and then frying them in the cauldron behind Stamp Thunderhorn.", progress = "Do I smell fresh crunchy frog?", completion = "These are perfectly cooked, <name>. You've done an excellent job." }
WordHunterWoW_QuestEN[29510] = { title = "Putting Trash to Good Use", description = "People don't just come to the faire for fun and fortunes, {name}. Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets.\n\nFor that, I need a steady supply of soothsayer's dust. Take a look around the grounds and you'll see a lot of discarded weapons. Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?", objectives = "Collect 6 Soothsayer's Dusts by disenchanting Discarded Weapons found around the grounds of the Darkmoon Faire.", progress = "Did you manage to get any of that soothsayer's dust?", completion = "This will help maintain my supply. Anytime you want to help, just look up old Sayge while the Darkmoon Faire's in town." }
WordHunterWoW_QuestEN[29511] = { title = "Talkin' Tonks", description = "The steam tonks are one of the Darkmoon Faire's most popular amusements. Our visitors love to test their skills for hours and hours, but the tonks take a real beating from all that fun.\n\nYou look like you know your way around a wrench. Mind helping me fix some of the damaged tonks and return them to working order? I'll compensate you for your time.", objectives = "Repair 5 Damaged Steam Tonks around the grounds of the Darkmoon Faire.", progress = "You get those repairs done? Visitors are hard on those tonks and I'll need all of them up and running.", completion = "Good job getting those tonks back online. Here are those tickets I promised." }
WordHunterWoW_QuestEN[29512] = { title = "DEPRECATED: Putting the Carnies Back Together Again", description = "Working the Darkmoon Faire is a dangerous job, <name>. It's no surprise that many of our workers get injured setting up, taking down, and transporting all of its attractions.\n\nSome of the injured workers can be found around here, near the wagons. Others have gone to the healing tent for treatment. Would you take these bandages and see if you can help any of the injured workers?", objectives = "Use the Darkmoon Bandage to heal 4 Injured Carnies.", progress = "Did you see to the needs of the injured workers?", completion = "Thank you for your help, <name>. It takes all of us to keep the faire up and running." }
WordHunterWoW_QuestEN[29513] = { title = "Spoilin' for Salty Sea Dogs", description = "We've just introduced another exciting new menu item, the salty sea dog. It's so popular, we can barely keep up with the demand!\n\nYou look like a decent angler and a spry {race}. Would you help me restock my fish supplies?\n\nWe wouldn't want to disappoint all those faire-goers looking to try a new food, would we?", objectives = "Catch 5 Great Sea Herring in the ocean around Darkmoon Island.", progress = "Do you have those fish?", completion = "These are wonderful! Here are your tickets, as promised." }
WordHunterWoW_QuestEN[29514] = { title = "Herbs for Healing", description = "The little purple flowers that grow wild around the grounds aren't just pretty.\n\nThey play a role in everything from treating wounds to seasoning food.\n\nYou seem to have some talent for harvesting herbs. Would you like to help me rebuild my stocks of darkblossom?", objectives = "Gather 6 Darkblossoms from around the Darkmoon Faire grounds.", progress = "How's that herb collection coming along?", completion = "Thank you, <name>. Anytime the Darkmoon Faire is in town, I'd be glad to have your help again." }
WordHunterWoW_QuestEN[29515] = { title = "Writing the Future", description = "As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures.\n\nMost times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice.\n\nMy stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. You can get the parchment you'll need from any trade goods vendor in Elwynn Forest or Mulgore.", objectives = "Use the Bundle of Exotic Herbs to make Prophetic Ink and then combine the ink with Light Parchment to create Sayge's Fortunes.", progress = "Have you penned any of those fortunes?", completion = "These look just like mine. You've quite an eye for detail. Thank you for all your help, <name>." }
WordHunterWoW_QuestEN[29516] = { title = "Keeping the Faire Sparkling", description = "The Darkmoon Faire's performers and animals go through more jewelry than I'd ever imagined. Thankfully, the gems are just cut glass, but someone has to craft all of it.\n\nIf you've some skill as a jewelcrafter, perhaps you'd be willing to help craft some of the sparkling glass gems for our performers.\n\nSometimes you can find odd and amazing bits of glass around the grounds. Those make stunning gems when cut by someone with an eye for this craft.", objectives = "Find Bits of Glass around the grounds of the Darkmoon Faire and craft it into 5 Sparkling 'Gemstones'.", progress = "Were you able to craft any replacement gems for the performers' jewelry?", completion = "Very nice work, <name>. You've quite a talent for this." }
WordHunterWoW_QuestEN[29517] = { title = "Eyes on the Prizes", description = "The games are more popular than ever, and that means we're giving out prizes faster than we ever have before!\n\nWe're going to need more prizes, and fast. If you've some skill in leatherworking, I can give you a kit. You'll need to buy some of the pieces from any trade goods merchant in Elwynn Forest or Mulgore, but they're inexpensive.\n\nAre you willing to help?", objectives = "Use the Darkmoon Craftsman's Kit to make 5 Darkmoon Prizes from Coarse Thread, Shiny Baubles, and Blue Dye.", progress = "Have you had a chance to make those prizes?", completion = "Excellent work! These look just like the others. Thank you for your help.\n\nIf you ever want to help again, look for me next time the Darkmoon Faire is in town." }
WordHunterWoW_QuestEN[29518] = { title = "Rearm, Reuse, Recycle", description = "Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap.\n\nIt'd be a shame to let all that good metal just sit in the dirt.\n\nIf you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?", objectives = "Collect 6 pieces of Tonk Scrap from around the Darkmoon Faire grounds.", progress = "Did you manage to find any scrap? The grounds are full of it.", completion = "There's a good bit of scrap here. Thanks for your help. It'll be a big help when I refit the steam tonks.\n\nPlease take this as a reward for your help." }
WordHunterWoW_QuestEN[29519] = { title = "Tan My Hide", description = "The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment.\n\nYou seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.", objectives = "Scrape 4 Staked Skins around the grounds of the Darkmoon Faire.", progress = "It's a busy job keeping the Darkmoon Faire running.", completion = "Thanks for the help, <name>. I'll never forget your contribution to the Darkmoon Faire.\n\nAnd if you feel inclined, come back and help again next time we're in town." }
WordHunterWoW_QuestEN[29520] = { title = "Banners, Banners Everywhere!", description = "Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced.\n\nIf you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stones scattered around the grounds of the faire?\n\nIt's missing a few pieces, but you should be able to get what you need from any trade goods vendor in Elwynn Forest or Mulgore.", objectives = "Use Coarse Thread, Red Dye, and Blue Dye with a Darkmoon Banner Kit to make a Darkmoon Banner, then set it up in a pile of Loose Stones on the grounds of the Darkmoon Faire.", progress = "Were you able to find a place for that new banner of yours?", completion = "Thanks for helping with those banners. You have quite a talent for needlework. Next time the Darkmoon Faire's in town, why not come by and help again?" }
WordHunterWoW_QuestEN[29521] = { title = "The Singing Pools", description = "It is crucial that we bring all of the three remaining spirits back safely. I am too old to do this myself, and for all their strengths, both Aysa and Ji are single-minded in their ideals.\n\nYou possess all the qualities of a hero, and a balance that they do not. It is you that must do this.\n\nShu, the spirit of water is somewhere in the singing pools to the east. Find Aysa there and work with her to locate him. We are all depending on you.", objectives = "Speak to Aysa Cloudsinger in the Singing Pools.", completion = "It's good to see you again, <name>.\n\nThis is the pool of the skunk, as I'm sure you noticed.\n\nOver the many ages of Shen-zin Su, animals have died in some of these magical pools. Through their deaths, their spirits were infused into the waters, and anyone touching those waters will take their form.\n\nThere are several cursed pools here, some more dangerous than others." }
WordHunterWoW_QuestEN[29522] = { title = "Ji of the Huojin", description = "Another of my most talented students is awaiting you in Wu-Song Village to the northwest. He is of a different mind than Aysa, but in their differences, they bring balance to each other.\n\nJi Firepaw will instruct you on gathering the offerings for the spirit of fire. Trust in his wisdom.", objectives = "Speak to Ji Firepaw in Wu-Song Village.", completion = "Hello! You look poised and confident... I like that!\n\nI've heard some rather impressive whispers about you from the training grounds. If you're half as capable as they say, I think you and I are going to be good friends!" }
WordHunterWoW_QuestEN[29523] = { title = "Fanning the Flames", description = "Strange thing about wind, it can be hard to wrap your hands around it.\n\nBest practice for me has been finding some sort of living wind. If it can punch you, you can punch it back, and it won't slip through your grasp.\n\nHead over to the Shrine of the Summer Breeze to the south and summon just such a living wind using this wind stone. Best it, gather a Fluttering Breeze from it, and come back over this way so that we can figure out what's next.", objectives = "Retrieve a Fluttering Breeze.", progress = "When opportunity rises, it is our responsibility to reach out and grab it. Second guessing is as good as giving up.", completion = "You know what it is to seize opportunity. I think you and I are kindred spirits, <name>." }
WordHunterWoW_QuestEN[29524] = { title = "The Lesson of Stifled Pride", description = "Facing a living opponent is a very different thing from the stationary targets in the yard. Living opponents strike back. There is the very real fear of failure, and sometimes, even death.\n\nYou must have the courage to overcome those fears.\n\nChallenge the other trainees within the temple or down the steps below, and defeat them.", objectives = "Defeat 6 Huojin Trainees or Tushui Trainees.", progress = "There is a time for meditation and contemplation, and there is a time for action. Diving the balance between the two is one of the greatest wisdoms we seek.", completion = "Intriguing, my young pupil.\n\nMost of the other trainees have been here for quite some time, but you are able to match them even within this first hour.\n\nThis speaks well of you, but there are yet other lessons I would see you learn." }
WordHunterWoW_QuestEN[29527] = { title = "War on the Ramparts", description = "Watchkeeper Gargolmar and Vazruden the Herald are in charge of defending these ramparts.\n\nIf you take them out, their forces will be in complete disarray.\n\nSlay them both and bring me proof so the invasion can begin!", objectives = "Slay Watchkeeper Gargolmar, Vazruden the Herald and Vazruden's drake, Nazan. Return Gargolmar's Hand and Nazan's Head to Stone Guard Stok'ton.", progress = "This operation depends on your success, <name>.", completion = "With their leadership dead their forces should be in disarray.\n\nBut there's far more to this than killing a few guards, <class>." }
WordHunterWoW_QuestEN[29528] = { title = "War on the Ramparts", description = "Hellfire Citadel's entire defensive network relies on the ramparts as a sort of early warning system.\n\nYou need to take out Watchkeeper Gargolmar and Vazruden the Herald. Without them, taking the ramparts will be simple.", objectives = "Slay Watchkeeper Gargolmar, Vazruden the Herald and Vazruden's drake, Nazan. Return Gargolmar's Hand and Nazan's Head to Advance Scout Chadwick.", progress = "Were you successful? We have a lot riding on this operation, <name>.", completion = "I knew I could count on you!\n\nWith their forces in disarray, we can really get this invasion going." }
WordHunterWoW_QuestEN[29529] = { title = "Demons in the Citadel", description = "One of our scouts spotted what he thought was an agent of the Burning Legion somewhere in the ramparts. If that is true, then Honor Hold may be in grave danger of a combined assault!\n\nIf you find this fiend in there, kill it on sight.", objectives = "Slay Omor the Unscarred and bring his hoof to Advance Scout Chadwick.", progress = "Did you find any demons in there?", completion = "So it's true. The fel orcs and the Burning Legion are working together in some capacity." }
WordHunterWoW_QuestEN[29530] = { title = "Demons in the Citadel", description = "One of our scouts brought back unpleasant news. We've spotted a powerful agent of the Burning Legion in the ramparts!\n\nI need you to kill this demon before he has a chance to relay news of our efforts to his superiors.", objectives = "Kill Omor the Unscarred and bring his hoof to Stone Guard Stok'ton.", progress = "Were you able to dispose of the foul creature?", completion = "Well done. We need the time you've bought us to investigate this link between the fel orcs and the Burning Legion. You very well may have saved hundreds of lives through your actions." }
WordHunterWoW_QuestEN[29531] = { title = "Kill Stuff", description = "I really need you to kill some stuff for me. It's pretty important.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill stuff for Questvendor." }
WordHunterWoW_QuestEN[29532] = { title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n$Advance Scout Chadwick will definitely want to take a look at this!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Ominous Letter to Advance Scout Chadwick." }
WordHunterWoW_QuestEN[29533] = { title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nStone Guard Stok'ton will definitely want to take a look at this!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Ominous Letter to Stone Guard Stok'ton." }
WordHunterWoW_QuestEN[29534] = { title = "Collect Things", description = "The Quest Wizard demands Stuff Tails! Go now and fetch them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Stuff Tails for the Quest Wizard." }
WordHunterWoW_QuestEN[29535] = { title = "Make Them Bleed", description = "The Maker serves the purpose of creating more fel orcs by infusing them with demon blood.\n\nMy superiors believe that we may be able to reverse the process, but we need samples of their blood and The Maker's infusion rod before we can know for sure.", objectives = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Caza'rez.", progress = "You're back! Even better, you're not dead! Well done. Better than anyone else so far.", completion = "These vials could mean the end of the fel orcs. I hope you understand just how important that is to our campaign here." }
WordHunterWoW_QuestEN[29536] = { title = "Heart of Rage", description = "We know that the fel orcs are growing their forces by infusing orcs with demon blood.\n\nI need you to venture deep inside these unholy halls and find out how that's happening. We can't risk sending an army into this place until we know exactly what we're dealing with.", objectives = "Fully investigate the Blood Furnace and then report back to Caza'rez.", completion = "<You tell Caza'rez everything you saw in the Blood Furnace.>\n\nI see.\n\nIf they can do this to the Mag'har brown orcs, they can do it to us! We must be careful lest they turn all of Thrallmar into those mindless beasts." }
WordHunterWoW_QuestEN[29537] = { title = "Mind the Gap", description = "In all of the Blood Furnace, there is one area where our scryers cannot reach despite their efforts.\n\nThis 'gap', as they've been calling it, is fairly large, and must be where Magtheridon is being held captive..\n\nYou must find the source of the interference and dispose of it.", objectives = "Kill Keli'dan the Breaker and return to Caza'rez.", completion = "The interference has gone down, but we still cannot access that area. We will continue to investigate the matter. Thank you for your help." }
WordHunterWoW_QuestEN[29538] = { title = "Make Them Bleed", description = "The Maker uses demon blood and a special rod to turn brown and green orcs into red ones. We'd like to see if we can take that blood, mess around with it a bit, and make it turn orcs of all colors into harmless docile lumps. \n\nYou're going to bring me some samples of their blood so we can see. Don't forget to grab that rod!", objectives = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Gunny.", progress = "You have that blood, darlin'?  Might be kind of important if we asked you to get it, you know?", completion = "Out-frikkin-standing! As of right now, you are my eighth favorite person on the smoldering remains of this sorry planet!" }
WordHunterWoW_QuestEN[29539] = { title = "Heart of Rage", description = "As it turns out, the eggheads back at Honor Hold can't see much into this place. Bunch of lying lazy mages, is what they are.\n\nEither way, we don't really know exactly what's going on in here. So, you're going in to find out!", objectives = "Fully investigate the Blood Furnace and then report back to Gunny.", completion = "<You tell Gunny everything you saw in the Blood Furnace.>\n\nYou brought back some loot for ol' Gunny, right?\n\nNo, no, you're right, clearly I owe you a reward for all your hard work. Not like Gunny didn't arrange all this and send you in there in the first place." }
WordHunterWoW_QuestEN[29540] = { title = "The Breaker", description = "So they've got this big ol' demon stashed away in this place, is what they're telling me. And there's an orc that's in charge of keeping him under wraps.\n\nKilling an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', orcs are always ripe for the slaughter!", objectives = "Kill Keli'dan the Breaker and return to Gunny.", completion = "Really? You want a reward for killing an orc? As in fame and riches and noble steeds?\n\nBack in my day killing orcs WAS the reward!" }
WordHunterWoW_QuestEN[29541] = { title = "Take Care of It", description = "This looks bad... you'd better do something.", objectives = "Resolve the dispute any way you see fit." }
WordHunterWoW_QuestEN[29542] = { title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Thrallmar is going to be overrun if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Stone Guard Stok'ton. He's in charge of a covert operation to start a Horde invasion on the entire citadel.", objectives = "Speak with Stone Guard Stok'ton in Hellfire Ramparts.", completion = "Shatterskull's not personable by anyone's standards, but he certainly gets the job done. Let's put you to work." }
WordHunterWoW_QuestEN[29543] = { title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Honor Hold is going to be overrun in a matter of time if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Advance Scout Chadwick. He's in charge of a covert operation to start an Alliance invasion on the entire citadel.", objectives = "Speak with Advance Scout Chadwick in Hellfire Ramparts.", completion = "That Altumus is certainly a gem, isn't she? But there won't be any of us left alive out here if we aren't successful in our efforts in the ramparts." }
WordHunterWoW_QuestEN[29544] = { title = "The Blood Furnace", description = "Caza'rez awaits you within the Blood Furnace. He's already cleared out a small area and has our scryers hard at work figuring out what's going on down there.\n\nBut I don't trust that scrying will be enough. I'm sure Caza'rez has plans in mind for a solid blade or two. I want you to go there and lend him your expertise in dealing with the fel orcs. ", objectives = "Speak with Caza'rez in the Blood Furnace.Caza'rez awaits you within the Blood Furnace. He's already cleared out a small area and has our scryers hard at work figuring out what's going on down there.\n\nBut I don't trust that scrying will be enough. I'm sure Caza'rez has plans in mind for a solid blade or two. I want you to go there and lend him your expertise in dealing with the fel orcs.You will receive:" }
WordHunterWoW_QuestEN[29545] = { title = "The Blood Furnace", description = "This war is far from over. We need to stop the flow of new recruits to the fel orc front if we are to have any hope of victory.\n\nTravel to the Blood Furnace and speak with Gunny, he's secured a small area within and I'm sure he could use your assistance. Be forewarned, Gunny is...unusual.", objectives = "Speak with Gunny in the Blood Furnace.This war is far from over. We need to stop the flow of new recruits to the fel orc front if we are to have any hope of victory.\n\nTravel to the Blood Furnace and speak with Gunny, he's secured a small area within and I'm sure he could use your assistance. Be forewarned, Gunny is...unusual.You will receive:" }
WordHunterWoW_QuestEN[29546] = { title = "Tipping the Scales", description = "These blasted native monkey savages have been assaulting us since the day we put to shore!\n\nWe were holding our own until they kidnapped half our men, including the Admiral.\n\nJust look at their numbers! They're endless, and we're standing on our last legs.\n\nIf you're here to get us out of this mess, go help take down some monkeys.\n\nIt's them or us, <race>!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 12 Hozen Ravagers." }
WordHunterWoW_QuestEN[29547] = { title = "The King's Command", description = "Greetings, {class}.\n\nI have been asked to assemble a team for a high priority mission.\n\nPlease come to Stormwind Keep immediately for a briefing with King Varian Wrynn. I will be waiting in the King's war room.", objectives = "Find Grand Admiral Jes-Tereth in the war room at Stormwind Keep in Stormwind City.", completion = "Our role is of utmost importance. Admiral Taylor and his flagship have gone missing. More importantly, the young Prince was with him, and it is our primary objective to bring him back home safely." }
WordHunterWoW_QuestEN[29548] = { title = "The Mission", description = "Well, you heard the King. Admiral Taylor's last transmission came from somewhere in the southern seas.\n\nWe will begin our search from the air! Locating the Prince - the White Pawn - is of critical priority.\n\nThe Skyfire is fueled, supplied, and ready to depart. She and her crew idle in the sky just north of the harbor.\n\nMake your last preparations, then meet Admiral Rogers on the deck. We will depart without delay.", objectives = "Report to Admiral Rogers on The Skyfire.", progress = "Ah, a veteran of the Cataclysm campaigns! Good, I could use more experienced hands.", completion = "That's a whole Horde base down there! Where was our intel?\n\nWell <class>, it's time to see what this upgraded gunship is capable of." }
WordHunterWoW_QuestEN[29549] = { title = "Flightmaster Down", description = "I've taken stock of the missing, and among them is Donovar Murall, our Flightmaster.\n\nHe is not only a vital part of our crew, he is a dear friend as well.\n\nPlease find him and bring him back alive.You will receive:", objectives = "Speak to Donovar Murall in Veridian Grove.I've taken stock of the missing, and among them is Donovar Murall, our Flightmaster.\n\nHe is not only a vital part of our crew, he is a dear friend as well.\n\nPlease find him and bring him back alive.You will receive:" }
WordHunterWoW_QuestEN[29550] = { title = "Saving Snowpuff", description = "<Donovar bursts into tears upon seeing you.>\n\nTh-th-those blasted monkey hooligans d-d-dragged me inta these woods. I thot I were dunnert, but mah faithful Snowpuff came flyin' to mah rescue!\n\nShe fought 'em off and then they all jumped 'er! Wot with them apes prowlin' around, she's...\n\n<Donovar blows his nose loudly.>\n\n...she's done for! Wahaahaaaaaa! Unless...\n\nListen <class>, I saw Gingerleaf growing all over these woods. I beg ya, bring me some o' that healing herb and Snowpuff just might make et!You will receive:", objectives = "Collect 4 Gingerleaf for Snowpuff." }
WordHunterWoW_QuestEN[29551] = { title = "Grove Stalkers", description = "We're still trying to take stock of our crew after the fighting.\n\nI'm afraid many of them are stranded out in the woods, probably wounded and fighting to survive.\n\nWe know that the forest to the north is full of vicious tigers.\n\nGo clear them out of the woods. You'll give more of our men and women a chance to make it back alive.You will receive:", objectives = "Kill 8 Grove Stalkers." }
WordHunterWoW_QuestEN[29552] = { title = "Critical Condition", description = "We may have won the first battle, but a critical task still remains.\n\nDozens of Skyfire pilots were shot down during the initial aerial battle.\n\nWithout medical aid, their condition will deteriorate over time, until they finally perish. We are their only hope for survival.\n\nGo into the orchard and revive as many pilots as you can find.\n\nWe will leave no one behind.", objectives = "Revive 6 Wounded Pilots in Paw'don Glade. You can also use healing spells or bandages to revive them.", progress = "We will remember all the brave Alliance soldiers who fell today. Though they can no longer continue, we carry the fight onward.", completion = "Good work, <name>. Those soldiers will live and fight another day because of your efforts." }
WordHunterWoW_QuestEN[29553] = { title = "The Missing Admiral", description = "Alright. According to the clues you found, that was Anduin's ship, and Admiral Taylor was the captain. \n\nAnd Admiral Taylor's last entry says he was going to fight off the hozen and protect the vessel after the shipwreck.\n\nThe locals say these hozen sometimes take prisoners, and I didn't see Taylor's corpse anywhere among the wreckage. So you'll probably find Taylor at the hozen encampment to the northeast.\n\nGet going, we have no time to lose!", objectives = "Find Admiral Taylor.", completion = "<You found him, but the Admiral is unconscious. He looks on the verge of death.>" }
WordHunterWoW_QuestEN[29554] = { title = "Sunken Junk", description = "Hey <name>!\n\nThe coast here is littered with scraps of tools and metal from the shipwreck.\n\nThe ordinary person might think that this is junk, but I'm sure I can salvage most of it. I once repaired a submarine using only a bronze tube and a luffa!\n\nGet me some of the waterlogged scraps along the shore by the ship. I need them for my next project.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 8 Waterlogged Scraps." }
WordHunterWoW_QuestEN[29555] = { title = "The White Pawn", description = "Alright, soldier. I've got a critical mission for you.\n\nGet down to the coastline south of here - in the cove there you'll find a wrecked Alliance vessel. I need you to search it and find out if it was the ship that was carrying Anduin. \n\nThen, recover the Captain's Log and see if it has any information on where we can find him.\n\nSince the log is from a military ship, it'll be written using a cipher - take it to Nodd Codejack afterwards. He's keeping watch on the wreck from the other end of the cove.", objectives = "Search the Wreck of the Vanguard in Jade Forest for clues about its cargo, and recover the Encoded Captain's Log.", progress = "Well?", completion = "Alright... let me see... using the cipher from when the ship went missing...\n\n<Nodd is clearly doing some calculations in his head.>\n\nAha!" }
WordHunterWoW_QuestEN[29556] = { title = "Hozen Aren't Your Friends, Hozen Are Your Enemies", description = "We've located an Alliance wreck to the south. Unfortunately, the locals have informed us that it's currently being scavenged by a group of creatures called \"hozen.\"\n\nBy pillaging our wrecked ships, these creatures have already shown that they aren't friendly. We can't have them taking spoils from our ships, stealing our supplies, and worse, potentially capturing or killing any survivors.\n\nGet down there and take them out! When you're done, meet up with Nodd Codejack, our SI:7 agent in the area.", objectives = "Kill 10 Hozen at the Wreck of the Vanguard.", completion = "Good work. Dirty creatures trying to kick us when we're down... \n\nThat'll teach 'em to try and salvage an Alliance vessel!" }
WordHunterWoW_QuestEN[29557] = { title = "The Mission Continues", description = "The King's flagship went aground not far from here.\n\nApparently, the ship signaled Anduin's safe arrival shortly after landing, but when they sent men to retrieve the Prince, he was gone.\n\nI want to investigate the wreckage for clues.\n\nNodd and Sully are already at the crash site. Go east along the beach and see if they need help.You will receive:", objectives = "Speak to Nodd at Sapphire's End in the Jade Forest.The King's flagship went aground not far from here.\n\nApparently, the ship signaled Anduin's safe arrival shortly after landing, but when they sent men to retrieve the Prince, he was gone.\n\nI want to investigate the wreckage for clues.\n\nNodd and Sully are already at the crash site. Go east along the beach and see if they need help.You will receive:" }
WordHunterWoW_QuestEN[29558] = { title = "The Path of War", description = "I see you want to save your friend. I can help you, if you will help me.\n\nFirst of all, it should be obvious that the fewer the Slingtail roaming around, the easier it will be to escape.\n\nKill the hozen guards around us, and we will be one step closer to freedom.", objectives = "Kill 12 Slingtail Treeleapers or Slingtail Mudseers.", progress = "You fight well, foreigner.", completion = "Ahahaha! You are brave.\n\nAn admirable trait." }
WordHunterWoW_QuestEN[29559] = { title = "Freeing Our Brothers", description = "You may be an outsider, but you and I have a common enemy in the hozen.\n\nMany members of my tribe are trapped in cages nearby. I have also seen your... Alliance... soldiers as well.\n\nI cannot leave without freeing my brethren, just as you cannot leave yours.\n\nThe Slingtail hold the keys to those cages. Find the keys and free our friends.", objectives = "Free 6 Jinyu Prisoners or Alliance Prisoners.", progress = "Are they freed?", completion = "You have freed my brothers? Good.\n\nWe are in your debt." }
WordHunterWoW_QuestEN[29560] = { title = "Ancient Power", description = "Hozen skulls are prized tokens among my village.\n\nWe use them to perform ceremonial rites, and the older the skull, the more potent its magic.\n\nLuckily for us, the hozen are careless, filthy beasts. They leave the skulls of their dead scattered among their huts and campfires.\n\nCollect these skulls for me, and I will reward you handsomely.", objectives = "Collect 8 Ancient Hozen Skulls.", progress = "The skulls are precious to my tribe. How many have you collected?", completion = "It is good to see that you are so resourceful, <name>. It is a trait admired by my people.\n\nThe fine specimens you have brought me will produce powerful magic." }
WordHunterWoW_QuestEN[29561] = { title = "Against the Odds", description = "You and I are the only mission operatives who made it to base camp, <class>.\n\nI saw the other SI:7 eject over the forest to the north.\n\nYou'd better go quickly and rescue any survivors.You will receive:", objectives = "Find the lost SI:7 agents." }
WordHunterWoW_QuestEN[29562] = { title = "Jailbreak", description = "Without healing, your friend Taylor will die. My village is just east of here, in the middle of the large lake.\n\nI will take Taylor myself, but the fighting is most dangerous in that direction.\n\nI need you to help clear a path through the hozen, so that I may run safely into my village.\n\nCan you do this?", objectives = "Kill 10 Slingtail Fishrippers.", progress = "Our conflict with the hozen goes back many generations.", completion = "Thank you, <name>. Because of you, we were able to make it here safely." }
WordHunterWoW_QuestEN[29563] = { title = "Lost in Action", description = "You have to help me! We were sent here to investigate the various parts of the reservoir, but my friends haven't come back yet, and it's been a long time.\n\nThat's why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb went this way.", objectives = "Discover what happened to Naturalist Bite and Weeder Greenthumb. Then, return to Watcher Jhang.", progress = "Have you discovered anything?", completion = "The loss of life...it pains me.\n\n<Watcher Jhang sighs.>\n\nThank you, <name>. When we are all reunited, the naga won't stand a chance." }
WordHunterWoW_QuestEN[29564] = { title = "A Brother Betrayed", description = "My village was able to escape the naga onslaught at first. We would have all made it to Nagrand had it not been for my brother. He sold our souls for his own freedom.\n\nNow he works here as a slave driver, whipping his own brothers until their backs bleed. Make Mennu pay, {race}.", objectives = "Kill Mennu the Betrayer, then return to Nahuud.", progress = "Is the traitor dead?", completion = "Mennu's death will not fix the broken backs of my family and friends, but it will give them a chance to live the rest of their lives free." }
WordHunterWoW_QuestEN[29565] = { title = "The Heart of the Matter", description = "From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and Quagmirran, were among the first enslaved by the naga when they arrived. They helped to subjugate many of the native races of Zangarmarsh.\n\nThough it pains me greatly to ask you to do so, you must put them down.", objectives = "Bring The Invader's Claw and The Slave Master's Eye to Watcher Jhang.", progress = "Did you slay them?", completion = "I'm glad that their spirits are now free. I wish we could say the same for the rest of their kind.\n\nThere is still much work to be done, especially elsewhere in Coilfang." }
WordHunterWoW_QuestEN[29566] = { title = "Checking Up", description = "These marshes are beautiful, wouldn't you agree? That is, except for the naga forces draining the water away.\n\nI sent a small expedition to the Coilfang Reservoir to investigate the naga, and they haven't returned. I'm concerned that something has happened to them.\n\nWould you travel to the Slave Pens underneath Serpent Lake and find Watcher Jhang?", objectives = "Speak with Watcher Jhang in the Slave Pens.", completion = "What're you doing all the way down here? As you can see, it isn't exactly safe!" }
WordHunterWoW_QuestEN[29567] = { title = "Stalk the Stalker", description = "The spore giants may be attacking my people today, but the marsh walkers have taken more innocent lives than any creature I've ever seen. They are our ancient enemies.\n\nTheir brood mother, the Black Stalker, resides deep within this bog. If you were to destroy her and bring me her brain as proof, I would tell tales of your bravery to my grandchildren.", objectives = "Bring the Brain of the Black Stalker to T'shu.", progress = "You have returned.  Does this mean that The Black Stalker is no more?", completion = "The Black Stalker is dead!  Normally I would not revel in such butchery, but the pain that the great mother and her brood have put my people through over the centuries is unspeakable.\n\nYou have my deepest thanks, brave <class>." }
WordHunterWoW_QuestEN[29568] = { title = "A Necessary Evil", description = "Hungarfen and Quagmirran used to jointly rule over the spore giants. With Quagmirran gone, the burden rests solely on Hungarfen's tendrils.\n\nWe have no choice but to put the giant down before he can be enslaved and turned into a weapon.", objectives = "Kill Hungarfen, then report back to Naturalist Bite.", progress = "Is the deed done, <name>?", completion = "You've done all of Zangarmarsh a favor this day, <name>. The spore giants may be naturally aggressive, but they're still a vital part of the ecosystem." }
WordHunterWoW_QuestEN[29569] = { title = "Warlord Kalithresh's Prized Possession", description = "Warlord Kalithresh has been utilizing the Underbog as a sort of breeding ground for Ghaz'an, a powerful hydra that he plans to unleash upon Zangarmarsh once it is fully grown.\n\nI fear nobody will be able to stop the naga if the beast reaches its full size. Find Ghaz'an and slay him for the good of us all.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Ghaz'an and bring his scale to Watcher Jhang." }
WordHunterWoW_QuestEN[29570] = { title = "Rescuing the Expedition", description = "The last members of my expedition are somewhere in here. We're going to need the knowledge they've gathered and their skills if we're to have any chance at defeating the naga.\n\nSee if you can find Earthbinder Rayge and Windcaller Claw, and make sure they're ok.", objectives = "Discover what happened to Earthbinder Rayge and Windcaller Claw. Then, return to Watcher Jhang.", progress = "Were you able to find either of them? Are they ok?", completion = "Soon we'll all be together again, and I owe it all to you!\n\nWe'll bring the naga down before you know it, they don't stand a chance!" }
WordHunterWoW_QuestEN[29571] = { title = "Defending the Wilds", description = "The Earthen Ring often finds itself working closely with the druids of the Cenarion Circle. Now is one such time.\n\nTravel north to the Underbog and speak with Watcher Jhang. She is in charge of an expedition in the Coilfang Reservoir to stop the naga there and save Zangarmarsh.", objectives = "Speak with Watcher Jhang in the Underbog.", completion = "The Underbog lies precariously on the edge of becoming another part of the Coilfang naga system. You must help us!" }
WordHunterWoW_QuestEN[29572] = { title = "Safety Is Job One", description = "Shaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.\n\nI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.\n\nActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\n\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it." }
WordHunterWoW_QuestEN[29573] = { title = "Safety is Job One", description = "It's nearly safe for our men to come in here and take what's rightfully ours. The real danger now is Shaffar's personal army that he has crawling all over this place.\n\nI need you to take care of his forces for me while I regain my strength.", objectives = "Kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers, and 5 Ethereal Spellbinders, then return to Artificer Morphalius.", progress = "Done already? You humans continue to fascinate me.", completion = "Splendid! Haramad will be delighted to hear the good news! All of this ripe for his taking!" }
WordHunterWoW_QuestEN[29574] = { title = "Intriguing Specimens", description = "There is a creature not far inside these halls called Pandemonius who is able to twist void energies to sustain and empower itself.\n\nA bit further in lies Tavarok, a being that takes those same void energies and converts them into a crystalline structure stronger than any I've ever seen!\n\nI absolutely must obtain samples for further study.", objectives = "Bring Pandemonius' Essence and Tavarok's Heart to Mamdy the \"Ologist\".", progress = "If you don't have what I'm looking for, stop wasting my time.", completion = "These samples are absolutely fascinating. They'll work very nicely." }
WordHunterWoW_QuestEN[29575] = { title = "Undercutting the Competition", description = "With his ward in place and his forces ready, Nexus-Prince Shaffar has been able to pillage this place for all it's worth without so much as an ounce of trouble.\n\nUnsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a hefty bounty on Shaffar's head.", objectives = "Bring Shaffar's Wrappings to Artificer Morphalius.", progress = "Were you interested in the bounty on Shaffar's head?", completion = "I didn't honestly think a <race> would be able to defeat a Nexus-Prince. You've surprised me, and you've earned the handsome reward you were promised." }
WordHunterWoW_QuestEN[29576] = { title = "An Air of Worry", description = "My sight has long since faded, but when the wind is right I can still smell the blossoms of Nectarbreeze Orchard as if they were in my own palm.\n\nToday, though, their fragrance is muddled with smoke. Please, if you are able, check in on the orchard and see that things are okay. Perhaps my old nose is playing tricks on me.\n\nYou'll find the orchard to the southwest, beyond the statue of the Jade Serpent.", objectives = "Speak with Shao the Defiant at Nectarbreeze Orchard.", completion = "If you've come to speak with my fists, take your place in line. Otherwise, I could use your help." }
WordHunterWoW_QuestEN[29577] = { title = "Ashyo's Vision", description = "Have a look at that!\n\n<Ashyo motions at the massive waterfall to the north.>\n\nThis must be the water supply for the whole valley!\n\nThink about it, {name}: the pandaren use this water to grow vegetables the size of a house. Where could it come from? What is so special about it?\n\nThe elders among my people know a technique for speaking with the water and divining the future. Perhaps this same technique can provide insight into the water's source...\n\nIt's worth a shot at least!", objectives = "Speak with Ashyo at the Pools of Purity and observe his ritual.", progress = "What is that jinyu up to over there?", completion = "I can't believe he was able to see that with a stick... perhaps there is more to \"crazy jinyu rituals\" than we thought." }
WordHunterWoW_QuestEN[29578] = { title = "Defiance", description = "The damn mogu hit us out of nowhere! Anyone they don't kill on sight is being dragged away into the woods.\n\nThis is the only safehouse, and its all I can do to hold the door.\n\nWhat do you say, friend? Are you willing to stand up and fight for the weak?", objectives = "Kill 8 Gormali Raiders and 8 Gormali Incinerators in Nectarbreeze Orchard.", progress = "Don't worry - they won't get through me.", completion = "Nice work, but there's more to be done if we are to save this village." }
WordHunterWoW_QuestEN[29579] = { title = "Rally the Survivors", description = "The people of this village are simple farmers - not fighters like you and I. Still, they are stubbornly defending their homes as best they can.\n\nSearch the village for anyone still on their feet and tell them to rally here at Hanae's place.", objectives = "Speak with 5 Nectarbreeze Farmers around Nectarbreeze Orchard and send them to the safehouse.", progress = "Please tell me some still live...", completion = "They're inside. Shaken, but alive thanks to you." }
WordHunterWoW_QuestEN[29580] = { title = "Orchard-Supplied Hardware", description = "They may not be weaponmasters, but many of these farmers can wield a simple hoe or a rake as an extension of their own will.\n\nThat mastery coupled with the right motivation could muster a force capable of standing against the mogu.\n\nIf you can bring back some tools from the orchard, I'll distribute them to anyone willing to fight.", objectives = "Retrieve 6 Orchard Tools from Nectarbreeze Orchard.", progress = "Were there any tools left?", completion = "There are no hunters among us, but we'll fight to protect our loved ones." }
WordHunterWoW_QuestEN[29581] = { title = "The Golden Dream", description = "Ashyo must have experienced what we call the golden dream.\n\nMany of us working here have seen it, too - often after a long day of toiling in the pools. It is said this vision--and the feeling of elation it brings--is a reward to the mind for working the body.\n\nThere IS an easier way, though we rarely resort to it anymore: a tea can be brewed using lotus root and dreamleaf, which grows around the shrine on the upper tier.\n\nBring the dreamleaf to Yan back in town and he can brew the tea for you.", objectives = "Bring a Sprig of Dreamleaf to Yan in New Cifera.", progress = "Yes, did you need something?", completion = "Ah... dreamleaf! So you want to see the Golden Dream, do you?\n\nCome to think of it, I haven't seen the Dream in years - not since I was a cub spending long hours playing in the pools. Long before I took up the culinary arts.\n\nLooks like you brought enough dreamleaf for two cups of tea... so why not?\n\nHere's to better days!" }
WordHunterWoW_QuestEN[29582] = { title = "Grek's Crazy Night", description = "Grek had bad night last night.\n\nShiny mummy man came into Grek's house and told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read wanted poster!\n\n<Grek's face lights up.>\n\nGrek knows! You go find shiny mummy man and tell him Grek sent you. It perfect plan!", objectives = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", completion = "That meathead send you instead?\n\n<Artificer Morphalius looks you over.>\n\nI suppose you'll have to do." }
WordHunterWoW_QuestEN[29583] = { title = "Eckert the Mad", description = "I'm a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen.\n\nDo they call me those things? No.\n\nBut you have one run-in with an ethereal and all of the sudden everyone and their mother calls you \"the mad\".\n\nI saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!", objectives = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", completion = "I was truly hoping that the gnome I sought out would be the one to answer my call.\n\n<Artificer Morphalius looks you over.>\n\nI suppose you'll do." }
WordHunterWoW_QuestEN[29584] = { title = "Kill Mogu Firestarters", description = "As if the attack weren't bad enough, the mogu are setting these ancient orchards ablaze.\n\nI cannot understand what they hope to achieve, but we must stop them. Clear out the orchard so these people have a livelihood to return to.You will receive:", objectives = "Kill 8 Mogu Firestarters in Nectarbreeze Orchard." }
WordHunterWoW_QuestEN[29585] = { title = "Spitfire", description = "We've tended these orchards and made cider from their nectar for generations. In that time, we've learned a special trick for putting out fires in a pinch.\n\n<Hanae pushes a jug of cider into your hand.>\n\nThe cider itself - when mixed with crushed gingerleaf and saliva - quickly becomes sticky and viscous. Perfect for smothering flames.\n\nPlease, while you're out there, try to get the flames under control. I've already mixed in the gingerleaf, just swig and spit.", objectives = "Use the Nectarbreeze Cider to put out 12 fires around Nectarbreeze Orchard.", progress = "Best not to judge our prized cider by its flavor in this state.", completion = "A survivor came in moments ago and said the flames are beginning to die down.\n\nWe owe our very way of life to you, stranger. I cannot possibly reward you adequately, but please take this." }
WordHunterWoW_QuestEN[29586] = { title = "The Splintered Path", description = "First... before the war-cries... we heard the trees.\n\nGroaning, creaking, and finally crashing down as the mogu cut their way through the woods. They were making the return trip easier...\n\nThey're dragging our friends back down that path, to the ruins west of the village! Those ruins have been empty for years - our children play there.\n\nWhy would the mogu come back to them now?", objectives = "Follow the path of fallen trees from the northwest corner of Nectarbreeze Orchard and find the mogu raiders camp.", completion = "This doesn't look like a quick snatch and run. They're setting up for something big." }
WordHunterWoW_QuestEN[29587] = { title = "Unbound", description = "Can you see them, {name}? Farmers from the orchard, tied up and under inspection. Being hauled off in chains.\n\nThe mogu value strength above all else. Anyone deemed fit for work will be sent to toil under their cruel whips.\n\nAs for the others, well...\n\nLet's not waste any more time.", objectives = "Set 10 Captured Nectarbreeze Farmers free in Camp Gormal.", progress = "Those ropes should give with a strong tug.", completion = "The pandaren were subjected to mogu rule in ancient times - we'll never let it happen again." }
WordHunterWoW_QuestEN[29590] = { title = "The Dead Watcher", description = "A terrifying otherworldly being haunts both the spirit and physical worlds. We call it Shirrak.\n\nIt can only be harmed in your realm. Please help rid us of this nightmare.", objectives = "Kill Shirrak the Dead Watcher, then return to the Draenei Spirit.", completion = "Perhaps now we can finally be at peace." }
WordHunterWoW_QuestEN[29591] = { title = "Raging Spirits", description = "The Auchenai have turned their backs on everything we used to stand for. They've taken to raising the dead as unholy minions!\n\nThis cannot stand. Put the spirits back to rest, and massacre those responsible for raising them into undeath. ", objectives = "Slay 5 Angered Skeletons, 5 Raging Skeletons, and 3 Auchenai Necromancers, then return to the Tormented Soulpriest in Auchenai Crypts.", progress = "Don't speak to me again until the deed is done.", completion = "The dead belong in the spirit realm. Just as you belong in this one." }
WordHunterWoW_QuestEN[29592] = { title = "Caster Legendary BREADCRUMB TRACKER", description = "", objectives = "" }
WordHunterWoW_QuestEN[29593] = { title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", objectives = "Steal 3 piles of Hellfire Supplies, then return to Stone Guard Stok'ton in Hellfire Ramparts.", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be." }
WordHunterWoW_QuestEN[29594] = { title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", objectives = "Steal 3 piles of Hellfire Supplies, then return to Advance Scout Chadwick in Hellfire Ramparts.", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be." }
WordHunterWoW_QuestEN[29595] = { title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.", objectives = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and speak with the Draenei Spirit.", completion = "Welcome to the Auchenai Crypts, <name>, where our two worlds meet." }
WordHunterWoW_QuestEN[29596] = { title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.", objectives = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts.", completion = "You have done our realm a great service. You will not be forgotten." }
WordHunterWoW_QuestEN[29597] = { title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.Upon completion of this quest you will gain:", objectives = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts." }
WordHunterWoW_QuestEN[29598] = { title = "Taretha's Diversion", description = "It was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges.", objectives = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\n\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.", progress = "Who are you?", completion = "You are friends of Taretha? So this is her new plan? Very well then..." }
WordHunterWoW_QuestEN[29599] = { title = "Escape from Durnholde", description = "I have plans for my people, stranger.\n\nOne day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nWe will leave when you are ready.", objectives = "When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.\n\nSpeak with Erozion in Old Hillsbrad should you complete this task.", progress = "<Erozion nods.>", completion = "You have done a great thing, <name>. Alas, the young warchief's memory of these events must be as they originally were..." }
WordHunterWoW_QuestEN[29600] = { title = "Snap Judgment", description = "These pools are very special: they nurture life like nothing else in Pandaria.\n\nUnfortunately this means they draw all kinds of attention from local fauna. Recently, dragon turtles have discovered that toadspawn pools are common on the tier just above us. They're running wild up there, trampling the lotuses and snapping at my workers.\n\nThey aren't much of a threat on their own, but in groups they can be pretty nasty. Please, if you can spare your strength, help clear them out.", objectives = "Kill 16 Razorback Snappers at the Pools of Purity.", progress = "<Yue sighs.>\n\nIf only we'd kept up with our maintenance, the situation would not have come to this.", completion = "You have my gratitude, <name>.\n\nPlease take this as a token of my appreciation." }
WordHunterWoW_QuestEN[29601] = { title = "The Darkmoon Field Guide", description = "Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you.\n\nIt can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave.", objectives = "Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you.\n\nIt can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave.You will receive:" }
WordHunterWoW_QuestEN[29602] = { title = "Tracking Event: Gryphon Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[29603] = { title = "Tracking Event: Provisioner Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[29604] = { title = "Tracking Event: Saw East Temple Arrival Cinematic", description = "", objectives = "" }
WordHunterWoW_QuestEN[29605] = { title = "Brother Against Brother", description = "The Sethekk departed Skettis when Auchindoun exploded.\n\nMy brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god.\n\nIn time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka. Will you help me rescue her?", objectives = "Free Lakka from captivity. Return to Isfar inside the Sethekk Halls when you've completed the rescue.", progress = "Did you find her, <name>? Was she still being held within the halls?", completion = "Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him." }
WordHunterWoW_QuestEN[29606] = { title = "Terokk's Legacy", description = "Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind.\n\nDarkweaver Syth still holds his mask and Talon King Ikiss guards his spear.\n\nIt would mean a great deal to my people if these items were returned to us.", objectives = "Bring Terokk's Mask and Terokk's Quill to Isfar inside the Sethekk Halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself." }
WordHunterWoW_QuestEN[29607] = { title = "Eyes of Desire", description = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here.\n\nIf you were to bring me some of these rare gems, I would cut you a portion of the profits.\n\nDo we have a deal?", objectives = "Dealer Vijad inside the Sethekk Halls wants you to bring him 3 Cobalt Eyes.", progress = "Did you bring the eyes?", completion = "These are marvelous. Well done!\n\nHere's your cut, as promised." }
WordHunterWoW_QuestEN[29608] = { title = "Allies in Dalaran", description = "Welcome to Northrend, {name}. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there.\n\nRide the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately.\n\nShe can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.", objectives = "Accept a gryphon ride to Dalaran and speak with Isirami Fairwind at A Hero's Welcome.", completion = "Welcome to Dalaran! This inn is part of the Silver Enclave, the headquarters of the official Alliance presence in our city.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Stormwind next door." }
WordHunterWoW_QuestEN[29609] = { title = "Friends in Dalaran", description = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city.\n\nSpeak with me and accept a ride to Dalaran. Once you land, make your way to The Filthy Animal.\n\nMake contact with Uda the Beast immediately.\n\nShe can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.", objectives = "Accept a ride to Dalaran from the flight master and speak with Uda the Beast at The Filthy Animal.", completion = "I've been expecting you! This inn is part of Sunreaver's Sanctuary, the Horde's enclave in Dalaran.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Orgrimmar, out by the fountain." }
WordHunterWoW_QuestEN[29610] = { title = "Tracking Event: Player's First Arrival", description = "", objectives = "" }
WordHunterWoW_QuestEN[29611] = { title = "The Art of War", description = "Lok'tar ogar, {race}. I am Nazgrim.\n\nYou are hereby ordered to present yourself at Grommash Hold immediately.\n\nAll in service to the Horde are to swear an oath of allegiance to their new Warchief.\n\nDo not keep him waiting, {race}.", objectives = "Speak to General Nazgrim in Grommash Hold.", progress = "Blood and thunder, orc.", completion = "Ahh, good. You're here. And not a moment too soon..." }
WordHunterWoW_QuestEN[29612] = { title = "The Art of War", description = "Lok'tar Ogar, old friend. It has been too long since last we spoke.\n\nIt is good to see that you emerged safely from the depths of Vashj'ir.\n\nI am stationed here in Grommash Hold.\n\nAll in service to the Horde are to swear allegiance to their new Warchief.\n\nYou would do well not to keep him waiting, {name}.", objectives = "Speak to General Nazgrim in Grommash Hold in Orgrimmar.", completion = "Ahh, good. You're here. And not a moment too soon..." }
WordHunterWoW_QuestEN[29613] = { title = "A Proper Fate", description = "Warlord Kalithresh is in charge of the entire Steamvault operation.\n\nI need you to kill him, {name}. The naga have left us with no option but violence.\n\nShow him no mercy.", objectives = "Kill Warlord Kalithresh and return to Watcher Jhang inside the Steamvault.", completion = "I wish it had not come to this, but the naga refused all attempts to negotiate." }
WordHunterWoW_QuestEN[29614] = { title = "Containment is Key", description = "The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault.\n\nClear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!", objectives = "Kill 3 Bog Overlords, 6 Coilfang Lepers, and obtain an Irradiated Gear from Mekgineer Steamrigger, then return to Naturalist Bite inside the Steamvault.", progress = "Be as thorough as possible. The fate of Zangarmarsh depends on it.", completion = "I'm glad we were able to contain this before it spread across all of Zangarmarsh or further. Thank you." }
WordHunterWoW_QuestEN[29615] = { title = "Windcaller Claw and the Water Thief", description = "The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts.\n\nTaking her out would seriously hinder their operation.", objectives = "Kill Hydromancer Thespia and return to Windcaller Claw inside the Steamvault.", progress = "Did you dispatch of the water thief?", completion = "Perhaps now we can restore all of the desperately needed water to the land." }
WordHunterWoW_QuestEN[29616] = { title = "Storming the Steamvault", description = "We have not as of yet been able to stop the naga in the Steamvault, where most of their pumping infrastructure is located.\n\nThankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?", objectives = "Speak with Watcher Jhang in the Steamvault.", completion = "Thank the stars you're here. We need your help!" }
WordHunterWoW_QuestEN[29617] = { title = "Tian Monastery", description = "People come from all over Pandaria to train at the Tian Monastery, just to the north of here. Probably because they never turn anybody down. They'll accept jinyu, hozen... or even a foreign {race} like you!\n\nMy childhood friend, Lin, just joined the monastery's order a few weeks ago. If you're interested in learning how our monks train, maybe you should go talk with her!", objectives = "Speak with Lin Tenderpaw at the Tian Monastery in the Jade Forest.", completion = "You've arrived at an exciting time. High Elder Cloudfall has agreed to take on a new class of trainees within the monastery. This could be my big chance to finally learn how to fight!" }
WordHunterWoW_QuestEN[29618] = { title = "The High Elder", description = "How strange, to have such a foreign-looking {class} visiting our temple. Are you here to study?\n\nYou... you look very strong. You wouldn't have any trouble getting accepted into the monastery. You should talk to the High Elder, up on the balcony above.", objectives = "Speak with High Elder Cloudfall at the Tian Monastery in the Jade Forest.", completion = "Welcome to Tian Monastery. I see young Lin has helped you understand the role we fill here in our hilltop village.\n\nWe are unaccustomed to outsiders. You would do us a great honor to train alongside our younglings. We do not have anything to offer you, <class>... except knowledge, and perhaps an appreciation of what it means to be pandaren." }
WordHunterWoW_QuestEN[29619] = { title = "A Courteous Guest", description = "I heard, I heard! The High Elder wants you to train with us!\n\nThere's going to be a banquet for us, the trainees... and you should probably bring a gift, as a sign of courtesy.\n\nThe oranges in the grove south of the temple are extra-sweet right now. Bring some back, for the banquet.", objectives = "Gather 8 Ripe Oranges from the orange groves south of Tian Monastery.", progress = "Are you ready for the banquet? I can't wait.", completion = "These will do perfectly. What a thoughtful gift, <name>!\n\nMe? I'm bringing beer, of course." }
WordHunterWoW_QuestEN[29620] = { title = "The Great Banquet", description = "The banquet should be starting any time now. Go find the High Elder and pay your respects. I'll be right behind you.", objectives = "Speak with High Elder Cloudfall at the banquet grounds in the Tian Monastery.", progress = "We will move on to the training soon enough, young <class>. First, we must talk, and drink, and eat.\n\nThough I must say, I admire your discipline.", completion = "That concludes our introductions. You should be ready to begin your training.\n\nThat is... you should be ready to begin your training... AFTER we have one more mug of ale. Perhaps two. Shall we, <name>?" }
WordHunterWoW_QuestEN[29621] = { title = "UNUSED", description = "I have but one task for you, and it is a simple one. I would like you to speak with the spirits of the high elders that came before Cloudfall.\n\nTheir spirits have left their bodies, but they have not left this place. Go, speak with them, absorb their wisdom, and curry their favor.\n\nI anxiously await your return.You will receive:", objectives = "Speak with the four High Elder spirits in Tian Monastery." }
WordHunterWoW_QuestEN[29622] = { title = "Your Training Starts Now", description = "<Xiao does not look up from his bowl.>\n\nHey, new guy! Glad to see you survived the banquet! Trial One: Complete!\n\n<Xiao eats noisily.>\n\nYou'd better speak up with Instructor Xann. He'll be expecting you for your daily exercises.\n\n<He continues eating. You suspect that he is done talking to you.>", objectives = "Report to Instructor Xann at the Tian Monastery in the Jade Forest.", completion = "First, you drink too much beer... and then you show up to class late? Looks like you've already conformed to pandaren culture.\n\nLet's begin." }
WordHunterWoW_QuestEN[29623] = { title = "Perfection", description = "Perfection can be achieved through repetition. Every single student in the training arena below will eventually perfect his or her form... assuming they don't give up first. This is a fact.\n\nI encourage you to join them, {name}. As an honorary guest of the monastery, you are not required to perform the requisite 10,000 daily strikes. Simply follow the leader's example for a few minutes.", objectives = "Perform 12 practice strikes in the Monastery Training Arena by following the leader's example.", progress = "I, too, once trained in this very arena. Times were simpler then.", completion = "This isn't your first time fighting, is it? Your form isn't perfect, but it is certainly practiced." }
WordHunterWoW_QuestEN[29624] = { title = "Attention", description = "Your next test also involves concentration and attention. I want you to practice your abilities on the training bags in the pit below.\n\nThe bags are hung in groups of two. When I call out \"Left\", attack the bag on the left. When I call out \"Right\", attack the bag on the right.\n\nIf you fail to follow my simple directions, this task will become much harder.\n\nNow beat on those practice bags until they burst, {name}.", objectives = "Destroy 2 Training Bags. Follow Instructor Xann's instructions to determine which bags to attack.", progress = "What are you waiting for?", completion = "You may not be a full-time trainee here, but do not let that keep you from learning anything.\n\nI can assure you, the ability to quickly switch targets will prove valuable in future fights." }
WordHunterWoW_QuestEN[29625] = { title = "UNUSED", description = "temp", objectives = "temp" }
WordHunterWoW_QuestEN[29626] = { title = "Groundskeeper Wu", description = "We don't have many rules here, but we do have one particular rule that is worth remembering. If you want to eat...\n\n<Xiao's stomach grumbles audibly.>\n\n...you have to work. Groundskeeper Wu can give you your chores for the day. He's in the market, to the west.", objectives = "Report to Groundskeeper Wu at the Tian Monastery in the Jade Forest.", completion = "<Wu addresses you sharply.>\n\n<name>, is it? The High Elder's favored son? Yes, I remember you from the banquet.\n\nDon't expect any special treatment from me, boy. You'll be working just as hard as the greenest pandaren trainee here.\n\nPerhaps harder." }
WordHunterWoW_QuestEN[29627] = { title = "A Proper Weapon", description = "First things first, though.\n\nA proper trainee needs a proper weapon. And a scrupulous trainee builds his own... or at least gathers the materials.\n\nThe switches which grow nearby should suffice for any respectable weapon. You'll also need to shop for black walnut extract to treat the wood. While you're there, get some ale, for...\n\n<Wu pauses.>\n\n...well, you know what ale is for.", objectives = "Obtain 6 Rattan Switches from the area around the market in the Tian Monastery.\n\nPurchase a vial of Black Walnut Extract from June Whiteblossom.\n\nPurchase 3 Triple-Bittered Ales from Brewmaster Lei Kanglei.", progress = "<Wu looks at you expectantly.>", completion = "<Groundskeeper Wu gratefully scoops up the gathered materials.>\n\nI will have a weapon prepared for you by the end of your training. Now, onto the real work." }
WordHunterWoW_QuestEN[29628] = { title = "A Strong Back", description = "Some of our trainees have... larger-than normal appetites. We have occasionally had difficulty supplying enough food for all of them. In times like these, we have to ask for help.\n\nA kindly older woman, who lives in a small house to the northwest, has agreed to make some stew for our trainees. All you need to do is go and get it.", objectives = "Obtain a Boiling Cauldron from Mother Wu in the Waxwood Forest, then return to Groundskeeper Wu in the Tian Monastery.", progress = "She really is a nice woman. And an excellent cook.\n\nThe best cook in the world, actually.", completion = "I will see to it that this stew is distributed evenly and appropriately among the trainees.\n\nAfter I set some aside for myself, of course." }
WordHunterWoW_QuestEN[29629] = { title = "A Steady Hand", description = "The black walnut extract you purchased from Miss Whiteblossom is but one of many extracts we keep in stock for various applications.\n\nBlushleaf extract can be gathered from the flowers in the Waxwood Forest to the west. Several units can be extracted from one flower, but only those with calm nerves and steady hands can remove all of the extract from one flower.", objectives = "Obtain 80 vials of Blushleaf Extract from Blushleaf Clusters in the Waxwood Forest.", progress = "It is said that the ancient herbalism masters were able to remove 20 vials of extract from each blossom.", completion = "Do not forget to wash your hands. Blushleaf stains forever." }
WordHunterWoW_QuestEN[29630] = { title = "And a Heavy Fist", description = "The greenwood sprites in the Waxwood Forest to the west pose no direct threat to us, this is true. However, their numbers have increased as of late, as have their wily antics.\n\nPart of our duty as wardens of this forest is to maintain the balance. Your duty is to do so by returning these sprites to the earth.", objectives = "Slay 10 Greenwood Tricksters in the Waxwood Forest.", progress = "Very recently, I was walking in the Waxwood, when one of these sprites got on all fours behind my knees, evading my notice. Soon afterward, a second sprite approached me from the front, shoving me forcefully in the chest. Unaware of the first sprite, I stepped backwards, only to stumble on his prostrate form and fall, embarrassingly, onto my backside.\n\nSo yes, I have a vested interest in this assignment.", completion = "Thank you, <name>. The sprites' numbers will return in several days' time, but for now, the balance is maintained." }
WordHunterWoW_QuestEN[29631] = { title = "Burning Bright", description = "Might I ask a favor of you, trainee {name}?\n\nBefore I came to the monastery, I was a stranger to battle. During my time as a trainee, I performed adequately, but I was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am expected to protect this perimeter at all costs.\n\nI can handle greenwood sprites, but the tigers in the western Waxwood are something different altogether. Would you mind taking care of them for me?", objectives = "Slay 6 Waxwood tigers.", progress = "Please, do not speak of our arrangement with others. My cowardice shames me.", completion = "Thank you, <name>. A thousand times, thank you." }
WordHunterWoW_QuestEN[29632] = { title = "Becoming Battle-Ready", description = "Alright, {race}. I'd like to see what you're really made of.\n\nYou'll find my pupils all over the monastery. Challenge them to fights. Push them to their limits. They have been instructed to do the same to you.\n\nWin or lose, you both will come out of the fight stronger.", objectives = "Defeat 8 Tian Pupils in sparring matches at the Tian Monastery.", progress = "You may be a hero in your own lands, but here, you must prove your worth.", completion = "<Master Stone Fist eyes you warily.>\n\nAlright, I've seen enough. No more beating up on the younger pupils. We will proceed to the next phase." }
WordHunterWoW_QuestEN[29633] = { title = "Zhi-Zhi, the Dextrous", description = "Upon the hills to my right, you will find a hozen named Zhi-Zhi. He, too, won enough sparring matches to move up the ranks. I think he will provide you with more of a challenge.\n\nChallenge him, and try to defeat him.", objectives = "Defeat Zhi-Zhi at the Tian Monastery.", progress = "Zhi-Zhi's style is different than that of most pandaren monks. He and his kind tend to have more... energy... than us.", completion = "It appears that I must move you up the ranks yet again, <class>." }
WordHunterWoW_QuestEN[29634] = { title = "Husshun, the Wizened", description = "The jinyu are long-standing allies of the pandaren, and we welcome any of their kind into our monastery. Husshun, one of their elder shaman, is one of our newest trainees.\n\nHis skills as a monk are mediocre at best, but he is still a fierce combatant. He should provide you with the challenge that you deserve.", objectives = "Challenge and defeat Husshun at the Tian Monastery.", progress = "I do not know why he decided to take the monastic path so late in life. It is not my place to ask. Such questions fall under the responsibility of our Spirit-Sage.", completion = "I must warn you, <class>:\n\nIf you continue defeating my best trainees, I will no longer be able to train you. And then you will have no excuse to enjoy the presence of my company.\n\nThink wisely before you quickly dispatch any more of my students." }
WordHunterWoW_QuestEN[29635] = { title = "Xiao, the Eater", description = "You may have already met my best student, Xiao, at the banquet tables. I personally would have graduated him several times over, but Instructor Xann insists that he needs more discipline.\n\nIf you ask me, discipline means very little if you win every fight you enter. I'm curious to see if Xiao can keep his streak alive against you.", objectives = "Challenge and defeat Xiao at the Tian Monastery.", progress = "Young Xiao has a great future in martial arts. I wish you luck in your upcoming match.", completion = "I must admit, I was never surprised, <race>. You are a born fighter, and an excellent <class>." }
WordHunterWoW_QuestEN[29636] = { title = "A Test of Endurance", description = "I have taught you everything that I can, {name}. It is time you spoke with Instructor Myang.\n\nThe fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait.\n\nFarewell, {name}, and best of luck on the remainder of your training.", objectives = "Report to Instructor Myang on the western side of the Tian Monastery.", completion = "Greetings, <name>. You are becoming quite famous among the trainees here. I have already heard your name whispered several times, usually between the puffy and discolored lips one of your sparring partners.\n\nI'm looking forward to working with you." }
WordHunterWoW_QuestEN[29637] = { title = "The Rumpus", description = "Master Stone Fist has trained you in the art of one-on-one combat. Now you learn the art of one-on-many.\n\nHow does fifty sound?\n\nLower yourself into the Ring of Inner Focus below, then, when you're ready, set off this firework. My assistants will come at you, several at a time.\n\nAll you need to do is survive.", objectives = "Set off the Monastery Fireworks in the Ring of Inner Focus, then survive the Rumpus for two minutes.", progress = "Good luck, <name>.", completion = "Your <class> fighting style is strong, <name>. Our trainees could learn much from watching you." }
WordHunterWoW_QuestEN[29638] = { title = "UNUSED", description = "Your training is over, young one. The cycle is complete. Thankfully, this particular cycle ends exactly where it started... with a banquet.\n\nI will meet you over at the banquet grounds. I will likely be dancing on a table.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.Your training is over, young one. The cycle is complete. Thankfully, this particular cycle ends exactly where it started... with a banquet.\n\nI will meet you over at the banquet grounds. I will likely be dancing on a table.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29639] = { title = "Flying Colors", description = "You have passed every test we prepared for you, {name}. It is now time for you to move on to bigger and better things.\n\n...but not before another banquet. The High Elder will be waiting for you at the banquet grounds to celebrate your graduation from our monastery.", objectives = "Report to High Elder Cloudfall at the Tian Monastery in the Jade Forest.", completion = "Congratulations, <name>. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit." }
WordHunterWoW_QuestEN[29640] = { title = "Find Spy To'gun", description = "The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in!\n\nYou must find him. He may be reckless, but we need to find out what he knows.", objectives = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", completion = "Do you think you could help me get out of this cage?  It's a bit cramped." }
WordHunterWoW_QuestEN[29641] = { title = "The Soul Devices", description = "They've been torturing me, trying to get me to tell them everything that I know.\n\nThey fed the others to Hellmaw, and I was to be next. But I told them nothing!\n\nThey're using special devices to make their summoning more powerful. You must steal these devices!", objectives = "Steal 5 Soul Devices and deliver them to Spy Grik'tha inside the Shadow Labyrinth of Auchindoun.", progress = "Were you able to find To'gun?", completion = "So, these are the soul devices that the Shadow Council were using to enhance their summoning power?  Intriguing." }
WordHunterWoW_QuestEN[29642] = { title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", objectives = "Report to Field Commander Mahfuun inside the Shadow Labyrinth at Auchindoun in Terokkar Forest.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!" }
WordHunterWoW_QuestEN[29643] = { title = "The Codex of Blood", description = "Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake.\n\nRead the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.", objectives = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!" }
WordHunterWoW_QuestEN[29644] = { title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!", objectives = "Destroy Murmur and inform Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", completion = "I cringe to think what would have happened had Murmur escaped to the outside world.\n\nThank you, brave hero." }
WordHunterWoW_QuestEN[29645] = { title = "Ambassador Hellmaw", description = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one.\n\nOur men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw.\n\nIt is a most deserving fate.", objectives = "Kill 12 Cabal Ritualists and Ambassador Hellmaw, then return to Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", completion = "It won't bring anyone back, but at least justice has been done." }
WordHunterWoW_QuestEN[29646] = { title = "Flying Colors", description = "Well, I've done all that I can with you. Sounds like the others have, too.\n\nHigh Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate your departure. Not that we're happy you're leaving... he just enjoys celebrations.", objectives = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.", completion = "Congratulations, <name>. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit." }
WordHunterWoW_QuestEN[29647] = { title = "Flying Colors", description = "The Rumpus was your final test. You have mastered the disciplines taught at this monastery.\n\nJust as your training began with a banquet, so shall it end. High Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.", objectives = "Report to High Elder Cloudfall at the Banquet Grounds in the Jade Forest.", completion = "Congratulations, <name>. While your traineeship was strictly honorary, your results were undeniably impressive. The young ones look up to you.\n\nGroundskeeper Wu had this prepared for you. Please, use it as you see fit." }
WordHunterWoW_QuestEN[29648] = { title = "UNUSED", description = "", objectives = "" }
WordHunterWoW_QuestEN[29649] = { title = "How to Save a Life", description = "Gunny is dying from a powerful curse, {name}.\n\nGrand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?", objectives = "Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", progress = "Did you bring the ember? We don't have much time!", completion = "He was a good soldier." }
WordHunterWoW_QuestEN[29650] = { title = "Fel Ember", description = "Caza'rez is dying a coward's death.\n\nGrand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?", objectives = "Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", progress = "Did you bring the ember? Caza'rez deserves a warrior's death.", completion = "I will sing many songs of his glories." }
WordHunterWoW_QuestEN[29651] = { title = "Honor the Dying", description = "Their elite warriors are ruthless... so... powerful.\n\n<Caza'rez spits up blood.>\n\nYou have to kill them... or we will never defeat Kargath...\n", objectives = "Caza'rez inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", progress = "Are they dead, <class>?", completion = "Caza'rez...is no more." }
WordHunterWoW_QuestEN[29652] = { title = "One Last Favor", description = "Ol' Gunny doesn't have much longer...\n\nDo me one last favor, and kill the biggest, meanest fel orcs ye can find.\n\nFor old times' sake, aye?", objectives = "Gunny inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", progress = "Did ye kill 'em?", completion = "If only we could have saved him." }
WordHunterWoW_QuestEN[29653] = { title = "The Will of the Warchief", description = "Kargath was once one of the Horde's greatest heroes.\n\nHe now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.", objectives = "Bring Warchief Kargath's Fist to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "We should not forget the orc Kargath once was, nor the lessons to be learned from his downfall." }
WordHunterWoW_QuestEN[29654] = { title = "Turning the Tide", description = "There is only one true way to end the fel orc threat to Honor Hold and the Alliance.\n\nTheir Warchief must be slain.\n\nBring me his namesake weapon, so that we can always remember his death.", objectives = "Bring Warchief Kargath's Fist to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "We have struck a major blow against the enemy with your help.\n\nHonor Hold is far safer than it's been in years." }
WordHunterWoW_QuestEN[29655] = { title = "A Very Special Cloth", description = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful.\n\nTake him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!", objectives = "Kill Warbringer O'mrogg and bring his warcloth to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", progress = "Did you bring me the cloth?", completion = "Well done. This will show those blood crazed monsters what they're up against." }
WordHunterWoW_QuestEN[29656] = { title = "O'mrogg's Warcloth", description = "Stormwind wants to see proof of our successes in the war effort.\n\nRather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?", objectives = "Kill Warbringer O'mrogg and bring his warcloth to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", progress = "Did you bring me the cloth?", completion = "My superiors will be very pleased to see this. Thank you." }
WordHunterWoW_QuestEN[29657] = { title = "With Great Power, Comes Great Responsibility", description = "<A voice like the sound of light bells rings in your head.>\n\nThe Mechanar employs my race's technology to create manacells, objects which provide great amounts of power.\n\nI need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.", objectives = "A'dal has asked you to slay Mechano-Lord Capacitus in the Mechanar of Tempest Keep.", completion = "You have done well, <name>. But more work remains to be done." }
WordHunterWoW_QuestEN[29658] = { title = "The Calculator", description = "<A gentle wind caresses your face.>\n\nOne more task yet remains.\n\nPathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world.\n\nI ask that you eliminate him.", objectives = "A'dal has asked you to slay Pathaleon the Calculator in the Mechanar of Tempest Keep.", completion = "You have my gratitude, <name>." }
WordHunterWoW_QuestEN[29659] = { title = "Lost Treasure", description = "I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion.\n\nWe cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.", objectives = "Retrieve the Blinding Fury for A'dal from the Cache of the Legion in the Mechanar of Tempest Keep.", progress = "You've obtained it, I assume?", completion = "You have done well. Any advantage we can take away from Kael'thas' forces is to our benefit." }
WordHunterWoW_QuestEN[29660] = { title = "Saving the Botanica", description = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs.\n\nThe first step is to eliminate their forces so that they cannot cause further problems.", objectives = "A'dal wants you to kill Commander Sarannis, High Botanist Freywinn, and Thorngrin the Tender inside the Botanica of Tempest Keep.", completion = "They were going to die to the creatures contained here soon even without our interference. It is for the greater good." }
WordHunterWoW_QuestEN[29661] = { title = "The Lesson of Dry Fur", description = "Through meditation, I intend to find a route to locating Shu. In the meantime, you would benefit from practice and discipline.\n\nYour first task is the task of all trainees entering the pools: cross the balance poles to the west and ring the bell without falling into the pool.\n\nShould you fall, the pool's curse will make it difficult to get on a pole again, so you will need to return to the edge of the pool to start over.\n\nOh, and beware the cranes.", objectives = "Cross the balance poles and ring the training bell.", completion = "Good. You're a quick study." }
WordHunterWoW_QuestEN[29662] = { title = "Stronger Than Reeds", description = "Gather me reeds from the nearby pools.\n\nDo not question why. Do, and then observe the results.", objectives = "Gather 8 Hard Tearwood Reeds.", progress = "Telling you of my strength means nothing. I must show you.", completion = "Good.\n\nNo number of reeds have ever withstood my might.\n\nStep back, and let me dispel your doubts." }
WordHunterWoW_QuestEN[29663] = { title = "The Lesson of the Balanced Rock", description = "I require peace to perform my meditation. Practice your arts while I meditate on Shu's location.\n\nOther monks practice balance and combat upon the balance poles in the surrounding pools. Engage them and defeat them.", objectives = "Defeat 6 Tushui Monks atop the balance poles.", completion = "Even now, your skills increase. Your footing becomes more sure. Your blows strike with more force.\n\nDiscipline and practice are the keys to reaching our full potential." }
WordHunterWoW_QuestEN[29664] = { title = "The Challenger's Fires", description = "You're strong of mind and strong of will, but you lack the skills to face me in combat. You must fight with your body, but in truth, it is your character that is being tested.\n\nLet us even the playing field.\n\nTake this torch, light it in the brazier next to me, and then use it to light the three unlit braziers around the pool.", objectives = "Light your Unlit Challenger's Torch at the Brazier of Flickering Flame, then use it to light the 3 braziers near Master Li Fei.", completion = "These fires will give you the strength that you've not yet obtained. They will illuminate your potential." }
WordHunterWoW_QuestEN[29665] = { title = "From Bad to Worse", description = "After their ship crashed, evil creatures swept up from the sea to pick through the wreckage. Our aid may seem but a drop in the pond at the thought of the misfortune they've faced today.\n\nDefeat their tormentors. These people desperately need our help.", objectives = "Defeat 8 Deepscale Tormentors.", completion = "You are a fear to behold upon the battlefield." }
WordHunterWoW_QuestEN[29666] = { title = "The Sting of Learning", description = "There are dangers in the pools. The latest and most vicious are the water pincers. A time has come for their numbers to be diminished, and I am no longer up to the task.\n\nIf you could clear out some of the water pincers, I would be very appreciative. Beware their numbers... sometimes it's best to lure them from the pool-side rather than wading all the way in.", objectives = "Kill 6 Water Pincers.", completion = "The water pincers are strange creatures. They seem to be drawn to still water." }
WordHunterWoW_QuestEN[29667] = { title = "Culling the Herd", description = "It seems that Kael'thas' forces have twisted the Botanica's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have.\n\nThere is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.", objectives = "A'dal has asked you to kill 6 Mutate Fleshlashers, 6 Mutate Fear-shriekers, 6 Mutate Horrors, and to obtain a Rapidly Evolving Frond from Laj in the Botanica of Tempest Keep.", progress = "I see you have obtained the frond. Very good.", completion = "You have done well thus far, <name>. However, there is still one more task I must ask that you complete." }
WordHunterWoW_QuestEN[29669] = { title = "A Most Somber Task", description = "I must now ask you to complete a most somber task.\n\nWarp Splinter used to act as guardian to all of the Botanica. He is now impure, and must be taken down.", objectives = "A'dal has asked you to slay Warp Splinter in the Botanica of Tempest Keep.", completion = "He was a noble guardian in life. His presence will be missed." }
WordHunterWoW_QuestEN[29670] = { title = "Maul Gormal", description = "Thanks to you, there's a small militia of farmers hiding nearby. Hanae said something about giving them \"liquid courage\" which, I'm pretty sure, means they're sauced and ANGRY.\n\nThe mogu think they can walk all over us - we'll give them a fight that will open their eyes.\n\nFollow the trail through the ruins and down to the beach. Find their leader. When you engage him, we'll be there to back you up.", objectives = "Kill Subjugator Gormal in Camp Gormal.", progress = "We are ready to fight the mogu leader whenever you are.", completion = "This is extremely unsettling. If mogu are banding together like this all over the continent, it could become a major threat to Pandaria." }
WordHunterWoW_QuestEN[29671] = { title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.Upon completion of this quest you will gain:", objectives = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29672] = { title = "The Opening of the Dark Portal", description = "Here the Guardian Medivh feverishly works to open the Dark Portal.\n\nScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.\n\nKill their rift lords and leaders until Medivh succeeds!You will be able to choose one of these rewards:", objectives = "Sa'at inside the Black Morass of the Caverns of Time has tasked you with defending Medivh until he succeeds in opening the Dark Portal.\n\nReturn to Sa'at should you succeed in your task." }
WordHunterWoW_QuestEN[29673] = { title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.Upon completion of this quest you will gain:", objectives = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29674] = { title = "Unbound Darkness", description = "<The sound of chimes enters your head, but it is distressed.>\n\nWe imprisoned the most dangerous beings we came across in our travels.\n\nZereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.", objectives = "A'dal has asked you to slay Zereketh the Unbound in the Arcatraz of Tempest Keep.", completion = "Creatures of the void are naturally chaotic. They are a necessary part of the universe, but they must be kept in check by the Light." }
WordHunterWoW_QuestEN[29675] = { title = "Hey There Dalliah", description = "Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer, have begun rallying the demons on board together into a small army.\n\nYou cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.", objectives = "A'dal has asked you to kill Wrath-Scryer Soccothrates and Dalliah the Doomsayer in the Arcatraz of Tempest Keep.", completion = "The Legion seeks only to consume. They hold no regard for the balance." }
WordHunterWoW_QuestEN[29676] = { title = "Finding an Old Friend", description = "It seems Shu, the spirit of water, had a play companion when he came to the pools throughout the years. An old pandaren we know as Old Man Liang.\n\nLiang moved away from the main town and stopped practicing in the pools some time ago. I am told he lives in a small house northeast of here, up the hill.\n\nLiang may know what has driven Shu away, and where the spirit might be found.\n\nGo to Liang. Ask of Shu.", objectives = "Speak to Old Man Liang at Liang's Retreat in the Singing Pools.", completion = "Visitors are rare up here, but you are welcome. It is nice to meet you, young <class>." }
WordHunterWoW_QuestEN[29677] = { title = "The Sun Pearl", description = "Shu, the spirit of water, is eternally young, as are all the spirits of Shen-zin Su. I have been friends with Shu all of my life, but I no longer have it within me to play with him. I am old, and lack the energy.\n\nFor all his complexities, Shu is simple to please: he desires friendship. When I returned to play with Shu each season, I would always bring a Sun Pearl as a gift, and then we would play together. You can find a Sun Pearl in the pools to the southeast. Perhaps you can be his new friend.", objectives = "Retrieve the Sun Pearl.", progress = "The decision to not return to the pools was a hard one. I don't think Shu ever truly understood. He does not know what it is to get older and weaker.", completion = "Shu's desires are not so different from our own. He does not want to be alone. Unwanted, unloved. He longs to be needed, and to share his life with others.\n\nKnowing that, earning his trust is not terribly difficult. He just wants company." }
WordHunterWoW_QuestEN[29678] = { title = "Shu, the Spirit of Water", description = "Shu, the spirit of water, is sulking in the deep pool to the north. Cross the rocks and then drop the sun pearl in the center of the pool. He will know what this means.", objectives = "Coax Shu, the spirit of water, into a game." }
WordHunterWoW_QuestEN[29679] = { title = "A New Friend", description = "He wants you to play with him. Go for it!", objectives = "Water walk into 5 of Shu's Water Spouts.", progress = "This is your task, <class>. See it through.", completion = "I have to admit, that looked pretty fun from my angle.\n\nAnd you seem to have made a new friend." }
WordHunterWoW_QuestEN[29680] = { title = "The Source of Our Livelihood", description = "We have done as Master Shang asked of us. I will return to the temple to inform the master of our progress. You should continue south on the road to the farmlands to seek out Wugou, the spirit of earth.\n\nJi awaits you at the Dai-Lo Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his directness. Remember well the things I have taught you: discipline and patience.", objectives = "Speak to Ji at the Dai-Lo Farmstead. A cart is waiting near the road to take you there.", completion = "<name>! I wondered when I would see you again!\n\nWell, the plus side is that finding Wugou, the spirit of earth, was easy enough. Waking him... not so much. I think he's going to wake quite sore from all the pushing and hitting I've done trying to rouse him." }
WordHunterWoW_QuestEN[29681] = { title = "Maximum Security Breakout", description = "Harbinger Skyriss is the heart of the problem in the Arcatraz.\n\nHe corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose.\n\n{name}, you cannot let a servant of the Old Gods live!", objectives = "A'dal has asked you to slay Harbinger Skyriss in the Arcatraz of Tempest Keep.", completion = "Thank you, <name>. Your actions this day have prevented countless tragedies." }
WordHunterWoW_QuestEN[29682] = { title = "Magisters' Terrace", description = "We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there.\n\nHowever, we haven't heard from them since, and I fear the worst.\n\nWill you go there and try to find Exarch Larethor? He's in charge of the expedition.", objectives = "Captain Theris Dawnhearth wants you to find Exarch Larethor inside the Magisters' Terrace.", completion = "Dawnhearth thought we were dead? Hah!\n\nI haven't sent a report because we haven't made any progress past this point.\n\nPerhaps you can help us change that?" }
WordHunterWoW_QuestEN[29683] = { title = "The Scryer's Scryer", description = "<Tyrith winces in pain as he speaks.>\n\nGo to the terrace... use the orb.\n\n...They're...feeding the sunwell....\n\n <Tyrith gasps for breath.>\n\nHurry... They must be stopped... before they can....\n\n<Tyrith dies.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace." }
WordHunterWoW_QuestEN[29684] = { title = "Severed Communications", description = "We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him.\n\nThe information he was collecting is vital to our mission.", objectives = "Exarch Larethor inside the Magisters' Terrace wants you to find Tyrith, a blood elf spy.", completion = "...Come closer, <race>... Listen carefully to my words...." }
WordHunterWoW_QuestEN[29685] = { title = "Hard to Kill", description = "As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.", objectives = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor inside the Magisters' Terrace.", progress = "Well, <class>, I must admit, I wasn't sure I'd see you again.", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain." }
WordHunterWoW_QuestEN[29686] = { title = "A Radical Notion", description = "We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die.\n\nThe Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.", objectives = "Exarch Larethor in the Magisters' Terrace wants you to kill Vexallus and obtain its essence.", progress = "Were you able to get your hands on its essence?", completion = "Excellent! I can't wait to present this project to my superiors!" }
WordHunterWoW_QuestEN[29687] = { title = "Twisted Associations", description = "The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply.\n\nFrom what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.", objectives = "Exarch Larethor in the Magisters' Terrace wants you to kill Selin Fireheart and Priestess Delrissa.", completion = "Well done, soldier. One step at a time." }
WordHunterWoW_QuestEN[29688] = { title = "Advancing the Campaign", description = "I mostly listen, {class}. I listen so that the Warchief doesn't have to.\n\nI've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls, seat of power for the fel orcs.\n\nGo speak with Stone Guard Stok'ton, he's in charge there.", objectives = "Shadow Hunter Ty'jin has asked you to speak with Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", completion = "Keep your head down, or it's likely to end up on the wrong end of an arrow." }
WordHunterWoW_QuestEN[29689] = { title = "Advancing the Campaign", description = "The time has come to lay the final blow against the fel orcs.\n\nAdvance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!", objectives = "Force Commander Danath Trollbane has asked you to speak with Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", completion = "Be quiet! We'll surely be overwhelmed if they notice us now." }
WordHunterWoW_QuestEN[29690] = { title = "Into the Mists", description = "<Nazgrim fills his lungs with sea air.>\n\nYou smell that, {name}? It's the smell of our home, the lands our kind have bled and died to preserve.\n\nAnd listen... you hear that? It's the sound of peace and safety - a haven we've carved, where our enemies fear to tread.\n\nRemember these things. You won't experience them again anytime soon. We have ourselves a war to win.\n\nNow go get settled, we're shovin' off!", objectives = "Speak to General Nazgrim on Hellscream's Fist.", completion = "<name>!?\n\nThey told me you were dead...\n\nI'm glad to see it wasn't true. There's Alliance to kill!" }
WordHunterWoW_QuestEN[29691] = { title = "Bring Me A Shrubbery!", description = "My people use sanguine hibiscus for a number of purposes.\n\nIt grows naturally only in the Underbog, and many of the bog's denizens have taken a liking to it.\n\nIf you could bring me some, I would be very grateful.", objectives = "Collect 5 Sanguine Hibiscus and return them to T'shu in the Underbog.", progress = "Were you able to gather any hibiscus?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
WordHunterWoW_QuestEN[29692] = { title = "Bring Me Another Shrubbery!", description = "", objectives = "We can still use more sanguine hibiscus. We're always struggling to find more.\n\nBring them to me in bunches of five and I will be most grateful.", progress = "We can still use more sanguine hibiscus. We're always struggling to find more.\n\nBring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
WordHunterWoW_QuestEN[29693] = { title = "The General's Edge", description = "As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage.\n\nIt occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling...\n\nYou know that dead or alive, the General would want his weapon back in his possession.", objectives = "Bring Nazgrim's axe to General Nazgrim.\n\nProvided item:" }
WordHunterWoW_QuestEN[29694] = { title = "Regroup!", description = "They have an airbase! I have underestimated this Alliance Captain for the last time. So many good warriors lost...\n\nThere must have been a few survivors who were able to bail during the crash. We need every able-bodied fighter we can get.\n\nFind as many survivors as you can in the forest below, and I will investigate the wreckage itself. Rally everyone together at the nearby village for a counter-attack.", objectives = "Rescue Shademaster Kiryn, Rivett Clutchpop, Shokia, and Sergeant Gorrok from Honeydew Glade.", progress = "Did you find any survivors?", completion = "These are the only survivors, <name>?\n\nSo be it. We will play the hand fate has dealt us.\n\n\n\nNumbers be damned. This is where heroes are made." }
WordHunterWoW_QuestEN[29695] = { title = "Kiryn TRACKING", description = "", objectives = "" }
WordHunterWoW_QuestEN[29696] = { title = "My Stars!", description = "A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you.\n\nThe bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished.\n\nIf you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.", objectives = "Collect 100 of Kiryn's Throwing Stars from Devious Wood Sprites." }
WordHunterWoW_QuestEN[29697] = { title = "Rivett TRACKING", description = "", objectives = "" }
WordHunterWoW_QuestEN[29698] = { title = "Tracking Event: Alliance Banner Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[29699] = { title = "Tracking Event: Alliance Chest Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[29700] = { title = "Tracking Event: Bodyguard Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[29701] = { title = "Tracking Event: Journal Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[29702] = { title = "Gorrok TRACKING", description = "", objectives = "" }
WordHunterWoW_QuestEN[29703] = { title = "Barrel of Monkies", description = "These monkeymen are driving me insane!  I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them.  Can you please go take a few of them out as a lesson to the others?  I'll make it worth your while.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Sally Fizzlefury wants you to kill 5 drunken monkies." }
WordHunterWoW_QuestEN[29704] = { title = "Shokia TRACKING", description = "", objectives = "" }
WordHunterWoW_QuestEN[29705] = { title = "Invasion of the Bottle Snatchers", description = "As if the hozu weren't enough now we have a bunch of renegade dwarven brewmaster wannabes floating around.\n\n Can you please recover the brewskies they stole? It would cripple the Ironforge economy if this many \"entrepreneurs\" started popping up.You will receive:", objectives = "Sally Fizzlefury wants you to recover 5 stolen brewskies from the Brewhunters near the farm in Shen-zin Su." }
WordHunterWoW_QuestEN[29706] = { title = "Kegplosion", description = "Oh no <class>!  In what can only be described as a contrived act of contention, the nearby spirit walkers have become enraged.\n\nPlease do something about them before they eat our faces!You will receive:", objectives = "Kill 5 Enraged Spirit Walkers before they eat Sally Fizzlefury's face." }
WordHunterWoW_QuestEN[29707] = { title = "Tracking Event: Opened Shackle 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[29708] = { title = "Tracking Event: Opened Shackle 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[29709] = { title = "Tracking Event: Opened Shackle 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[29710] = { title = "Tracking Event: Looted Food Crate", description = "", objectives = "" }
WordHunterWoW_QuestEN[29711] = { title = "Tracking Event: Looted Scroll", description = "", objectives = "" }
WordHunterWoW_QuestEN[29712] = { title = "Horde Justice", description = "Your mind races as you struggle to come to terms with your predicament - shipwrecked on an uncharted land, nearly all of the crew lost....\n\nAs you look at the corpse of this unfortunate creature you realize that the area is crawling with his kind, and that they're pillaging whatever supplies haven't been destroyed.\n\nIt's time to introduce these vermin to some good old-fashioned Horde justice.", objectives = "Kill 15 Hozu at the Wreck of the Sky Shark." }
WordHunterWoW_QuestEN[29713] = { title = "Standard Protocol", description = "The Sky Shark has been totally destroyed.\n\nWith Alliance forces about, standard protocol requires the destruction of any sensitive technologies. These solenoids most certainly fall under that category.\n\nThe Horde's directives are clear, round up the solenoids for destruction.", objectives = "Gather 8 Unstable Solenoids." }
WordHunterWoW_QuestEN[29714] = { title = "Wet Work!", description = "If any Alliance naval forces have come ashore, the smoky fires from your crash will lead them right to you and what remains of your crew.\n\nThere must be a way to extinguish those flames...\n\nThis barrel seems to have survived the catastrophe intact. Perhaps it's still water-tight.\n\nOnly one way to find out!", objectives = "Collect 5 Water Globules from Spiritsong Lake and combine them with the Horde Barrel." }
WordHunterWoW_QuestEN[29715] = { title = "The Witch in the Woods", description = "Oh please {race}!  Can you help me?\n\nSome of the village children were playing in the woods and haven't come back. Could you please keep an eye out for them if you are going out there?\n\nI told those village rascals to leave that old widow up in the woods alone. My guess is they are probably harassing her. They think she is a witch.", objectives = "Find An Windfur on the road north of the Jade Witch Hut.Oh please <race>!  Can you help me?\n\nSome of the village children were playing in the woods and haven't come back. Could you please keep an eye out for them if you are going out there?\n\nI told those village rascals to leave that old widow up in the woods alone. My guess is they are probably harassing her. They think she is a witch." }
WordHunterWoW_QuestEN[29716] = { title = "The Double Hozen Dare", description = "There is a witch in the woods but no one believes me. She turned my friend Shin into jade!\n\nWe were all so scared we tried to run back but she sicced her big jade monsters on us. A bunch of my friends tried to get away by climbing trees.\n\nCan you help me save my friends?", objectives = "Rescue 6 Scared Pandaren cubs.", progress = "Where is Shin? I didn't see Shin.", completion = "Oh thank you so much for helping find my friends.  I still don't see Shin though..." }
WordHunterWoW_QuestEN[29717] = { title = "Down Kitty!", description = "I tried to fight one of the jade tigers in the woods but they were too scary. They stare at you and you turn to a jade statue!\n\nHonest truth! Chen's sister's friend Ni heard it from Kai's mom.\n\nI want to be brave like you though. Can you show me how to beat up those jade tigers?", objectives = "Destroy 8 Jade Guardians.", progress = "Wow! You are tough!", completion = "Wow! You were awesome! You were like *bam* and they were like *aaaaa* and then they were smashed!" }
WordHunterWoW_QuestEN[29718] = { title = "Sixteen Fluid Ounces of Prevention", description = "Better safe than sorry.\n\nThe pillars of smoke surrounding the crash site will be a beacon to any Alliance who might have seen your Zeppelin in distress.\n\nUntil you and your depleted crew get your bearings, you could do without that kind of trouble.\n\nExtinguishing the wreckage fires is just plain common sense.", objectives = "Use the Spirit-Touched Water Barrel to extinguish the four fires near the Zeppelin Wreckage." }
WordHunterWoW_QuestEN[29719] = { title = "The Double Hozu Dare", description = "Shin is still missing!\n\nI never... I mean the other kids never should have double hozu dared him to knock on the witch's door. \n\nWe saw a bunch of jade statues south of the Jade Witch's hut. \n\nCan you come with me and see if any of them are Shin?You will receive:", objectives = "Inspect 7 Lifelike Jade Statues south of the Jade Witch Hut." }
WordHunterWoW_QuestEN[29720] = { title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it!  I don't want to see the witch.  Can you please go talk to her?  You're an adult.  I don't think she would turn you into jade.", objectives = "Speak with the Widow Greenpaw at the Jade Witch Hut.The Jade Witch must still have Shin.\n\nI... I can't do it!  I don't want to see the witch. Can you please go talk to her?  You're an adult. I don't think she would turn you into jade.You will receive:" }
WordHunterWoW_QuestEN[29721] = { title = "An Offering", description = "Well young one, if you would do me a kindness before I help.  \n\nBehind my hut is a small pond.  I keep a stock of very rare fish that I need for ritual.  It was a favorite of my late husband.\n\nCould you please bring me one?You will receive:", objectives = "Widow Greenpaw has asked for you to bring her a fish from the pool behind the Jade Witch's Hut in the Jade Forest.Well young one, if you would do me a kindness before I help. \n\nBehind my hut is a small pond. I keep a stock of very rare fish that I need for ritual. It was a favorite of my late husband.\n\nCould you please bring me one?You will receive:" }
WordHunterWoW_QuestEN[29722] = { title = "A Lesson in Bravery", description = "Can you help teach me to be brave like you?\n\nWhen we played our prank on the witch we made a bunch of Leafy Tricksters angry.  I think the witch did something to them.\n\nCan you show me how you stand up to them?", objectives = "Defeat 8 Leafy Tricksters south of the Jade Witch Hut." }
WordHunterWoW_QuestEN[29723] = { title = "The Jade Witch", description = "The Jade Witch must still have Shin.\n\nI... I can't do it! I don't want to see the witch. Can you please go talk to her and see if she has Shin?\n\nYou're an adult, I don't think she would try to turn you into jade.", objectives = "Defeat the Jade Witch.", completion = "Hurray! Thank you so much! Shin is saved and you beat up the old witch! And the best part is our parents were never told what we were up to. Hurray!\n\nIt looks like everybody who came back are trying to get rid of whatever jade they had. Toya's been collecting it for some reason and said you should go chat with him." }
WordHunterWoW_QuestEN[29724] = { title = "Burial at Sea", description = "These savages are... ruthless.\n\nThey've dragged off our dying soldiers to be tormented in their camps. This is no way for our valiant brothers to die.\n\nI shall join them soon enough, {class}. Please, put my mind at ease and their bodies to rest.\n\nFind their remains at the camps surrounding the wreckage. Put them out of the reach of these creatures.", objectives = "Bring the 3 Vanguard Corpses to the Immobile Catapult at the Wreck of the Sky Shark." }
WordHunterWoW_QuestEN[29725] = { title = "SI:7 Report: Fire From the Sky", description = "Yeah, we found Amber, she's alive, and all that. That's about where the good news stops though.\n\nLet's see if I can pick up where ol' Rell left off...", objectives = "Listen to Sully's report.", progress = "I'm not done with the report yet, <name>. Settle down.", completion = "So, now you know why ol' Rell's all beat up.\n\n<You detect a change in Sully's facial expression, and he quickly turns away. Is he... crying?>" }
WordHunterWoW_QuestEN[29726] = { title = "SI:7 Report: Hostile Natives", description = "I... I can tell you what happened next! We continued north, into the forest...", objectives = "Listen to Little Lu's report.", completion = "Luckily, we all made it out alive.\n\nWell... all of us except for Socks..." }
WordHunterWoW_QuestEN[29727] = { title = "SI:7 Report: Take No Prisoners", description = "The final leg of our journey took us west, to a large hozen village. We set up a small camp in the mountains, outside of their line of sight...", objectives = "Listen to Amber Kearnen's report.", progress = "Please, allow me to finish.", completion = "So there you have it. We didn't find the White Pawn, but we came back with intel that could be of even greater importance to the Alliance.\n\nThe Horde have allied with the hozen, and are arming them as we speak. They and their monkey army now outnumber us thirty to one." }
WordHunterWoW_QuestEN[29728] = { title = "Explosive Evidence", description = "I must ask you to do one more thing for me, {name}.\n\nThe personal effects on this ship cannot be left for others to find. We'll have to destroy it.\n\nI cobbled together some Makeshift Dynamite from the scraps you brought me.\n\nPlace the dynamite anywhere on the ship, but take care not to put them too close together.\n\nThey might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.", objectives = "Plant 4 Makeshift Dynamite near the sunken ship at Sapphire's End. Makeshift Dynamite must be placed at least 10 yards apart." }
WordHunterWoW_QuestEN[29729] = { title = "Without a Trace", description = "The explosives are set. All we have to do now is pull the trigger.", objectives = "Press the detonator to erase the remaining evidence." }
WordHunterWoW_QuestEN[29730] = { title = "Scouting Report: Hostile Natives", description = "I bet I know your first question: \"What the ook happened to Sergeant Gorrok?\" Don't worry, don't worry. He's totally alive. Not dead or anything.\n\n<Riko shuffles uncomfortably.>\n\nWell, we THINK he's alive, but he ALSO might be very, very dead.\n\n<Riko looks into your eyes for approval.>\n\nFine! Let me tell you exactly what happened.", objectives = "Listen to Riko's report.", progress = "I'm not ookin' done yet!", completion = "So, as you can see, none of this is Riko's fault." }
WordHunterWoW_QuestEN[29731] = { title = "Scouting Report: On the Right Track", description = "MOST of what Riko said is true.\n\nWe didn't dare pursue Gorrok - the Horde's numbers here are far too few. Our forces can only sustain so many losses, and frankly, we don't know how powerful that witch really is.\n\nLet me pick up where the hozen left off...", objectives = "Listen to Kiryn's report.", progress = "If I may continue, please?", completion = "And that's how we found our Alliance captive.\n\nBut that's not all that happened. Not by a long shot..." }
WordHunterWoW_QuestEN[29732] = { title = "What Goes Down, Must Come Up!", description = "Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser.\n\nWith a simple calibration, the device is set to deliver drones to Nazgrim's basecamp.\n\nEasy enough....\n\nThere's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact.\n\nAs you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...", objectives = "Use the Goblin Drone Dispenser near the Exposed Root to recover supplies.\n\nNOTE: Each use will require one Cliff Glider Tail." }
WordHunterWoW_QuestEN[29733] = { title = "SI:7 Report: Lost in the Woods", description = "<Rell coughs heavily before speaking.>\n\nPlease, {name}. You need to hear what we've been through.\n\nThe whole damned Alliance needs to hear what we've been through. There may not be much time left.", objectives = "Listen to Rell's report.", progress = "<Rell doesn't look too good. He should probably save his energy.>", completion = "...and that's <cough> how we found...\n\n<Rell's speech devolves into heavy coughing. The corner of his mouth produces a trickle of blood.>" }
WordHunterWoW_QuestEN[29734] = { title = "Deepforge the Elder", description = "", objectives = "Your spirit burns with life, young <class>.  I accept the homage you pay, and offer in return this token..." }
WordHunterWoW_QuestEN[29735] = { title = "Stonebrand the Elder", description = "", objectives = "Your spirit burns with life, young <class>.  I accept the homage you pay, and offer in return this token..." }
WordHunterWoW_QuestEN[29736] = { title = "Darkfeather the Elder", description = "", objectives = "Your spirit burns with life, young <class>.  I accept the homage you pay, and offer in return this token..." }
WordHunterWoW_QuestEN[29737] = { title = "Firebeard the Elder", description = "", objectives = "Your spirit burns with life, young <class>.  I accept the homage you pay, and offer in return this token..." }
WordHunterWoW_QuestEN[29738] = { title = "Moonlance the Elder", description = "", objectives = "The heavens, in their countless stars, hold answers to earthly mysteries, <name>.  Might, then, the wise, and the lucky, gaze up and find truth?" }
WordHunterWoW_QuestEN[29739] = { title = "Windsong the Elder", description = "", objectives = "The heavens, in their countless stars, hold answers to earthly mysteries, <name>.  Might, then, the wise, and the lucky, gaze up and find truth?" }
WordHunterWoW_QuestEN[29740] = { title = "Evershade the Elder", description = "", objectives = "The heavens, in their countless stars, hold answers to earthly mysteries, <name>.  Might, then, the wise, and the lucky, gaze up and find truth?" }
WordHunterWoW_QuestEN[29741] = { title = "Sekhemi the Elder", description = "", objectives = "All tol'vir were once as I am. Now, my people are flesh and blood, and more in need of the wisdom of the ages than ever before." }
WordHunterWoW_QuestEN[29742] = { title = "Menkhaf the Elder", description = "", objectives = "All tol'vir were once as I am. Now, my people are flesh and blood, and more in need of the wisdom of the ages than ever before." }
WordHunterWoW_QuestEN[29743] = { title = "Monstrosity", description = "It's plain to see that this statue and the surrounding ruins are of ancient origin. Clearly, this land has a deep history, which means it could not have been born of the cataclysm.\n\nAnd yet these waters have been explored for ages now, with no record of anything here but open sea.\n\nPerhaps if you were to sketch the pieces of this broken statue, you might shed light on the continent's origins.", objectives = "Collect sketches of each piece of the ancient statue." }
WordHunterWoW_QuestEN[29744] = { title = "Some \"Pupil of Nature\"", description = "Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat.\n\nThese particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted.\n\nSo yeah, that's out.\n\nI guess we'll never know.\n\n<Weng coughs.>\n\nOrrrr... A big brave adventurer like YOU could go check it out! What do you say?", objectives = "Investigate the Woods of the Lost, northeast of the Greenstone Quarry." }
WordHunterWoW_QuestEN[29745] = { title = "The Sprites' Plight", description = "<Living statues rampage through the woods.\n\nFor now, they seem content in pummeling the forest sprites into splinters, but if they continue any further the pandaren will have more than just missing jade to worry about.>", objectives = "Slay 10 Stonebound Destroyer the Woods of the Lost and discover their source." }
WordHunterWoW_QuestEN[29746] = { title = "Breadcrumb Into Ruins", description = "The spirits released from these statues are being pulled--rather violently--toward the coastal ruins up ahead.\n\nIt seems unlikely that they'll be allowed to rest...You will receive:", objectives = "Head into the Ruins of Gan Shi, northwest of the [JADE MINES]." }
WordHunterWoW_QuestEN[29747] = { title = "Break the Cycle", description = "<Mogu conjurers call forth hapless spirits from beyond, forcing them into statues.\n\nIt seems that destroying the statues alone will not be enough to break the cycle.>", objectives = "Kill 8 Shan'ze Spiritbinders in the Terrace of Ten Thunders." }
WordHunterWoW_QuestEN[29748] = { title = "Simulacrumble", description = "<The shattered remains of an ancient mogu statue. This one looks like it never animated before it was broken.\n\nWhatever dark magic the mogu are employing here, it seems to make the brittle statues significantly tougher. Better to destroy them while they are still vacant.\n\nA good old-fashioned kick should do the job.>", objectives = "Kick 6 Vacant Destroyers in the Terrace of Ten Thunders." }
WordHunterWoW_QuestEN[29749] = { title = "An Urgent Plea", description = "<Your mind is racked with a howl. Beneath it, a wispy voice is barely audible, as if from far away.>\n\nPlease... help... heart of the ruins... a ritual... conjuring...\n\n...should not be here...\n\nMy staff... on the altar... take it. Please hurry.", objectives = "Recover the Staff of Pei-Zhi and interrupt the mogu ritual in the center of the Terrace of Ten Thunders.", progress = "Spirit-binding! How can the mogu have been allowed to resume such a disgusting practice?! And now here I am, the product of a half-failed conjuring...\n\n<The spirit fumes for a moment, then turns to you.>\n\nWhat century is this?", completion = "Allow me to introduce myself: I am Pei-Zhi, Master Spiritsage under the last pandaren emperor Shaohao.\n\nAt least... I was." }
WordHunterWoW_QuestEN[29750] = { title = "Vessels of the Spirit", description = "The Spiritclaws are a sect of mogu assassin-priests who, at the height of the mogu empire, were the most elite and most feared of the emperor's troops.\n\nAll have mastered a deathblow which ensnares the spirit of the enemy, trapping it in a jade bottle for delivery to a Spiritbinder.\n\nIf you encounter any Spiritclaws further ahead in the ruins, take note: their belts hang with a cursed weight.\n\nRelieve them of their burden and bring the bottles back to me.", objectives = "Recover 8 Spirit Bottles from Shan'ze Spiritclaws in the Terrace of Ten Thunders.", progress = "To think the mogu have continued training the Spiritclaws for all these years...\n\nDid you get the bottles?", completion = "Thank you, <class>.\n\nI can already sense the spirits within these bottles - they cry out with fear, confusion... rage." }
WordHunterWoW_QuestEN[29751] = { title = "Ritual Artifacts", description = "So many spirits held in captivity here... I can feel them everywhere. Even the walls are a cage for the long-dead.\n\n{name}, we cannot simply break the sorcery over this place - doing so would release countless agonized souls to wander the earth. They will need a beacon, something to guide them.\n\nWith your help, I can create a tan-chao: a bridge from this world to the heavens. For this ritual, I'll need a bowl, a candle, and a jade cong. You should be able to find them all within the ruins.", objectives = "Bring Pei-Zhi a Chipped Ritual Bowl, a Pungent Ritual Candle, and a Jade Cong from the Terrace of Ten Thunders.", progress = "Have you found the items we need for the ritual? We cannot guide these spirits back without them.", completion = "Good work. With these, I can complete the ritual to send all of the spirits here--including myself--back where they belong." }
WordHunterWoW_QuestEN[29752] = { title = "The Wayward Dead", description = "The process of mass conjuring, as the mogu are doing here, is not without byproduct. Some spirits arrive too distraught or unruly to be harnessed, so they are confined and left to wander until their desperation leaves them more malleable.\n\nI suspect the mogu have such a holding area somewhere nearby, likely guarded by spiritclaws.\n\nPlease, take my staff again and use it to collect these wayward spirits. You needn't fight them - present the staff and they should be drawn in.", objectives = "Use the Staff of Pei-Zhi to absorb 10 Wayward Ancestors in the Terrace of Ten Thunders.", completion = "Thank you, <name>. I will take them with me into the nether." }
WordHunterWoW_QuestEN[29753] = { title = "Back to Nature", description = "I'm afraid I have another favor to ask, {name}.\n\nThe bottles you recovered contain neither the spirits of mogu ancestors nor recently slain foes; they contain spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to fuel their simulacra.\n\nThis complicates our task, for I cannot take the beasts with me through the bridge.\n\nTake the bottles west to Tideview Thicket and smash them to return the spirits to nature. Some may be blind with rage and will need to be subdued.", objectives = "Throw Spirit Bottles on the ground in Tideview Thicket to release 8 Beast Spirits.", progress = "Do not fear for the spirits of the beasts - they will find peace here.", completion = "Their bodies had long since returned to the land - their spirits can now follow." }
WordHunterWoW_QuestEN[29754] = { title = "To Bridge Earth and Sky", description = "We are ready to open the tan-chao and guide all of these spirits back to peace.\n\nIf I may, I would have your assistance once more. The mogu will surely sense the ritual taking place and will do everything in their power to halt it. I need only a few moments without interference, and once the path is open it will surge too greatly to be closed.\n\nIf you are willing to help one more time, please accompany me to the ritual site.", objectives = "Protect Pei-Zhi during his ritual at the Terrace of Ten Thunders." }
WordHunterWoW_QuestEN[29755] = { title = "Pei-Back", description = "<Ancestral spirits stream into the tan-chao, Pei-Zhi's bridge to freedom.\n\nOne final chamber lingers in the ruins, just north of the tan-chao. The air above crackles with foul energy. Shan Jitong is already at work.>", objectives = "Confront Shan Jitong and rescue Pei-Zhi at the Seat of the Spirit Waker in the Terrace of Ten Thunders.", completion = "This age must be one of great strife to breed heroes such as you. I can only imagine what adventures must lie ahead.\n\nIt has been my great honor to have met you, <name>.\n\nI will remain here to usher out the last of the spirits before crossing the tan-chao myself.\n\nStill, I am disturbed by the spirit waker's dying curse...\n\n\"You will not stop the thunder.\"\n\nWhat could he have meant?" }
WordHunterWoW_QuestEN[29756] = { title = "A Humble Offering", description = "I'm almost ready for the ritual, there's just one more thing we need: An offering.\n\nRelax, I don't mean a sacrifice. Just a bit of food.\n\nThere are sure to be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. Please bring some.", objectives = "Gather 10 Tidemist Caps from Tideview Thicket.", progress = "Even the dead know hunger.", completion = "Thank you, <name>. These mushrooms may not seem like much of an offering, but the sentiment alone will be enough to draw the spirits to us.\n\nAlso, they make a pretty fine stir-fry." }
WordHunterWoW_QuestEN[29757] = { title = "Bottletoads", description = "Have you heard about the crisis we're having at the pools?\n\nToads have moved in and are spawning like crazy! It's become a real problem for the lotus farmers.\n\nCoincidentally, I make a jam out of gelatinous toadspawn. I call it \"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in stock.\n\nIf you're heading to the pools, you'd be doing everyone a favor by uh... liberating some of those toad eggs.\n\nInto this bottle. For me.\n\nJust look for bubbles and scoop right in!", objectives = "Scoop toad eggs from 8 Gurgling Toadspawn on the top level of the Pools of Purity.", progress = "\"It just ain't a party without Bottletoads!\"\n\nHmm... no, that doesn't work.\n\n\"Bottletoads: not as gross as they sound!\"", completion = "Now when the kids ask: \"Do you have Bottletoads?\" I can say YES!" }
WordHunterWoW_QuestEN[29758] = { title = "Guess Whose Back", description = "<This dragon turtle's massive shell is rock-hard and covered in sharp ridges. One of the locals could almost certainly make use of it.>", objectives = "Bring Krosh's Back to Yan in New Cifera.\n\nProvided item:", completion = "My MY now look at THIS! What a beautiful shell!\n\nYou were wise to bring this to me, my friend. It will make a fantastic serving platter.\n\nPlease, take this for your troubles." }
WordHunterWoW_QuestEN[29759] = { title = "Kung Din", description = "I hope you are capable of this next task, for our lives depend on it.\n\nThere is only one key that will unlock our chains. Unfortunately, the key hangs around the neck of the hozen's pet tiger, Kung Din.\n\nThey keep the tiger in the great pit to the north. The only way to retrieve the key will be to kill the beast.", objectives = "Obtain the Slingtail Key by slaying Kung Din.", progress = "Did you find him?", completion = "Yes, with this key I will be able to free our chains.\n\nYou have delivered us from this vile place." }
WordHunterWoW_QuestEN[29760] = { title = "Pit Fighter", description = "There must be more to being a master pit fighter than this...\n\nPerhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.", objectives = "Speak with Korgol Crushskull at the Darkmoon Faire.\n\nProvided item:", completion = "Well met, <class>.\n\nGaining but one trinket is not enough to make you a Master Pit Fighter.\n\nNow is the time to truly prove your steel." }
WordHunterWoW_QuestEN[29761] = { title = "Master Pit Fighter", description = "", objectives = "Well met again, <class>.\n\nBring me 12 trinkets of the Pit Fighter and then you shall be a Master Pit Fighter of the Darkmoon Deathmatch!", progress = "Well met again, <class>.\n\nBring me 12 trinkets of the Pit Fighter and then you shall be a Master Pit Fighter of the Darkmoon Deathmatch!", completion = "Many foes have you bested and many crowds entertained.\n\nI am glad to name you Master Pit Fighter of the Darkmoon Deathmatch!" }
WordHunterWoW_QuestEN[29762] = { title = "Family Heirlooms", description = "We recently lost a fierce battle against the hozen at Moonwater Retreat.\n\nWe evacuated as many of our people as we could, but still, there were many we could not save.\n\nWe have no tokens of our lost over which to send our prayers.\n\nIf someone could go and retrieve heirlooms from the dead bodies, we could properly lay them to rest, and move on.\n\nIt would mean so much to us if you could do this, {name}.", objectives = "Collect 8 Pearlfin Heirlooms from dead Pearlfin Villagers in Moonwater Retreat.", progress = "We still grieve for our fallen brothers.", completion = "Thank you, <name>. You do not know how much this means to the families of the lost." }
WordHunterWoW_QuestEN[29763] = { title = "Stealing Their Thunder", description = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.", objectives = "Defender Mordun has asked you to acquire the head of Ingvar the Plunderer.", progress = "Good to see you're well, <name>.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for." }
WordHunterWoW_QuestEN[29764] = { title = "Disarmament", description = "Take it from me, lad, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nI need you to pilfer some o' them weapons before they're used on us!", objectives = "Defender Mordun wants you to steal 5 Vrykul Weapons.", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck..." }
WordHunterWoW_QuestEN[29765] = { title = "Cryin' My Eyes Out", description = "I coulda taken out da whole lot of 'em, mon.\n\nShot 'em one by one, den played dead when dey be gettin' close. Fell for it every time, dey did - well almost every time...\n\nOne of 'em finally got wise. Called my bluff. Before I knew it, dey was usin' my eyes as marbles.\n\nRan off with my goods an' left me here ta die, da savages...\n\nHelp me, mon. Lemme die wit my dignity intact.", objectives = "Collect Zin'Jun's belongings from the Hozen Groundpounders.\n\nIf you lose Zin'Jun, speak to him at the Ascent of Swirling Winds.", progress = "You got me goods, mon?", completion = "<Zin'Jun sobs...you think.>\n\nDey done killed Snuff...\n\nWhat'd 'ol Snuff ever do ta dem?" }
WordHunterWoW_QuestEN[29766] = { title = "A Good Start", description = "Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet.\n\nBut first, we must deal with these savages!\n\nYou see these corpses I've stacked up around the camp? I want mountains of them!\n\nWe are the Horde!\n\nThese vermin have not learned to fear us yet, but we will fix that soon enough...", objectives = "Kill 4 Hozen Mudflingers, 4 Hozen Skullthumpers, and 3 Hozen Fishcatchers." }
WordHunterWoW_QuestEN[29767] = { title = "Fish Fry", description = "Fortune favors the bold!\n\nYour calculated aggressive actions have yielded unexpected rewards. If you can slay these fishcatchers after a successful haul, you'll inherit their slippery spoils.\n\nThinning out the enemy while feeding your allies - the picture of efficiency!You will receive:", objectives = "Collect 12 Mature Carp from Hozu Fishcatchers" }
WordHunterWoW_QuestEN[29768] = { title = "Missing Mallet", description = "{name}, I've got it! It's simple really. Let's make a ruckus so loud that there's no way he can sleep through it.\n\nWhy look at that, a conveniently placed gong! Makes me think this may just be how they've awoken him in the past. We just need the matching mallet to get it ringing as loud as possible.\n\nThe village leader tells me the mallet is over at the Ki-Han Brewery on the river, to the southwest. It's not far. Mind picking it up for me while I give the village some fair warning?", objectives = "Recover the Dai-Lo Recess Mallet at the Ki-Han Brewery.", progress = "Well, they're as warned as they're going to get. Do you have the mallet?", completion = "Hah, <name>! Now that's a mallet if I've ever seen one! Let's make some noise." }
WordHunterWoW_QuestEN[29769] = { title = "Rascals", description = "I'll keep trying to find ways to wake this stubborn little guy up, but there is no shortage of trouble on the island it seems. The crops to the south are infested with virmen, rabbit-like thieves and pillagers.\n\nRascals!\n\nThey breed faster than we can kill them! I have the perfect solution for such a situation: kill them faster! With you here, {name}, that shouldn't be a problem.", objectives = "Kill 10 Virmen.", completion = "<name>, that's the way to do it! You show up, and problems start getting solved. That's just one of many reasons why I like you!" }
WordHunterWoW_QuestEN[29770] = { title = "Still Good!", description = "The virmen to the south have been running off with all of our crops, but they're taking more than they can eat. They must be stockpiling them somewhere - the ones they like anyway.\n\nWill you go out and recover any of the uprooted crops you can find? I've got an island's worth of people to feed, and every single vegetable makes a difference.", objectives = "Recover 3 Uprooted Turnips, 3 Stolen Carrots, and 3 Pilfered Pumpkins.", progress = "Ever since Wugou. the spirit of earth, fell asleep, the dirt is drying out and it's getting harder and harder to get new seeds to sprout. We need to hold on to any food we can, or the island will have hard times ahead.", completion = "Some of these have mouth-sized chunks bitten out of them! Ah well, we can still make use.\n\nThank you for your help, friend." }
WordHunterWoW_QuestEN[29771] = { title = "Stronger Than Wood", description = "Gather me wood planks from construction near the Ki-Han Brewery.\n\nYou do not yet know the extent of my strength, so I shall display it to you.", objectives = "Gather 12 Discarded Wood Planks.", progress = "Have you done as I've asked?", completion = "Good.\n\nMy head, it is harder than the densest wood.\n\nStep back, and let me dispel your doubts." }
WordHunterWoW_QuestEN[29772] = { title = "Raucous Rousing", description = "You ready for this, {name}? I'm thinking maybe we should have looked for something to cover our ears, but it's a bit late for that now. Just remember that the intense ringing you'll be hearing for the next few hours is the ringing sound of victory!\n\nThe honor's all yours, {name}. Ring the gong whenever you're ready!", objectives = "Ring the gong.", completion = "Huh... well... that's definitely the ringing I expected, but I was hoping for a bit more from Wugou. This guy's a deep sleeper, that's for sure.\n\nIt's alright, <name>. I've got another idea, and there's not much preparation needed at all - just how I like it." }
WordHunterWoW_QuestEN[29773] = { title = "Wugou, the Spirit of Earth", description = "{name}! Well, the plus side is that finding Wugou was easy enough. Waking him... not so much. I think he's going to wake quite sore from all the pushing and hitting I've done trying to rouse him.\n\nAre you a deep sleeper at all, {name}? What wakes you up in the morning?\n\nRolling out of bed always seems to do it for me, so I figure let's just go for that! I tied off some ropes to the ox cart. We send it running and give him a good roll, and we should be good! Care to give the ox a good slap to get it going?", objectives = "Slap the ox." }
WordHunterWoW_QuestEN[29774] = { title = "Not In the Face!", description = "Alright {name}, I was thinking about what we'd try next if the whole gong thing didn't work, and it came to me just like that! Water in the face always worked on me. It's got to be twice as effective for someone so dry and earthy!\n\nMind going over and asking Shu, the spirit of water, if he'll help us out?  He should be playing in the pool next to the waterfall, just on the other side of that tree.", objectives = "Request Shu's help in waking Wugou, the spirit of earth.", completion = "YEAH!!! <name>, we make quite a team. Persistence over planning, I always say!" }
WordHunterWoW_QuestEN[29775] = { title = "The Spirit and Body of Shen-zin Su", description = "Well, that wraps it up here, doesn't it {name}?  Now that we've got these two roused and all friendly towards you, we just need to get them back to the Temple of Five Dawns.\n\nYou go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.", objectives = "Bring Shu and Wugou, the spirits of water and earth, to the Temple of Five Dawns. A cart is waiting near the road to take you there.", completion = "You have done well, young student. Three of the four spirits have been returned to the temple. We are closer to the answers we seek." }
WordHunterWoW_QuestEN[29776] = { title = "Morning Breeze Village", description = "The fourth and final spirit is Dafeng, the spirit of air. When he is not in the skies, he can be found on the Ridge of Laughing Winds to the west. I've sent both Aysa and Ji to help you find him.\n\nWhen you are ready, I will summon winds to carry you to the top of the temple. From there, cross the bridges to the west and find Ji in Morning Breeze Village.", objectives = "Meet with Ji Firepaw in Morning Breeze Village.", completion = "<name>, give me a hug! Our parting was not so long this time - I quite prefer it that way!\n\nYou've been working with Aysa, have you not? Our disciplines have always kept us apart, so I know little of her. Watching her perform her exercises now, I must confess that she possesses a grace and discipline that is strangely alluring.\n\nThere are more pressing thoughts though, aren't there? <name>, let's take care of this monkey problem while we search for Dafeng." }
WordHunterWoW_QuestEN[29777] = { title = "Tools of the Enemy", description = "The hozen have stolen our brushes and are painting over our scrolls of wisdom with their own wisdoms, if you can call them that. If you're here to help, stop them and bring our brushes back before they can do more harm.", objectives = "Retrieve 8 Paint Soaked Brushes.", progress = "I do not wish to disparage the hozen for their aspirations - each race must walk its own path. In this moment, however, they are bringing harm to our bodies and our culture. That is a line that cannot be crossed.", completion = "I am very thankful, young one. I will soon begin the slow task of documenting all of our wisdoms again, so that the scrolls can be hung for the benefit of all to come." }
WordHunterWoW_QuestEN[29778] = { title = "Rewritten Wisdoms", description = "{name}, we must help Elder Shaopai. There are few more deserving of our kindness.\n\nOn the way here, you surely noticed the scrolls of wisdom hanging in the grotto to the south. The hozen have defiled many of them, and sadly, they are not recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the hozen writings away entirely.\n\nDo not worry for Elder Shaopai. The people shall come together and help him rewrite the wisdoms in time. I shall see to that.", objectives = "Burn 5 Defaced Scroll of Wisdom.", completion = "You're a good man, <name>. You have proven that again and again, and I am glad to stand beside you." }
WordHunterWoW_QuestEN[29779] = { title = "The Direct Solution", description = "Alright {name}, this is the second time we've had to deal with ravaging hozen. I think it's time we take care of this problem the Huojin way. No more patience. No more mediation. We go to the source.\n\nWe're going into the hozen village to the north and we're punishing those smelly troublemakers. I've been looking forward to a chance to fight by your side again, {name}.", objectives = "Kill 20 hozen in Fe-Feng Village.", completion = "Invigorating! A good fight always makes me feel better!" }
WordHunterWoW_QuestEN[29780] = { title = "Do No Evil", description = "{name}, I need you to understand that the way of the Huojin is not the way of violence. When fighting is needed, we will not hesitate, but when fighting is not needed, neither do we instigate. However, the direct solution is often cutting the head off the snake, as they say.\n\nThe hozen have a leader instigating these attacks. If we remove Ruk-Ruk, we won't have to wipe the hozen out entirely.\n\nI know you are not of the Huojin, but are you with me in what must be done, {name}?", objectives = "Kill Ruk-ruk, the Fe-Feng Chief.", completion = "<name>, I think you've got a bit of Huojin in you. Stick with me and I'll bring you around, I think." }
WordHunterWoW_QuestEN[29781] = { title = "Monkey Advisory Warning", description = "The monkeys have been stealing from the village during their attacks. We should be fine without some of the extra food stores, but the idea of monkeys with fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks will come in handy?\n\nHelp me recover the stolen fireworks from their village, {name}?", objectives = "Recover 8 Stolen Firework Bundles.", progress = "I'm somewhat impressed they hadn't set their village on fire with these things.", completion = "<name>, I'm thinking we should celebrate with these later. What do you think?" }
WordHunterWoW_QuestEN[29782] = { title = "Stronger Than Bone", description = "This giant jade tiger pillar doesn't seem to fit in amidst the hozen buildings.\n\nWhat it does seem is very hard. Very solid.\n\nYou know just the person to bring this to.", objectives = "Bring the Jade Tiger Pillar to Jojo Ironbrow in Morning Breeze Village.\n\nProvided item:", completion = "GOOD! A true challenge. Let us put this pillar to the test!" }
WordHunterWoW_QuestEN[29783] = { title = "Stronger Than Stone", description = "Gather me stone blocks from the Ridge of Laughing Winds to the south.\n\nYou have seen my strength twice, yet I still spy doubt within your eyes. It will not last.", objectives = "Gather 12 Abandoned Stone Blocks.", progress = "The strength of the body cannot exist without the strength of the mind.", completion = "Good.\n\nMy head, it is harder than the strongest stone.\n\nStep back, and let me dispel your doubts." }
WordHunterWoW_QuestEN[29784] = { title = "Balanced Perspective", description = "Aysa has been meditating on the lake since we've arrived, all her thoughts focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, and Master Shang Xi has entrusted this task with her.\n\nYou will need to cross the ropes leading from the end of the dock to reach her. It shall test your balance, but I think you're up to the task, {name}.", objectives = "Cross the ropes and speak to Aysa Cloudsinger on Morning Breeze Lake.", completion = "I'm impressed. Most students that are even capable of reaching this spot do so soaking wet." }
WordHunterWoW_QuestEN[29785] = { title = "Dafeng, the Spirit of Air", description = "If you listen long enough, the wind will carry the answer to you.\n\nDafeng, the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He hides within the Chamber of Whispers, at the south side of the plateau.\n\nGo to him. Ji and I will join you there.", objectives = "Speak to Dafeng, the spirit of air, in the Chamber of Whispers.", completion = "Dafeng looks frightened as you approach, but settles a bit at the sound of your voice." }
WordHunterWoW_QuestEN[29786] = { title = "Battle for the Skies", description = "Dafeng, the spirit of air, is terrified by Zhao-Ren, the Onyx Serpent. We must help him face that fear, or face it for him ourselves.\n\nWhen I told Ji of the serpent, he said he had an idea and would begin preparations outside of the chamber. Despite his rash nature, I must admit, I envy his passion and conviction.\n\nLet us go outside and confront the Onyx Serpent.", objectives = "Defeat Zhao-Ren, the Onyx Serpent with the aid of Ji's fireworks.", completion = "You have helped Dafeng, the spirit of air, find his courage! The final spirit has been restored." }
WordHunterWoW_QuestEN[29787] = { title = "Worthy of Passing", description = "The four elemental spirits will help you speak with the land and uncover its plight, but first, I have one small task to ask of you.\n\nJoin me, my pupil. Accompany this old pandaren to the western grove.", objectives = "Defeat the Guardian of the Elders.", completion = "I do not have the strength of body or will that I once did. I'm glad there are noble <race> like you to fight on for our people. You've come far, <name>." }
WordHunterWoW_QuestEN[29788] = { title = "Unwelcome Nature", description = "You faced forest sprites in the Dawning Valley, but the forest sprites in this grove are a different breed. Crueler and more dangerous.\n\nIf you would clear some of these sprites out, the spirits would thank you.", objectives = "Kill 8 Thornbranch Scamps.", completion = "The spirits thank you, <class>." }
WordHunterWoW_QuestEN[29789] = { title = "Small, But Significant", description = "I am tired, {name}. I must rest.\n\nWe have a ritual to perform, but we require some of the charms from this grove. If you wander the grove, you should see them all over hanging from the trees. \n\nIf it does not offend one as young as you, will you permit me to sit and recover my strength while you gather these charms?", objectives = "Retrieve 8 Kun-Pai Ritual Charms.", progress = "Rest feels good. The burdens of life have become a great weight after so many years.", completion = "You come through, as you always have. You are truly one of my greatest students. I think you will be something the likes of which the world has never seen." }
WordHunterWoW_QuestEN[29790] = { title = "Passing Wisdom", description = "This journey shall soon be yours to undertake without me. Stay for a few moments and listen to an old man's words. Let my knowledge serve as a foundation for yours, that you might be greater than I ever was.", objectives = "Listen to Master Shang Xi.", completion = "I know, <name>... I know. Such is the way of things." }
WordHunterWoW_QuestEN[29791] = { title = "The Suffering of Shen-zin Su", description = "Now is not the time to grieve. The balloon is ready, and Shen-zin Su awaits.\n\nWe shall be the first pandaren to speak to Shen-zin Su in hundreds of years. It is a great honor.", objectives = "Board the Hot Air Balloon and Speak to Shen-zin Su.", completion = "You have undergone a great honor, <class>. Have you come back wiser for it?" }
WordHunterWoW_QuestEN[29792] = { title = "Bidden to Greatness", description = "It is up to all of you to remove the thorn from the side of Shen-zin Su. Do not let your differences come between you. Trust in each other.\n\nWithin the Pei-Wu Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark things that now lurk in the trees.", objectives = "Open the gates to Pei-Wu Forest.", completion = "Evil is rising from the seas and filling the forest. It's not just tigers anymore... something far more sinister lurks in the shadows, waiting to take any <race> unwise enough to stray out alone.\n\nYou are not safe here." }
WordHunterWoW_QuestEN[29793] = { title = "Evil from the Seas", description = "I do not know what this evil is that is infesting the forest, {name}, but I know exactly how to deal with it. So do you, I think.", objectives = "Kill 8 Darkened Horrors or Darkened Terrors.", completion = "You make me proud, <name>. You make all of us proud." }
WordHunterWoW_QuestEN[29794] = { title = "None Left Behind", description = "Your friend has been doing everything she can to save my crew. I'm deeply appreciative.\n\nWe're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads.\n\nI still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?", objectives = "Rescue 3 Injured Sailors.", completion = "I have no idea who you people are, but fate surely smiled on us this day. Many more would be dead if not for the help of you and your friends. I am in your debt." }
WordHunterWoW_QuestEN[29795] = { title = "Stocking Stalks", description = "My men are malnourished, injured, and exhausted, but they are Horde. Every one will fight to their dying breath. As our new ally, we will stand by you when the time comes, but we would stand stronger with weapons.\n\nI have my men out gathering bamboo stalks to fashion into spears. If you can spare the effort, we could use the extra pair of capable hands.", objectives = "Gather 10 Broken Bamboo Stalks.", progress = "The Horde does not back down from a fight.", completion = "These are excellent! We'll have them crafted into weapons in no time." }
WordHunterWoW_QuestEN[29796] = { title = "Urgent News", description = "I'm sure Aysa won't love this plan, but it's the only plan we've got. Would you mind being the bearer of bad news for me, {name}? She needs to know what we're doing so she can get everyone to safety.", objectives = "Speak to Delora Lionheart at the Wreck of the Skyseeker.", completion = "Your friend is out fighting to save my crew. Fiercely I might add. I'm afraid your message may have to wait." }
WordHunterWoW_QuestEN[29797] = { title = "Medical Supplies", description = "We need supplies to tend to our wounded, but the supply crates containing them were scattered in the crash. If you can bring back any crates you find, I would be very grateful.", objectives = "Recover 8 Crates of Medical Supplies.", progress = "Did you find the boxes I spoke of?", completion = "These will do perfectly. I'll get my medics to work immediately.\n\nThank you." }
WordHunterWoW_QuestEN[29798] = { title = "An Ancient Evil", description = "{name}, I was looking for you!\n\nOne of the escaping sailors just spotted Aysa in the wreckage of the ship, facing some enormous beast. She might need your help - you should go to her, quickly!", objectives = "Defeat the Vordraka, the Deep Sea Nightmare.", completion = "<Aysa is clearly exhausted from the fight.>\n\nYour skills in battle... are unquestionable... <class>.\n\n\n\nDid you save the escaped prisoners?  ...Where is Ji? Is he okay?" }
WordHunterWoW_QuestEN[29799] = { title = "The Healing of Shen-zin Su", description = "This is more horrific than I imagined, but we can handle this. We need to gather the healers and close the wound. We need to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", objectives = "Rescue and defend healers until Shen-zin Su's wound is healed.", progress = "We need to get the healers to the wound and keep them safe!", completion = "You are a sight to see when under pressure, <name>! We wouldn't have stood a chance without you.\n\nI think it's working. The flow of blood is slowing. I knew it would work!" }
WordHunterWoW_QuestEN[29800] = { title = "New Allies", description = "{name}, I did what had to be done. And the plan worked. Things could have been much worse had we not acted. I only wish Aysa could understand that.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", objectives = "Return to the Temple of Five Dawns. A cart is waiting near the Wreck of the Skyseeker to take you there.", completion = "It is good to see you again, <name>. You've done all that I've asked of you and more... you have saved Shen-zin Su.\n\nYou make an old master proud." }
WordHunterWoW_QuestEN[29801] = { title = "Proving Your Worth", description = "Hello, {name}! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.'\n\nWe need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right man for the job.\n\nWhen the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring. Are you up to the task?", objectives = "Pickpocket a cryptomancer's decoder ring from Hagara the Stormbinder at the Eye of Eternity within the Dragon Soul raid encounter.", progress = "Have you completed our task?\n\nThese artifacts are crafted such that they dissolve if their bearer is killed, so only a skilled thief can acquire them.", completion = "You've found one! You're a credit to your race, <name>.\n\nRings like these are capable of decoding even the most complicated of ciphers. Unfortunately, the ring is inert until it is charged..." }
WordHunterWoW_QuestEN[29802] = { title = "A Hidden Message", description = "Corastrasza, currently stationed at the Vermillion Redoubt in the Twilight Highlands, has intercepted a coded message of grave importance. I'll let her explain the full situation, but we need your expertise to unravel the cipher!\n\nTake your decoder ring to an ethereal thaumaturge in your capital city - he should know how to charge it. Acquire the encoded cipher from Corastrasza and use the ring to decode it for her. Hurry! Time is ticking... ", objectives = "Charge your Cryptomancer's Decoder Ring and use it to decode the Corastrasza's Singed Cipher.", progress = "I was hoping Lord Afrasastrasz would find us a competent <class>.\n\nWhat have you got for us, <name>? Do you have a means of decrypting the message?", completion = "What's this about? \"Ravenholdt Manor?\" I thought that was just a motley band of thieves up in the Hillsbrad Foothills.\n\nWhat would they want with a dragon egg? More importantly, how did they find out about it?\n\nWe're going to need some answers, <name>!" }
WordHunterWoW_QuestEN[29803] = { title = "Ears of the Lich King", description = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord.\n\nI don't like that one bit!\n\nGo and give him a round o' pain. You'll be doing the world a favor by doing so.", objectives = "Defender Mordun inside Utgarde Keep wants you to slay Prince Keleseth.", completion = "I bet the pale whelp felt that!\n\nThat's one more step towards yer judgment day, Arthas!" }
WordHunterWoW_QuestEN[29804] = { title = "Seein' Red", description = "I was just about ta curl up an' die, mon.\n\nNow, dis!\n\nSnuff an' me go way back. Oh, da memories...\n\nNo way I can face Snuff in da afterlife without avengin' his death first, mon!\n\nDese hooligans be led by one named Konk. We gotta sniff him out an' den snuff him out - for Snuff!", objectives = "Kill Konk.", completion = "Zin'jun is lost?\n\nThis is a dark day indeed, brother. These vermin will pay!" }
WordHunterWoW_QuestEN[29805] = { title = "Tracking Event: Found Mishka at Plane", description = "", objectives = "" }
WordHunterWoW_QuestEN[29806] = { title = "The Wanderer", description = "[ph] Find and challenge the Roaming Brawler to a fight.", objectives = "Defeat the Roaming Brawler in a fight.[ph] Find and challenge the Roaming Brawler to a fight." }
WordHunterWoW_QuestEN[29807] = { title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub.\n\nHe has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King.\n\nBring an end to his reign.", objectives = "Reclaimer A'zak in Azjol-Nerub has tasked you with defeating Anub'arak. You are to return to A'zak with Anub'arak's Broken Husk.", progress = "Is it done, <class>? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Azak's eyes as he stares at the husk.>\n\nIt is DONE!\n\nYour name shall be recorded in the extensive history of our people, <race>!" }
WordHunterWoW_QuestEN[29808] = { title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise.\n\nThe eggs have been tainted with foul magics. Our only recourse is to dispose of them.", objectives = "Reclaimer A'zak in Azjol-Nerub wants you to destroy 6 Nerubian Scourge Eggs.", completion = "Do not worry, <race>.\n\nThe eggs they found were but a fraction of our hidden stores within Azjol-Nerub.\n\nOur mighty kingdom shall be reborn." }
WordHunterWoW_QuestEN[29809] = { title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", objectives = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:" }
WordHunterWoW_QuestEN[29810] = { title = "The Faceless Ones", description = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground. In desperation, they dug too deep.\n\nWe inadvertently exposed a tendril of the old god's will, which was made manifest in the creatures known only as the Faceless.\n\nIn the end, we could not fight on two fronts against such powerful enemies. Our misfortune cost us the war against the undead, and ultimately, our home.\n\nEnter Ahn'kahet, <class>, and cleanse our former home of these Faceless atrocities.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kilix the Unraveler in the Pit of Narjun wants you to kill Herald Volazj and the three Forgotten Ones that accompany him in Ahn'Kahet." }
WordHunterWoW_QuestEN[29811] = { title = "The Gatewatcher's Talisman", description = "Krik'thir, guardian of the gates to Azjol-Nerub, was not a traitor.\n\nHe fell in the War of the Spider defending our home from the Scourge.\n\nAs per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.", objectives = "Reclaimer A'zak in Azjol-Nerub wants you to retrieve the Gatewatcher's Talisman from Krik'thir the Gatewatcher.", progress = "Has Krik'thir's spirit been released from the curse of undeath? What of the talisman?", completion = "Just as I suspected.\n\nMost of the empire has remained closed off since Krik'thir's final stand. Perhaps my people have already secured the depths and merely await release? Perhaps the faceless ones fester behind closed doors.\n\nOnly time will tell. The exposed upper reaches of Azjol-Nerub must first be cleansed of Arthas' taint." }
WordHunterWoW_QuestEN[29812] = { title = "Save the Cuddlies", description = "The Fox Grove has become a dangerous place for the local red pandas. \n\nSadly due to my actions helping that crazy Brewmaster Shadowpour, the foxes of the grove have developed an inebriation bite.  The result is the little red pandas keep getting drunk until they can no longer defend themselves.  \n\nPlease!  Can you help me?\n\nIf you round up some of them I have an aroma about this fire that will help sober them up.  That should keep them safe for at least a short while.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Lasso 5 Drunk Red Pandas in Fox Grove and bring them to Apprentice Ji Alerage." }
WordHunterWoW_QuestEN[29813] = { title = "Lethal Hangovers", description = "I told him not to do it!  But \"no one stands in the way of Brewmaster Shadowpour\".\n\nMy master went and contaminated the local water supply trying to \"add flavor\" to the water. The toxins trickled down here to the Fox Grove where the brew has an irreversible effect on the foxes. \n\nIt warps their minds and sends them into a frenzy.  Now they are a permanent danger to any travelers and local wildlife.\n\nCan you help me cull some of their numbers please?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 8 intoxicated foxes in the Fox Grove." }
WordHunterWoW_QuestEN[29814] = { title = "Need a Chaser", description = "It appears now that my master managed to poison the entire local water supply with his flavor experiments.\n\nI might have a treatment but need some supplies.  In lighter cases my people have found orchids to be a wonderful remedy.\n\nDefeat the orchid chasers in the Orchis Hollow and collect some of the pollinated orchids they carry. We will use them to cleanse the central water source.You will receive:", objectives = "Defeat Orchid Chasers and obtain 15 of the Pollinated Orchids they spawn." }
WordHunterWoW_QuestEN[29815] = { title = "Forensic Science", description = "These creatures are everywhere - and very hostile! We'll need to deal with them before any more Alliance show up.\n\nThis one's taken quite a beating, but I've still made some determinations about its anatomy.\n\nWith the proper reagents, I'll be able to fashion a poison that should be quite effective against this species. In fact, I'll just need to modify a bit of the poison I have with me.\n\nGo and find me some viscous chlorophyll down by the water. Any semi-sentient flora should do.", objectives = "Collect 8 Viscous Chlorophyll.", progress = "I hope you were successful. Our survival here may depend on it.", completion = "Oh, yes, <name>. This will do nicely." }
WordHunterWoW_QuestEN[29816] = { title = "Get a Sample", description = "It is time the Mad Brewer got a taste of his own poison.\n\nTo the east are a number of pandaren who attended a near fatal \"tasting\" session of Shadowpour's.\n\nCan you head into the valley and see if they have any samples left of what they taste tested last night. If you get enough samples I can try to recreate his concoction.\n\nGive the samples to my friend Jian.  He should be able to modify them a bit.\n\nOh, and be careful.  It would appear his beverage had some hateful side effects.You will receive:", objectives = "Obtain 8 Toxin Samples from smashed pandaren and bring them to Jian in the Valley of the Mad Brewer." }
WordHunterWoW_QuestEN[29817] = { title = "Drunken Tigers", description = "Orchids may be the cure for my people, but they are an intense opiate for the local tigers.  These beasts are often drawn to orchid fields and the intoxicating effects the flowers have on them.\n\nWhen you add the toxins Shadowpour introduced to the water supply it results in very dangerous and rabid animals.  It won't be long before they are threatening the Jade Temple. \n\nCan you thin some of their numbers please?You will receive:", objectives = "Kill 9 rabid tigers in the Orchis Hollow." }
WordHunterWoW_QuestEN[29818] = { title = "Fix the Flavor", description = "These orchids you gathered might help us fix the larger issue.\n\nIn the valley east of here is the lake Brewmaster Shadowpour contaminated.  Travel there and toss these herbs in the water to draw out the contamination so you can defeat it.  \n\nSpeak to my friend Jian when you are done.  He's a friendly water sprite that has helped the brewmaster and myself make a number of recipes.You will receive:", objectives = "Use Cleansing Orchids near the lake water in the Valley of the Mad Brewer and defeat the resulting contaminations." }
WordHunterWoW_QuestEN[29819] = { title = "The New Master", description = "I figured it out!  With the toxins you provided I not only recreated Shadowpour's recipe but also fixed the problem he was having that was causing illness.\n\nDo you know what this means?  All that flavor and none of the lethal side effects!\n\nNow to deal with the Brewmaster.  I've loaded up Chalky with samples. Can you take these to challenge Shadowpour to a tasters' duel?\n\nYou'll be subjected to his brews but I will help you cheat by bringing my sobering fire.You will receive:", objectives = "Travel to the Tasters' Arena and challenge Brewmaster Shadowpour to a tasters' duel." }
WordHunterWoW_QuestEN[29820] = { title = "Into the Nexus", description = "I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days.\n\nWould you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.", objectives = "Archmage Berinand has asked you to speak with Warmage Kaitlyn in the Nexus.I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days.\n\nWould you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29821] = { title = "Missed Me By... That Much!", description = "Listen, pal.\n\nI sent out a coupla supply drones from the gunship, and they've all been lost or crashed. Almost all, that is.\n\nOne of 'em buzzed right through the camp here and crashed out by them waterfalls.\n\nHow 'bout you see what you can do about bringin' the contents of that crate back here, hmm?\n\nWe're all outta drones, but my rocket boots might yet come in handy... or footy, as the case may be.\n\nHah! I just kill me...", objectives = "Find the missing supply crate at Serenity Falls.\n\nProvided item:", completion = "This crate should be full of supplies..." }
WordHunterWoW_QuestEN[29822] = { title = "Lay of the Land", description = "Curse these furry pests! Kill one, and two more rise in its place...\n\nNothing has changed, {name}. Orders are orders, no matter how few of us stand and regardless of the odds.\n\nI have plans to make and problems to solve.\n\nI want you to get out there and learn the lay of the land. Don't return until you have something useful to report.\n\nAnd silence that yammering fool while you're out there!\n\nDismissed!", objectives = "Visit the Shrine of the Sun, the Shrine of the Moon, and Kill Dook Ookem.", completion = "Welcome, traveler.\n\nPlease, make yourself comfortable." }
WordHunterWoW_QuestEN[29823] = { title = "Scouting Report: The Friend of My Enemy", description = "We weren't only looking for Alliance, you know. We were also looking for those snooked-up, tik-flikklin' jinyu!\n\nWell, we found 'em all right...", objectives = "Listen to Riko's report.", progress = "Riko wishes you were a bit more patient, <name>.", completion = "Yeah, I ran away. So blikkin' what? If it weren't for me, Kiryn would be dead. Oh, wait... she's already dead... already...\n\nGo away! Riko's head hurts." }
WordHunterWoW_QuestEN[29824] = { title = "Scouting Report: Like Jinyu in a Barrel", description = "With our leader turned to jade, our hozen guide disappeared, and a prisoner of war in tow, there was only one thing that Kiryn and I could do:\n\nMarch into our enemy's territory and deliver some vengeance.\n\nWant to know how it went?", objectives = "Listen to Shokia's report.", progress = "I'm not quite done yet, <name>.", completion = "The most important thing we learned was that... not only have the Alliance befriended the jinyu, but they're giving them weapons, and teaching them how to use them.\n\nThe Alliance now control a force that outnumbers us thirty-to-one. And we - the HORDE - have befriended monkeys." }
WordHunterWoW_QuestEN[29825] = { title = "Pupil No More", description = "I once called Elder Nadox my teacher.\n\nThat changed forever when I was forced to watch him mercilessly slaughter my friends and family as a servant of the damned.\n\nFind him within the depths and make him pay for his crimes, {race}.", objectives = "Seer Ixit in Ahn'Kahet has tasked you with the assassination of Elder Nadox.", progress = "Is the mighty Nadox dead for good?", completion = "With Nadox gone, I hope to take his place as a leader of my people.\n\nThe Empire of Azjol-Nerub is destined for greatness, <race>..." }
WordHunterWoW_QuestEN[29826] = { title = "Reclaiming Ahn'Kahet", description = "Prince Taldaram and his army of Scourge use the same wards we once used to hide our empire to keep themselves safe from the native denizens of the icy depths.\n\nDeactivate the wards and slaughter the Scourge guarding them. My forces will help the natives slaughter the rest.", objectives = "Seer Ixit in Ahn'Kahet wants you to kill 3 Eyes of Taldaram, a Bonegrinder, and Prince Taldaram.", progress = "Much work remains to be done in Ahn'Kahet, even long after the Scourge are defeated.", completion = "Excellent.\n\n<You heard a series of clicking sounds.>\n\nNow to vanquish our other foe." }
WordHunterWoW_QuestEN[29827] = { title = "Acid Rain", description = "Since you've been gone, more and more of these creatures are approaching our camp. They appear to be amassing for a major assault!\n\nWe're going to have to take some drastic measures if we hope to see tomorrow.\n\nHere, take my poisoned throwing stars and figure out a way to thin out their numbers.", objectives = "Using the Recovered Gyrocopter, kill 25 Hozen Gutrippers and 25 Hozen Nibstabbers.", progress = "Well, <name>? Do we live to see another day?", completion = "Excellent! What a creative solution!\n\nThat should hold them off for a while." }
WordHunterWoW_QuestEN[29828] = { title = "What the Scourge Dred", description = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that was immune to the plague.\n\nIf you could find King Dred and bring me one of his teeth, perhaps I could fashion it into a weapon.", objectives = "Kurzel inside Drak'Tharon Keep wants you to slay King Dred and bring her his tooth.", progress = "Does the great beast exist?", completion = "<Kurzel's eyes open wide.>\n\nWow! That's enormous!" }
WordHunterWoW_QuestEN[29829] = { title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", objectives = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Lieutenant Sinclari.", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, <class>?" }
WordHunterWoW_QuestEN[29830] = { title = "Containment", description = "My forces are in absolute shambles, and Malygos' assailants just keep coming.\n\nI fear that the worst has yet to come.\n\nYou must engage them until their leader, Cyanigosa, comes. Only her death will stop the invasion and save Dalaran.\n\nSpeak to me again when you are ready.", objectives = "Lieutenant Sinclari in the Violet Hold wants you to put an end to the blue dragon invasion force. You are to speak to her again once Cyanigosa is slain.", progress = "Is it over? Were you able to withstand the assault?", completion = "Thank you, hero!\n\nDalaran is safe for another day because of your bravery." }
WordHunterWoW_QuestEN[29831] = { title = "DEPRECATED: Terror on the High Seas", description = "Word has reached Stormwind of terrible crimes committed against ships carrying Alliance citizens. The Horde stands accused of stopping Alliance ships, boarding them, mistreating passengers, and stealing cargo.\n\nHeroes of the Alliance, your help is needed to determine the truth of these allegations! Seek out Grand Admiral Jes-Tereth at Stormwind Keep if you would answer the call.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Grand Admiral Jes-Tereth in the throne room of Stormwind Keep.Word has reached Stormwind of terrible crimes committed against ships carrying Alliance citizens. The Horde stands accused of stopping Alliance ships, boarding them, mistreating passengers, and stealing cargo.\n\nHeroes of the Alliance, your help is needed to determine the truth of these allegations! Seek out Grand Admiral Jes-Tereth at Stormwind Keep if you would answer the call.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29832] = { title = "DEPRECATED: Gathering Evidence", description = "A ship called the Bravery routinely ferries passengers and cargo from Stormwind port to Rut'theran Village, right outside Darnassus.\n\nWell, the ship has just returned with distressing news. Both passengers and crew say that Horde vessels stopped and boarded the Bravery in the waters off Teldrassil, mistreated those on board, and stole some of the cargo before turning the ship around.\n\nWe have to find out what happened, <name>. Would you go to Stormwind Harbor and listen to the stories of the passengers?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Visit Stormwind Harbor and speak with Sentinel Eloria, Lumian Starwhisper, Nayeth Frostmoon, and Finelar Mistwalker." }
WordHunterWoW_QuestEN[29833] = { title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way to Gundrak and speak with Tol'mar. He will be able to direct you further in this cause.", objectives = "Har'koa wants you to speak with Tol'mar in Gundrak.", completion = "Lissen up, mon. Dere be dangerous work ta be done!" }
WordHunterWoW_QuestEN[29834] = { title = "Gal'darah Must Pay", description = "It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nMy job be to observe only. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", objectives = "Tol'mar wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", progress = "Has Akali's death been avenged, <race>?", completion = "Ya done it?! Dey be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to da frozen wastes." }
WordHunterWoW_QuestEN[29835] = { title = "Gal'darah Must Pay", description = "Da mighty Akali has been slain, {race}.\n\nMy role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", objectives = "Chronicler Bah'Kini wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", completion = "Ya really did it?\n\nYou surpassed my expectations, mon. Take dis gift for bringin' justice to da frozen wastes." }
WordHunterWoW_QuestEN[29836] = { title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from inside Gundrak. Perhaps you could find the time to check in on her for me?", objectives = "To'kini wants you to speak to Bah'kini in Gundrak.", completion = "To'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!\n\nDis place be full of troll history. We can't let Gal'darah and his crazed followers keep it hidden forever!" }
WordHunterWoW_QuestEN[29837] = { title = "Sacred Scroll", description = "The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of.\n\nYou suspect that, like everything else these Hozu possess, this is stolen merchandise.\n\nPerhaps the original owner of the scroll is still nearby...", objectives = "Bring the Illegible Scroll to Lorewalker Cho.\n\nProvided item:" }
WordHunterWoW_QuestEN[29838] = { title = "One of a Kind", description = "At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nIf what I learned be true, den dey have a special golem - one like nuthin' created before!\n\nBring me back a piece from dat golem ta study.", objectives = "Chronicler Bah'Kini wants you to recover a piece of the Drakkari Colossus in Gundrak.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles." }
WordHunterWoW_QuestEN[29839] = { title = "One of a Kind", description = "Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem.\n\nI heard dat dey have a special golem - one imbued with forbidden powah.\n\nBring me back a piece from dat golem so we can learn from our bruddas and sistahs.", objectives = "Tol'mar wants you to recover a piece of the Drakkari Colossus in Gundrak.", progress = "You find da golem? I'm sure it's in there somewhere.", completion = "Amazin'! Dis be like nothing I've ever seer before.\n\nGood work, mon." }
WordHunterWoW_QuestEN[29840] = { title = "For Posterity", description = "Gundrak looks doomed. You know dis to be true.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be bringin' dem back to der former glory.", objectives = "Chronicler Bah'Kini in Gundrak wants you to collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "You be havin' my thanks, mon.\n\nThese will be very useful to us, I'm sure of it." }
WordHunterWoW_QuestEN[29841] = { title = "Lay of the Land[TEMP]", description = "Grah!!\n\nFor every one of these muck-flingers we kill, another two spring from the woods to take its place. I wouldn't share this with the others, but it's clear that we won't last long here, {name}.\n\nI must stay and defend what remains of our belongings. You scout out the region and seek a solution to our primate problem.\n\nGo now. Our hope goes with you...", objectives = "Explore the region.Grah!!\n\nFor every one of these muck-flingers we kill, another two spring from the woods to take its place. I wouldn't share this with the others, but it's clear that we won't last long here, <name>.\n\nI must stay and defend what remains of our belongings. You scout out the region and seek a solution to our primate problem.\n\nGo now. Our hope goes with you...You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29842] = { title = "Seeking Answers", description = "<Cho endures your stream of questions before speaking.>\n\nSo much to ponder, traveler...\n\nYou first must learn how to ask before your mind can discern the truth.\n\nI have completed my meditations for today, but my candles remain at the Cairn of Blood.\n\nGo there. Clear your mind. We will speak again when you are prepared to hear my words.", objectives = "Use the candles to meditate at the Cairn of Blood." }
WordHunterWoW_QuestEN[29843] = { title = "Aunty Lin Windfur", description = "We will start heading back to town once everyone gets organized.  No way is anyone going to mess with me now!  I'll boot them in the head! I'm sure I won't be in trouble after this.\n\nThank you so much for your help. Can you tell Aunty Lin back in Panda Town that we are okay and on our way back?  She has tons of old cool stuff she might give you as a reward.You will receive:", objectives = "Speak with Lin Windfur in Panda Town.We will start heading back to town once everyone gets organized. No way is anyone going to mess with me now!  I'll boot them in the head! I'm sure I won't be in trouble after this.\n\nThank you so much for your help. Can you tell Aunty Lin back in Panda Town that we are okay and on our way back?  She has tons of old cool stuff she might give you as a reward.You will receive:" }
WordHunterWoW_QuestEN[29844] = { title = "For Posterity", description = "Da land of da ice trolls is a shadow of its former glory.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be givin' dis land back to a new line of frost trolls.", objectives = "Tol'mar in Gundrak wants you to collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "We trolls been subject to da splittin' of empires for longer than some races been existin'.\n\nWe always regrow from da ruins." }
WordHunterWoW_QuestEN[29845] = { title = "DEPRECATED: The Merchants' Plight", description = "If King Wrynn thinks that the attack on the Bravery is an isolated incident, he's mistaken.\n\nLook around the harbor and you'll see all the angry merchants who can't get their goods or money to Kalimdor. Perhaps the king will listen to their voices if he won't heed mine alone.\n\nGo talk to them, <name>. Hear their grievances and gather their petitions before you return to Stormwind Keep.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Angry Merchants around Stormwind Harbor and gather 7 Merchant's Petitions.If King Wrynn thinks that the attack on the Bravery is an isolated incident, he's mistaken.\n\nLook around the harbor and you'll see all the angry merchants who can't get their goods or money to Kalimdor. Perhaps the king will listen to their voices if he won't heed mine alone.\n\nGo talk to them, <name>. Hear their grievances and gather their petitions before you return to Stormwind Keep.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29846] = { title = "DEPRECATED: Captain Rufus Hardwick", description = "The Gilnean captain, Rufus Hardwick, would serve our cause well.\n\nThe usual promises of plunder and booty might sway his crew, but to secure the good captain's help, we'll need to offer our assistance with a more delicate matter.\n\nFind an alchemist's shop and purchase a supply of diluted lime sulfur, extract of dogwood, and a soothing shampoo. Bring these items to the captain, but do nothing that will embarrass him.\n\nThe fleet is depending on you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Purchase Diluted Lime Sulfur, Dogwood Extract, and Soothing Shampoo from the Alchemy shop in the Mage Quarter, then speak with Captain Rufus Hardwick." }
WordHunterWoW_QuestEN[29847] = { title = "To Catch a Thief", description = "Just beyond this cave lies Ravenholdt Manor. You need to get inside without being seen!\n\n<Mostrasz places an enchantment on you.>\n\nThere - now I'll be able to keep an eye on you and communicate as you venture into the compound. Now sneak into that manor, locate the egg, and don't get caught...", objectives = "Infiltrate Ravenholdt Manor and locate the missing black dragon egg.", completion = "So, you will join with me?\n\nGood. Very good." }
WordHunterWoW_QuestEN[29848] = { title = "The Forlorn Watcher", description = "I would gladly give my life for the Makers or their creations.\n\nHowever, since Loken's betrayal it seems all of Ulduar has turned on the world. One in particular, the Maiden of Grief, seems to reel in agony at her new orders.\n\nPlease lay her to rest and bring me one of her tears.", objectives = "Kaldir Ironbane in the Halls of Stone has asked you to put the Maiden of Grief to rest and to obtain a Crystal Tear of Grief.", progress = "I wish there were another way, but it seems death is the maiden's only salvation now.", completion = "<Kaldir stares into the crystal in silence for a moment.>\n\nNo being has ever felt such sincere sorrow as the Maiden of Grief has.\n\nLet us remember her spirit as we continue our efforts against Loken." }
WordHunterWoW_QuestEN[29849] = { title = "DEPRECATED: Gunner Blastbarrel", description = "The second ship we'll want is captained by one of the best dwarves ever to to man a cannon, Ardan Blastbarrel. If there's anyone who can blow Horde ships out of the water, it'll be him and his crew.\n\nYou'll find Blastbarrel in the Military Ward of Ironforge. Speak with him and see if you can convince him to commit his crew to our cause.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Travel to Ironforge, speak with Ardan Blastbarrel, and then help him gather 6 of his crew members from around Ironforge." }
WordHunterWoW_QuestEN[29850] = { title = "Corrupt Constructs", description = "The iron dwarves are busy at work carving out massive stone constructs that I fear will soon be used as powerful weapons.\n\nYou must defeat their overseer, Krystallus, and the dark rune giants already walking the halls before it is too late!", objectives = "Kaldir Ironbane in the Halls of Stone has asked you to kill 3 Dark Rune Giants and Krystallus.", completion = "Well done, <race>.\n\nEvery weapon we can take away from Loken is a great boon to our own war effort." }
WordHunterWoW_QuestEN[29851] = { title = "Champion of the Tournament", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n{name}, fight with valor and honor. Every fighter here has gathered for the common good.\n\nTogether, we will stop Arthas!", objectives = "Highlord Tirion Fordring has tasked you with the completion of the Trial of the Champion." }
WordHunterWoW_QuestEN[29852] = { title = "DEPRECATED: They Call Him Swifthands", description = "The third privateer we should hire for the fleet will be \"Swifthands\" Sutton, a notoriously fierce fighter in close combat. Where Blastbarrel loves his cannons, Captain Sutton prefers to close in for the kill.\n\nYou'll find Sutton hanging around in Stormwind Harbor, looking for work. Be warned, he'll probably set some sort of task for you before he agrees to join us.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Captain \"Swifthands\" Sutton and persuade him to join you by defeating First Mate Williams." }
WordHunterWoW_QuestEN[29853] = { title = "Champion of the King", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n<name>, you are to represent the Alliance in this grand arena.\n\nProve yourself against Azeroth's finest. Go forward with honor.You will receive:", objectives = "King Varian Wrynn has tasked you with the completion of the Trial of the Champion." }
WordHunterWoW_QuestEN[29854] = { title = "DEPRECATED: Claiming Kalimdor", description = "Victory shall soon be ours! Our forces have engaged the enemy all over Kalimdor.\n\nWarchief Garrosh Hellscream has commanded all able-bodied <race>s to report for duty in support of our latest offensive.\n\nMake your way to Grommash Hold in Orgrimmar and present yourself to General Nazgrim for immediate assignment! For the Horde!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to General Nazgrim at Grommash Hold in Orgrimmar.Victory shall soon be ours! Our forces have engaged the enemy all over Kalimdor.\n\nWarchief Garrosh Hellscream has commanded all able-bodied <race>s to report for duty in support of our latest offensive.\n\nMake your way to Grommash Hold in Orgrimmar and present yourself to General Nazgrim for immediate assignment! For the Horde!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[29856] = { title = "Cairn of Bone", description = "Your mind felt clear.\n\nYou thought you were focused.\n\nMaybe it was the droning of the nearby insects that put you to sleep. That must've been it!\n\nOut of the corner of your eye, you see another of the stone formations just north of here.\n\nPerhaps it's quieter at that one...", objectives = "Use the Meditation Candle at the Cairn of Bone." }
WordHunterWoW_QuestEN[29857] = { title = "DEPRECATED: Where Are Those Ships?", description = "With most of our fleet leading the attack on Theramore and engaging the enemy elsewhere, we're going to need more ships to complete our blockade of Kalimdor.\n\nThe warchief ordered the shipwrights at Zoram'gar Outpost in Ashenvale to work overtime to meet the demand, but none of the new craft have arrived yet.\n\nTravel there and put the question to their overseer. Tell them the warchief wants his ships!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Overseer Moxx at Zoram'gar Outpost in Ashenvale and kill 6 Night Elf Raiders on the ships outside the town." }
WordHunterWoW_QuestEN[29858] = { title = "Wisdom of the Ages", description = "You must learn to approach your life's trials with humility and an open mind, stranger.\n\nWisdom cannot fit through the narrow slits of the skeptic's eye.\n\nMeet me at the Cairn of Stone and I shall teach you the ancient art of meditation.\n\nOnce you are at peace, you may find that the answers you seek are not as distant as you might think them to be.", objectives = "Speak to Lorewalker Cho at the Cairn of Stone to practice meditation." }
WordHunterWoW_QuestEN[29859] = { title = "DEPRECATED: Spies in Our Midst", description = "This is unacceptable! The warchief needs every ship he can get to secure Kalimdor!\n\nHow DID the night elves find out about the new fleet in time to destroy it? There's only one way...\n\nOrgrimmar is full of the enemy's eyes and ears, <name>, and it is our job to root them out. Belloc Brightblade has provided me with a tool that he says can help reveal the spies.\n\nUse it, but don't trust it alone. Use your judgment.You will receive:", objectives = "Uncover and eliminate 6 Night Elf Spies by questioning Suspicious Citizens." }
WordHunterWoW_QuestEN[29860] = { title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nVolkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.", objectives = "Stormherald Eljrrin in the Halls of Lightning wants you to defeat Volkhan.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little <race>. In time, I am certain my people will grow to forgive Thorim." }
WordHunterWoW_QuestEN[29861] = { title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nThe honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my unending gratitude.", objectives = "Stormherald Eljrinn in the Halls of Lightning wants you to defeat Loken. You are then to return to Stormherald Eljrinn with Loken's Tongue.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little <race>.\n\nPlease accept this gift in return for your loyal friendship." }
WordHunterWoW_QuestEN[29862] = { title = "Clearing the Way", description = "Loken's forces prepare for war. What they are not ready for is to be attacked themselves.\n\nNow is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!", objectives = "Stormherald Eljrrin in the Halls of Lightning wants you to kill 3 Stormforged Menders, 3 Stormforged Tacticians, and General Bjarngrim.", progress = "Have you vanquished their forces?", completion = "Though few outside of us shall ever know it, you have certainly saved the world on this day." }
WordHunterWoW_QuestEN[29863] = { title = "Stormherald Eljrrin", description = "I have sent an emissary to the Halls of Lightning to take the battle to Loken.\n\nHe undoubtedly needs assistance, given the strength of Loken's armies. Lend him any aid you can so that we may finally stop the traitor.", objectives = "King Jokkum wants you to enter the Halls of Lightning and speak with Stormherald Eljrrin.", completion = "Our time to act is short. Loken prepares for war." }
WordHunterWoW_QuestEN[29864] = { title = "Working at the Source", description = "We are hard at work ensuring that we minimize our losses to the Scourge war machine.\n\nThe vrykul here are undermining that mission by willingly joining the Lich King's ranks.\n\nPlease, brave champion, you must defeat their spiritual leader, Svala, before she leads her people into the eternal shadow!", objectives = "Argent Confessor Paletress wants you to slay Svala Sorrowgrave.", progress = "I have faith in you, <name>.", completion = "Every soldier we deny to the Scourge is more than one life saved.\n\nThank you." }
WordHunterWoW_QuestEN[29865] = { title = "The Silkwood Road", description = "West of here is the Silkwood Road. It has fallen into shadow as the spiders there have turned to a more evil and gluttonous path.\n\nI would face these villains myself but someone has to defend the noodle shop from... um... dangers and such.\n\nGo, hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some of my epic tales of heroism.\n\nI'll also pay you.", objectives = "Defeat 8 Silkwood Stalkers.", progress = "The silkwood stalkers are not in balance with nature. Predators are one thing but these creatures kill for pleasure. Harmony must be restored.", completion = "Such a noble hero. You remind me of a younger, less good looking version of myself." }
WordHunterWoW_QuestEN[29866] = { title = "The Threads that Stick", description = "Ah, welcome traveler. I have need of your services!\n\nSyra Goldendraft was looking for some silk. Personally I hate silk as it always gets stuck in my fur.\n\nI really want to impress her though.\n\nIf you bring me some silk from the Silkwood to the west of here I will gladly pay you for your help.", objectives = "Gather 7 Pristine Silk Strands.", progress = "Did you find the Silkwood?", completion = "Oh thank you so much! This is perfect!\n\nI hope it didn't stick to you like it stuck to me.\n\nI'm going to go find Syra and give this to her right away!" }
WordHunterWoW_QuestEN[29867] = { title = "DEPRECATED: Shadow Hunter Urko'jin", description = "We need to fill the remaining slots in the new blockade fleet before the night elves can reestablish their spy network in the city.\n\nThe Darkspears have yet to contribute much to the war effort, but if we can convince Shadow Hunter Urko'jin to add his forces to the fleet, that will change.\n\nProblem is, Urko'jin won't go to war without the blessing of the spirits. Pay a visit to Darkspear Hold in the Echo Isles, retrieve the totem of seafaring, and deliver it to Urko'jin in the Valley of Spirits.Upon completion of this quest you will gain:", objectives = "Retrieve the Totem of Seafaring from Darkspear Hold in the Echo Isles and bring it to Shadow Hunter Urko'jin in Orgrimmar's Valley of Spirits." }
WordHunterWoW_QuestEN[29868] = { title = "DEPRECATED: Captain Cartheron", description = "We'll need more ships to round out the blockade fleet, and I know just the blood elf we need.\n\nCaptain Cartheron is his name and his men are some of the most experienced sailors in the Horde. Problem is, Cartheron and his men will want payment up front for their services.\n\nBring your gold with you to Ratchet in the Northern Barrens and find out how much it'll cost to hire Captain Cartheron's crew and how much bonus pay he's going to demand.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Captain Cartheron at Ratchet in the Northern Barrens and offer him 100 gold as a down payment for his crew's service." }
WordHunterWoW_QuestEN[29869] = { title = "One Hand Clapping", description = "You have much yet to learn, but your feet are now on the path to enlightenment.\n\nTake what I have taught you here and apply it at the lake to the west.\n\nWith patience and practice, harmony and enlightenment can be attained. Then, wisdom will flow freely into your mind.\n\nAlso, you will be far enough away that your snoring will not interfere with my own studies.\n\nFarewell, stranger.", objectives = "Meditate at the Cairn of Scales." }
WordHunterWoW_QuestEN[29871] = { title = "Clever Ashyo", description = "I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are clever, and I wouldn't say that he's any more clever than most of them.\n\nQuite the opposite, actually.\n\nAt least he's a capable fighter. He did well enough at Tian Monastery to be selected for our training mission.\n\nIf you want to help him look for the Hidden Master, you can find him along the Valley's northern border.", objectives = "Find Clever Ashyo.", completion = "Where have I seen you before?" }
WordHunterWoW_QuestEN[29872] = { title = "Lin Tenderpaw", description = "Lin is more talented than she thinks she is. Strong of fist but weak of spirit. With more confidence, she could be better than all of us.\n\nPerhaps she will find the surety she needs on her trip into the west. She's probably on her way to Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the Valley.", objectives = "Find Lin Tenderpaw.", completion = "Oh, it's you!\n\nNo, I haven't found the Hidden Master yet. I probably wasted my time coming out here.\n\n<Sigh...>" }
WordHunterWoW_QuestEN[29873] = { title = "Ken-Ken", description = "So... Ken-Ken. The hozen.\n\nPersonally, I'm impressed he's progressed so far in his training. He's got a brain between his ears, which is more than can be said for most of his kind.\n\nHe said he was headed east, but, seeing as we're already on the far east side of the valley, I can't imagine he went too far from here. Look for him at Zhu's Watch, in Krasarang Wilds, down the path to the south. See what he's found.", objectives = "Find Ken-Ken.", completion = "This place... it... it so SAD!\n\nKen-Ken never seen a place so sad." }
WordHunterWoW_QuestEN[29874] = { title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", objectives = "Find Kang Bramblestaff.", completion = "I'm pretty sure this settlement wasn't here a few weeks ago. Where did these people come from?" }
WordHunterWoW_QuestEN[29875] = { title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", objectives = "Find Kang Bramblestaff.", completion = "I'm pretty sure this settlement wasn't here a few weeks ago. Where did these people come from?" }
WordHunterWoW_QuestEN[29876] = { title = "DEPRECATED: The Third Captain", description = "", objectives = "" }
WordHunterWoW_QuestEN[29877] = { title = "A Poor Grasp of the Basics", description = "Virmen - they no just eat our food. They trying to start farms of their own. The problem is... well, they ookin' dumb.\n\nYou no believe Muno? Last night, they break into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows planted in ground.\n\nThey was WATERING them. They was trying to GROW WHEELBARROWS.\n\nPlease, while you out there, unbury our stuff.", objectives = "Unearth 7 pieces of farm equipment.", progress = "Man, those virmen is dumb.", completion = "Thanks, friend. Now maybe a hozen can get some ookin' work done around here." }
WordHunterWoW_QuestEN[29878] = { title = "Building a Better Hozen Trap", description = "One thing is now painfully clear. The Hozen love their 'slickies'.\n\nWhile deep in your meditative trance, scattered images and impressions came to your mind. Now fully awake, you struggle to make sense of the experience.\n\nThe beginnings of an absurd plan begin to take shape in your head. It might just be crazy enough to work...", objectives = "Collect 8 Slickies and 8 Intact Pottery Jars from Lake Kittitata." }
WordHunterWoW_QuestEN[29879] = { title = "Swallowed Whole", description = "Now, back to your dilemma.\n\nI believe you can help your people build relations with our hozen, as my people have.\n\nThe trail behind me will lead you to a body of water the hozen use to gather the fish that feeds them.\n\nAround this time every year, fearsome beasts call those waters home and many hungry hozen are lost to them.\n\nIf you were to rescue some of the victims and gather some fish, perhaps you will be regarded more favorably.", objectives = "Free 5 hozen from the Engorged Crocolisks, and gather 5 Speckled Trout from Lake Kittitata.", progress = "Wikket got slickies... for me!?", completion = "Wikket save hozen? And bring slickies?\n\nHmm, maybe wikket not so bad.\n\nTooki Tooki never liked Dook Ookem anyway..." }
WordHunterWoW_QuestEN[29880] = { title = "Catch and Release!", description = "As you place one fish in each jar, your optimism grows.\n\nThis just might work! Ideally, rescuing the Hozen from your makeshift trap will soften their stance towards you.\n\nTime to set some bait.", objectives = "Use Hozen Traps in Camp Nooka-Nooka, then break them to free 5 trapped Hozen." }
WordHunterWoW_QuestEN[29881] = { title = "The Perfect Color", description = "As you have seen, this grove is abundant with beautiful pink petals.  As each petal ages, the tone deepens and fades.\n\nIf you would be so kind, I am in need of a few petals that have freshly fallen.  Only the ones that have just fallen will have precisely the right color I am after.\n\nFrom it I can forge an ink that will be breathtaking.  Can you help me?", objectives = "Gather 8 Freshly Fallen Petals.", progress = "There is only a small window of time after each petal falls that it may be used to achieve the perfect hue.", completion = "Ah! You have a wonderful eye for color my friend.  These will make a superb pigment." }
WordHunterWoW_QuestEN[29882] = { title = "Quill of Stingers", description = "To achieve perfect paint strokes, one must have the right tools. My own have fallen into disrepair, their bristles becoming as unmanageable as hozu hair.\n\nHave you seen the wasps throughout the Arboretum? Their stingers can be fashioned into quills that provide just the right level of sharpness in each line.\n\nCould you gather some for me please? ", objectives = "Gather 6 Wasp Stingers from Orchard Wasps.", progress = "Have you been able to acquire some stingers? I would normally ask a monk for help with this but they all seem to be elsewhere at the moment.", completion = "My thanks traveler. These will make a fine set of quills. Here is something for your trouble." }
WordHunterWoW_QuestEN[29883] = { title = "The Pearlfin Situation", description = "I've been thinking.\n\nWe are cut off from support and a long way from home.\n\nAlthough these Pearlfin jinyu mistrust our presence, they do not appear to be hostile.\n\nIf we could convince them that we are their friends, an alliance between our races could prove extremely valuable.\n\n{name}, you must go speak to the jinyu around the village.\n\nConvince their leaders that we are not to be feared, and that we only wish for peace.", objectives = "Speak to Elder Lusshan, Pearlkeeper Fujin, Instructor Sharpfin, and Ot-Temmdo at Pearlfin Village.", progress = "If we can win over the jinyu, they may allow us to stay.", completion = "It sounds like you made quite the good impression.\n\nWell done, <name>!" }
WordHunterWoW_QuestEN[29884] = { title = "Tracking Event: Spies Leave", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "See the scouts off, then speak to Big Lu." }
WordHunterWoW_QuestEN[29885] = { title = "Road Rations", description = "We do not have time to wait around for the Admiral to recover.\n\nSully and I are planning to search for Anduin to the north, but we'll need supplies for our journey.\n\nThe lake here is teeming with wildlife, which we have received permission to hunt.\n\nGo and gather some supplies while Sully and I finalize our preparations.", objectives = "Collect 6 Tortoise Flanks.", progress = "Time is short. Each hour we delay, the White Pawn may move further away.\n\nWhere are the supplies I asked for?", completion = "This should be plenty, <name>. Thanks." }
WordHunterWoW_QuestEN[29886] = { title = "Zen Healing", description = "Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure.\n\nLuckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries.\n\nThe flowers growing on the surface of Glass Lake are needed to make the antidote.\n\n{name}, go quickly and bring back some blooms. Your Admiral's life depends on it.", objectives = "Collect 6 Zen Lotus." }
WordHunterWoW_QuestEN[29887] = { title = "The Elder's Instruments", description = "Oh dear, oh dear... The Elder mustn't find out!\n\nI must have left the Elder's ceremonial instruments behind during the escape.\n\nBut... Moonwater Retreat is crawling with hozen by now!\n\nWhat sort of Pearlkeeper am I, to have lost them so carelessly?\n\n<The old jinyu buries his face into his hands.>\n\nStranger, could you find it in your heart to help me?", objectives = "Collect the Waterspeaker's Staff, Ceremonial Robe, Jade Crown, and Rosewood Beads from Slingtail Stickypaws.", progress = "The Elder is a Waterspeaker. He speaks to the waters, and they answer.", completion = "You found them? Oh thank the spirits of water!\n\nYou have saved my tailfin, <name>." }
WordHunterWoW_QuestEN[29888] = { title = "Seek Out the Lorewalker", description = "I see that you and your people are desperate to find your Prince Anduin.\n\nI know someone who may be able to help you, a pandaren Lorewalker who knows this land better than anyone. I cannot guarantee what kind of reception you will receive, but he will almost certainly be as curious about you as you are of him!\n\nThe Lorewalker lives in the forest to the southwest. Tell him that the Pearlfin have sent you.", objectives = "Search for Lorewalker Cho at the Dreamer's Pavilion in the Jade Forest.", completion = "You look around the empty house.\n\nIt appears you are in the right place, but there is no sign of its inhabitant." }
WordHunterWoW_QuestEN[29889] = { title = "Borrowed Brew", description = "A delicious smell wafts out from the bottle on the table.\n\nA little taste couldn't hurt, right?", objectives = "Taste the mouthwatering brew.", completion = "I heard your people had washed up on our shores, but I did not expect to find one washed up on my very doorstep! What brings you here, stranger?\n\n<You explain about your search for Prince Anduin, and describe the boy to the pandaren.>\n\nVery interesting! And so the Pearlfin sent you to me, did they?" }
WordHunterWoW_QuestEN[29890] = { title = "Finding Your Center", description = "The dream brew is complete! This time, when you drink it, you must embrace the visions you see from a state of inner focus.\n\nFollow me to my pagoda, and I will teach you how to achieve the inner calm that we pandaren value so much.\n\nYour troubled mind will present you with many distractions, but just remember to stay centered!   ", objectives = "Meditate with Lorewalker Cho at the pagoda at the Dreamer's Pavilion in the Jade Forest.", completion = "How did you find me?\n\n<Anduin listens to you describe the vision from the Dream Brew.>\n\nRemarkable! That's exactly what happened several days ago. We've been laying low since then." }
WordHunterWoW_QuestEN[29891] = { title = "Potency", description = "To make the Dream Brew, we will need several ingredients.\n\nFirst, to improve its strength, I will need an ingredient from a fearsome creature, the legendary Mist Horror.\n\nIt is said that this creature only appears where the fog is deepest.\n\nNorth and east of here, you will find smaller Mist Creepers roaming the swamps. Kill these creatures until the Mist Horror appears, and then bring me its heart.", objectives = "Kill Mist Creepers until a Mist Horror appears, then collect a Mist Horror Heart.", progress = "The mists seem to have a mind of their own, do they not?", completion = "This is an amazing specimen! I am quite shocked that you have succeeded, actually." }
WordHunterWoW_QuestEN[29892] = { title = "Body", description = "A brew's body is an important and often overlooked factor.\n\nTo create the perfect consistency, I will need pristine eyes from the Bog Crocolisks to the east.\n\nTake care. The creatures are quite vicious.", objectives = "Collect 5 Pristine Crocolisk Eyes from Bog Crocolisks.", progress = "Watch your step in the swamp, my new friend.", completion = "Do you have crocolisks where you are from?" }
WordHunterWoW_QuestEN[29893] = { title = "Hue", description = "The most distinguishing feature of the Dream Brew is its iridescent, dream-like color.\n\nTo the east, you will find Glittering Amberflies. I will need their wings to create the final luminescent color of the brew.\n\nTake this knife and use it to collect 8 wings.", objectives = "Collect 8 Amberfly Wings.", progress = "Have you collected all the ingredients? It is almost time to make the Dream Brew.", completion = "Beautiful color, rare transparency, shimmer but not sparkle...these will do quite well.\n\nI am beginning to see great potential in you, strange one." }
WordHunterWoW_QuestEN[29894] = { title = "Spirits of the Water", description = "Our war against the hozen rages without end, and the future of our tribe is uncertain.\n\nThis is why our waterspeaker has decided to seek wisdom from the waters.\n\nElder Lusshan is waiting. Please deliver the instruments so that they may begin.", objectives = "Speak to Elder Lusshan and witness the waterspeaking ceremony.", progress = "<The Elder's eyes are glazed over. His vision is cast inward, toward the wisdom he has gained.>", completion = "I saw the vision, <name>. What do you think it means?\n\nI think it is clear that you play some part in it." }
WordHunterWoW_QuestEN[29895] = { title = "Trail of the White Pawn", description = "Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest.\n\nYou should show it to your Alliance commander.", objectives = "Show the cloak to Admiral Taylor at Pearlfin Village in the Jade Forest.\n\nProvided item:", completion = "This is Anduin's cloak, <name>!\n\nThis must mean he passed through this forest.\n\nWe must heighten our efforts to find him." }
WordHunterWoW_QuestEN[29896] = { title = "Steaking a Claim", description = "Since we're already out here, no sense in going back empty-handed, right?\n\nNow, did you know that the porcupines around these parts have just about the rarest, juiciest steak a person has ever tasted?\n\nThey're difficult to hunt because of their sharp spikes, but you look like you can handle your own.\n\nGo on and round me up a couple of steaks to take back to camp.\n\nWe may be roughing it out in this wilderness, but we can still eat like kings!You will receive:", objectives = "Collect 5 Porcupine Steaks." }
WordHunterWoW_QuestEN[29897] = { title = "No Such Thing As A Free Lunch", description = "The fighting's over, but we're not out of trouble yet. Not by a long shot.\n\nOur camp is falling dangerously low on supplies, but our provisioner didn't make it back from the battle.\n\nSome of the troops saw her being dragged into the forest to the north.\n\nPlease, would you find her?You will receive:", objectives = "Find Sandra Emerella at the Veridian Grove in the Jade Forest.The fighting's over, but we're not out of trouble yet. Not by a long shot.\n\nOur camp is falling dangerously low on supplies, but our provisioner didn't make it back from the battle.\n\nSome of the troops saw her being dragged into the forest to the north.\n\nPlease, would you find her?You will receive:" }
WordHunterWoW_QuestEN[29898] = { title = "Sacred Waters", description = "I appreciate you coming all this way to save me, but Ren is gravely injured.\n\nThe old pandaren had no reason to help me, yet still he risked his life to save my own.\n\nBefore the fever set in, he mentioned that there are healing waters in the cave just down the hill.\n\nIt is dangerous, but I will do anything to help my friend. Will you help me retrieve the waters?", objectives = "Collect healing waters from the four Sacred Bowls in the Den of Sorrow.", progress = "Perhaps I could bring some of these healing waters back to Stormwind with me.", completion = "The healing waters should abate Ren's fever for a short while, but alas, I fear it is no permanent cure.\n\nThank you, <class>. We have granted him a little more time, at least." }
WordHunterWoW_QuestEN[29899] = { title = "Rest in Peace", description = "The spirits... the cavedwellers... they howl in agony... \n\nTrapped... in this world... cannot move... to the next.\n\nI... will go mad... listening... to their cries... \n\nPlease...go...put them to rest.", objectives = "Kill 6 Tortured Spirits.", completion = "Thank you... friend. I am... happy... knowing... the spirits... are at peace." }
WordHunterWoW_QuestEN[29900] = { title = "An Ancient Legend", description = "My father has dedicated his life to studying the Vale of Eternal Blossoms.\n\nThe Vale is a mythical place, sealed after the Pandaren revolution twelve thousand years ago. We know so little about it!\n\nMy father followed a trail of clues to the cave down the hill, seeking a very old poem known as the Song of the Vale, but he is in no condition to retrieve it. It is guarded by some sort of ancestor spirit.\n\nIf you are heading that way anyway, would you mind bringing it back to him?", objectives = "Retrieve the Song of the Vale from the Den of Sorrow.", progress = "Did you... find the scroll?", completion = "Oh... it is the poem! Did you... read it? What did you learn about the Vale?" }
WordHunterWoW_QuestEN[29901] = { title = "Anduin's Decision", description = "You have done all you can for the Prince's friends.\n\nYou completed your mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 agents will be eager to have the boy safe in their custody.\n\nIt is time to return home.", objectives = "Tell Anduin that it is time to return home.", completion = "He did WHAT?!?!?\n\nHe's lucky that I haven't found him yet, because when I do, I just might kill him myself!\n\nWhatever he thinks he's doing... chasing after this Vale... it is not behavior fit for a prince!\n\nIf we didn't have more pressing matters at hand, I would send our entire fleet chasing after his heels!" }
WordHunterWoW_QuestEN[29902] = { title = "Fighting the Flames", description = "Those monkeys seem to be more savage than intelligent, but they're smart enough to know that fire is a powerful weapon.\n\nI don't need to explain that if those fires are left unchecked, they'll destroy everything we've built here.\n\nAll my men have their hands full, so you'll have to do it. Take this bucket of water and put out those flames!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Put out 6 fires in Wayward Landing." }
WordHunterWoW_QuestEN[29903] = { title = "A Perfect Match", description = "Elder Lusshan and I agree that the best path forward will be to work together.\n\nWe will share with the Pearlfin our superior military knowledge and weaponry.\n\nIn return, they will be a powerful ally should we again encounter the Horde.\n\nTake this crate of equipment and weapons. I need you to go around the village and equip the jinyu with weapons befitting their skills.", objectives = "Speak to Pearlfin Aqualytes and arm them with the proper equipment.", progress = "The jinyu are skilled in different ways. It is up to us to find their strengths.", completion = "Good. Let those Horde mongrels show their faces now!" }
WordHunterWoW_QuestEN[29904] = { title = "Bigger Fish to Fry", description = "I've prepared a team of bright young Pearlfin trainees who need field experience.\n\nTake them northeast, into the Bamboo Wilds, and kill any wildlife that you find.\n\nDon't bring them back until they're fit for battle.", objectives = "Train the Pearlfin Adepts by killing 24 wildlife in the Bamboo Wilds.", progress = "How are those trainees looking?", completion = "Your trainees returned recently. I could hardly believe my eyes! They did not look like the same jinyu that you left with.\n\nExcellent work, <class>. Couldn't have done better myself." }
WordHunterWoW_QuestEN[29905] = { title = "Let Them Burn", description = "Advance scouts report that the hozen at the Slingtail Pits are amassing with reinforcements from their tribes to the north.\n\nOur forces are gathered for battle on the ridge to the northwest. They are just waiting for you.\n\nNow is the time to show them what we are made of. Now is the time to destroy them indefinitely.", objectives = "Kill 15 Grookin Reinforcements or Slingtail Recruits.", completion = "The waters were right about you, <name>. Because of your efforts, this village has a future. We will not forget the lessons you've taught us, <class>." }
WordHunterWoW_QuestEN[29906] = { title = "Carp Diem", description = "Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut, is the shrewd mastermind behind their attacks.\n\nHe is organizing their movements at the great pit at the hozen camp to the northwest.\n\nStrike now and show him no mercy, {name}, for he will do the same.", objectives = "Kill Chief Gukgut.", completion = "Without their leader, these hozen should once again settle into disarray.\n\nToday we rejoice in our victory! <name>, you came to us a stranger, but you depart as a friend.\n\nFrom henceforth, you are the highest of the high - a valued friend and defender of the Pearlfin tribe." }
WordHunterWoW_QuestEN[29907] = { title = "Chen and Li Li", description = "My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going.\n\nThat farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li?\n\n{race}? Would you like to share the road with us?", objectives = "Follow Chen Stormstout to Pang's Stead.", progress = "Yes?", completion = "Welcome, welcome, visitors! You've come to sample some of my son's turnips? Perhaps purchase a few pigs?\n\nPlease, make yourselves at home. I have plenty of room." }
WordHunterWoW_QuestEN[29908] = { title = "A Seemingly Endless Nuisance", description = "I apologize for the state of things around here. The virmen - those rabbity creatures, down the hill - have been pushing further and further into my family's farm, and our crops - which are normally bigger, and more delicious, by the way - have been suffering because of it.\n\nI'm no soldier... but you might be! Would you mind pushing some of these virmen off of our land?", objectives = "Slay 8 Snagtooth Spotters, Tool-Grabbers, or Troublemakers. Then slay 18 Snagtooth Pesterlings.", progress = "Have you pushed the virmen out yet, <class>? We need to bring in our crops soon, or they'll be lost for sure.", completion = "<Pang surveys the area around his farm.>\n\nWell, they're not ALL gone yet, but there's less of them. And they aren't holding their ears quite as high anymore.\n\nI'd guess that they're scared of you, <name>." }
WordHunterWoW_QuestEN[29909] = { title = "Low Turnip Turnout", description = "Your help here is appreciated, {name}. I'd like to give you another job, if you're interested.\n\nMy son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day.\n\nWould you go down there and see what's going on?", objectives = "Find Ang Thunderfoot.", completion = "Wha-? Who the...? My father sent you?\n\nPshh... he can be so nosy sometimes. I have everything under control here." }
WordHunterWoW_QuestEN[29910] = { title = "Rampaging Rodents", description = "I went off this morning to watch my papa fight the virmen. When I came back, the farm was full of marmots!\n\nI don't want to kill them, but we need to get rid of them. Hey, I know! We can close the holes!\n\nFill in their holes with dirt, so they can't come out in our farm anymore.", objectives = "Move 6 Plump Marmots off of Thunderfoot Farm, and fill in 6 Marmot Holes.", progress = "The marmots won't be happy when you try to fill in their holes.", completion = "Thank you, sir! Now I can get back to my chores." }
WordHunterWoW_QuestEN[29911] = { title = "Practically Perfect Produce", description = "Here, {name}. My father will be wanting this.\n\nThank you, again, for helping with the virmen.", objectives = "Bring the Crate of Fresh Crops to Pang Thunderfoot.", progress = "Do I smell turnips?", completion = "Ho ho! Now that's what I like to see!" }
WordHunterWoW_QuestEN[29912] = { title = "The Fabulous Miss Fanny", description = "Most of these vegetables will be sold, but I'd like to keep some for my family. Specifically, my nephew Liang needs some to feed to his pigs.\n\nUnfortunately, the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to have to ask Miss Fanny to help us out.\n\nBring some of the food we've gathered to Miss Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to Liang's ranch.", objectives = "Bring Ang's Giant Pink Turnip, Ang's Summer Watermelon, and Pang's Extra-Spicy Tofu to Miss Fanny, and ask her to deliver them. The food must land on Thunderfoot Ranch.", progress = "Not now, neighbor. I need to scrounge up some food for these pigs.", completion = "I understand you're the one who sent the food down from uncle's farm. Thank you.\n\nMy pigs are picky eaters, but those turnips and watermelons are some of their favorites." }
WordHunterWoW_QuestEN[29913] = { title = "The Meat They'll Eat", description = "I told you earlier, my pigs are picky eaters. They need to eat meat to grow strong, but they don't like mutton, they don't like yak, and I'm not about to feed them any pig meat.\n\nThey do, however, eat meat off of the mushan beasts, and they're also quite partial to turtle. Both creatures can be found in abundance to the west.\n\nMy skills as a hunter are admittedly quite weak. Can you help out a young rancher and his pigs?", objectives = "Obtain 4 Mushan Shoulder Steaks and 80 Turtle Meat Scraps.", progress = "It hurts my ears to hear their hungry squeals.\n\nOnce you've been a pig rancher for a while, you can distinguish hungry squeals from regular squeals.", completion = "<Liang sorts through the meat.>\n\nYou're not just a <class>, but you're a butcher, too? You've got an eye for quality pig food, neighbor." }
WordHunterWoW_QuestEN[29914] = { title = "Back to the Sty", description = "I try to keep an eye on my stock, but every once in a while some of them sneak away. With all the confusion these virmen are causing, I may have let my guard down for a few moments, and some of my pigs escaped.\n\nCare to look for them? I'd start by looking down the hill, to the west.", objectives = "Find Jian, Ling, and Smelly.", progress = "Have you found them? There should be three missing, I think.", completion = "There they are! Back into the sty with you three, now!\n\n<Liang looks up at you.>\n\nThank you, neighbor. I'm truly grateful for your assistance." }
WordHunterWoW_QuestEN[29915] = { title = "A Neighbor's Duty", description = "I'm not the only one having trouble with his stock, it seems. One of Francis' sheep has wandered over to my ranch, for the third time this week. I'm beginning to think he needs help tending to his flock.\n\nYou should check up on him, neighbor. And bring this poor little thing with you.", objectives = "Bring the Wayward Lamb to Francis the Shepherd Boy.", progress = "Oh... you have one of my... my lambs?", completion = "You really shouldn't have brought the lamb back to me. He... he was safer in that pigsty than he is over here." }
WordHunterWoW_QuestEN[29916] = { title = "Piercing Talons and Slavering Jaws", description = "First the hawks came. You've probably seen some of them circling up above.\n\nThe wolves came shortly after. I think they smelled my weakness.\n\nI'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts.\n\nCan... can you help, sir?", objectives = "Kill 5 Thieving Plainshawks and 6 Thieving Wolves.", progress = "I wish I were brave enough to fight them, but...", completion = "They... they're not stopping, but at least we fought back. Right?" }
WordHunterWoW_QuestEN[29917] = { title = "Lupello", description = "I've been thinking... the wolves might stop attacking if we kill their pack leader.\n\nWe call him Lupello, and he patrols the opposite riverbank.\n\n<Francis' concentration is broken by another attack. Perhaps you should go deal with Lupello yourself.>", objectives = "Slay Lupello.", progress = "What will Master Shang say when he finds out?", completion = "I know I should be the one fighting them off. Maybe I'm not cut out for shepherding after all." }
WordHunterWoW_QuestEN[29918] = { title = "A Lesson in Bravery", description = "<Master Shang speaks to his shepherd boy.>\n\nFrancis, you need to show bravery! You have everything it takes to make a great shepherd, except the courage to face your fears!\n\n<He looks over to you.>\n\nYou, stranger. You helped the rest of my family. Francis is like a second son to me.\n\nShow my apprentice what it means to lack fear. Use this rope to lasso and defeat one of the great white hawks above us.\n\n<Shang points to the sky, looks at Francis, and leaves.>", objectives = "Use the Rancher's Lariat to lasso and defeat a Great White Plainshawk.", progress = "You lack fear. I can sense it in your heart.", completion = "Francis has taken longer than I expected to become an effective shepherd. We all go through these phases... my son Liang was weak once, too. As was I.\n\nBut he will learn. It is the Thunderfoot way." }
WordHunterWoW_QuestEN[29919] = { title = "Great Minds Drink Alike", description = "Hello again, {name}. What is this, the fourth time we've run into one another already?\n\nSay... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?", objectives = "Escort Chen Stormstout and Li Li to the brewery in the southwest.", completion = "If yer lookin' fer beer, you came to the right place, neighbor.\n\nJust, ah... excuse the mess. Had me a bit of a problem with virmen the last few days." }
WordHunterWoW_QuestEN[29920] = { title = "Getting Permission", description = "My love, Lo, tried to get permission to marry me from the pandriarchs. Though they have passed beyond, their favor would carry a lot of weight.\n\nThing is, they are spirits, and none of the gifts or tributes we brought impress them. To win their favor they claimed that either Lo or a champion must defeat them in single combat.\n\nLo is a good man, but not a fighter.\n\nWould you be our champion?", objectives = "Challenge and defeat Pandriarch Goldendraft, Pandriarch Windfur, and Pandriarch Bramblestaff.", progress = "Each of the pandriarchs earned their reputation in life and retained them afterward.  I can't even imagine how you will defeat them.", completion = "They... they agreed?! Fantastic! Thank you so much! With their blessing we can be the happiest pandaren in all the land!\n\nPlease, take this. We meant it to be a tribute for the pandriarchs but they didn't seem interested." }
WordHunterWoW_QuestEN[29922] = { title = "In Search of Wisdom", description = "Lorewalker Cho came by and asked for you while you were gone.\n\nHe needs your assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did not say.\n\nSpeak to Kitemaster Ut-Nam. He would be happy to send you there.", objectives = "Speak to Kitemaster Ut-Nam and get a ride to Dawn's Blossom.", progress = "Ah! You made it. Fantastic!", completion = "Your deeds have sparked a long forgotten memory I have of an ancient prophecy. This deserves investigation.\n\nIn order to investigate, I need jade though. I have instructed Toya to gather as much as he can find and give it to you when he is done. Bring it to me and we will see about deciphering the ancient \"Emperor's Omen.\"\n\nWhile he gathers the jade, feel free to explore. You may find the people of this town are in need of a person of your caliber." }
WordHunterWoW_QuestEN[29923] = { title = "The Dream Brew", description = "The Dream Brew is ready.\n\nDrink it at the Seer's Stone, just to the right of the red pagoda.\n\nSeek, and find.You will receive:", objectives = "Drink the Dream Brew at the Seer's Stone and find the White Pawn." }
WordHunterWoW_QuestEN[29924] = { title = "Kill Kher Shan", description = "Kher Shan is one big dooker.\n\nGrooked all my sons! Ick Ick, Nab Nab, Eet Eet, Bitty Bitty, and the others I can't remember.\n\nWikket wanna help hozen? Go grook Kher Shan!\n\nThe dooker's over there.\n\n<Nibi Nibi points to the east.>", objectives = "Kill Kher Shan in Tigers' Wood." }
WordHunterWoW_QuestEN[29925] = { title = "All We Can Spare", description = "Alright, I called in every favor I could. Here's what we got.\n\nCho must be on to something big!\n\nLemme know when you're ready to go see him - I got a ride all prepared for ya.", objectives = "Deliver the Scavenged Jade to Lorewalker Cho at Emperor's Omen. Speak with Toya in Dawn's Blossom for a ride.", progress = "Ah, hello again, <name>! You received my message, then?", completion = "I knew Toya would come through for me!\n\nHe can get anything, you know." }
WordHunterWoW_QuestEN[29926] = { title = "Calamity Jade", description = "You ever seen a shale spider, {class}? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\"\n\nA few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys.\n\nYou get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.", objectives = "Slay 12 Greenstone Nibblers and 6 Greenstone Gorgers at the Greenstone Quarry.", completion = "Well I'll be... you actually did it!\n\nYou lookin' for a more permanent job, buddy? I could use a bruiser like you around full-time!" }
WordHunterWoW_QuestEN[29927] = { title = "Mann's Man", description = "<For once, the foreman lowers her voice.>\n\nLook, this ain't easy... I got another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice as stupid. Says the boys need him around for \"moral support.\"\n\n<Mann sneers.>\n\nWhat about my moral support?! What am I gonna do if that idiot dies?!\n\nPlease... keep an eye out for him. Tell him to come home.\n\n<Her eyes soften before she turns away.>", objectives = "Locate Hao Mann at the Greenstone Quarry.", completion = "<Hao looks up at you, struggling to pull himself from the rubble.>\n\nNo, no. I got it. HNNGHHH!!\n\nOkay, maybe I don't got it." }
WordHunterWoW_QuestEN[29928] = { title = "I Have No Jade And I Must Scream", description = "Our whole jade supply line has fallen apart. The mines are a death trap, morale is historically low, and - as if that weren't bad enough - the mason's quarter has been overrun by wood sprites!\n\nNow even the plants are out to ruin me!\n\nYou need jade so badly, you can follow the road southwest to the mason's quarter and get it from those glorified chopsticks yourself.", objectives = "Recover 15 Chunks of Jade from Puckish Sprites around the Greenstone Mason's Quarter.", progress = "<Mann looks at you expectantly, eyes wide and nostrils flared.>", completion = "Catch? They were playin' CATCH with my product?!\n\nI hope you showed those walkin' toothpicks a thing or two.\n\nYou know, maybe you ain't a cub after all. I've been lookin' for some muscle to help out with my problem at the quarry.\n\nAnd judgin' by the size of the Lorewalker's restoration project here, I think you'll need a lot more jade." }
WordHunterWoW_QuestEN[29929] = { title = "Trapped!", description = "<Hao struggles against the rubble with all his might.>\n\nHNNNGHHH!!\n\nLet me guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a little--HNNGGHHH!!--cave-in to keep ol' Hao down.\n\nSome o' the boys, on the other hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine.\n\nReally.", objectives = "Free 8 Greenstone Miners in the Greenstone Quarry.", completion = "<Hao lets out a hearty laugh.>\n\nI seen 'em come runnin' out o' there like ol' Kher Shan himself were givin' chase." }
WordHunterWoW_QuestEN[29930] = { title = "What's Mined Is Yours", description = "Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time.\n\nI should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her.\n\nNow, I ain't never met no {race} t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.", objectives = "Board the jade cart and ride with Hao back to Emperor's Omen.", progress = "Well? Where's Hao?\n\nDon't tell me you couldn't find him...", completion = "You did it! You brought my honey-bear back!\n\nOh thank you, <name>! Thank you!" }
WordHunterWoW_QuestEN[29931] = { title = "The Serpent's Heart", description = "You've done great here, kid. Thanks to you, we have quite a bit of extra jade, and I know just the someone who could use it.\n\nMy friend Foreman Raike is running the great statue project at the Serpent's Heart.\n\nBring a shipment of extra jade to him, and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.", objectives = "Speak to Foreman Raike at the Serpent's Heart in the Jade Forest.", completion = "Am I seeing this right? A whole shipment of pure, high quality uncut jade?\n\nThank goodness. I knew Foreman Mann would come through for us.\n\nOh and you too. Thanks for bringing it by." }
WordHunterWoW_QuestEN[29932] = { title = "The Temple of the Jade Serpent", description = "You've done us a huge favor here, traveler.\n\nNow that we have enough jade to complete the statue, we should send word of our progress to Yu'Lon, the Jade Serpent.\n\nWhen you arrive, speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent.\n\nIf you wish to speed your journey, speak to Kitemaster Shoku. I'm sure he can spare an extra kite for you.", objectives = "Speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent. Speak to Kitemaster Shoku for a kite ride to the temple.", progress = "Yes?", completion = "You bring news from the Serpent's Spine?\n\n<The Elder Sage patiently listens to your tale of what occurred at the Jade Mines and at the large jade statue.>\n\nThank you for coming all this way, stranger. However, I cannot allow you to speak to the Jade Serpent right now.\n\nThe ancient one is very busy, and as you can see, is not here at the moment." }
WordHunterWoW_QuestEN[29933] = { title = "The Bees' Knees", description = "You really hozen friend, wikket? Let's see, hmm?\n\nHozen at Grookin' Hill all outta slicky bait. Tigerflies' legs stay twitchy in water - make best bait!\n\nBo Bo sick from stings. Wikket get bait and take to Grookin.", objectives = "Collect 30 Bug Legs from Tigerflies in Tigers' Wood.", progress = "Slicky food!", completion = "Woot! Woot! Wikket da Ook Dook!" }
WordHunterWoW_QuestEN[29934] = { title = "To Ravenholdt", description = "If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure.\n\nThat's you, {name}.\n\nMostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!", objectives = "Speak to Mostrasz at the Vermillion Redoubt and fly to Ravenholdt Manor together.", progress = "So, are you ready to do some spying?", completion = "So far so good. Are you ready to do some spying?" }
WordHunterWoW_QuestEN[29935] = { title = "Orders are Orders", description = "Hmm, maybe wikket not so bad after all!\n\nOther baldskins not nice to hozen.\n\nHozen take this from bad wikkets!\n\nAll wikket loot goes to Kah Kah - Chief's orders!\n\nHere, wikket. You take it. Kah Kah will want to meet new hozen friend.\n\nHis camp south at Grookin Hill.", objectives = "Bring the Alliance Orders to Chief Kah Kah at Grookin.\n\nProvided item:", completion = "Hmm.\n\nMean wikkets fighting with nice wikkets?\n\nHozen fight mean wikkets too!" }
WordHunterWoW_QuestEN[29936] = { title = "Instant Messaging", description = "Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen.\n\nDook Ookem wanted to be chief, but good wikket grook him good - big gift to Kah Kah.\n\nHozen has gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.", objectives = "Use the Hellscream's Fist Signal Flare near Chief Kah Kah at Grookin Hill.", completion = "Impressive work, <name>.\n\nIt had not occurred to me that we might somehow befriend these creatures.\n\nWith their acceptance, we can now turn our attention to more important matters." }
WordHunterWoW_QuestEN[29937] = { title = "Furious Fowl", description = "So these guys like fish, huh? Well how about we finish what you started and make them LOVE us?\n\nI've still got some explosive powder from the wreck, just need something to attract the fish.\n\nGuts is sure to do the trick - never fails. I saw some birds flyin' around south of town.\n\nWell? Whatcha waitin' for?", objectives = "Collect 6 Fistfuls of Bird Guts from Bloodtalons in Dookin' Grounds.", progress = "You didn't touch that stuff with your hands did ya?", completion = "Yeah!\n\nNow that's the stuff. Just you wait and see..." }
WordHunterWoW_QuestEN[29938] = { title = "Friends and Foes", description = "These ookin' Jinyu grookin Kah Kah's nephews!\n\nWikket once kill many hozen. Now wikket kill many jinyu.", objectives = "Kill 7 Riverstride Jinyu at the Slicky Stream." }
WordHunterWoW_QuestEN[29939] = { title = "Boom Bait", description = "There. I've plastered your bird guts over my explosives.\n\nI call 'em Gut Bombs, patent pending.\n\nSince you made friends with these fellas, how about you do the honors?\n\nJust light the fuse and throw 'em down by the shoreline!", objectives = "Use the Gut Bombs at Murky Bank and collect 5 Exploded Slickies.", progress = "I have yet to face a crisis that couldn't be fixed with dynamite.", completion = "We've just revolutionized how these cretins.. err, hozen, feed themselves.\n\nThey'll never be the same!" }
WordHunterWoW_QuestEN[29940] = { title = "Taking a Crop", description = "Alright, fine. I DON'T have everything under control here. I spent all morning fighting off virmen. I managed to clear them off of my property, but they got away with some of my crops.\n\nThey took them down to the river, to the south. I have no idea what they're doing with them, but it's probably not eating them.\n\nIf my father wants his delivery now, I'm going to need some help getting those crops back. Could you help me out?", objectives = "Obtain 5 Stolen Turnips and 5 Stolen Watermelons.", progress = "If my father wants his vegetables, I'm going to need your help.", completion = "Perfect.\n\n<Ang surveys the bruised turnips and the soggy watermelons.>\n\nWhat were they DOING down there!?" }
WordHunterWoW_QuestEN[29941] = { title = "Beyond the Horizon", description = "I recognize all you've managed to do here, {class}. My report to the Warchief will include an account of your deeds.\n\nBut there's no time to rest!\n\nThis land must be charted and prepared for Horde settlement. I've already selected an away team to do just that.\n\nFind them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide.\n\nYou'll be staying here with me. We have preparations to make.", objectives = "Speak to Shokia, Sergeant Gorrok, Shademaster Kiryn, and Chief Kah Kah.", progress = "Has the away team been dispatched, <name>?", completion = "Good work <name>.\n\nThe away team you assembled has departed.\n\nI hope Gorrok had the sense to change out of that ragged red shirt. I admire his patriotism, but he's had it on since we left Orgrimmar.\n\nThey won't be surprising anyone if he's wearing it..." }
WordHunterWoW_QuestEN[29942] = { title = "Silly Wikket, Slickies are for Hozen", description = "You think hozen crazy, wikket? Wait til you see hozen with no slickies!\n\nNot enough slickies for hozen and wikkets.\n\nSnappers! Hozen hate them ookin' snappers. Wikkets can eat all the snappers!\n\n<Eekle Eekle points to the south.>", objectives = "Collect 4 Snapper Steaks from the Murky Bank.", progress = "Wikket grook all them ookin' snappers?", completion = "Now everybody got grub! Great hozen wisdom in Eekle Eekle.\n\nMaybe Eekle Eekle become Chieftain someday..." }
WordHunterWoW_QuestEN[29943] = { title = "Guerrillas in our Midst", description = "Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, {name}.\n\nBut there's another side of this coin. We'd be naive to think the child was left alone.\n\nAny Alliance scum within sight of this land must be searching desperately for their precious princeling.\n\nYou and I are going to scour the area and root out his would-be rescuers.", objectives = "Kill 8 Alliance Infiltrators near the Scenic Overlook.", completion = "Yes!\n\nBy Thrall's bloodied fist, I've missed hunting Alliance!" }
WordHunterWoW_QuestEN[29944] = { title = "Leaders Among Breeders", description = "Before any kegs are tapped, we have work to do. These virmen are no different than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits they resemble.\n\nSure, we could kill every last virmen we find, but what's the point in needless bloodshed? Let's just take out their alphas, and they'll slow down with their... reproduction.", objectives = "Slay Aiyu the Skillet, Jinanya the Clawblade, and Frenzyhop.", progress = "The virmen here have strange habits. Stranger names.", completion = "<Chen nods.>\n\nGood work, <name>. You're not bad in combat.\n\nWhat do you say we team up for the next part?" }
WordHunterWoW_QuestEN[29945] = { title = "Yellow and Red Make Orange", description = "Uncle Chen says we're going to help this guy out with his virmen problem. Fine by me! I LOVE messing with virmen.\n\nHere's the plan: we're going to paint some turnips orange, and then we'll try to convince the virmen that they're carrots.\n\nThis can only end in comedy.\n\nI'll gather turnips. You find something that we can use to make edible orange paint.", objectives = "Obtain 10 Meadow Marigolds and 40 Vials of Animal Blood.", progress = "You have the stuff ready for the paint? I went ahead and gathered some turnips.", completion = "Whoah, whoah, WHOAH! You brought back BLOOD? I guess I should have looked around for a half second before I asked you to bring me something red.\n\nYeesh!\n\n<Li Li turns back to the ingredients, spends a moment crushing the flower petals, and then mixes in some of the blood.>\n\n<She begins to giggle.>" }
WordHunterWoW_QuestEN[29946] = { title = "The Warren-Mother", description = "We've dealt with the alpha males. Now, the alpha female.\n\nVirmen aren't terribly selective when it comes to breeding, but most broods will still have a dominant mother figure. She's usually bigger, meaner, and tougher than anyone else in the brood.\n\nYou know, I wouldn't mind testing my skills against a warren-mother. Mind if I fight alongside you?", objectives = "Defeat Chufa, the Twitchheel Warren-Mother.", completion = "That should take care of the virmen for a few weeks, at least. Enough time for Mudmug to get out a few good batches of beer, uninterrupted.\n\nAnd isn't that what's really important?" }
WordHunterWoW_QuestEN[29947] = { title = "Crouching Carrot, Hidden Turnip", description = "Uncle Chen's still got his eye on me, which means I won't be wandering off any time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into the Twisted Warren and deliver them for me.\n\nIt should be pretty simple. Just toss the vegetables in front of virmen, then watch their reaction when they find out it's really a turnip!", objectives = "Toss Orange-Colored Turnips in front of 12 Twitchheel Hoarders.", progress = "Go, torment those virmen, <name>!", completion = "Bah ha hah haaaa! I love messing with virmen." }
WordHunterWoW_QuestEN[29948] = { title = "Thieves to the Core", description = "You and that Chen fellow are good people, helpin' out with the virmen like you are. I don't like to ask for favors, but I ain't gonna turn 'em away, either.\n\nWhile you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last night.\n\nProbably usin' em for pillows, knowin' how they are.", objectives = "Recover 6 Stolen Sacks of Hops from the Twisted Warren.", progress = "I done told those virmen to stay off my land.", completion = "Aww, thank ya kindly, sir. You're a real gentleman." }
WordHunterWoW_QuestEN[29949] = { title = "Legacy", description = "I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.", objectives = "Have a drink with Chen, Li Li, and Mudmug.", completion = "I know Uncle Chen's coming back. I'm not worried.\n\nActually, this is probably my big chance to finally explore Pandaria! No fat uncle tying me down!" }
WordHunterWoW_QuestEN[29950] = { title = "Li Li's Day Off", description = "Uncle Chen asked me not to get into any fights while he was away... but that doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without stopping every forty-seven steps for another rest!\n\nYou want to come with me? I'll bet there's all kinds of cool places we can visit, not too far away from here.", objectives = "Bring Li Li to the Silken Fields, New Cifera, and Huangtze Falls.", progress = "You ready to go out yet?", completion = "That was great! You and I should go exploring again sometime.\n\nAnd it looks like we finished before Uncle Chen got back, too. Perfect." }
WordHunterWoW_QuestEN[29951] = { title = "Muddy Water", description = "While you're just hangin' around, I might as well get you involved in my whole beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff together and wait.\n\nYou probably heard - I like to use the muddy water from the riverbanks, to the south. Would you mind fillin' up this flask with that water and bringin' it back? I'll start gettin' the hops and barley all ready.", objectives = "Use Mudmug's Vial to gather muddy water.", progress = "I knowed you for a friend as soon as I seen you.", completion = "You done good, <name>. You done good." }
WordHunterWoW_QuestEN[29952] = { title = "Broken Dreams", description = "Yes, I found the Stormstout Brewery... although I didn't exactly get the warm reception I expected.\n\n<Chen pours himself a mug of ale.>\n\nDo you want to hear the story?", objectives = "Speak with Chen Stormstout and listen to his story.", progress = "...", completion = "Maybe I wasn't meant to settle down anyhow." }
WordHunterWoW_QuestEN[29966] = { title = "Burning Down the House", description = "Look, {name}!\n\nThese Alliance dogs built a camp up on the ridge.\n\nHere, take my grog. Let's make a fire they can see from Stormwind!\n\nFor the Horde!", objectives = "Use Nazgrim's Grog to destroy the Alliance Camp atop the Scenic Overlook.", completion = "The Alliance must be purged from this land, <name>!\n\nNo half-measures will do!" }
WordHunterWoW_QuestEN[29967] = { title = "Boom Goes the Doonamite!", description = "It's an emergency!\n\nLooks like you stirred up a hornet's nest killin' all them fish-folk.\n\nThey're conductin' a full-on counterattack on Grookin Hill!\n\nI was hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work right away!\n\nMeet me on the east side of the fort, and bring yer throwin' arm!", objectives = "Speak to Rivett east of Grookin Hill. Use his Methane Grenades to fend off the Jinyu attack.", progress = "I think these methane-grenades are gunna impact the environment, if ya know what I mean...", completion = "I'd say repelling the attack is an understatement!" }
WordHunterWoW_QuestEN[29968] = { title = "Green-ish Energy", description = "One word: Methane!\n\nWe're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world.\n\nThat, and I ran out of blasting powder...\n\nSo, I need your help, {name}.\n\nNo, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself.\n\nYou gather up some wood for an outhouse - I'm thinking long-term here!", objectives = "Gather 7 Green Branches in the Dookin' Grounds.", progress = "Gotta watch out for the wet ones...whewee!", completion = "Ah, the smell of progress, and methane." }
